WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']->init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p> </p>\n<p>register_shutdown_function( \'shutdown_action_hook\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p> </p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p> </p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p></p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-13 18:01:35','2019-05-13 09:01:35','',1816,'https://tech.embodyer.com/anothor/1816-revision-v1',0,'revision','',0),(1974,1,'2019-05-13 18:01:38','2019-05-13 09:01:38','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p></p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>冒頭～メンテナンスモードまで</h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n\n<pre class=\"lang:php decode:true\" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>メンテナンスモード～ コアファイルの読み込みまで </h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p> </p>\n\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> コアファイルの読み込み ～ まで</h3>\n<!-- /wp:heading -->\n\n<pre class=\"\">\n<?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH . WPINC . \'/capabilities.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-roles.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-role.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-query.php\' );\nrequire( ABSPATH . WPINC . \'/query.php\' );\nrequire( ABSPATH . WPINC . \'/date.php\' );\nrequire( ABSPATH . WPINC . \'/theme.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-theme.php\' );\nrequire( ABSPATH . WPINC . \'/template.php\' );\nrequire( ABSPATH . WPINC . \'/user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-met