-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p></p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p></p>\n<p>apply_filters();</p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-30 17:22:21','2019-05-30 08:22:21','',1816,'https://tech.embodyer.com/anothor/1816-revision-v1',0,'revision','',0),(2334,1,'2019-05-30 18:04:11','2019-05-30 09:04:11','<p>wordpressのコアファイルを読んでる途中で、global宣言と$GLOBALS[変数名]が出てきたのですが、ちょっとあやふやなとこがあったので、今更ながらphpの基礎から確認してみました。</p>\n\n<!-- wp:heading -->\n<h2>変数の宣言とスコープ</h2>\n<!-- /wp:heading -->\n\n<p>phpでは</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>擬似変数：$this-> って何だ？</h3>\n<!-- /wp:heading -->\n\n<p>https://www.sejuku.net/blog/51537</p>\n\n<!-- wp:heading -->\n<h2>global宣言と$GLOBALS</h2>\n<!-- /wp:heading -->','phpの変数とスコープ','wordpressのコアファイルを読んでる途中でglobal宣言と$GLOBALS[]が出てきたのでphpの基礎から確認','inherit','closed','closed','','368-revision-v1','','','2019-05-30 18:04:11','2019-05-30 09:04:11','',368,'https://tech.embodyer.com/anothor/368-revision-v1',0,'revision','',0),(2336,0,'2019-06-09 09:53:49','2019-06-09 00:53:49','','wp-include/load.phpを解読してみた','','private','open','closed','','wp-include-load-php','','','2019-06-10 11:00:15','2019-06-10 02:00:15','',0,'https://tech.embodyer.com/?post_type=web_and_aplication&#038;p=2336',0,'web_and_aplication','',0),(2337,1,'2019-05-31 09:55:36','2019-05-31 00:55:36','','wp-include/load.phpを解読してみた','','inherit','closed','closed','','2336-revision-v1','','','2019-05-31 09:55:36','2019-05-31 00:55:36','',2336,'https://tech.embodyer.com/anothor/2336-revision-v1',0,'revision','',0),(2338,0,'2019-06-16 09:56:34','2019-06-16 00:56:34','','wp-include/query.phpを解読してみた','','publish','open','closed','','wp-include-query-php','','','2019-05-31 09:58:41','2019-05-31 00:58:41','',0,'https://tech.embodyer.com/?post_type=web_and_aplication&#038;p=2338',0,'web_and_aplication','',0),(2339,1,'2019-05-31 09:58:38','2019-05-31 00:58:38','','wp-include/query.phpを解読してみた','','inherit','closed','closed','','2338-revision-v1','','','2019-05-31 09:58:38','2019-05-31 00:58:38','',2338,'https://tech.embodyer.com/anothor/2338-revision-v1',0,'revision','',0),(2350,1,'2019-06-03 09:35:21','2019-06-03 00:35:21','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n\n<!-- wp:image {\"id\":2252,\"align\":\"center\"} -->\n<div class=\"wp-block-image\"><figure class=\"aligncenter\"><img src=\"https://tech.embodyer.com/wp-content/uploads/2019/05/wp_core-640x634.png\" alt=\"\" class=\"wp-image-2252\"/></figure></div>\n<!-- /wp:image -->\n\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n\n<!-- wp:heading -->\n<h2>冒頭～メンテナンスモードまで</h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<pre class=\"lang:php decode:true \" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>メンテナンスモード～ コアファイルの読み込みまで </h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p></p>\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading -->\n<h2> コアファイルの読み込み ～ まで</h2>\n<!-- /wp:heading -->\n\n<pre class=\"\"><!--?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH . WPINC . \'/capabilities.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-roles.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-role.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-query.php\' );\nrequire( ABSPATH . WPINC . \'/query.php\' );\nrequire( ABSPATH . WPINC . \'/date.php\' );\nrequire( ABSPATH . WPINC . \'/theme.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-theme.php\' );\nrequire( ABSPATH . WPINC . \'/template.php\' );\nrequire( ABSPATH . WPINC . \'/user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );\nrequire( ABSPATH . WPINC . \'/general-template.php\' );\nrequire( ABSPATH . WPINC . \'/link-template.php\' );\nrequire( ABSPATH . WPINC . \'/author-template.php\' );\nrequire( ABSPATH . WPINC . \'/post.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post.php\' );\nrequire( ABSPATH . WPINC . \'/post-template.php\' );\nrequire( ABSPATH . WPINC . \'/revision.php\' );\nrequire( ABSPATH . WPINC . \'/post-formats.php\' );\nrequire( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );\nrequire( ABSPATH . WPINC . \'/category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/category-template.php\' );\nrequire( ABSPATH . WPINC . \'/comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-comment.php\' );\nrequire( ABSPATH . WPINC . \'/comment-template.php\' );\nrequire( ABSPATH . WPINC . \'/rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/feed.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark-template.php\' );\nrequire( ABSPATH . WPINC . \'/kses.php\' );\nrequire( ABSPATH . WPINC . \'/cron.php\' );\nrequire( ABSPATH . WPINC . \'/deprecated.php\' );\nrequire( ABSPATH . WPINC . \'/script-loader.php\' );\nrequire( ABSPATH . WPINC . \'/taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );\nrequire( ABSPATH . WPINC . \'/update.php\' );\nrequire( ABSPATH . WPINC . \'/canonical.php\' );\nrequire( ABSPATH . WPINC . \'/shortcodes.php\' );\nrequire( ABSPATH . WPINC . \'/embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-oembed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );\nrequire( ABSPATH . WPINC . \'/media.php\' );\nrequire( ABSPATH . WPINC . \'/http.php\' );\nrequire( ABSPATH . WPINC . \'/class-http.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p></p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p></p>\n<p>apply_filters();</p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-06-03 09:35:21','2019-06-03 00:35:21','',1816,'https://tech.embodyer.com/anothor/1816-revision-v1',0,'revision','',0),(2351,0,'2019-10-04 11:46:45','2019-10-04 02:46:45','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p></p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p></p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p></p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p></p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p></p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p></p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p></p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p></p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p></p>\n<p></p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p></p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p></p>\n<p>例題３）</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p></p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p></p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>\n\n<!-- wp:heading -->\n<h2>DDos攻撃を防ぐ</h2>\n<!-- /wp:heading -->\n\n<p>別にDDos攻撃防止だけじゃなく、予期しないトラフィックの増加が見込まれる場合にもcloudfrontは使用されますが。</p>\n<p> </p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','publish','closed','closed','','certified-solutions-architect-professional-cloudfront','','','2019-10-03 11:19:04','2019-10-03 02:19:04','',0,'https://tech.embodyer.com/?post_type=infrastructure&#038;p=2351',0,'infrastructure','',0),(2354,1,'2019-06-04 11:49:40','2019-06-04 02:49:40','','Amazon-CloudFront@4x','','inherit','open','closed','','amazon-cloudfront4x','','','2019-06-04 11:50:16','2019-06-04 02:50:16','',2351,'https://tech.embodyer.com/wp-content/uploads/2019/06/bc90f48b43ea887ca26661f0e910aa7e.png',0,'attachment','image/png',0),(2474,1,'2019-06-04 18:40:08','2019-06-04 09:40:08','<p>データベースに接続して取得したり、インサートするファイルになります。</p>\n<p> </p>\n\n','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-04 18:40:08','2019-06-04 09:40:08','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2476,1,'2019-06-04 18:41:26','2019-06-04 09:41:26','<p>データベースに接続して取得したり、インサートするファイルになります。</p>\n<p> </p>\n\n<pre class=\"lang:php decode:true crayon-selected\" title=\"wp-db.php\">&lt;?php\n/**\n * WordPress DBクラス\n *\n * 元のコード  {@link http://php.justinvincent.com Justin Vincent (justin@visunet.ie)}\n *\n * @package WordPress\n * @subpackage Database\n * @since 0.71\n */\n\n/**\n * @since 0.71\n */\ndefine( \'EZSQL_VERSION\', \'WP1.25\' );\n\n/**\n * @since 0.71\n */\ndefine( \'OBJECT\', \'OBJECT\' );\n// phpcs:ignore Generic.NamingConventions.UpperCaseConstantName.ConstantNotUpperCase\ndefine( \'object\', \'OBJECT\' ); // Back compat.\n\n/**\n * @since 2.5.0\n */\ndefine( \'OBJECT_K\', \'OBJECT_K\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_A\', \'ARRAY_A\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_N\', \'ARRAY_N\' );\n\n/**\n * WordPressデータベースアクセス抽象化オブジェクト\n *\n * wp-content / db.phpファイルの$ wpdbグローバル変数を\n * あなたのクラスに設定することで、このクラスをあなた自身のクラスに\n * 置き換えることが可能です。\n *\n * @link https://codex.wordpress.org/Function_Reference/wpdb_Class\n *\n * @since 0.71\n */\nclass wpdb {\n\n	/**\n	 * SQL / DBエラーを表示するかどうか\n	 *\n	 * デフォルトの動作では、WP_DEBUGとWP_DEBUG_DISPLAYの両方がtrueと評価された場合に\n	 * エラーを表示します。\n	 *\n	 * @since 0.71\n	 * @var bool\n	 */\n	var $show_errors = false;\n\n	/**\n	 * DBブートストラップ中のエラーを抑制するかどうか。\n	 *\n	 * @since 2.5.0\n	 * @var bool\n	 */\n	var $suppress_errors = false;\n\n	/**\n	 * クエリ中の最後のエラー\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $last_error = \'\';\n\n	/**\n	 * 行われたクエリの量\n	 *\n	 * @since 1.2.0\n	 * @var int\n	 */\n	public $num_queries = 0;\n\n	/**\n	 * 前のクエリによって返された行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $num_rows = 0;\n\n	/**\n	 * 前の照会による影響を受けた行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	var $rows_affected = 0;\n\n	/**\n	 * 前回のクエリによってAUTO_INCREMENTカラムに対して生成されたID（通常はINSERT）。\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $insert_id = 0;\n\n	/**\n	 * 最後に行われたクエリ\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	var $last_query;\n\n	/**\n	 * 最後に行われたクエリの結果\n	 *\n	 * @since 0.71\n	 * @var array|null\n	 */\n	var $last_result;\n\n	/**\n	 * MySQLの結果。これはリソースまたはブール値です。\n	 *\n	 * @since 0.71\n	 * @var mixed\n	 */\n	protected $result;\n\n	/**\n	 * 挿入前のサニティチェックデータ用のキャッシュされた列情報\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $col_meta = array();\n\n	/**\n	 * テーブルの計算文字セット\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $table_charset = array();\n\n	/**\n	 * 現在のクエリのテキストフィールドを健全性チェックする必要があるかどうか。\n	 *\n	 * @since 4.2.0\n	 * @var bool\n	 */\n	protected $check_current_query = true;\n\n	/**\n	 * 照合をチェックするときに再帰問題に遭遇しないようにするためのフラグ。\n	 *\n	 * @since 4.2.0\n	 * @see wpdb::check_safe_collation()\n	 * @var bool\n	 */\n	private $checking_collation = false;\n\n	/**\n	 * テーブルカラムに保存された情報\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	protected $col_info;\n\n	/**\n	 * デバッグ目的で実行されたクエリのログ。\n	 *\n	 * @since 1.5.0\n	 * @since 2.5.0 各クエリログの3番目の要素は、呼び出し元の関数を記録するために追加されました。\n	 * @since 5.1.0 各クエリログの4番目の要素は、開始時刻を記録するために追加されました。\n	 *\n	 * @var array[] {\n	 *     実行されたクエリの配列。\n	 *\n	 *     @type array ...$0 {\n	 *         Data for each query.\n	 *\n	 *         @type string $0 The query\'s SQL.\n	 *         @type float  $1 照会に費やした合計時間（秒単位）。\n	 *         @type string $2 呼び出し側関数のコンマ区切りリスト。\n	 *         @type float  $3 問い合わせの開始時のUnixタイムスタンプ。\n	 *     }\n	 * }\n	 */\n	var $queries;\n\n	/**\n	 * 死ぬまでに再接続を再試行する回数\n	 *\n	 * @since 3.9.0\n	 * @see wpdb::check_connection()\n	 * @var int\n	 */\n	protected $reconnect_retries = 5;\n\n	/**\n	 * WordPressのテーブルプレフィックス\n	 *\n	 * 単一のデータベースに複数のWordPressをインストールするように設定できます。\n	 * 2番目の理由は、考えられるセキュリティ上の予防策です。\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $prefix = \'\';\n\n	/**\n	 * WordPressのベーステーブルプレフィックス。\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $base_prefix;\n\n	/**\n	 * Whether the database queries are ready to start executing.\n	 *\n	 * @since 2.3.2\n	 * @var bool\n	 */\n	var $ready = false;\n\n	/**\n	 * Blog ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $blogid = 0;\n\n	/**\n	 * Site ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $siteid = 0;\n\n	/**\n	 * ブログ毎のWordPress一覧表\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $tables = array(\n		\'posts\',\n		\'comments\',\n		\'links\',\n		\'options\',\n		\'postmeta\',\n		\'terms\',\n		\'term_taxonomy\',\n		\'term_relationships\',\n		\'termmeta\',\n		\'commentmeta\',\n	);\n\n	/**\n	 * 廃止予定のWordPressテーブルのリスト\n	 *\n	 * categories、post2cat、およびlink2catは、2.3.0、dbバージョン5539で非推奨となりました。\n	 *\n	 * @since 2.9.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $old_tables = array( \'categories\', \'post2cat\', \'link2cat\' );\n\n	/**\n	 * WordPressグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $global_tables = array( \'users\', \'usermeta\' );\n\n	/**\n	 * マルチサイトグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $ms_global_tables = array(\n		\'blogs\',\n		\'blogmeta\',\n		\'signups\',\n		\'site\',\n		\'sitemeta\',\n		\'sitecategories\',\n		\'registration_log\',\n		\'blog_versions\',\n	);\n\n	/**\n	 * WordPress Comments table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $comments;\n\n	/**\n	 * WordPress Comment Metadata table\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	public $commentmeta;\n\n	/**\n	 * WordPress Links table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $links;\n\n	/**\n	 * WordPress Options table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $options;\n\n	/**\n	 * WordPress Post Metadata table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $postmeta;\n\n	/**\n	 * WordPress Posts table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $posts;\n\n	/**\n	 * WordPress Terms table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $terms;\n\n	/**\n	 * WordPress Term Relationships table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_relationships;\n\n	/**\n	 * WordPress Term Taxonomy table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_taxonomy;\n\n	/**\n	 * WordPress Term Meta table.\n	 *\n	 * @since 4.4.0\n	 * @var string\n	 */\n	public $termmeta;\n\n	//\n	// Global and Multisite tables\n	//\n\n	/**\n	 * WordPress User Metadata table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $usermeta;\n\n	/**\n	 * WordPress Users table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $users;\n\n	/**\n	 * Multisite Blogs table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blogs;\n\n	/**\n	 * Multisite Blog Metadata table\n	 *\n	 * @since 5.1.0\n	 * @var string\n	 */\n	public $blogmeta;\n\n	/**\n	 * Multisite Blog Versions table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blog_versions;\n\n	/**\n	 * Multisite Registration Log table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $registration_log;\n\n	/**\n	 * Multisite Signups table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $signups;\n\n	/**\n	 * Multisite Sites table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $site;\n\n	/**\n	 * Multisite Sitewide Terms table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitecategories;\n\n	/**\n	 * Multisite Site Metadata table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitemeta;\n\n	/**\n	 * DB列のフォーマット指定子ここにリストされていない列は、デフォルトで％sになります。WPロード中に初期化されました。\n	 *\n	 * キーはカラム名、値はフォーマットタイプです。 \'ID\' =&gt; \'％d\'\n	 *\n	 * @since 2.8.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::insert()\n	 * @see wpdb::update()\n	 * @see wpdb::delete()\n	 * @see wp_set_wpdb_vars()\n	 * @var array\n	 */\n	public $field_types = array();\n\n	/**\n	 * Database table columns charset\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $charset;\n\n	/**\n	 * Database table columns collate\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $collate;\n\n	/**\n	 * Database Username\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	protected $dbuser;\n\n	/**\n	 * Database Password\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbpassword;\n\n	/**\n	 * Database Name\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbname;\n\n	/**\n	 * Database Host\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbhost;\n\n	/**\n	 * Database Handle\n	 *\n	 * @since 0.71\n	 * @var string\n	 */\n	protected $dbh;\n\n	/**\n	 * 最後のクエリ/ get_row / get_var呼び出しの説明文\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $func_call;\n\n	/**\n	 * MySQLがデータベースエンジンとして使用されているかどうか。\n	 *\n	 * デフォルトでは、WPDB :: db_connect（）をtrueに設定します。 \n	 * これはWordPressに必要なMySQLバージョンをチェックするときに使われます。 \n	 * 通常、置換データベースドロップイン（db.php）はこれらのチェックをスキップしますが、\n	 * これをtrueに設定するとチェックを強制的に実行させます。\n	 *\n	 * @since 3.3.0\n	 * @var bool\n	 */\n	public $is_mysql = null;\n\n	/**\n	 * 互換性のないSQLモードのリスト。\n	 *\n	 * @since 3.9.0\n	 * @var array\n	 */\n	protected $incompatible_modes = array(\n		\'NO_ZERO_DATE\',\n		\'ONLY_FULL_GROUP_BY\',\n		\'STRICT_TRANS_TABLES\',\n		\'STRICT_ALL_TABLES\',\n		\'TRADITIONAL\',\n	);\n\n	/**\n	 * mysql上でmysqliを使用するかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $use_mysqli = false;\n\n	/**\n	 * ある時点でうまく接続できたかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $has_connected = false;\n\n	/**\n	 * データベースサーバーに接続してデータベースを選択する\n	 *\n	 * PPHP 5との互換性のためのHP 5スタイルのコンストラクタ。 Does\n	 * クラスプロパティの実際の設定とデータベースへの接続を行います。\n	 * \n	 *\n	 * @link https://core.trac.wordpress.org/ticket/3354\n	 * @since 2.0.8\n	 *\n	 * @global string $wp_version\n	 *\n	 * @param string $dbuser     MySQL database user\n	 * @param string $dbpassword MySQL database password\n	 * @param string $dbname     MySQL database name\n	 * @param string $dbhost     MySQL database host\n	 */\n	public function __construct( $dbuser, $dbpassword, $dbname, $dbhost ) {\n		register_shutdown_function( array( $this, \'__destruct\' ) );\n\n		if ( WP_DEBUG &amp;&amp; WP_DEBUG_DISPLAY ) {\n			$this-&gt;show_errors();\n		}\n\n		// WP_USE_EXT_MYSQLがtrueとして定義されていない限り、存在する場合はext / mysqliを使用\n		if ( function_exists( \'mysqli_connect\' ) ) {\n			$this-&gt;use_mysqli = true;\n\n			if ( defined( \'WP_USE_EXT_MYSQL\' ) ) {\n				$this-&gt;use_mysqli = ! WP_USE_EXT_MYSQL;\n			}\n		}\n\n		$this-&gt;dbuser     = $dbuser;\n		$this-&gt;dbpassword = $dbpassword;\n		$this-&gt;dbname     = $dbname;\n		$this-&gt;dbhost     = $dbhost;\n\n		// wp-config.phpの作成は準備ができたら手動で接続します。\n		if ( defined( \'WP_SETUP_CONFIG\' ) ) {\n			return;\n		}\n\n		$this-&gt;db_connect();\n	}\n\n	/**\n	 * PHP 5スタイルのデストラクタで、データベースオブジェクトが破棄されたときに実行されます。\n	 *\n	 * @see wpdb::__construct()\n	 * @since 2.0.8\n	 * @return true\n	 */\n	public function __destruct() {\n		return true;\n	}\n\n	/**\n	 * 下位互換性のためにプライベートプロパティを読み取り可能にします\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name The private member to get, and optionally process\n	 * @return mixed The private member\n	 */\n	public function __get( $name ) {\n		if ( \'col_info\' === $name ) {\n			$this-&gt;load_col_info();\n		}\n\n		return $this-&gt;$name;\n	}\n\n	/**\n	 *プライベートプロパティを下位互換性のために設定可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to set\n	 * @param mixed  $value The value to set\n	 */\n	public function __set( $name, $value ) {\n		$protected_members = array(\n			\'col_meta\',\n			\'table_charset\',\n			\'check_current_query\',\n		);\n		if ( in_array( $name, $protected_members, true ) ) {\n			return;\n		}\n		$this-&gt;$name = $value;\n	}\n\n	/**\n	 * プライベートプロパティを下位互換性のためにチェック可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to check\n	 *\n	 * @return bool If the member is set or not\n	 */\n	public function __isset( $name ) {\n		return isset( $this-&gt;$name );\n	}\n\n	/**\n	 * Makes private properties un-settable for backward compatibility.\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to unset\n	 */\n	public function __unset( $name ) {\n		unset( $this-&gt;$name );\n	}\n\n	/**\n	 * Set $this-&gt;charset and $this-&gt;collate\n	 *\n	 * @since 3.1.0\n	 */\n	public function init_charset() {\n		$charset = \'\';\n		$collate = \'\';\n\n		if ( function_exists( \'is_multisite\' ) &amp;&amp; is_multisite() ) {\n			$charset = \'utf8\';\n			if ( defined( \'DB_COLLATE\' ) &amp;&amp; DB_COLLATE ) {\n				$collate = DB_COLLATE;\n			} else {\n				$collate = \'utf8_general_ci\';\n			}\n		} elseif ( defined( \'DB_COLLATE\' ) ) {\n			$collate = DB_COLLATE;\n		}\n\n		if ( defined( \'DB_CHARSET\' ) ) {\n			$charset = DB_CHARSET;\n		}\n\n		$charset_collate = $this-&gt;determine_charset( $charset, $collate );\n\n		$this-&gt;charset = $charset_collate[\'charset\'];\n		$this-&gt;collate = $charset_collate[\'collate\'];\n	}\n\n	/**\n	 * 与えられた文字セットと照合順序を使用して、使用するのに最適な文字セットと照合順序を決定します。\n	 *\n	 * たとえば、可能であれば、utf8の代わりにutf8mb4を使用する必要があります。\n	 *\n	 * @since 4.6.0\n	 *\n	 * @param string $charset The character set to check.\n	 * @param string $collate The collation to check.\n	 * @return array The most appropriate character set and collation to use.\n	 */\n	public function determine_charset( $charset, $collate ) {\n		if ( ( $this-&gt;use_mysqli &amp;&amp; ! ( $this-&gt;dbh instanceof mysqli ) ) || empty( $this-&gt;dbh ) ) {\n			return compact( \'charset\', \'collate\' );\n		}\n\n		if ( \'utf8\' === $charset &amp;&amp; $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8mb4\';\n		}\n\n		if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8\';\n			$collate = str_replace( \'utf8mb4_\', \'utf8_\', $collate );\n		}\n\n		if ( \'utf8mb4\' === $charset ) {\n			// _general_ is outdated, so we can upgrade it to _unicode_, instead.\n			if ( ! $collate || \'utf8_general_ci\' === $collate ) {\n				$collate = \'utf8mb4_unicode_ci\';\n			} else {\n				$collate = str_replace( \'utf8_\', \'utf8mb4_\', $collate );\n			}\n		}\n\n		// _unicode_520_ is a better collation, we should use that when it\'s available.\n		if ( $this-&gt;has_cap( \'utf8mb4_520\' ) &amp;&amp; \'utf8mb4_unicode_ci\' === $collate ) {\n			$collate = \'utf8mb4_unicode_520_ci\';\n		}\n\n		return compact( \'charset\', \'collate\' );\n	}\n\n	/**\n	 * 接続の文字セットを設定します。\n	 *\n	 * @since 3.1.0\n	 *\n	 * @param resource $dbh     The resource given by mysql_connect\n	 * @param string   $charset Optional. The character set. Default null.\n	 * @param string   $collate Optional. The collation. Default null.\n	 */\n	public function set_charset( $dbh, $charset = null, $collate = null ) {\n		if ( ! isset( $charset ) ) {\n			$charset = $this-&gt;charset;\n		}\n		if ( ! isset( $collate ) ) {\n			$collate = $this-&gt;collate;\n		}\n		if ( $this-&gt;has_cap( \'collation\' ) &amp;&amp; ! empty( $charset ) ) {\n			$set_charset_succeeded = true;\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( function_exists( \'mysqli_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysqli_set_charset( $dbh, $charset );\n				}\n\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysqli_query( $dbh, $query );\n				}\n			} else {\n				if ( function_exists( \'mysql_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysql_set_charset( $charset, $dbh );\n				}\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysql_query( $query, $dbh );\n				}\n			}\n		}\n	}\n\n	/**\n	 * 現在のSQLモードを変更し、そのWordPress互換性を確認してください。\n	 *\n	 * If no modes are passed, it will ensure the current MySQL server\n	 * modes are compatible.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param array $modes Optional. A list of SQL modes to set.\n	 */\n	public function set_sql_mode( $modes = array() ) {\n		if ( empty( $modes ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$res = mysqli_query( $this-&gt;dbh, \'SELECT @@SESSION.sql_mode\' );\n			} else {\n				$res = mysql_query( \'SELECT @@SESSION.sql_mode\', $this-&gt;dbh );\n			}\n\n			if ( empty( $res ) ) {\n				return;\n			}\n\n			if ( $this-&gt;use_mysqli ) {\n				$modes_array = mysqli_fetch_array( $res );\n				if ( empty( $modes_array[0] ) ) {\n					return;\n				}\n				$modes_str = $modes_array[0];\n			} else {\n				$modes_str = mysql_result( $res, 0 );\n			}\n\n			if ( empty( $modes_str ) ) {\n				return;\n			}\n\n			$modes = explode( \',\', $modes_str );\n		}\n\n		$modes = array_change_key_case( $modes, CASE_UPPER );\n\n		/**\n		 * Filters the list of incompatible SQL modes to exclude.\n		 *\n		 * @since 3.9.0\n		 *\n		 * @param array $incompatible_modes An array of incompatible modes.\n		 */\n		$incompatible_modes = (array) apply_filters( \'incompatible_sql_modes\', $this-&gt;incompatible_modes );\n\n		foreach ( $modes as $i =&gt; $mode ) {\n			if ( in_array( $mode, $incompatible_modes ) ) {\n				unset( $modes[ $i ] );\n			}\n		}\n\n		$modes_str = implode( \',\', $modes );\n\n		if ( $this-&gt;use_mysqli ) {\n			mysqli_query( $this-&gt;dbh, \"SET SESSION sql_mode=\'$modes_str\'\" );\n		} else {\n			mysql_query( \"SET SESSION sql_mode=\'$modes_str\'\", $this-&gt;dbh );\n		}\n	}\n\n	/**\n	 * WordPressテーブルのテーブルプレフィックスを設定します。\n	 *\n	 * @since 2.5.0\n	 *\n	 * @param string $prefix          Alphanumeric name for the new prefix.\n	 * @param bool   $set_table_names Optional. Whether the table names, e.g. wpdb::$posts, should be updated or not.\n	 * @return string|WP_Error Old prefix or WP_Error on error\n	 */\n	public function set_prefix( $prefix, $set_table_names = true ) {\n\n		if ( preg_match( \'|[^a-z0-9_]|i\', $prefix ) ) {\n			return new WP_Error( \'invalid_db_prefix\', \'Invalid database prefix\' );\n		}\n\n		$old_prefix = is_multisite() ? \'\' : $prefix;\n\n		if ( isset( $this-&gt;base_prefix ) ) {\n			$old_prefix = $this-&gt;base_prefix;\n		}\n\n		$this-&gt;base_prefix = $prefix;\n\n		if ( $set_table_names ) {\n			foreach ( $this-&gt;tables( \'global\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			if ( is_multisite() &amp;&amp; empty( $this-&gt;blogid ) ) {\n				return $old_prefix;\n			}\n\n			$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n			foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n		}\n		return $old_prefix;\n	}\n\n	/**\n	 * ブログIDを設定する\n	 *\n	 * @since 3.0.0\n	 *\n	 * @param int $blog_id\n	 * @param int $network_id Optional.\n	 * @return int previous blog id\n	 */\n	public function set_blog_id( $blog_id, $network_id = 0 ) {\n		if ( ! empty( $network_id ) ) {\n			$this-&gt;siteid = $network_id;\n		}\n\n		$old_blog_id  = $this-&gt;blogid;\n		$this-&gt;blogid = $blog_id;\n\n		$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n		foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		return $old_blog_id;\n	}\n\n	/**\n	 * Gets blog prefix.\n	 *\n	 * @since 3.0.0\n	 * @param int $blog_id Optional.\n	 * @return string Blog prefix.\n	 */\n	public function get_blog_prefix( $blog_id = null ) {\n		if ( is_multisite() ) {\n			if ( null === $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_id = (int) $blog_id;\n			if ( defined( \'MULTISITE\' ) &amp;&amp; ( 0 == $blog_id || 1 == $blog_id ) ) {\n				return $this-&gt;base_prefix;\n			} else {\n				return $this-&gt;base_prefix . $blog_id . \'_\';\n			}\n		} else {\n			return $this-&gt;base_prefix;\n		}\n	}\n\n	/**\n	 * WordPressテーブルの配列を返します。\n	 *\n	 * またCUSTOM_USER_TABLEとCUSTOM_USER_META_TABLEがWordPressユーザーと\n	 * usermetaテーブルを上書きすることを可能にします。そうでなければプレフィックスによって決定されます。\n	 *\n	 * scope引数は、以下のいずれかを取ります。\n	 *\n	 * \'all\' - \'all\'および \'global\'テーブルを返します。古いテーブルは返されません。\n	 * \'blog\' - 照会されたブログのブログレベルのテーブルを返します。\n	 * \'global\'インストール用のグローバルテーブルを返します。マルチサイトを実行している場合にのみマルチサイトテーブルを返します。\n	 * \'ms_global\' - 現在のインストールがマルチサイトかどうかにかかわらず、マルチサイトグローバルテーブルを返します。\n	 * \'old\' - 廃止予定のテーブルを返します。\n	 *\n	 * @since 3.0.0\n	 * @uses wpdb::$tables\n	 * @uses wpdb::$old_tables\n	 * @uses wpdb::$global_tables\n	 * @uses wpdb::$ms_global_tables\n	 *\n	 * @param string $scope  オプションです。 all、global、ms_global、blog、または古いテーブルにすることができます。デフォルトはallです。\n	 * @param bool   $ prefixオプション。テーブルプレフィックスを含めるかどうか。ブログならデフォルトはtrueです。\n	 * 接頭辞が要求されると、カスタムユーザーとusermetaテーブルがマッピングされます。\n	 * @param int    $blog_id Optional. The blog_id to prefix. Defaults to wpdb::$blogid. Used only when prefix is requested.\n	 * @return array Table names. When a prefix is requested, the key is the unprefixed table name.\n	 */\n	public function tables( $scope = \'all\', $prefix = true, $blog_id = 0 ) {\n		switch ( $scope ) {\n			case \'all\':\n				$tables = array_merge( $this-&gt;global_tables, $this-&gt;tables );\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'blog\':\n				$tables = $this-&gt;tables;\n				break;\n			case \'global\':\n				$tables = $this-&gt;global_tables;\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'ms_global\':\n				$tables = $this-&gt;ms_global_tables;\n				break;\n			case \'old\':\n				$tables = $this-&gt;old_tables;\n				break;\n			default:\n				return array();\n		}\n\n		if ( $prefix ) {\n			if ( ! $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_prefix   = $this-&gt;get_blog_prefix( $blog_id );\n			$base_prefix   = $this-&gt;base_prefix;\n			$global_tables = array_merge( $this-&gt;global_tables, $this-&gt;ms_global_tables );\n			foreach ( $tables as $k =&gt; $table ) {\n				if ( in_array( $table, $global_tables ) ) {\n					$tables[ $table ] = $base_prefix . $table;\n				} else {\n					$tables[ $table ] = $blog_prefix . $table;\n				}\n				unset( $tables[ $k ] );\n			}\n\n			if ( isset( $tables[\'users\'] ) &amp;&amp; defined( \'CUSTOM_USER_TABLE\' ) ) {\n				$tables[\'users\'] = CUSTOM_USER_TABLE;\n			}\n\n			if ( isset( $tables[\'usermeta\'] ) &amp;&amp; defined( \'CUSTOM_USER_META_TABLE\' ) ) {\n				$tables[\'usermeta\'] = CUSTOM_USER_META_TABLE;\n			}\n		}\n\n		return $tables;\n	}\n\n	/**\n	 * 現在のデータベース接続を使用してデータベースを選択します。\n	 *\n	 * データベース名は現在のデータベース接続に基づいて変更されます。\n	 * 失敗すると、実行は停止し、DBエラーを表示します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string        $db  MySQL database name\n	 * @param resource|null $dbh Optional link identifier.\n	 */\n	public function select( $db, $dbh = null ) {\n		if ( is_null( $dbh ) ) {\n			$dbh = $this-&gt;dbh;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$success = mysqli_select_db( $dbh, $db );\n		} else {\n			$success = mysql_select_db( $db, $dbh );\n		}\n		if ( ! $success ) {\n			$this-&gt;ready = false;\n			if ( ! did_action( \'template_redirect\' ) ) {\n				wp_load_translations_early();\n\n				$message = \'&lt;h1&gt;\' . __( \'Can&amp;#8217;t select database\' ) . \"&lt;/h1&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'We were able to connect to the database server (which means your username and password is okay) but not able to select the %s database.\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/p&gt;\\n\";\n\n				$message .= \"&lt;ul&gt;\\n\";\n				$message .= \'&lt;li&gt;\' . __( \'Are you sure it exists?\' ) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: 1: database user, 2: database name */\n					__( \'Does the user %1$s have permission to use the %2$s database?\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbuser, ENT_QUOTES ) . \'&lt;/code&gt;\',\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'On some systems the name of your database is prefixed with your username, so it would be like &lt;code&gt;username_%1$s&lt;/code&gt;. Could that be the problem?\' ),\n					htmlspecialchars( $db, ENT_QUOTES )\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \"&lt;/ul&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: support forums URL */\n					__( \'If you don&amp;#8217;t know how to set up a database you should &lt;strong&gt;contact your host&lt;/strong&gt;. If all else fails you may find help at the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n					__( \'https://wordpress.org/support/\' )\n				) . \"&lt;/p&gt;\\n\";\n\n				$this-&gt;bail( $message, \'db_select_fail\' );\n			}\n		}\n	}\n\n	/**\n	 * 使用しないでください、廃止予定です。\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 2.8.0\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare\n	 * @see esc_sql()\n	 *\n	 * @param string $string\n	 * @return string\n	 */\n	function _weak_escape( $string ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		return addslashes( $string );\n	}\n\n	/**\n	 * Real escape, using mysqli_real_escape_string() or mysql_real_escape_string()\n	 *\n	 * @see mysqli_real_escape_string()\n	 * @see mysql_real_escape_string()\n	 * @since 2.8.0\n	 *\n	 * @param  string $string to escape\n	 * @return string escaped\n	 */\n	function _real_escape( $string ) {\n		if ( $this-&gt;dbh ) {\n			if ( $this-&gt;use_mysqli ) {\n				$escaped = mysqli_real_escape_string( $this-&gt;dbh, $string );\n			} else {\n				$escaped = mysql_real_escape_string( $string, $this-&gt;dbh );\n			}\n		} else {\n			$class = get_class( $this );\n			if ( function_exists( \'__\' ) ) {\n				/* translators: %s: database access abstraction class, usually wpdb or a class extending wpdb */\n				_doing_it_wrong( $class, sprintf( __( \'%s must set a database connection for use with escaping.\' ), $class ), \'3.6.0\' );\n			} else {\n				_doing_it_wrong( $class, sprintf( \'%s must set a database connection for use with escaping.\', $class ), \'3.6.0\' );\n			}\n			$escaped = addslashes( $string );\n		}\n\n		return $this-&gt;add_placeholder_escape( $escaped );\n	}\n\n	/**\n	 * Escape data. Works on arrays.\n	 *\n	 * @uses wpdb::_real_escape()\n	 * @since  2.8.0\n	 *\n	 * @param  string|array $data\n	 * @return string|array escaped\n	 */\n	public function _escape( $data ) {\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;_escape( $v );\n				} else {\n					$data[ $k ] = $this-&gt;_real_escape( $v );\n				}\n			}\n		} else {\n			$data = $this-&gt;_real_escape( $data );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Do not use, deprecated.\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 0.71\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare()\n	 * @see esc_sql()\n	 *\n	 * @param mixed $data\n	 * @return mixed\n	 */\n	public function escape( $data ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;escape( $v, \'recursive\' );\n				} else {\n					$data[ $k ] = $this-&gt;_weak_escape( $v, \'internal\' );\n				}\n			}\n		} else {\n			$data = $this-&gt;_weak_escape( $data, \'internal\' );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Escapes content by reference for insertion into the database, for security\n	 *\n	 * @uses wpdb::_real_escape()\n	 *\n	 * @since 2.3.0\n	 *\n	 * @param string $string to escape\n	 */\n	public function escape_by_ref( &amp;$string ) {\n		if ( ! is_float( $string ) ) {\n			$string = $this-&gt;_real_escape( $string );\n		}\n	}\n\n	/**\n	 * 安全に実行できるようにSQLクエリを準備します。sprintf（）に似た構文を使用。\n	 *\n	 * クエリ文字列では、次のプレースホルダを使用できます。\n	 *   %d (integer)数字\n	 *   %f (float)\n	 *   %s (string)　文字列\n	 *\n	 * すべてのプレースホルダは、クエリ文字列では引用符で囲まないでおく必要があります。各プレースホルダーに対応する引数を渡す必要があります。\n	 *\n	 * 古い振る舞いとの互換性のために、番号付きまたはフォーマットされた文字列プレースホルダー（例えば、％1 $ s、％5s）は引用符を含みません\n	 * この関数によって追加されたので、あなたの使用法のためにそれらを囲む適切な引用符で渡されるべきです。\n	 *\n	 * エリ文字列内のリテラルパーセント記号（％）は、%%として記述する必要があります。 （たとえばLIKE構文で使用するため）\n	 * ワイルドカードパーセンテージは、完全なLIKE文字列を含む置換引数を介して渡す必要があります。\n	 * これらは、クエリ文字列に直接挿入することはできません。  {@see wpdb :: esc_like（）}もご覧ください。\n	 *\n	 * 引数は、メソッドへの個々の引数として渡すことも、すべての引数を含む単一の配列として渡すこともできます。\n	 * この2つの組み合わせはサポートされていません。\n	 *\n	 * 例えば\n	 *     $wpdb-&gt;prepare( \"SELECT * FROM `table` WHERE `column` = %s AND `field` = %d OR `other_field` LIKE %s\", array( \'foo\', 37, \'%bar\' ) );\n	 *     $wpdb-&gt;prepare( \"SELECT DATE_FORMAT(`field`, \'%%c\') FROM `table` WHERE `column` = %s\", \'foo\' );\n	 *\n	 * @link https://secure.php.net/sprintf Description of syntax.\n	 * @since 2.3.0\n	 *\n	 * @param string      $query    Query statement with sprintf()-like placeholders\n	 * @param array|mixed $args     The array of variables to substitute into the query\'s placeholders if being called with an array of arguments,\n	 *       or the first variable to substitute into the query\'s placeholders if being called with individual arguments.\n	 * @param mixed       $args,... further variables to substitute into the query\'s placeholders if being called wih individual arguments.\n	 * @return string|void Sanitized query string, if there is a query to prepare.\n	 */\n	public function prepare( $query, $args ) {\n		if ( is_null( $query ) ) {\n			return;\n		}\n\n		// これは絶対に確実というわけではないが明らかに誤った用法を捕らえるでしょう.\n		if ( strpos( $query, \'%\' ) === false ) {\n			wp_load_translations_early();\n			_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'The query argument of %s must have a placeholder.\' ), \'wpdb::prepare()\' ), \'3.9.0\' );\n		}\n\n		$args = func_get_args();\n		array_shift( $args );\n\n		// 引数が（vsprintfのように）配列として渡された場合は、それらを上に移動します。\n		$passed_as_array = false;\n		if ( is_array( $args[0] ) &amp;&amp; count( $args ) == 1 ) {\n			$passed_as_array = true;\n			$args            = $args[0];\n		}\n\n		foreach ( $args as $arg ) {\n			if ( ! is_scalar( $arg ) &amp;&amp; ! is_null( $arg ) ) {\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'Unsupported value type (%s).\' ), gettype( $arg ) ), \'4.8.2\' );\n			}\n		}\n\n		/*\n		 * プレースホルダで許可されている書式設定を指定します。以下が許可されています。\n		 *\n		 * - Sign specifier. eg, $+d\n		 * - Numbered placeholders. eg, %1$s\n		 * - Padding specifier, including custom padding characters. eg, %05s, %\'#5s\n		 * - Alignment specifier. eg, %05-s\n		 * - Precision specifier. eg, %.2f\n		 */\n		$allowed_format = \'(?:[1-9][0-9]*[$])?[-+0-9]*(?: |0|\\\'.)?[-+0-9]*(?:\\.[0-9]+)?\';\n\n		/*\n		 * ％sプレースホルダの周囲に引用符が既にある場合は、既存の引用符を削除してそれらを再挿入\n		 * すると、引用符の整合性が保証されます。\n		 *\n		 * 下位互換性のために、これは％sにのみ適用され、長い文字列の途中で頻繁に使用される％1 $ sなどのプレースホルダ、またはテーブル名プレースホルダには適用されません。\n		 */\n		$query = str_replace( \"\'%s\'\", \'%s\', $query ); // 既存の一重引用符を削除します。\n		$query = str_replace( \'\"%s\"\', \'%s\', $query ); // 既存の二重引用符を削除します。\n\n		// %% sのようなエスケープ文字列を避けて、文字列を引用符で囲みます。\n		$query = preg_replace( \'/(?&lt;!%)%s/\', \"\'%s\'\", $query );\n\n		 // フロートをロケールに気付かないようにします。\n		$query = preg_replace( \"/(?&lt;!%)(%($allowed_format)?f)/\", \'%\\\\2F\', $query ); \n\n		$query = preg_replace( \"/%(?:%|$|(?!($allowed_format)?[sdF]))/\", \'%%\\\\1\', $query ); // エスケープされていないパーセントをエスケープします。\n\n		// クエリ内の有効なプレースホルダの数を数えます。\n		$placeholders = preg_match_all( \"/(^|[^%]|(%%)+)%($allowed_format)?[sdF]/\", $query, $matches );\n\n		if ( count( $args ) !== $placeholders ) {\n			if ( 1 === $placeholders &amp;&amp; $passed_as_array ) {\n				// If the passed query only expected one argument, but the wrong number of arguments were sent as an array, bail.\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', __( \'The query only expected one placeholder, but an array of multiple placeholders was sent.\' ), \'4.9.0\' );\n\n				return;\n			} else {\n				/*\n				 * 適切な数のプレースホルダがなくても、それらが個別の引数として渡された場合、\n				 * または配列内に複数の引数があることが予想される場合は、警告をスローします。\n				 */\n				wp_load_translations_early();\n				_doing_it_wrong(\n					\'wpdb::prepare\',\n					/* translators: 1: number of placeholders, 2: number of arguments passed */\n					sprintf(\n						__( \'The query does not contain the correct number of placeholders (%1$d) for the number of arguments passed (%2$d).\' ),\n						$placeholders,\n						count( $args )\n					),\n					\'4.8.3\'\n				);\n			}\n		}\n\n		array_walk( $args, array( $this, \'escape_by_ref\' ) );\n		$query = @vsprintf( $query, $args );\n\n		return $this-&gt;add_placeholder_escape( $query );\n	}\n\n	/**\n	 * MySQLの準備の前にLIKE特殊文字％と_をエスケープする前半。\n	 *\n	 * これはwpdb ::prepare（）またはesc_sql（）の前にのみ使用してください。順序を逆にすると、セキュリティが非常に悪くなります。\n	 *\n	 * 準備済みステートメントの例：\n	 *\n	 *     $wild = \'%\';\n	 *     $find = \'only 43% of planets\';\n	 *     $like = $wild . $wpdb-&gt;esc_like( $find ) . $wild;\n	 *     $sql  = $wpdb-&gt;prepare( \"SELECT * FROM $wpdb-&gt;posts WHERE post_content LIKE %s\", $like );\n	 *\n	 * Example Escape Chain:\n	 *\n	 *     $sql  = esc_sql( $wpdb-&gt;esc_like( $input ) );\n	 *\n	 * @since 4.0.0\n	 *\n	 * @param string $text The raw text to be escaped. The input typed by the user should have no\n	 *                     extra or deleted slashes.\n	 * @return string Text in the form of a LIKE phrase. The output is not SQL safe. Call $wpdb::prepare()\n	 *                or real_escape next.\n	 */\n	public function esc_like( $text ) {\n		return addcslashes( $text, \'_%\\\\\' );\n	}\n\n	/**\n	 * Print SQL/DB error.\n	 *\n	 * @since 0.71\n	 * @global array $EZSQL_ERROR Stores error information of query and error string\n	 *\n	 * @param string $str The error to display\n	 * @return false|void False if the showing of errors is disabled.\n	 */\n	public function print_error( $str = \'\' ) {\n		global $EZSQL_ERROR;\n\n		if ( ! $str ) {\n			if ( $this-&gt;use_mysqli ) {\n				$str = mysqli_error( $this-&gt;dbh );\n			} else {\n				$str = mysql_error( $this-&gt;dbh );\n			}\n		}\n		$EZSQL_ERROR[] = array(\n			\'query\'     =&gt; $this-&gt;last_query,\n			\'error_str\' =&gt; $str,\n		);\n\n		if ( $this-&gt;suppress_errors ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		if ( $caller = $this-&gt;get_caller() ) {\n			/* translators: 1: Database error message, 2: SQL query, 3: Name of the calling function */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s made by %3$s\' ), $str, $this-&gt;last_query, $caller );\n		} else {\n			/* translators: 1: Database error message, 2: SQL query */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s\' ), $str, $this-&gt;last_query );\n		}\n\n		error_log( $error_str );\n\n		// Are we showing errors?\n		if ( ! $this-&gt;show_errors ) {\n			return false;\n		}\n\n		// If there is an error then take note of it\n		if ( is_multisite() ) {\n			$msg = sprintf(\n				\"%s [%s]\\n%s\\n\",\n				__( \'WordPress database error:\' ),\n				$str,\n				$this-&gt;last_query\n			);\n\n			if ( defined( \'ERRORLOGFILE\' ) ) {\n				error_log( $msg, 3, ERRORLOGFILE );\n			}\n			if ( defined( \'DIEONDBERROR\' ) ) {\n				wp_die( $msg );\n			}\n		} else {\n			$str   = htmlspecialchars( $str, ENT_QUOTES );\n			$query = htmlspecialchars( $this-&gt;last_query, ENT_QUOTES );\n\n			printf(\n				\'&lt;div id=\"error\"&gt;&lt;p class=\"wpdberror\"&gt;&lt;strong&gt;%s&lt;/strong&gt; [%s]&lt;br /&gt;&lt;code&gt;%s&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;\',\n				__( \'WordPress database error:\' ),\n				$str,\n				$query\n			);\n		}\n	}\n\n	/**\n	 * データベースエラーの表示を有効にします。\n	 *\n	 * この機能はエラーの表示を可能にするためだけに使用されるべきです。\n	 * wpdb::hide_errors() should be used instead for hiding of errors. However,\n	 * this function can be used to enable and disable showing of database\n	 * errors.\n	 *\n	 * @since 0.71\n	 * @see wpdb::hide_errors()\n	 *\n	 * @param bool $show Whether to show or hide errors\n	 * @return bool Old value for showing errors.\n	 */\n	public function show_errors( $show = true ) {\n		$errors            = $this-&gt;show_errors;\n		$this-&gt;show_errors = $show;\n		return $errors;\n	}\n\n	/**\n	 * Disables showing of database errors.\n	 *\n	 * By default database errors are not shown.\n	 *\n	 * @since 0.71\n	 * @see wpdb::show_errors()\n	 *\n	 * @return bool Whether showing of errors was active\n	 */\n	public function hide_errors() {\n		$show              = $this-&gt;show_errors;\n		$this-&gt;show_errors = false;\n		return $show;\n	}\n\n	/**\n	 * Whether to suppress database errors.\n	 *\n	 * By default database errors are suppressed, with a simple\n	 * call to this function they can be enabled.\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::hide_errors()\n	 * @param bool $suppress Optional. New value. Defaults to true.\n	 * @return bool Old value\n	 */\n	public function suppress_errors( $suppress = true ) {\n		$errors                = $this-&gt;suppress_errors;\n		$this-&gt;suppress_errors = (bool) $suppress;\n		return $errors;\n	}\n\n	/**\n	 * Kill cached query results.\n	 *\n	 * @since 0.71\n	 */\n	public function flush() {\n		$this-&gt;last_result   = array();\n		$this-&gt;col_info      = null;\n		$this-&gt;last_query    = null;\n		$this-&gt;rows_affected = $this-&gt;num_rows = 0;\n		$this-&gt;last_error    = \'\';\n\n		if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n			mysqli_free_result( $this-&gt;result );\n			$this-&gt;result = null;\n\n			// Sanity check before using the handle\n			if ( empty( $this-&gt;dbh ) || ! ( $this-&gt;dbh instanceof mysqli ) ) {\n				return;\n			}\n\n			// Clear out any results from a multi-query\n			while ( mysqli_more_results( $this-&gt;dbh ) ) {\n				mysqli_next_result( $this-&gt;dbh );\n			}\n		} elseif ( is_resource( $this-&gt;result ) ) {\n			mysql_free_result( $this-&gt;result );\n		}\n	}\n\n	/**\n	 * データベースに接続して選択します。\n	 *\n	 * $ allow_bailがfalseの場合、データベース接続の欠如は手動で処理する必要があります。.\n	 *\n	 * @since 3.0.0\n	 * @since 3.9.0 $allow_bail parameter added.\n	 *\n	 * @param bool $ allow_bailオプション。機能を保釈することを許可します。デフォルトはtrueです。\n	 * @return 成功した場合はtrue、失敗した場合はfalse。\n	 */\n	public function db_connect( $allow_bail = true ) {\n		$this-&gt;is_mysql = true;\n\n		/*\n		 * MySQLiを使用している場合は3.9以降では非推奨です。同等のものはありません\n		 * mysqli_ *関数には$ new_linkパラメータがあります。\n		 */\n		$new_link     = defined( \'MYSQL_NEW_LINK\' ) ? MYSQL_NEW_LINK : true;\n		$client_flags = defined( \'MYSQL_CLIENT_FLAGS\' ) ? MYSQL_CLIENT_FLAGS : 0;\n\n		if ( $this-&gt;use_mysqli ) {\n			$this-&gt;dbh = mysqli_init();\n\n			$host    = $this-&gt;dbhost;\n			$port    = null;\n			$socket  = null;\n			$is_ipv6 = false;\n\n			if ( $host_data = $this-&gt;parse_db_host( $this-&gt;dbhost ) ) {\n				list( $host, $port, $socket, $is_ipv6 ) = $host_data;\n			}\n\n			/*\n			 * If using the `mysqlnd` library, the IPv6 address needs to be\n			 * enclosed in square brackets, whereas it doesn\'t while using the\n			 * `libmysqlclient` library.\n			 * @see https://bugs.php.net/bug.php?id=67563\n			 */\n			if ( $is_ipv6 &amp;&amp; extension_loaded( \'mysqlnd\' ) ) {\n				$host = \"[$host]\";\n			}\n\n			if ( WP_DEBUG ) {\n				mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			} else {\n				@mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			}\n\n			if ( $this-&gt;dbh-&gt;connect_errno ) {\n				$this-&gt;dbh = null;\n\n				/*\n				 * ext / mysqliの設定が間違っている可能性があります。以下の場合、ext / mysqlにフォールバックしてください。\n				  *  - We haven\'t previously connected, and\n				  *  - WP_USE_EXT_MYSQL isn\'t set to false, and\n				  *  - ext/mysql is loaded.\n				  */\n				$attempt_fallback = true;\n\n				if ( $this-&gt;has_connected ) {\n					$attempt_fallback = false;\n				} elseif ( defined( \'WP_USE_EXT_MYSQL\' ) &amp;&amp; ! WP_USE_EXT_MYSQL ) {\n					$attempt_fallback = false;\n				} elseif ( ! function_exists( \'mysql_connect\' ) ) {\n					$attempt_fallback = false;\n				}\n\n				if ( $attempt_fallback ) {\n					$this-&gt;use_mysqli = false;\n					return $this-&gt;db_connect( $allow_bail );\n				}\n			}\n		} else {\n			if ( WP_DEBUG ) {\n				$this-&gt;dbh = mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			} else {\n				$this-&gt;dbh = @mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			}\n		}\n\n		if ( ! $this-&gt;dbh &amp;&amp; $allow_bail ) {\n			wp_load_translations_early();\n\n			// Load custom DB error template, if present.\n			if ( file_exists( WP_CONTENT_DIR . \'/db-error.php\' ) ) {\n				require_once( WP_CONTENT_DIR . \'/db-error.php\' );\n				die();\n			}\n\n			$message = \'&lt;h1&gt;\' . __( \'Error establishing a database connection\' ) . \"&lt;/h1&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: 1: wp-config.php, 2: database host */\n				__( \'This either means that the username and password information in your %1$s file is incorrect or we can&amp;#8217;t contact the database server at %2$s. This could mean your host&amp;#8217;s database server is down.\' ),\n				\'&lt;code&gt;wp-config.php&lt;/code&gt;\',\n				\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n			) . \"&lt;/p&gt;\\n\";\n\n			$message .= \"&lt;ul&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure you have the correct username and password?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that you have typed the correct hostname?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \"&lt;/ul&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: %s: support forums URL */\n				__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n				__( \'https://wordpress.org/support/\' )\n			) . \"&lt;/p&gt;\\n\";\n\n			$this-&gt;bail( $message, \'db_connect_fail\' );\n\n			return false;\n		} elseif ( $this-&gt;dbh ) {\n			if ( ! $this-&gt;has_connected ) {\n				$this-&gt;init_charset();\n			}\n\n			$this-&gt;has_connected = true;\n\n			$this-&gt;set_charset( $this-&gt;dbh );\n\n			$this-&gt;ready = true;\n			$this-&gt;set_sql_mode();\n			$this-&gt;select( $this-&gt;dbname, $this-&gt;dbh );\n\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Parse the DB_HOST setting to interpret it for mysqli_real_connect.\n	 *\n	 * mysqli_real_connect doesn\'t support the host param including a port or\n	 * socket like mysql_connect does. This duplicates how mysql_connect detects\n	 * a port and/or socket file.\n	 *\n	 * @since 4.9.0\n	 *\n	 * @param string $host The DB_HOST setting to parse.\n	 * @return array|bool Array containing the host, the port, the socket and whether\n	 *                    it is an IPv6 address, in that order. If $host couldn\'t be parsed,\n	 *                    returns false.\n	 */\n	public function parse_db_host( $host ) {\n		$port    = null;\n		$socket  = null;\n		$is_ipv6 = false;\n\n		// First peel off the socket parameter from the right, if it exists.\n		$socket_pos = strpos( $host, \':/\' );\n		if ( $socket_pos !== false ) {\n			$socket = substr( $host, $socket_pos + 1 );\n			$host   = substr( $host, 0, $socket_pos );\n		}\n\n		// We need to check for an IPv6 address first.\n		// An IPv6 address will always contain at least two colons.\n		if ( substr_count( $host, \':\' ) &gt; 1 ) {\n			$pattern = \'#^(?:\\[)?(?P&lt;host&gt;[0-9a-fA-F:]+)(?:\\]:(?P&lt;port&gt;[\\d]+))?#\';\n			$is_ipv6 = true;\n		} else {\n			// We seem to be dealing with an IPv4 address.\n			$pattern = \'#^(?P&lt;host&gt;[^:/]*)(?::(?P&lt;port&gt;[\\d]+))?#\';\n		}\n\n		$matches = array();\n		$result  = preg_match( $pattern, $host, $matches );\n\n		if ( 1 !== $result ) {\n			// Couldn\'t parse the address, bail.\n			return false;\n		}\n\n		$host = \'\';\n		foreach ( array( \'host\', \'port\' ) as $component ) {\n			if ( ! empty( $matches[ $component ] ) ) {\n				$$component = $matches[ $component ];\n			}\n		}\n\n		return array( $host, $port, $socket, $is_ipv6 );\n	}\n\n	/**\n	 * Checks that the connection to the database is still up. If not, try to reconnect.\n	 *\n	 * If this function is unable to reconnect, it will forcibly die, or if after the\n	 * the {@see \'template_redirect\'} hook has been fired, return false instead.\n	 *\n	 * If $allow_bail is false, the lack of database connection will need\n	 * to be handled manually.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param bool $allow_bail Optional. Allows the function to bail. Default true.\n	 * @return bool|void True if the connection is up.\n	 */\n	public function check_connection( $allow_bail = true ) {\n		if ( $this-&gt;use_mysqli ) {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysqli_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		} else {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysql_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		}\n\n		$error_reporting = false;\n\n		// Disable warnings, as we don\'t want to see a multitude of \"unable to connect\" messages\n		if ( WP_DEBUG ) {\n			$error_reporting = error_reporting();\n			error_reporting( $error_reporting &amp; ~E_WARNING );\n		}\n\n		for ( $tries = 1; $tries &lt;= $this-&gt;reconnect_retries; $tries++ ) {\n			// On the last try, re-enable warnings. We want to see a single instance of the\n			// \"unable to connect\" message on the bail() screen, if it appears.\n			if ( $this-&gt;reconnect_retries === $tries &amp;&amp; WP_DEBUG ) {\n				error_reporting( $error_reporting );\n			}\n\n			if ( $this-&gt;db_connect( false ) ) {\n				if ( $error_reporting ) {\n					error_reporting( $error_reporting );\n				}\n\n				return true;\n			}\n\n			sleep( 1 );\n		}\n\n		// If template_redirect has already happened, it\'s too late for wp_die()/dead_db().\n		// Let\'s just return and hope for the best.\n		if ( did_action( \'template_redirect\' ) ) {\n			return false;\n		}\n\n		if ( ! $allow_bail ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		$message = \'&lt;h1&gt;\' . __( \'Error reconnecting to the database\' ) . \"&lt;/h1&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: database host */\n			__( \'This means that we lost contact with the database server at %s. This could mean your host&amp;#8217;s database server is down.\' ),\n			\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n		) . \"&lt;/p&gt;\\n\";\n\n		$message .= \"&lt;ul&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is not under particularly heavy load?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \"&lt;/ul&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: support forums URL */\n			__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n			__( \'https://wordpress.org/support/\' )\n		) . \"&lt;/p&gt;\\n\";\n\n		// We weren\'t able to reconnect, so we better bail.\n		$this-&gt;bail( $message, \'db_connect_fail\' );\n\n		// Call dead_db() if bail didn\'t die, because this database is no more. It has ceased to be (at least temporarily).\n		dead_db();\n	}\n\n	/**\n	 * 現在のデータベース接続を使用して、MySQLデータベースクエリを実行します。\n	 *\n	 * より詳しい情報はコーデックスページにあります。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query Database query\n	 * @return int|bool Boolean true for CREATE, ALTER, TRUNCATE and DROP queries. Number of rows\n	 *                  affected/selected for all other queries. Boolean false on error.\n	 */\n	public function query( $query ) {\n		if ( ! $this-&gt;ready ) {\n			$this-&gt;check_current_query = true;\n			return false;\n		}\n\n		/**\n		 * データベースクエリをフィルタリングします。\n		 *\n		 * プラグインがロードされる前にいくつかの問い合わせが行われます。\n		 * and thus cannot be filtered with this method.\n		 *\n		 * @since 2.1.0\n		 *\n		 * @param string $query Database query.\n		 */\n		$query = apply_filters( \'query\', $query );\n\n		$this-&gt;flush();\n\n		// Log how the function was called\n		$this-&gt;func_call = \"\\$db-&gt;query(\\\"$query\\\")\";\n\n		// If we\'re writing to the database, make sure the query will write safely.\n		if ( $this-&gt;check_current_query &amp;&amp; ! $this-&gt;check_ascii( $query ) ) {\n			$stripped_query = $this-&gt;strip_invalid_text_from_query( $query );\n			// strip_invalid_text_from_query() can perform queries, so we need\n			// to flush again, just to make sure everything is clear.\n			$this-&gt;flush();\n			if ( $stripped_query !== $query ) {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		$this-&gt;check_current_query = true;\n\n		// Keep track of the last query for debug.\n		$this-&gt;last_query = $query;\n\n		$this-&gt;_do_query( $query );\n\n		// MySQL server has gone away, try to reconnect.\n		$mysql_errno = 0;\n		if ( ! empty( $this-&gt;dbh ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$mysql_errno = mysqli_errno( $this-&gt;dbh );\n				} else {\n					// $dbh is defined, but isn\'t a real connection.\n					// Something has gone horribly wrong, let\'s try a reconnect.\n					$mysql_errno = 2006;\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$mysql_errno = mysql_errno( $this-&gt;dbh );\n				} else {\n					$mysql_errno = 2006;\n				}\n			}\n		}\n\n		if ( empty( $this-&gt;dbh ) || 2006 == $mysql_errno ) {\n			if ( $this-&gt;check_connection() ) {\n				$this-&gt;_do_query( $query );\n			} else {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		// If there is an error then take note of it.\n		if ( $this-&gt;use_mysqli ) {\n			if ( $this-&gt;dbh instanceof mysqli ) {\n				$this-&gt;last_error = mysqli_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		} else {\n			if ( is_resource( $this-&gt;dbh ) ) {\n				$this-&gt;last_error = mysql_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		}\n\n		if ( $this-&gt;last_error ) {\n			// Clear insert_id on a subsequent failed insert.\n			if ( $this-&gt;insert_id &amp;&amp; preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				$this-&gt;insert_id = 0;\n			}\n\n			$this-&gt;print_error();\n			return false;\n		}\n\n		if ( preg_match( \'/^\\s*(create|alter|truncate|drop)\\s/i\', $query ) ) {\n			$return_val = $this-&gt;result;\n		} elseif ( preg_match( \'/^\\s*(insert|delete|update|replace)\\s/i\', $query ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$this-&gt;rows_affected = mysqli_affected_rows( $this-&gt;dbh );\n			} else {\n				$this-&gt;rows_affected = mysql_affected_rows( $this-&gt;dbh );\n			}\n			// Take note of the insert_id\n			if ( preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				if ( $this-&gt;use_mysqli ) {\n					$this-&gt;insert_id = mysqli_insert_id( $this-&gt;dbh );\n				} else {\n					$this-&gt;insert_id = mysql_insert_id( $this-&gt;dbh );\n				}\n			}\n			// Return number of rows affected\n			$return_val = $this-&gt;rows_affected;\n		} else {\n			$num_rows = 0;\n			if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n				while ( $row = mysqli_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			} elseif ( is_resource( $this-&gt;result ) ) {\n				while ( $row = mysql_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			}\n\n			// Log number of rows the query returned\n			// and return number of rows selected\n			$this-&gt;num_rows = $num_rows;\n			$return_val     = $num_rows;\n		}\n\n		return $return_val;\n	}\n\n	/**\n	 * Internal function to perform the mysql_query() call.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @see wpdb::query()\n	 *\n	 * @param string $query The query to run.\n	 */\n	private function _do_query( $query ) {\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;timer_start();\n		}\n\n		if ( ! empty( $this-&gt;dbh ) &amp;&amp; $this-&gt;use_mysqli ) {\n			$this-&gt;result = mysqli_query( $this-&gt;dbh, $query );\n		} elseif ( ! empty( $this-&gt;dbh ) ) {\n			$this-&gt;result = mysql_query( $query, $this-&gt;dbh );\n		}\n		$this-&gt;num_queries++;\n\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;queries[] = array(\n				$query,\n				$this-&gt;timer_stop(),\n				$this-&gt;get_caller(),\n				$this-&gt;time_start,\n			);\n		}\n	}\n\n	/**\n	 * Generates and returns a placeholder escape string for use in queries returned by ::prepare().\n	 *\n	 * @since 4.8.3\n	 *\n	 * @return string String to escape placeholders.\n	 */\n	public function placeholder_escape() {\n		static $placeholder;\n\n		if ( ! $placeholder ) {\n			// If ext/hash is not present, compat.php\'s hash_hmac() does not support sha256.\n			$algo = function_exists( \'hash\' ) ? \'sha256\' : \'sha1\';\n			// Old WP installs may not have AUTH_SALT defined.\n			$salt = defined( \'AUTH_SALT\' ) &amp;&amp; AUTH_SALT ? AUTH_SALT : (string) rand();\n\n			$placeholder = \'{\' . hash_hmac( $algo, uniqid( $salt, true ), $salt ) . \'}\';\n		}\n\n		/*\n		 * レースホルダエスケープを削除するために、フィルタを追加します。優先順位0を使用します。\n		 * そのため、このフィルタに関連付けられている他のものはすべて、プレースホルダ文字列が削除されたクエリを受け取ります\n		 */\n		if ( ! has_filter( \'query\', array( $this, \'remove_placeholder_escape\' ) ) ) {\n			add_filter( \'query\', array( $this, \'remove_placeholder_escape\' ), 0 );\n		}\n\n		return $placeholder;\n	}\n\n	/**\n	 * printf（）のプレースホルダーに似たものをエスケープするために、プレースホルダーのエスケープ文字列を追加します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query to escape.\n	 * @return string 必要に応じてプレースホルダエスケープ文字列が挿入されたクエリ。\n	 */\n	public function add_placeholder_escape( $query ) {\n		/*\n		 * 漠然とプレースホルダーに似ているものでさえも返すことを防ぐために、私たちは見つけることが\n		 * できるあらゆる％をつぶします。\n		 */\n		return str_replace( \'%\', $this-&gt;placeholder_escape(), $query );\n	}\n\n	/**\n	 * クエリからプレースホルダエスケープ文字列を削除します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query from which the placeholder will be removed.\n	 * @return string The query with the placeholder removed.\n	 */\n	public function remove_placeholder_escape( $query ) {\n		return str_replace( $this-&gt;placeholder_escape(), \'%\', $query );\n	}\n\n	/**\n	 * Insert a row into a table.\n	 *\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows inserted, or false on error.\n	 */\n	public function insert( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'INSERT\' );\n	}\n\n	/**\n	 * Replace a row into a table.\n	 *\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	public function replace( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'REPLACE\' );\n	}\n\n	/**\n	 * Helper function for insert and replace.\n	 *\n	 * Runs an insert or replace query based on $type argument.\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param string $type         Optional. What type of operation is this? INSERT or REPLACE. Defaults to INSERT.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	function _insert_replace_helper( $table, $data, $format = null, $type = \'INSERT\' ) {\n		$this-&gt;insert_id = 0;\n\n		if ( ! in_array( strtoupper( $type ), array( \'REPLACE\', \'INSERT\' ) ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$formats = $values = array();\n		foreach ( $data as $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$formats[] = \'NULL\';\n				continue;\n			}\n\n			$formats[] = $value[\'format\'];\n			$values[]  = $value[\'value\'];\n		}\n\n		$fields  = \'`\' . implode( \'`, `\', array_keys( $data ) ) . \'`\';\n		$formats = implode( \', \', $formats );\n\n		$sql = \"$type INTO `$table` ($fields) VALUES ($formats)\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Update a row in the table\n	 *\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ), array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'ID\' =&gt; 1 ), array( \'%s\', \'%d\' ), array( \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $data         Data to update (in column =&gt; value pairs).\n	 *            Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *            Sending a null value will cause the column to be set to NULL - the corresponding\n	 *            format is ignored in this case.\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $format       Optional. An array of formats to be mapped to each of the values in $data.\n	 *            If string, that format will be used for all of the values in $data.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function update( $table, $data, $where, $format = null, $where_format = null ) {\n		if ( ! is_array( $data ) || ! is_array( $where ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$fields = $conditions = $values = array();\n		foreach ( $data as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$fields[] = \"`$field` = NULL\";\n				continue;\n			}\n\n			$fields[] = \"`$field` = \" . $value[\'format\'];\n			$values[] = $value[\'value\'];\n		}\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$fields     = implode( \', \', $fields );\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"UPDATE `$table` SET $fields WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Delete a row in the table\n	 *\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ), array( \'%d\' ) )\n	 *\n	 * @since 3.4.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function delete( $table, $where, $where_format = null ) {\n		if ( ! is_array( $where ) ) {\n			return false;\n		}\n\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$conditions = $values = array();\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"DELETE FROM `$table` WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Processes arrays of field/value pairs and field formats.\n	 *\n	 * This is a helper method for wpdb\'s CRUD methods, which take field/value\n	 * pairs for inserts, updates, and where clauses. This method first pairs\n	 * each value with a format. Then it determines the charset of that field,\n	 * using that to determine if any invalid text would be stripped. If text is\n	 * stripped, then field processing is rejected and the query fails.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param array  $data   Field/value pair.\n	 * @param mixed  $format Format for each field.\n	 * @return array|false Returns an array of fields that contain paired values\n	 *                    and formats. Returns false for invalid values.\n	 */\n	protected function process_fields( $table, $data, $format ) {\n		$data = $this-&gt;process_field_formats( $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_charsets( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_lengths( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$converted_data = $this-&gt;strip_invalid_text( $data );\n\n		if ( $data !== $converted_data ) {\n			return false;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Prepares arrays of value/format pairs as passed to wpdb CRUD methods.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data   Array of fields to values.\n	 * @param mixed $format Formats to be mapped to the values in $data.\n	 * @return array Array, keyed by field names with values being an array\n	 *               of \'value\' and \'format\' keys.\n	 */\n	protected function process_field_formats( $data, $format ) {\n		$formats = $original_formats = (array) $format;\n\n		foreach ( $data as $field =&gt; $value ) {\n			$value = array(\n				\'value\'  =&gt; $value,\n				\'format\' =&gt; \'%s\',\n			);\n\n			if ( ! empty( $format ) ) {\n				$value[\'format\'] = array_shift( $formats );\n				if ( ! $value[\'format\'] ) {\n					$value[\'format\'] = reset( $original_formats );\n				}\n			} elseif ( isset( $this-&gt;field_types[ $field ] ) ) {\n				$value[\'format\'] = $this-&gt;field_types[ $field ];\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Adds field charsets to field/value/format arrays generated by\n	 * the wpdb::process_field_formats() method.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_formats() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'charset\' keys.\n	 */\n	protected function process_field_charsets( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'charset\'] = false;\n			} else {\n				$value[\'charset\'] = $this-&gt;get_col_charset( $table, $field );\n				if ( is_wp_error( $value[\'charset\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * For string fields, record the maximum string length that field can safely save.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_charsets() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'length\' keys, or false if\n	 *                     any of the values were too long for their corresponding field.\n	 */\n	protected function process_field_lengths( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'length\'] = false;\n			} else {\n				$value[\'length\'] = $this-&gt;get_col_length( $table, $field );\n				if ( is_wp_error( $value[\'length\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Retrieve one variable from the database.\n	 *\n	 * Executes a SQL query and returns the value from the SQL result.\n	 * If the SQL result contains more than one column and/or more than one row, this function returns the value in the column and row specified.\n	 * If $query is null, this function returns the value in the specified column and row from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to null, use the result from the previous query.\n	 * @param int         $x     Optional. Column of value to return. Indexed from 0.\n	 * @param int         $y     Optional. Row of value to return. Indexed from 0.\n	 * @return string|null Database query result (as string), or null on failure\n	 */\n	public function get_var( $query = null, $x = 0, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_var(\\\"$query\\\", $x, $y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		// Extract var out of cached results based x,y vals\n		if ( ! empty( $this-&gt;last_result[ $y ] ) ) {\n			$values = array_values( get_object_vars( $this-&gt;last_result[ $y ] ) );\n		}\n\n		// If there is a value return it else return null\n		return ( isset( $values[ $x ] ) &amp;&amp; $values[ $x ] !== \'\' ) ? $values[ $x ] : null;\n	}\n\n	/**\n	 * Retrieve one row from the database.\n	 *\n	 * Executes a SQL query and returns the row from the SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query  SQL query.\n	 * @param string      $output Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which correspond to\n	 *     an stdClass object, an associative array, or a numeric array, respectively. Default OBJECT.\n	 * @param int         $y      Optional. Row to return. Indexed from 0.\n	 * @return array|object|null|void Database query result in format specified by $output or null on failure\n	 */\n	public function get_row( $query = null, $output = OBJECT, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_row(\\\"$query\\\",$output,$y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		if ( ! isset( $this-&gt;last_result[ $y ] ) ) {\n			return null;\n		}\n\n		if ( $output == OBJECT ) {\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} elseif ( $output == ARRAY_A ) {\n			return $this-&gt;last_result[ $y ] ? get_object_vars( $this-&gt;last_result[ $y ] ) : null;\n		} elseif ( $output == ARRAY_N ) {\n			return $this-&gt;last_result[ $y ] ? array_values( get_object_vars( $this-&gt;last_result[ $y ] ) ) : null;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} else {\n			$this-&gt;print_error( \' $db-&gt;get_row(string query, output type, int offset) -- Output type must be one of: OBJECT, ARRAY_A, ARRAY_N\' );\n		}\n	}\n\n	/**\n	 * Retrieve one column from the database.\n	 *\n	 * Executes a SQL query and returns the column from the SQL result.\n	 * If the SQL result contains more than one column, this function returns the column specified.\n	 * If $query is null, this function returns the specified column from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to previous query.\n	 * @param int         $x     Optional. Column to return. Indexed from 0.\n	 * @return array Database query result. Array indexed from 0 by SQL result row number.\n	 */\n	public function get_col( $query = null, $x = 0 ) {\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		$new_array = array();\n		// Extract the column values\n		if ( $this-&gt;last_result ) {\n			for ( $i = 0, $j = count( $this-&gt;last_result ); $i &lt; $j; $i++ ) {\n				$new_array[ $i ] = $this-&gt;get_var( null, $x, $i );\n			}\n		}\n		return $new_array;\n	}\n\n	/**\n	 * データベースからSQL結果セット全体（つまり多数の行）を取得します。\n	 *\n	 * SQLクエリを実行し、SQL結果全体を返します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query  SQL query.\n	 * @param string $output Optional. Any of ARRAY_A | ARRAY_N | OBJECT | OBJECT_K constants.\n	 *最初の3つのうちの1つでは、SQL結果の行番号によって0からインデックスされた行の配列を返します。\n	 *各行は連想配列（column =&gt; value、...）、数値インデックス配列（0 =&gt; value、...）、またはオブジェクトです。 （ - &gt; column = value）\n	 *OBJECT_Kを使用すると、各行の最初の列の値によってキー設定された行オブジェクトの連想配列を返します。\n	 *重複したキーは破棄されます。\n	 * @return 配列|オブジェクト|null データベースクエリ結果\n	 */\n	public function get_results( $query = null, $output = OBJECT ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_results(\\\"$query\\\", $output)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		$new_array = array();\n		if ( $output == OBJECT ) {\n			// Return an integer-keyed array of row objects\n			return $this-&gt;last_result;\n		} elseif ( $output == OBJECT_K ) {\n			// Return an array of row objects with keys from column 1\n			// (Duplicates are discarded)\n			if ( $this-&gt;last_result ) {\n				foreach ( $this-&gt;last_result as $row ) {\n					$var_by_ref = get_object_vars( $row );\n					$key        = array_shift( $var_by_ref );\n					if ( ! isset( $new_array[ $key ] ) ) {\n						$new_array[ $key ] = $row;\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( $output == ARRAY_A || $output == ARRAY_N ) {\n			// Return an integer-keyed array of...\n			if ( $this-&gt;last_result ) {\n				foreach ( (array) $this-&gt;last_result as $row ) {\n					if ( $output == ARRAY_N ) {\n						// ...integer-keyed row arrays\n						$new_array[] = array_values( get_object_vars( $row ) );\n					} else {\n						// ...column name-keyed row arrays\n						$new_array[] = get_object_vars( $row );\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result;\n		}\n		return null;\n	}\n\n	/**\n	 * Retrieves the character set for the given table.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table Table name.\n	 * @return string|WP_Error Table character set, WP_Error object if it couldn\'t be found.\n	 */\n	protected function get_table_charset( $table ) {\n		$tablekey = strtolower( $table );\n\n		/**\n		 * Filters the table charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will effectively short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 */\n		$charset = apply_filters( \'pre_get_table_charset\', null, $table );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		if ( isset( $this-&gt;table_charset[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		$charsets = $columns = array();\n\n		$table_parts = explode( \'.\', $table );\n		$table       = \'`\' . implode( \'`.`\', $table_parts ) . \'`\';\n		$results     = $this-&gt;get_results( \"SHOW FULL COLUMNS FROM $table\" );\n		if ( ! $results ) {\n			return new WP_Error( \'wpdb_get_table_charset_failure\' );\n		}\n\n		foreach ( $results as $column ) {\n			$columns[ strtolower( $column-&gt;Field ) ] = $column;\n		}\n\n		$this-&gt;col_meta[ $tablekey ] = $columns;\n\n		foreach ( $columns as $column ) {\n			if ( ! empty( $column-&gt;Collation ) ) {\n				list( $charset ) = explode( \'_\', $column-&gt;Collation );\n\n				// If the current connection can\'t support utf8mb4 characters, let\'s only send 3-byte utf8 characters.\n				if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n					$charset = \'utf8\';\n				}\n\n				$charsets[ strtolower( $charset ) ] = true;\n			}\n\n			list( $type ) = explode( \'(\', $column-&gt;Type );\n\n			// A binary/blob means the whole query gets treated like this.\n			if ( in_array( strtoupper( $type ), array( \'BINARY\', \'VARBINARY\', \'TINYBLOB\', \'MEDIUMBLOB\', \'BLOB\', \'LONGBLOB\' ) ) ) {\n				$this-&gt;table_charset[ $tablekey ] = \'binary\';\n				return \'binary\';\n			}\n		}\n\n		// utf8mb3 is an alias for utf8.\n		if ( isset( $charsets[\'utf8mb3\'] ) ) {\n			$charsets[\'utf8\'] = true;\n			unset( $charsets[\'utf8mb3\'] );\n		}\n\n		// Check if we have more than one charset in play.\n		$count = count( $charsets );\n		if ( 1 === $count ) {\n			$charset = key( $charsets );\n		} elseif ( 0 === $count ) {\n			// No charsets, assume this table can store whatever.\n			$charset = false;\n		} else {\n			// More than one charset. Remove latin1 if present and recalculate.\n			unset( $charsets[\'latin1\'] );\n			$count = count( $charsets );\n			if ( 1 === $count ) {\n				// Only one charset (besides latin1).\n				$charset = key( $charsets );\n			} elseif ( 2 === $count &amp;&amp; isset( $charsets[\'utf8\'], $charsets[\'utf8mb4\'] ) ) {\n				// Two charsets, but they\'re utf8 and utf8mb4, use utf8.\n				$charset = \'utf8\';\n			} else {\n				// Two mixed character sets. ascii.\n				$charset = \'ascii\';\n			}\n		}\n\n		$this-&gt;table_charset[ $tablekey ] = $charset;\n		return $charset;\n	}\n\n	/**\n	 * Retrieves the character set for the given column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return string|false|WP_Error Column character set as a string. False if the column has no\n	 *        character set. WP_Error object if there was an error.\n	 */\n	public function get_col_charset( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		/**\n		 * Filters the column charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 * @param string $column  The name of the column being checked.\n		 */\n		$charset = apply_filters( \'pre_get_col_charset\', null, $table, $column );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;table_charset[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		// If still no column information, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// If this column doesn\'t exist, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// Return false when it\'s not a string column.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation ) ) {\n			return false;\n		}\n\n		list( $charset ) = explode( \'_\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation );\n		return $charset;\n	}\n\n	/**\n	 * Retrieve the maximum string length allowed in a given column.\n	 * The length may either be specified as a byte length or a character length.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return array|false|WP_Error array( \'length\' =&gt; (int), \'type\' =&gt; \'byte\' | \'char\' )\n	 *       false if the column has no length (for example, numeric column)\n	 *       WP_Error object if there was an error.\n	 */\n	public function get_col_length( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return false;\n		}\n\n		$typeinfo = explode( \'(\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Type );\n\n		$type = strtolower( $typeinfo[0] );\n		if ( ! empty( $typeinfo[1] ) ) {\n			$length = trim( $typeinfo[1], \')\' );\n		} else {\n			$length = false;\n		}\n\n		switch ( $type ) {\n			case \'char\':\n			case \'varchar\':\n				return array(\n					\'type\'   =&gt; \'char\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'binary\':\n			case \'varbinary\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'tinyblob\':\n			case \'tinytext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 255,        // 2^8 - 1\n				);\n\n			case \'blob\':\n			case \'text\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 65535,      // 2^16 - 1\n				);\n\n			case \'mediumblob\':\n			case \'mediumtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 167772,   // 2^24 - 1\n				);\n\n			case \'longblob\':\n			case \'longtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 4294967295, // 2^32 - 1\n				);\n\n			default:\n				return false;\n		}\n	}\n\n	/**\n	 * Check if a string is ASCII.\n	 *\n	 * The negative regex is faster for non-ASCII strings, as it allows\n	 * the search to finish as soon as it encounters a non-ASCII character.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $string String to check.\n	 * @return bool True if ASCII, false if not.\n	 */\n	protected function check_ascii( $string ) {\n		if ( function_exists( \'mb_check_encoding\' ) ) {\n			if ( mb_check_encoding( $string, \'ASCII\' ) ) {\n				return true;\n			}\n		} elseif ( ! preg_match( \'/[^\\x00-\\x7F]/\', $string ) ) {\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Check if the query is accessing a collation considered safe on the current version of MySQL.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to check.\n	 * @return bool True if the collation is safe, false if it isn\'t.\n	 */\n	protected function check_safe_collation( $query ) {\n		if ( $this-&gt;checking_collation ) {\n			return true;\n		}\n\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $query ) ) {\n			return true;\n		}\n\n		// All-ASCII queries don\'t need extra checking.\n		if ( $this-&gt;check_ascii( $query ) ) {\n			return true;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( ! $table ) {\n			return false;\n		}\n\n		$this-&gt;checking_collation = true;\n		$collation                = $this-&gt;get_table_charset( $table );\n		$this-&gt;checking_collation = false;\n\n		// Tables with no collation, or latin1 only, don\'t need extra checking.\n		if ( false === $collation || \'latin1\' === $collation ) {\n			return true;\n		}\n\n		$table = strtolower( $table );\n		if ( empty( $this-&gt;col_meta[ $table ] ) ) {\n			return false;\n		}\n\n		// If any of the columns don\'t have one of these collations, it needs more sanity checking.\n		foreach ( $this-&gt;col_meta[ $table ] as $col ) {\n			if ( empty( $col-&gt;Collation ) ) {\n				continue;\n			}\n\n			if ( ! in_array( $col-&gt;Collation, array( \'utf8_general_ci\', \'utf8_bin\', \'utf8mb4_general_ci\', \'utf8mb4_bin\' ), true ) ) {\n				return false;\n			}\n		}\n\n		return true;\n	}\n\n	/**\n	 * Strips any invalid characters based on value/charset pairs.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data Array of value arrays. Each value array has the keys\n	 *                    \'value\' and \'charset\'. An optional \'ascii\' key can be\n	 *                    set to false to avoid redundant ASCII checks.\n	 * @return array|WP_Error The $data parameter, with invalid characters removed from\n	 * each value. This works as a passthrough: any additional keys\n	 * such as \'field\' are retained in each value array. If we cannot\n	 * remove invalid characters, a WP_Error object is returned.\n	 */\n	protected function strip_invalid_text( $data ) {\n		$db_check_string = false;\n\n		foreach ( $data as &amp;$value ) {\n			$charset = $value[\'charset\'];\n\n			if ( is_array( $value[\'length\'] ) ) {\n				$length                  = $value[\'length\'][\'length\'];\n				$truncate_by_byte_length = \'byte\' === $value[\'length\'][\'type\'];\n			} else {\n				$length = false;\n				// Since we have no length, we\'ll never truncate.\n				// Initialize the variable to false. true would take us\n				// through an unnecessary (for this case) codepath below.\n				$truncate_by_byte_length = false;\n			}\n\n			// There\'s no charset to work with.\n			if ( false === $charset ) {\n				continue;\n			}\n\n			// Column isn\'t a string.\n			if ( ! is_string( $value[\'value\'] ) ) {\n				continue;\n			}\n\n			$needs_validation = true;\n			if (\n				// latin1 can store any byte sequence\n				\'latin1\' === $charset\n			||\n				// ASCII is always OK.\n				( ! isset( $value[\'ascii\'] ) &amp;&amp; $this-&gt;check_ascii( $value[\'value\'] ) )\n			) {\n				$truncate_by_byte_length = true;\n				$needs_validation        = false;\n			}\n\n			if ( $truncate_by_byte_length ) {\n				mbstring_binary_safe_encoding();\n				if ( false !== $length &amp;&amp; strlen( $value[\'value\'] ) &gt; $length ) {\n					$value[\'value\'] = substr( $value[\'value\'], 0, $length );\n				}\n				reset_mbstring_encoding();\n\n				if ( ! $needs_validation ) {\n					continue;\n				}\n			}\n\n			// utf8 can be handled by regex, which is a bunch faster than a DB lookup.\n			if ( ( \'utf8\' === $charset || \'utf8mb3\' === $charset || \'utf8mb4\' === $charset ) &amp;&amp; function_exists( \'mb_strlen\' ) ) {\n				$regex = \'/\n					(\n						(?: [\\x00-\\x7F]                  # single-byte sequences   0xxxxxxx\n						|   [\\xC2-\\xDF][\\x80-\\xBF]       # double-byte sequences   110xxxxx 10xxxxxx\n						|   \\xE0[\\xA0-\\xBF][\\x80-\\xBF]   # triple-byte sequences   1110xxxx 10xxxxxx * 2\n						|   [\\xE1-\\xEC][\\x80-\\xBF]{2}\n						|   \\xED[\\x80-\\x9F][\\x80-\\xBF]\n						|   [\\xEE-\\xEF][\\x80-\\xBF]{2}\';\n\n				if ( \'utf8mb4\' === $charset ) {\n					$regex .= \'\n						|    \\xF0[\\x90-\\xBF][\\x80-\\xBF]{2} # four-byte sequences   11110xxx 10xxxxxx * 3\n						|    [\\xF1-\\xF3][\\x80-\\xBF]{3}\n						|    \\xF4[\\x80-\\x8F][\\x80-\\xBF]{2}\n					\';\n				}\n\n				$regex         .= \'){1,40}   # ...one or more times\n					)\n					| .           # anything else\n					/x\';\n				$value[\'value\'] = preg_replace( $regex, \'$1\', $value[\'value\'] );\n\n				if ( false !== $length &amp;&amp; mb_strlen( $value[\'value\'], \'UTF-8\' ) &gt; $length ) {\n					$value[\'value\'] = mb_substr( $value[\'value\'], 0, $length, \'UTF-8\' );\n				}\n				continue;\n			}\n\n			// We couldn\'t use any local conversions, send it to the DB.\n			$value[\'db\'] = $db_check_string = true;\n		}\n		unset( $value ); // Remove by reference.\n\n		if ( $db_check_string ) {\n			$queries = array();\n			foreach ( $data as $col =&gt; $value ) {\n				if ( ! empty( $value[\'db\'] ) ) {\n					// We\'re going to need to truncate by characters or bytes, depending on the length value we have.\n					if ( \'byte\' === $value[\'length\'][\'type\'] ) {\n						// Using binary causes LEFT() to truncate by bytes.\n						$charset = \'binary\';\n					} else {\n						$charset = $value[\'charset\'];\n					}\n\n					if ( $this-&gt;charset ) {\n						$connection_charset = $this-&gt;charset;\n					} else {\n						if ( $this-&gt;use_mysqli ) {\n							$connection_charset = mysqli_character_set_name( $this-&gt;dbh );\n						} else {\n							$connection_charset = mysql_client_encoding();\n						}\n					}\n\n					if ( is_array( $value[\'length\'] ) ) {\n						$length          = sprintf( \'%.0f\', $value[\'length\'][\'length\'] );\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( LEFT( CONVERT( %s USING $charset ), $length ) USING $connection_charset )\", $value[\'value\'] );\n					} elseif ( \'binary\' !== $charset ) {\n						// If we don\'t have a length, there\'s no need to convert binary - it will always return the same result.\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( CONVERT( %s USING $charset ) USING $connection_charset )\", $value[\'value\'] );\n					}\n\n					unset( $data[ $col ][\'db\'] );\n				}\n			}\n\n			$sql = array();\n			foreach ( $queries as $column =&gt; $query ) {\n				if ( ! $query ) {\n					continue;\n				}\n\n				$sql[] = $query . \" AS x_$column\";\n			}\n\n			$this-&gt;check_current_query = false;\n			$row= $this-&gt;get_row( \'SELECT \' . implode( \', \', $sql ), ARRAY_A );\n			if ( ! $row ) {\n				return new WP_Error( \'wpdb_strip_invalid_text_failure\' );\n			}\n\n			foreach ( array_keys( $data ) as $column ) {\n				if ( isset( $row[ \"x_$column\" ] ) ) {\n					$data[ $column ][\'value\'] = $row[ \"x_$column\" ];\n				}\n			}\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Strips any invalid characters from the query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query Query to convert.\n	 * @return string|WP_Error The converted query, or a WP_Error object if the conversion fails.\n	 */\n	protected function strip_invalid_text_from_query( $query ) {\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$trimmed_query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $trimmed_query ) ) {\n			return $query;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( $table ) {\n			$charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $charset ) ) {\n				return $charset;\n			}\n\n			// We can\'t reliably strip text from tables containing binary/blob columns\n			if ( \'binary\' === $charset ) {\n				return $query;\n			}\n		} else {\n			$charset = $this-&gt;charset;\n		}\n\n		$data = array(\n			\'value\'   =&gt; $query,\n			\'charset\' =&gt; $charset,\n			\'ascii\'   =&gt; false,\n			\'length\'  =&gt; false,\n		);\n\n		$data = $this-&gt;strip_invalid_text( array( $data ) );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[0][\'value\'];\n	}\n\n	/**\n	 * Strips any invalid characters from the string for a given table and column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @param string $value  The text to check.\n	 * @return string|WP_Error The converted string, or a WP_Error object if the conversion fails.\n	 */\n	public function strip_invalid_text_for_column( $table, $column, $value ) {\n		if ( ! is_string( $value ) ) {\n			return $value;\n		}\n\n		$charset = $this-&gt;get_col_charset( $table, $column );\n		if ( ! $charset ) {\n			// Not a string column.\n			return $value;\n		} elseif ( is_wp_error( $charset ) ) {\n			// Bail on real errors.\n			return $charset;\n		}\n\n		$data = array(\n			$column =&gt; array(\n				\'value\'   =&gt; $value,\n				\'charset\' =&gt; $charset,\n				\'length\'  =&gt; $this-&gt;get_col_length( $table, $column ),\n			),\n		);\n\n		$data = $this-&gt;strip_invalid_text( $data );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[ $column ][\'value\'];\n	}\n\n	/**\n	 * Find the first table name referenced in a query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to search.\n	 * @return string|false $table The table name found, or false if a table couldn\'t be found.\n	 */\n	protected function get_table_from_query( $query ) {\n		// Remove characters that can legally trail the table name.\n		$query = rtrim( $query, \';/-#\' );\n\n		// Allow (select...) union [...] style queries. Use the first query\'s table name.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n\n		// Strip everything between parentheses except nested selects.\n		$query = preg_replace( \'/\\((?!\\s*select)[^(]*?\\)/is\', \'()\', $query );\n\n		// Quickly match most common queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'SELECT.*?\\s+FROM\'\n				. \'|INSERT(?:\\s+LOW_PRIORITY|\\s+DELAYED|\\s+HIGH_PRIORITY)?(?:\\s+IGNORE)?(?:\\s+INTO)?\'\n				. \'|REPLACE(?:\\s+LOW_PRIORITY|\\s+DELAYED)?(?:\\s+INTO)?\'\n				. \'|UPDATE(?:\\s+LOW_PRIORITY)?(?:\\s+IGNORE)?\'\n				. \'|DELETE(?:\\s+LOW_PRIORITY|\\s+QUICK|\\s+IGNORE)*(?:.+?FROM)?\'\n			. \')\\s+((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		// SHOW TABLE STATUS and SHOW TABLES WHERE Name = \'wp_posts\'\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES).+WHERE\\s+Name\\s*=\\s*(\"|\\\')((?:[0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\\\1/is\', $query, $maybe ) ) {\n			return $maybe[2];\n		}\n\n		// SHOW TABLE STATUS LIKE and SHOW TABLES LIKE \'wp\\_3\\_%\'\n		// This quoted LIKE operand seldom holds a full table name.\n		// It is usually a pattern for matching a prefix so we just\n		// strip the trailing % and unescape the _ to get \'wp_3_\'\n		// which drop-ins can use for routing these SQL statements.\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES)\\s+(?:WHERE\\s+Name\\s+)?LIKE\\s*(\"|\\\')((?:[\\\\\\\\0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)%?\\\\1/is\', $query, $maybe ) ) {\n			return str_replace( \'\\\\_\', \'_\', $maybe[2] );\n		}\n\n		// Big pattern for the rest of the table-related queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'(?:EXPLAIN\\s+(?:EXTENDED\\s+)?)?SELECT.*?\\s+FROM\'\n				. \'|DESCRIBE|DESC|EXPLAIN|HANDLER\'\n				. \'|(?:LOCK|UNLOCK)\\s+TABLE(?:S)?\'\n				. \'|(?:RENAME|OPTIMIZE|BACKUP|RESTORE|CHECK|CHECKSUM|ANALYZE|REPAIR).*\\s+TABLE\'\n				. \'|TRUNCATE(?:\\s+TABLE)?\'\n				. \'|CREATE(?:\\s+TEMPORARY)?\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\'\n				. \'|ALTER(?:\\s+IGNORE)?\\s+TABLE\'\n				. \'|DROP\\s+TABLE(?:\\s+IF\\s+EXISTS)?\'\n				. \'|CREATE(?:\\s+\\w+)?\\s+INDEX.*\\s+ON\'\n				. \'|DROP\\s+INDEX.*\\s+ON\'\n				. \'|LOAD\\s+DATA.*INFILE.*INTO\\s+TABLE\'\n				. \'|(?:GRANT|REVOKE).*ON\\s+TABLE\'\n				. \'|SHOW\\s+(?:.*FROM|.*TABLE)\'\n			. \')\\s+\\(*\\s*((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\s*\\)*/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		return false;\n	}\n\n	/**\n	 * Load the column metadata from the last query.\n	 *\n	 * @since 3.5.0\n	 */\n	protected function load_col_info() {\n		if ( $this-&gt;col_info ) {\n			return;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$num_fields = mysqli_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysqli_fetch_field( $this-&gt;result );\n			}\n		} else {\n			$num_fields = mysql_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysql_fetch_field( $this-&gt;result, $i );\n			}\n		}\n	}\n\n	/**\n	 * Retrieve column metadata from the last query.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $info_type  Optional. Type one of name, table, def, max_length, not_null, primary_key, multiple_key, unique_key, numeric, blob, type, unsigned, zerofill\n	 * @param int    $col_offset Optional. 0: col name. 1: which table the col\'s in. 2: col\'s max length. 3: if the col is numeric. 4: col\'s type\n	 * @return mixed Column Results\n	 */\n	public function get_col_info( $info_type = \'name\', $col_offset = -1 ) {\n		$this-&gt;load_col_info();\n\n		if ( $this-&gt;col_info ) {\n			if ( $col_offset == -1 ) {\n				$i         = 0;\n				$new_array = array();\n				foreach ( (array) $this-&gt;col_info as $col ) {\n					$new_array[ $i ] = $col-&gt;{$info_type};\n					$i++;\n				}\n				return $new_array;\n			} else {\n				return $this-&gt;col_info[ $col_offset ]-&gt;{$info_type};\n			}\n		}\n	}\n\n	/**\n	 * Starts the timer, for debugging purposes.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return true\n	 */\n	public function timer_start() {\n		$this-&gt;time_start = microtime( true );\n		return true;\n	}\n\n	/**\n	 * Stops the debugging timer.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return float Total time spent on the query, in seconds\n	 */\n	public function timer_stop() {\n		return ( microtime( true ) - $this-&gt;time_start );\n	}\n\n	/**\n	 * エラーを素敵なヘッダーとフッターにラップして終わります。\n	 *\n	 * wpdb :: $ show_errorsがfalseであれば死にません。\n	 *\n	 * @since 1.5.0\n	 *\n	 * @param string $message    The Error message\n	 * @param string $error_code Optional. エラーを識別するためのコンピュータ可読文字列。\n	 * @return false|void\n	 */\n	public function bail( $message, $error_code = \'500\' ) {\n		if ( $this-&gt;show_errors ) {\n			$error = \'\';\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$error = mysqli_error( $this-&gt;dbh );\n				} elseif ( mysqli_connect_errno() ) {\n					$error = mysqli_connect_error();\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$error = mysql_error( $this-&gt;dbh );\n				} else {\n					$error = mysql_error();\n				}\n			}\n\n			if ( $error ) {\n				$message = \'&lt;p&gt;&lt;code&gt;\' . $error . \"&lt;/code&gt;&lt;/p&gt;\\n\" . $message;\n			}\n\n			wp_die( $message );\n		} else {\n			if ( class_exists( \'WP_Error\', false ) ) {\n				$this-&gt;error = new WP_Error( $error_code, $message );\n			} else {\n				$this-&gt;error = $message;\n			}\n\n			return false;\n		}\n	}\n\n\n	/**\n	 * 現在のデータベース接続を閉じます。\n	 *\n	 * @since 4.5.0\n	 *\n	 * @return bool True if the connection was successfully closed, false if it wasn\'t,\n	 *              or the connection doesn\'t exist.\n	 */\n	public function close() {\n		if ( ! $this-&gt;dbh ) {\n			return false;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$closed = mysqli_close( $this-&gt;dbh );\n		} else {\n			$closed = mysql_close( $this-&gt;dbh );\n		}\n\n		if ( $closed ) {\n			$this-&gt;dbh           = null;\n			$this-&gt;ready         = false;\n			$this-&gt;has_connected = false;\n		}\n\n		return $closed;\n	}\n\n	/**\n	 * MySQLデータベースが最低限必要な最小バージョンかどうか\n	 *\n	 * @since 2.5.0\n	 *\n	 * @global string $wp_version\n	 * @global string $required_mysql_version\n	 *\n	 * @return WP_Error|void\n	 */\n	public function check_database_version() {\n		global $wp_version, $required_mysql_version;\n		// サーバーに必要なMySQLバージョンがあることを確認してください。\n		if ( version_compare( $this-&gt;db_version(), $required_mysql_version, \'&lt;\' ) ) {\n			/* translators: 1: WordPress version number, 2: Minimum required MySQL version number */\n			return new WP_Error( \'database_version\', sprintf( __( \'&lt;strong&gt;ERROR&lt;/strong&gt;: WordPress %1$s requires MySQL %2$s or higher\' ), $wp_version, $required_mysql_version ) );\n		}\n	}\n\n	/**\n	 * データベースが照合をサポートしているかどうか\n	 *\n	 * WordPressがテーブルスキームを生成しているときに呼び出されます。\n	 *\n	 * Use `wpdb::has_cap( \'collation\' )`.\n	 *\n	 * @since 2.5.0\n	 * @deprecated 3.5.0 Use wpdb::has_cap()\n	 *\n	 * @return bool True if collation is supported, false if version does not\n	 */\n	public function supports_collation() {\n		_deprecated_function( __FUNCTION__, \'3.5.0\', \'wpdb::has_cap( \\\'collation\\\' )\' );\n		return $this-&gt;has_cap( \'collation\' );\n	}\n\n	/**\n	 * データベース文字の照合\n	 *\n	 * @since 3.5.0\n	 *\n	 * @return string The database character collate.\n	 */\n	public function get_charset_collate() {\n		$charset_collate = \'\';\n\n		if ( ! empty( $this-&gt;charset ) ) {\n			$charset_collate = \"DEFAULT CHARACTER SET $this-&gt;charset\";\n		}\n		if ( ! empty( $this-&gt;collate ) ) {\n			$charset_collate .= \" COLLATE $this-&gt;collate\";\n		}\n\n		return $charset_collate;\n	}\n\n	/**\n	 * データベースが特定の機能をサポートしているかどうかを確認します。\n	 *\n	 * @since 2.7.0\n	 * @since 4.1.0 Added support for the \'utf8mb4\' feature.\n	 * @since 4.6.0 Added support for the \'utf8mb4_520\' feature.\n	 *\n	 * @see wpdb::db_version()\n	 *\n	 * @param string $db_cap The feature to check for. Accepts \'collation\',\n	 *\'group_concat\', \'subqueries\', \'set_charset\',\n	 *\'utf8mb4\', or \'utf8mb4_520\'.\n	 * @return int|false Whether the database feature is supported, false otherwise.\n	 */\n	public function has_cap( $db_cap ) {\n		$version = $this-&gt;db_version();\n\n		switch ( strtolower( $db_cap ) ) {\n			case \'collation\':    // @since 2.5.0\n			case \'group_concat\': // @since 2.7.0\n			case \'subqueries\':   // @since 2.7.0\n				return version_compare( $version, \'4.1\', \'&gt;=\' );\n			case \'set_charset\':\n				return version_compare( $version, \'5.0.7\', \'&gt;=\' );\n			case \'utf8mb4\':      // @since 4.1.0\n				if ( version_compare( $version, \'5.5.3\', \'&lt;\' ) ) {\n					return false;\n				}\n				if ( $this-&gt;use_mysqli ) {\n					$client_version = mysqli_get_client_info();\n				} else {\n					$client_version = mysql_get_client_info();\n				}\n\n				/*\n				 * libmysql has supported utf8mb4 since 5.5.3, same as the MySQL server.\n				 * mysqlnd has supported utf8mb4 since 5.0.9.\n				 */\n				if ( false !== strpos( $client_version, \'mysqlnd\' ) ) {\n					$client_version = preg_replace( \'/^\\D+([\\d.]+).*/\', \'$1\', $client_version );\n					return version_compare( $client_version, \'5.0.9\', \'&gt;=\' );\n				} else {\n					return version_compare( $client_version, \'5.5.3\', \'&gt;=\' );\n				}\n			case \'utf8mb4_520\': // @since 4.6.0\n				return version_compare( $version, \'5.6\', \'&gt;=\' );\n		}\n\n		return false;\n	}\n\n	/**\n	 * wpdbを呼び出した関数の名前を取得してください。\n	 *\n	 * Searches up the list of functions until it reaches\n	 * the one that would most logically had called this method.\n	 *\n	 * @since 2.5.0\n	 *\n	 * @return string Comma separated list of the calling functions.\n	 */\n	public function get_caller() {\n		return wp_debug_backtrace_summary( __CLASS__ );\n	}\n\n	/**\n	 * MySQLサーバーのバージョンを取得します。\n	 *\n	 * @since 2.7.0\n	 *\n	 * @return null|string Null on failure, version number on success.\n	 */\n	public function db_version() {\n		if ( $this-&gt;use_mysqli ) {\n			$server_info = mysqli_get_server_info( $this-&gt;dbh );\n		} else {\n			$server_info = mysql_get_server_info( $this-&gt;dbh );\n		}\n		return preg_replace( \'/[^0-9.].*/\', \'\', $server_info );\n	}\n}\n</pre>\n<p> </p>','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-04 18:41:26','2019-06-04 09:41:26','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2477,1,'2019-06-04 18:41:30','2019-06-04 09:41:30','<p>データベースに接続して取得したり、インサートするファイルになります。</p>\n<p> </p>\n\n<pre class=\"lang:php decode:true \" title=\"wp-db.php\">&lt;?php\n/**\n * WordPress DBクラス\n *\n * 元のコード  {@link http://php.justinvincent.com Justin Vincent (justin@visunet.ie)}\n *\n * @package WordPress\n * @subpackage Database\n * @since 0.71\n */\n\n/**\n * @since 0.71\n */\ndefine( \'EZSQL_VERSION\', \'WP1.25\' );\n\n/**\n * @since 0.71\n */\ndefine( \'OBJECT\', \'OBJECT\' );\n// phpcs:ignore Generic.NamingConventions.UpperCaseConstantName.ConstantNotUpperCase\ndefine( \'object\', \'OBJECT\' ); // Back compat.\n\n/**\n * @since 2.5.0\n */\ndefine( \'OBJECT_K\', \'OBJECT_K\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_A\', \'ARRAY_A\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_N\', \'ARRAY_N\' );\n\n/**\n * WordPressデータベースアクセス抽象化オブジェクト\n *\n * wp-content / db.phpファイルの$ wpdbグローバル変数を\n * あなたのクラスに設定することで、このクラスをあなた自身のクラスに\n * 置き換えることが可能です。\n *\n * @link https://codex.wordpress.org/Function_Reference/wpdb_Class\n *\n * @since 0.71\n */\nclass wpdb {\n\n	/**\n	 * SQL / DBエラーを表示するかどうか\n	 *\n	 * デフォルトの動作では、WP_DEBUGとWP_DEBUG_DISPLAYの両方がtrueと評価された場合に\n	 * エラーを表示します。\n	 *\n	 * @since 0.71\n	 * @var bool\n	 */\n	var $show_errors = false;\n\n	/**\n	 * DBブートストラップ中のエラーを抑制するかどうか。\n	 *\n	 * @since 2.5.0\n	 * @var bool\n	 */\n	var $suppress_errors = false;\n\n	/**\n	 * クエリ中の最後のエラー\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $last_error = \'\';\n\n	/**\n	 * 行われたクエリの量\n	 *\n	 * @since 1.2.0\n	 * @var int\n	 */\n	public $num_queries = 0;\n\n	/**\n	 * 前のクエリによって返された行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $num_rows = 0;\n\n	/**\n	 * 前の照会による影響を受けた行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	var $rows_affected = 0;\n\n	/**\n	 * 前回のクエリによってAUTO_INCREMENTカラムに対して生成されたID（通常はINSERT）。\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $insert_id = 0;\n\n	/**\n	 * 最後に行われたクエリ\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	var $last_query;\n\n	/**\n	 * 最後に行われたクエリの結果\n	 *\n	 * @since 0.71\n	 * @var array|null\n	 */\n	var $last_result;\n\n	/**\n	 * MySQLの結果。これはリソースまたはブール値です。\n	 *\n	 * @since 0.71\n	 * @var mixed\n	 */\n	protected $result;\n\n	/**\n	 * 挿入前のサニティチェックデータ用のキャッシュされた列情報\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $col_meta = array();\n\n	/**\n	 * テーブルの計算文字セット\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $table_charset = array();\n\n	/**\n	 * 現在のクエリのテキストフィールドを健全性チェックする必要があるかどうか。\n	 *\n	 * @since 4.2.0\n	 * @var bool\n	 */\n	protected $check_current_query = true;\n\n	/**\n	 * 照合をチェックするときに再帰問題に遭遇しないようにするためのフラグ。\n	 *\n	 * @since 4.2.0\n	 * @see wpdb::check_safe_collation()\n	 * @var bool\n	 */\n	private $checking_collation = false;\n\n	/**\n	 * テーブルカラムに保存された情報\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	protected $col_info;\n\n	/**\n	 * デバッグ目的で実行されたクエリのログ。\n	 *\n	 * @since 1.5.0\n	 * @since 2.5.0 各クエリログの3番目の要素は、呼び出し元の関数を記録するために追加されました。\n	 * @since 5.1.0 各クエリログの4番目の要素は、開始時刻を記録するために追加されました。\n	 *\n	 * @var array[] {\n	 *     実行されたクエリの配列。\n	 *\n	 *     @type array ...$0 {\n	 *         Data for each query.\n	 *\n	 *         @type string $0 The query\'s SQL.\n	 *         @type float  $1 照会に費やした合計時間（秒単位）。\n	 *         @type string $2 呼び出し側関数のコンマ区切りリスト。\n	 *         @type float  $3 問い合わせの開始時のUnixタイムスタンプ。\n	 *     }\n	 * }\n	 */\n	var $queries;\n\n	/**\n	 * 死ぬまでに再接続を再試行する回数\n	 *\n	 * @since 3.9.0\n	 * @see wpdb::check_connection()\n	 * @var int\n	 */\n	protected $reconnect_retries = 5;\n\n	/**\n	 * WordPressのテーブルプレフィックス\n	 *\n	 * 単一のデータベースに複数のWordPressをインストールするように設定できます。\n	 * 2番目の理由は、考えられるセキュリティ上の予防策です。\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $prefix = \'\';\n\n	/**\n	 * WordPressのベーステーブルプレフィックス。\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $base_prefix;\n\n	/**\n	 * Whether the database queries are ready to start executing.\n	 *\n	 * @since 2.3.2\n	 * @var bool\n	 */\n	var $ready = false;\n\n	/**\n	 * Blog ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $blogid = 0;\n\n	/**\n	 * Site ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $siteid = 0;\n\n	/**\n	 * ブログ毎のWordPress一覧表\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $tables = array(\n		\'posts\',\n		\'comments\',\n		\'links\',\n		\'options\',\n		\'postmeta\',\n		\'terms\',\n		\'term_taxonomy\',\n		\'term_relationships\',\n		\'termmeta\',\n		\'commentmeta\',\n	);\n\n	/**\n	 * 廃止予定のWordPressテーブルのリスト\n	 *\n	 * categories、post2cat、およびlink2catは、2.3.0、dbバージョン5539で非推奨となりました。\n	 *\n	 * @since 2.9.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $old_tables = array( \'categories\', \'post2cat\', \'link2cat\' );\n\n	/**\n	 * WordPressグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $global_tables = array( \'users\', \'usermeta\' );\n\n	/**\n	 * マルチサイトグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $ms_global_tables = array(\n		\'blogs\',\n		\'blogmeta\',\n		\'signups\',\n		\'site\',\n		\'sitemeta\',\n		\'sitecategories\',\n		\'registration_log\',\n		\'blog_versions\',\n	);\n\n	/**\n	 * WordPress Comments table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $comments;\n\n	/**\n	 * WordPress Comment Metadata table\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	public $commentmeta;\n\n	/**\n	 * WordPress Links table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $links;\n\n	/**\n	 * WordPress Options table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $options;\n\n	/**\n	 * WordPress Post Metadata table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $postmeta;\n\n	/**\n	 * WordPress Posts table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $posts;\n\n	/**\n	 * WordPress Terms table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $terms;\n\n	/**\n	 * WordPress Term Relationships table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_relationships;\n\n	/**\n	 * WordPress Term Taxonomy table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_taxonomy;\n\n	/**\n	 * WordPress Term Meta table.\n	 *\n	 * @since 4.4.0\n	 * @var string\n	 */\n	public $termmeta;\n\n	//\n	// Global and Multisite tables\n	//\n\n	/**\n	 * WordPress User Metadata table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $usermeta;\n\n	/**\n	 * WordPress Users table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $users;\n\n	/**\n	 * Multisite Blogs table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blogs;\n\n	/**\n	 * Multisite Blog Metadata table\n	 *\n	 * @since 5.1.0\n	 * @var string\n	 */\n	public $blogmeta;\n\n	/**\n	 * Multisite Blog Versions table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blog_versions;\n\n	/**\n	 * Multisite Registration Log table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $registration_log;\n\n	/**\n	 * Multisite Signups table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $signups;\n\n	/**\n	 * Multisite Sites table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $site;\n\n	/**\n	 * Multisite Sitewide Terms table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitecategories;\n\n	/**\n	 * Multisite Site Metadata table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitemeta;\n\n	/**\n	 * DB列のフォーマット指定子ここにリストされていない列は、デフォルトで％sになります。WPロード中に初期化されました。\n	 *\n	 * キーはカラム名、値はフォーマットタイプです。 \'ID\' =&gt; \'％d\'\n	 *\n	 * @since 2.8.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::insert()\n	 * @see wpdb::update()\n	 * @see wpdb::delete()\n	 * @see wp_set_wpdb_vars()\n	 * @var array\n	 */\n	public $field_types = array();\n\n	/**\n	 * Database table columns charset\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $charset;\n\n	/**\n	 * Database table columns collate\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $collate;\n\n	/**\n	 * Database Username\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	protected $dbuser;\n\n	/**\n	 * Database Password\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbpassword;\n\n	/**\n	 * Database Name\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbname;\n\n	/**\n	 * Database Host\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbhost;\n\n	/**\n	 * Database Handle\n	 *\n	 * @since 0.71\n	 * @var string\n	 */\n	protected $dbh;\n\n	/**\n	 * 最後のクエリ/ get_row / get_var呼び出しの説明文\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $func_call;\n\n	/**\n	 * MySQLがデータベースエンジンとして使用されているかどうか。\n	 *\n	 * デフォルトでは、WPDB :: db_connect（）をtrueに設定します。 \n	 * これはWordPressに必要なMySQLバージョンをチェックするときに使われます。 \n	 * 通常、置換データベースドロップイン（db.php）はこれらのチェックをスキップしますが、\n	 * これをtrueに設定するとチェックを強制的に実行させます。\n	 *\n	 * @since 3.3.0\n	 * @var bool\n	 */\n	public $is_mysql = null;\n\n	/**\n	 * 互換性のないSQLモードのリスト。\n	 *\n	 * @since 3.9.0\n	 * @var array\n	 */\n	protected $incompatible_modes = array(\n		\'NO_ZERO_DATE\',\n		\'ONLY_FULL_GROUP_BY\',\n		\'STRICT_TRANS_TABLES\',\n		\'STRICT_ALL_TABLES\',\n		\'TRADITIONAL\',\n	);\n\n	/**\n	 * mysql上でmysqliを使用するかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $use_mysqli = false;\n\n	/**\n	 * ある時点でうまく接続できたかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $has_connected = false;\n\n	/**\n	 * データベースサーバーに接続してデータベースを選択する\n	 *\n	 * PPHP 5との互換性のためのHP 5スタイルのコンストラクタ。 Does\n	 * クラスプロパティの実際の設定とデータベースへの接続を行います。\n	 * \n	 *\n	 * @link https://core.trac.wordpress.org/ticket/3354\n	 * @since 2.0.8\n	 *\n	 * @global string $wp_version\n	 *\n	 * @param string $dbuser     MySQL database user\n	 * @param string $dbpassword MySQL database password\n	 * @param string $dbname     MySQL database name\n	 * @param string $dbhost     MySQL database host\n	 */\n	public function __construct( $dbuser, $dbpassword, $dbname, $dbhost ) {\n		register_shutdown_function( array( $this, \'__destruct\' ) );\n\n		if ( WP_DEBUG &amp;&amp; WP_DEBUG_DISPLAY ) {\n			$this-&gt;show_errors();\n		}\n\n		// WP_USE_EXT_MYSQLがtrueとして定義されていない限り、存在する場合はext / mysqliを使用\n		if ( function_exists( \'mysqli_connect\' ) ) {\n			$this-&gt;use_mysqli = true;\n\n			if ( defined( \'WP_USE_EXT_MYSQL\' ) ) {\n				$this-&gt;use_mysqli = ! WP_USE_EXT_MYSQL;\n			}\n		}\n\n		$this-&gt;dbuser     = $dbuser;\n		$this-&gt;dbpassword = $dbpassword;\n		$this-&gt;dbname     = $dbname;\n		$this-&gt;dbhost     = $dbhost;\n\n		// wp-config.phpの作成は準備ができたら手動で接続します。\n		if ( defined( \'WP_SETUP_CONFIG\' ) ) {\n			return;\n		}\n\n		$this-&gt;db_connect();\n	}\n\n	/**\n	 * PHP 5スタイルのデストラクタで、データベースオブジェクトが破棄されたときに実行されます。\n	 *\n	 * @see wpdb::__construct()\n	 * @since 2.0.8\n	 * @return true\n	 */\n	public function __destruct() {\n		return true;\n	}\n\n	/**\n	 * 下位互換性のためにプライベートプロパティを読み取り可能にします\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name The private member to get, and optionally process\n	 * @return mixed The private member\n	 */\n	public function __get( $name ) {\n		if ( \'col_info\' === $name ) {\n			$this-&gt;load_col_info();\n		}\n\n		return $this-&gt;$name;\n	}\n\n	/**\n	 *プライベートプロパティを下位互換性のために設定可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to set\n	 * @param mixed  $value The value to set\n	 */\n	public function __set( $name, $value ) {\n		$protected_members = array(\n			\'col_meta\',\n			\'table_charset\',\n			\'check_current_query\',\n		);\n		if ( in_array( $name, $protected_members, true ) ) {\n			return;\n		}\n		$this-&gt;$name = $value;\n	}\n\n	/**\n	 * プライベートプロパティを下位互換性のためにチェック可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to check\n	 *\n	 * @return bool If the member is set or not\n	 */\n	public function __isset( $name ) {\n		return isset( $this-&gt;$name );\n	}\n\n	/**\n	 * Makes private properties un-settable for backward compatibility.\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to unset\n	 */\n	public function __unset( $name ) {\n		unset( $this-&gt;$name );\n	}\n\n	/**\n	 * Set $this-&gt;charset and $this-&gt;collate\n	 *\n	 * @since 3.1.0\n	 */\n	public function init_charset() {\n		$charset = \'\';\n		$collate = \'\';\n\n		if ( function_exists( \'is_multisite\' ) &amp;&amp; is_multisite() ) {\n			$charset = \'utf8\';\n			if ( defined( \'DB_COLLATE\' ) &amp;&amp; DB_COLLATE ) {\n				$collate = DB_COLLATE;\n			} else {\n				$collate = \'utf8_general_ci\';\n			}\n		} elseif ( defined( \'DB_COLLATE\' ) ) {\n			$collate = DB_COLLATE;\n		}\n\n		if ( defined( \'DB_CHARSET\' ) ) {\n			$charset = DB_CHARSET;\n		}\n\n		$charset_collate = $this-&gt;determine_charset( $charset, $collate );\n\n		$this-&gt;charset = $charset_collate[\'charset\'];\n		$this-&gt;collate = $charset_collate[\'collate\'];\n	}\n\n	/**\n	 * 与えられた文字セットと照合順序を使用して、使用するのに最適な文字セットと照合順序を決定します。\n	 *\n	 * たとえば、可能であれば、utf8の代わりにutf8mb4を使用する必要があります。\n	 *\n	 * @since 4.6.0\n	 *\n	 * @param string $charset The character set to check.\n	 * @param string $collate The collation to check.\n	 * @return array The most appropriate character set and collation to use.\n	 */\n	public function determine_charset( $charset, $collate ) {\n		if ( ( $this-&gt;use_mysqli &amp;&amp; ! ( $this-&gt;dbh instanceof mysqli ) ) || empty( $this-&gt;dbh ) ) {\n			return compact( \'charset\', \'collate\' );\n		}\n\n		if ( \'utf8\' === $charset &amp;&amp; $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8mb4\';\n		}\n\n		if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8\';\n			$collate = str_replace( \'utf8mb4_\', \'utf8_\', $collate );\n		}\n\n		if ( \'utf8mb4\' === $charset ) {\n			// _general_ is outdated, so we can upgrade it to _unicode_, instead.\n			if ( ! $collate || \'utf8_general_ci\' === $collate ) {\n				$collate = \'utf8mb4_unicode_ci\';\n			} else {\n				$collate = str_replace( \'utf8_\', \'utf8mb4_\', $collate );\n			}\n		}\n\n		// _unicode_520_ is a better collation, we should use that when it\'s available.\n		if ( $this-&gt;has_cap( \'utf8mb4_520\' ) &amp;&amp; \'utf8mb4_unicode_ci\' === $collate ) {\n			$collate = \'utf8mb4_unicode_520_ci\';\n		}\n\n		return compact( \'charset\', \'collate\' );\n	}\n\n	/**\n	 * 接続の文字セットを設定します。\n	 *\n	 * @since 3.1.0\n	 *\n	 * @param resource $dbh     The resource given by mysql_connect\n	 * @param string   $charset Optional. The character set. Default null.\n	 * @param string   $collate Optional. The collation. Default null.\n	 */\n	public function set_charset( $dbh, $charset = null, $collate = null ) {\n		if ( ! isset( $charset ) ) {\n			$charset = $this-&gt;charset;\n		}\n		if ( ! isset( $collate ) ) {\n			$collate = $this-&gt;collate;\n		}\n		if ( $this-&gt;has_cap( \'collation\' ) &amp;&amp; ! empty( $charset ) ) {\n			$set_charset_succeeded = true;\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( function_exists( \'mysqli_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysqli_set_charset( $dbh, $charset );\n				}\n\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysqli_query( $dbh, $query );\n				}\n			} else {\n				if ( function_exists( \'mysql_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysql_set_charset( $charset, $dbh );\n				}\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysql_query( $query, $dbh );\n				}\n			}\n		}\n	}\n\n	/**\n	 * 現在のSQLモードを変更し、そのWordPress互換性を確認してください。\n	 *\n	 * If no modes are passed, it will ensure the current MySQL server\n	 * modes are compatible.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param array $modes Optional. A list of SQL modes to set.\n	 */\n	public function set_sql_mode( $modes = array() ) {\n		if ( empty( $modes ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$res = mysqli_query( $this-&gt;dbh, \'SELECT @@SESSION.sql_mode\' );\n			} else {\n				$res = mysql_query( \'SELECT @@SESSION.sql_mode\', $this-&gt;dbh );\n			}\n\n			if ( empty( $res ) ) {\n				return;\n			}\n\n			if ( $this-&gt;use_mysqli ) {\n				$modes_array = mysqli_fetch_array( $res );\n				if ( empty( $modes_array[0] ) ) {\n					return;\n				}\n				$modes_str = $modes_array[0];\n			} else {\n				$modes_str = mysql_result( $res, 0 );\n			}\n\n			if ( empty( $modes_str ) ) {\n				return;\n			}\n\n			$modes = explode( \',\', $modes_str );\n		}\n\n		$modes = array_change_key_case( $modes, CASE_UPPER );\n\n		/**\n		 * Filters the list of incompatible SQL modes to exclude.\n		 *\n		 * @since 3.9.0\n		 *\n		 * @param array $incompatible_modes An array of incompatible modes.\n		 */\n		$incompatible_modes = (array) apply_filters( \'incompatible_sql_modes\', $this-&gt;incompatible_modes );\n\n		foreach ( $modes as $i =&gt; $mode ) {\n			if ( in_array( $mode, $incompatible_modes ) ) {\n				unset( $modes[ $i ] );\n			}\n		}\n\n		$modes_str = implode( \',\', $modes );\n\n		if ( $this-&gt;use_mysqli ) {\n			mysqli_query( $this-&gt;dbh, \"SET SESSION sql_mode=\'$modes_str\'\" );\n		} else {\n			mysql_query( \"SET SESSION sql_mode=\'$modes_str\'\", $this-&gt;dbh );\n		}\n	}\n\n	/**\n	 * WordPressテーブルのテーブルプレフィックスを設定します。\n	 *\n	 * @since 2.5.0\n	 *\n	 * @param string $prefix          Alphanumeric name for the new prefix.\n	 * @param bool   $set_table_names Optional. Whether the table names, e.g. wpdb::$posts, should be updated or not.\n	 * @return string|WP_Error Old prefix or WP_Error on error\n	 */\n	public function set_prefix( $prefix, $set_table_names = true ) {\n\n		if ( preg_match( \'|[^a-z0-9_]|i\', $prefix ) ) {\n			return new WP_Error( \'invalid_db_prefix\', \'Invalid database prefix\' );\n		}\n\n		$old_prefix = is_multisite() ? \'\' : $prefix;\n\n		if ( isset( $this-&gt;base_prefix ) ) {\n			$old_prefix = $this-&gt;base_prefix;\n		}\n\n		$this-&gt;base_prefix = $prefix;\n\n		if ( $set_table_names ) {\n			foreach ( $this-&gt;tables( \'global\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			if ( is_multisite() &amp;&amp; empty( $this-&gt;blogid ) ) {\n				return $old_prefix;\n			}\n\n			$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n			foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n		}\n		return $old_prefix;\n	}\n\n	/**\n	 * ブログIDを設定する\n	 *\n	 * @since 3.0.0\n	 *\n	 * @param int $blog_id\n	 * @param int $network_id Optional.\n	 * @return int previous blog id\n	 */\n	public function set_blog_id( $blog_id, $network_id = 0 ) {\n		if ( ! empty( $network_id ) ) {\n			$this-&gt;siteid = $network_id;\n		}\n\n		$old_blog_id  = $this-&gt;blogid;\n		$this-&gt;blogid = $blog_id;\n\n		$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n		foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		return $old_blog_id;\n	}\n\n	/**\n	 * Gets blog prefix.\n	 *\n	 * @since 3.0.0\n	 * @param int $blog_id Optional.\n	 * @return string Blog prefix.\n	 */\n	public function get_blog_prefix( $blog_id = null ) {\n		if ( is_multisite() ) {\n			if ( null === $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_id = (int) $blog_id;\n			if ( defined( \'MULTISITE\' ) &amp;&amp; ( 0 == $blog_id || 1 == $blog_id ) ) {\n				return $this-&gt;base_prefix;\n			} else {\n				return $this-&gt;base_prefix . $blog_id . \'_\';\n			}\n		} else {\n			return $this-&gt;base_prefix;\n		}\n	}\n\n	/**\n	 * WordPressテーブルの配列を返します。\n	 *\n	 * またCUSTOM_USER_TABLEとCUSTOM_USER_META_TABLEがWordPressユーザーと\n	 * usermetaテーブルを上書きすることを可能にします。そうでなければプレフィックスによって決定されます。\n	 *\n	 * scope引数は、以下のいずれかを取ります。\n	 *\n	 * \'all\' - \'all\'および \'global\'テーブルを返します。古いテーブルは返されません。\n	 * \'blog\' - 照会されたブログのブログレベルのテーブルを返します。\n	 * \'global\'インストール用のグローバルテーブルを返します。マルチサイトを実行している場合にのみマルチサイトテーブルを返します。\n	 * \'ms_global\' - 現在のインストールがマルチサイトかどうかにかかわらず、マルチサイトグローバルテーブルを返します。\n	 * \'old\' - 廃止予定のテーブルを返します。\n	 *\n	 * @since 3.0.0\n	 * @uses wpdb::$tables\n	 * @uses wpdb::$old_tables\n	 * @uses wpdb::$global_tables\n	 * @uses wpdb::$ms_global_tables\n	 *\n	 * @param string $scope  オプションです。 all、global、ms_global、blog、または古いテーブルにすることができます。デフォルトはallです。\n	 * @param bool   $ prefixオプション。テーブルプレフィックスを含めるかどうか。ブログならデフォルトはtrueです。\n	 * 接頭辞が要求されると、カスタムユーザーとusermetaテーブルがマッピングされます。\n	 * @param int    $blog_id Optional. The blog_id to prefix. Defaults to wpdb::$blogid. Used only when prefix is requested.\n	 * @return array Table names. When a prefix is requested, the key is the unprefixed table name.\n	 */\n	public function tables( $scope = \'all\', $prefix = true, $blog_id = 0 ) {\n		switch ( $scope ) {\n			case \'all\':\n				$tables = array_merge( $this-&gt;global_tables, $this-&gt;tables );\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'blog\':\n				$tables = $this-&gt;tables;\n				break;\n			case \'global\':\n				$tables = $this-&gt;global_tables;\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'ms_global\':\n				$tables = $this-&gt;ms_global_tables;\n				break;\n			case \'old\':\n				$tables = $this-&gt;old_tables;\n				break;\n			default:\n				return array();\n		}\n\n		if ( $prefix ) {\n			if ( ! $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_prefix   = $this-&gt;get_blog_prefix( $blog_id );\n			$base_prefix   = $this-&gt;base_prefix;\n			$global_tables = array_merge( $this-&gt;global_tables, $this-&gt;ms_global_tables );\n			foreach ( $tables as $k =&gt; $table ) {\n				if ( in_array( $table, $global_tables ) ) {\n					$tables[ $table ] = $base_prefix . $table;\n				} else {\n					$tables[ $table ] = $blog_prefix . $table;\n				}\n				unset( $tables[ $k ] );\n			}\n\n			if ( isset( $tables[\'users\'] ) &amp;&amp; defined( \'CUSTOM_USER_TABLE\' ) ) {\n				$tables[\'users\'] = CUSTOM_USER_TABLE;\n			}\n\n			if ( isset( $tables[\'usermeta\'] ) &amp;&amp; defined( \'CUSTOM_USER_META_TABLE\' ) ) {\n				$tables[\'usermeta\'] = CUSTOM_USER_META_TABLE;\n			}\n		}\n\n		return $tables;\n	}\n\n	/**\n	 * 現在のデータベース接続を使用してデータベースを選択します。\n	 *\n	 * データベース名は現在のデータベース接続に基づいて変更されます。\n	 * 失敗すると、実行は停止し、DBエラーを表示します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string        $db  MySQL database name\n	 * @param resource|null $dbh Optional link identifier.\n	 */\n	public function select( $db, $dbh = null ) {\n		if ( is_null( $dbh ) ) {\n			$dbh = $this-&gt;dbh;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$success = mysqli_select_db( $dbh, $db );\n		} else {\n			$success = mysql_select_db( $db, $dbh );\n		}\n		if ( ! $success ) {\n			$this-&gt;ready = false;\n			if ( ! did_action( \'template_redirect\' ) ) {\n				wp_load_translations_early();\n\n				$message = \'&lt;h1&gt;\' . __( \'Can&amp;#8217;t select database\' ) . \"&lt;/h1&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'We were able to connect to the database server (which means your username and password is okay) but not able to select the %s database.\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/p&gt;\\n\";\n\n				$message .= \"&lt;ul&gt;\\n\";\n				$message .= \'&lt;li&gt;\' . __( \'Are you sure it exists?\' ) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: 1: database user, 2: database name */\n					__( \'Does the user %1$s have permission to use the %2$s database?\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbuser, ENT_QUOTES ) . \'&lt;/code&gt;\',\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'On some systems the name of your database is prefixed with your username, so it would be like &lt;code&gt;username_%1$s&lt;/code&gt;. Could that be the problem?\' ),\n					htmlspecialchars( $db, ENT_QUOTES )\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \"&lt;/ul&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: support forums URL */\n					__( \'If you don&amp;#8217;t know how to set up a database you should &lt;strong&gt;contact your host&lt;/strong&gt;. If all else fails you may find help at the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n					__( \'https://wordpress.org/support/\' )\n				) . \"&lt;/p&gt;\\n\";\n\n				$this-&gt;bail( $message, \'db_select_fail\' );\n			}\n		}\n	}\n\n	/**\n	 * 使用しないでください、廃止予定です。\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 2.8.0\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare\n	 * @see esc_sql()\n	 *\n	 * @param string $string\n	 * @return string\n	 */\n	function _weak_escape( $string ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		return addslashes( $string );\n	}\n\n	/**\n	 * Real escape, using mysqli_real_escape_string() or mysql_real_escape_string()\n	 *\n	 * @see mysqli_real_escape_string()\n	 * @see mysql_real_escape_string()\n	 * @since 2.8.0\n	 *\n	 * @param  string $string to escape\n	 * @return string escaped\n	 */\n	function _real_escape( $string ) {\n		if ( $this-&gt;dbh ) {\n			if ( $this-&gt;use_mysqli ) {\n				$escaped = mysqli_real_escape_string( $this-&gt;dbh, $string );\n			} else {\n				$escaped = mysql_real_escape_string( $string, $this-&gt;dbh );\n			}\n		} else {\n			$class = get_class( $this );\n			if ( function_exists( \'__\' ) ) {\n				/* translators: %s: database access abstraction class, usually wpdb or a class extending wpdb */\n				_doing_it_wrong( $class, sprintf( __( \'%s must set a database connection for use with escaping.\' ), $class ), \'3.6.0\' );\n			} else {\n				_doing_it_wrong( $class, sprintf( \'%s must set a database connection for use with escaping.\', $class ), \'3.6.0\' );\n			}\n			$escaped = addslashes( $string );\n		}\n\n		return $this-&gt;add_placeholder_escape( $escaped );\n	}\n\n	/**\n	 * Escape data. Works on arrays.\n	 *\n	 * @uses wpdb::_real_escape()\n	 * @since  2.8.0\n	 *\n	 * @param  string|array $data\n	 * @return string|array escaped\n	 */\n	public function _escape( $data ) {\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;_escape( $v );\n				} else {\n					$data[ $k ] = $this-&gt;_real_escape( $v );\n				}\n			}\n		} else {\n			$data = $this-&gt;_real_escape( $data );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Do not use, deprecated.\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 0.71\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare()\n	 * @see esc_sql()\n	 *\n	 * @param mixed $data\n	 * @return mixed\n	 */\n	public function escape( $data ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;escape( $v, \'recursive\' );\n				} else {\n					$data[ $k ] = $this-&gt;_weak_escape( $v, \'internal\' );\n				}\n			}\n		} else {\n			$data = $this-&gt;_weak_escape( $data, \'internal\' );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Escapes content by reference for insertion into the database, for security\n	 *\n	 * @uses wpdb::_real_escape()\n	 *\n	 * @since 2.3.0\n	 *\n	 * @param string $string to escape\n	 */\n	public function escape_by_ref( &amp;$string ) {\n		if ( ! is_float( $string ) ) {\n			$string = $this-&gt;_real_escape( $string );\n		}\n	}\n\n	/**\n	 * 安全に実行できるようにSQLクエリを準備します。sprintf（）に似た構文を使用。\n	 *\n	 * クエリ文字列では、次のプレースホルダを使用できます。\n	 *   %d (integer)数字\n	 *   %f (float)\n	 *   %s (string)　文字列\n	 *\n	 * すべてのプレースホルダは、クエリ文字列では引用符で囲まないでおく必要があります。各プレースホルダーに対応する引数を渡す必要があります。\n	 *\n	 * 古い振る舞いとの互換性のために、番号付きまたはフォーマットされた文字列プレースホルダー（例えば、％1 $ s、％5s）は引用符を含みません\n	 * この関数によって追加されたので、あなたの使用法のためにそれらを囲む適切な引用符で渡されるべきです。\n	 *\n	 * エリ文字列内のリテラルパーセント記号（％）は、%%として記述する必要があります。 （たとえばLIKE構文で使用するため）\n	 * ワイルドカードパーセンテージは、完全なLIKE文字列を含む置換引数を介して渡す必要があります。\n	 * これらは、クエリ文字列に直接挿入することはできません。  {@see wpdb :: esc_like（）}もご覧ください。\n	 *\n	 * 引数は、メソッドへの個々の引数として渡すことも、すべての引数を含む単一の配列として渡すこともできます。\n	 * この2つの組み合わせはサポートされていません。\n	 *\n	 * 例えば\n	 *     $wpdb-&gt;prepare( \"SELECT * FROM `table` WHERE `column` = %s AND `field` = %d OR `other_field` LIKE %s\", array( \'foo\', 37, \'%bar\' ) );\n	 *     $wpdb-&gt;prepare( \"SELECT DATE_FORMAT(`field`, \'%%c\') FROM `table` WHERE `column` = %s\", \'foo\' );\n	 *\n	 * @link https://secure.php.net/sprintf Description of syntax.\n	 * @since 2.3.0\n	 *\n	 * @param string      $query    Query statement with sprintf()-like placeholders\n	 * @param array|mixed $args     The array of variables to substitute into the query\'s placeholders if being called with an array of arguments,\n	 *       or the first variable to substitute into the query\'s placeholders if being called with individual arguments.\n	 * @param mixed       $args,... further variables to substitute into the query\'s placeholders if being called wih individual arguments.\n	 * @return string|void Sanitized query string, if there is a query to prepare.\n	 */\n	public function prepare( $query, $args ) {\n		if ( is_null( $query ) ) {\n			return;\n		}\n\n		// これは絶対に確実というわけではないが明らかに誤った用法を捕らえるでしょう.\n		if ( strpos( $query, \'%\' ) === false ) {\n			wp_load_translations_early();\n			_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'The query argument of %s must have a placeholder.\' ), \'wpdb::prepare()\' ), \'3.9.0\' );\n		}\n\n		$args = func_get_args();\n		array_shift( $args );\n\n		// 引数が（vsprintfのように）配列として渡された場合は、それらを上に移動します。\n		$passed_as_array = false;\n		if ( is_array( $args[0] ) &amp;&amp; count( $args ) == 1 ) {\n			$passed_as_array = true;\n			$args            = $args[0];\n		}\n\n		foreach ( $args as $arg ) {\n			if ( ! is_scalar( $arg ) &amp;&amp; ! is_null( $arg ) ) {\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'Unsupported value type (%s).\' ), gettype( $arg ) ), \'4.8.2\' );\n			}\n		}\n\n		/*\n		 * プレースホルダで許可されている書式設定を指定します。以下が許可されています。\n		 *\n		 * - Sign specifier. eg, $+d\n		 * - Numbered placeholders. eg, %1$s\n		 * - Padding specifier, including custom padding characters. eg, %05s, %\'#5s\n		 * - Alignment specifier. eg, %05-s\n		 * - Precision specifier. eg, %.2f\n		 */\n		$allowed_format = \'(?:[1-9][0-9]*[$])?[-+0-9]*(?: |0|\\\'.)?[-+0-9]*(?:\\.[0-9]+)?\';\n\n		/*\n		 * ％sプレースホルダの周囲に引用符が既にある場合は、既存の引用符を削除してそれらを再挿入\n		 * すると、引用符の整合性が保証されます。\n		 *\n		 * 下位互換性のために、これは％sにのみ適用され、長い文字列の途中で頻繁に使用される％1 $ sなどのプレースホルダ、またはテーブル名プレースホルダには適用されません。\n		 */\n		$query = str_replace( \"\'%s\'\", \'%s\', $query ); // 既存の一重引用符を削除します。\n		$query = str_replace( \'\"%s\"\', \'%s\', $query ); // 既存の二重引用符を削除します。\n\n		// %% sのようなエスケープ文字列を避けて、文字列を引用符で囲みます。\n		$query = preg_replace( \'/(?&lt;!%)%s/\', \"\'%s\'\", $query );\n\n		 // フロートをロケールに気付かないようにします。\n		$query = preg_replace( \"/(?&lt;!%)(%($allowed_format)?f)/\", \'%\\\\2F\', $query ); \n\n		$query = preg_replace( \"/%(?:%|$|(?!($allowed_format)?[sdF]))/\", \'%%\\\\1\', $query ); // エスケープされていないパーセントをエスケープします。\n\n		// クエリ内の有効なプレースホルダの数を数えます。\n		$placeholders = preg_match_all( \"/(^|[^%]|(%%)+)%($allowed_format)?[sdF]/\", $query, $matches );\n\n		if ( count( $args ) !== $placeholders ) {\n			if ( 1 === $placeholders &amp;&amp; $passed_as_array ) {\n				// If the passed query only expected one argument, but the wrong number of arguments were sent as an array, bail.\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', __( \'The query only expected one placeholder, but an array of multiple placeholders was sent.\' ), \'4.9.0\' );\n\n				return;\n			} else {\n				/*\n				 * 適切な数のプレースホルダがなくても、それらが個別の引数として渡された場合、\n				 * または配列内に複数の引数があることが予想される場合は、警告をスローします。\n				 */\n				wp_load_translations_early();\n				_doing_it_wrong(\n					\'wpdb::prepare\',\n					/* translators: 1: number of placeholders, 2: number of arguments passed */\n					sprintf(\n						__( \'The query does not contain the correct number of placeholders (%1$d) for the number of arguments passed (%2$d).\' ),\n						$placeholders,\n						count( $args )\n					),\n					\'4.8.3\'\n				);\n			}\n		}\n\n		array_walk( $args, array( $this, \'escape_by_ref\' ) );\n		$query = @vsprintf( $query, $args );\n\n		return $this-&gt;add_placeholder_escape( $query );\n	}\n\n	/**\n	 * MySQLの準備の前にLIKE特殊文字％と_をエスケープする前半。\n	 *\n	 * これはwpdb ::prepare（）またはesc_sql（）の前にのみ使用してください。順序を逆にすると、セキュリティが非常に悪くなります。\n	 *\n	 * 準備済みステートメントの例：\n	 *\n	 *     $wild = \'%\';\n	 *     $find = \'only 43% of planets\';\n	 *     $like = $wild . $wpdb-&gt;esc_like( $find ) . $wild;\n	 *     $sql  = $wpdb-&gt;prepare( \"SELECT * FROM $wpdb-&gt;posts WHERE post_content LIKE %s\", $like );\n	 *\n	 * Example Escape Chain:\n	 *\n	 *     $sql  = esc_sql( $wpdb-&gt;esc_like( $input ) );\n	 *\n	 * @since 4.0.0\n	 *\n	 * @param string $text The raw text to be escaped. The input typed by the user should have no\n	 *                     extra or deleted slashes.\n	 * @return string Text in the form of a LIKE phrase. The output is not SQL safe. Call $wpdb::prepare()\n	 *                or real_escape next.\n	 */\n	public function esc_like( $text ) {\n		return addcslashes( $text, \'_%\\\\\' );\n	}\n\n	/**\n	 * Print SQL/DB error.\n	 *\n	 * @since 0.71\n	 * @global array $EZSQL_ERROR Stores error information of query and error string\n	 *\n	 * @param string $str The error to display\n	 * @return false|void False if the showing of errors is disabled.\n	 */\n	public function print_error( $str = \'\' ) {\n		global $EZSQL_ERROR;\n\n		if ( ! $str ) {\n			if ( $this-&gt;use_mysqli ) {\n				$str = mysqli_error( $this-&gt;dbh );\n			} else {\n				$str = mysql_error( $this-&gt;dbh );\n			}\n		}\n		$EZSQL_ERROR[] = array(\n			\'query\'     =&gt; $this-&gt;last_query,\n			\'error_str\' =&gt; $str,\n		);\n\n		if ( $this-&gt;suppress_errors ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		if ( $caller = $this-&gt;get_caller() ) {\n			/* translators: 1: Database error message, 2: SQL query, 3: Name of the calling function */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s made by %3$s\' ), $str, $this-&gt;last_query, $caller );\n		} else {\n			/* translators: 1: Database error message, 2: SQL query */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s\' ), $str, $this-&gt;last_query );\n		}\n\n		error_log( $error_str );\n\n		// Are we showing errors?\n		if ( ! $this-&gt;show_errors ) {\n			return false;\n		}\n\n		// If there is an error then take note of it\n		if ( is_multisite() ) {\n			$msg = sprintf(\n				\"%s [%s]\\n%s\\n\",\n				__( \'WordPress database error:\' ),\n				$str,\n				$this-&gt;last_query\n			);\n\n			if ( defined( \'ERRORLOGFILE\' ) ) {\n				error_log( $msg, 3, ERRORLOGFILE );\n			}\n			if ( defined( \'DIEONDBERROR\' ) ) {\n				wp_die( $msg );\n			}\n		} else {\n			$str   = htmlspecialchars( $str, ENT_QUOTES );\n			$query = htmlspecialchars( $this-&gt;last_query, ENT_QUOTES );\n\n			printf(\n				\'&lt;div id=\"error\"&gt;&lt;p class=\"wpdberror\"&gt;&lt;strong&gt;%s&lt;/strong&gt; [%s]&lt;br /&gt;&lt;code&gt;%s&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;\',\n				__( \'WordPress database error:\' ),\n				$str,\n				$query\n			);\n		}\n	}\n\n	/**\n	 * データベースエラーの表示を有効にします。\n	 *\n	 * この機能はエラーの表示を可能にするためだけに使用されるべきです。\n	 * wpdb::hide_errors() should be used instead for hiding of errors. However,\n	 * this function can be used to enable and disable showing of database\n	 * errors.\n	 *\n	 * @since 0.71\n	 * @see wpdb::hide_errors()\n	 *\n	 * @param bool $show Whether to show or hide errors\n	 * @return bool Old value for showing errors.\n	 */\n	public function show_errors( $show = true ) {\n		$errors            = $this-&gt;show_errors;\n		$this-&gt;show_errors = $show;\n		return $errors;\n	}\n\n	/**\n	 * Disables showing of database errors.\n	 *\n	 * By default database errors are not shown.\n	 *\n	 * @since 0.71\n	 * @see wpdb::show_errors()\n	 *\n	 * @return bool Whether showing of errors was active\n	 */\n	public function hide_errors() {\n		$show              = $this-&gt;show_errors;\n		$this-&gt;show_errors = false;\n		return $show;\n	}\n\n	/**\n	 * Whether to suppress database errors.\n	 *\n	 * By default database errors are suppressed, with a simple\n	 * call to this function they can be enabled.\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::hide_errors()\n	 * @param bool $suppress Optional. New value. Defaults to true.\n	 * @return bool Old value\n	 */\n	public function suppress_errors( $suppress = true ) {\n		$errors                = $this-&gt;suppress_errors;\n		$this-&gt;suppress_errors = (bool) $suppress;\n		return $errors;\n	}\n\n	/**\n	 * Kill cached query results.\n	 *\n	 * @since 0.71\n	 */\n	public function flush() {\n		$this-&gt;last_result   = array();\n		$this-&gt;col_info      = null;\n		$this-&gt;last_query    = null;\n		$this-&gt;rows_affected = $this-&gt;num_rows = 0;\n		$this-&gt;last_error    = \'\';\n\n		if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n			mysqli_free_result( $this-&gt;result );\n			$this-&gt;result = null;\n\n			// Sanity check before using the handle\n			if ( empty( $this-&gt;dbh ) || ! ( $this-&gt;dbh instanceof mysqli ) ) {\n				return;\n			}\n\n			// Clear out any results from a multi-query\n			while ( mysqli_more_results( $this-&gt;dbh ) ) {\n				mysqli_next_result( $this-&gt;dbh );\n			}\n		} elseif ( is_resource( $this-&gt;result ) ) {\n			mysql_free_result( $this-&gt;result );\n		}\n	}\n\n	/**\n	 * データベースに接続して選択します。\n	 *\n	 * $ allow_bailがfalseの場合、データベース接続の欠如は手動で処理する必要があります。.\n	 *\n	 * @since 3.0.0\n	 * @since 3.9.0 $allow_bail parameter added.\n	 *\n	 * @param bool $ allow_bailオプション。機能を保釈することを許可します。デフォルトはtrueです。\n	 * @return 成功した場合はtrue、失敗した場合はfalse。\n	 */\n	public function db_connect( $allow_bail = true ) {\n		$this-&gt;is_mysql = true;\n\n		/*\n		 * MySQLiを使用している場合は3.9以降では非推奨です。同等のものはありません\n		 * mysqli_ *関数には$ new_linkパラメータがあります。\n		 */\n		$new_link     = defined( \'MYSQL_NEW_LINK\' ) ? MYSQL_NEW_LINK : true;\n		$client_flags = defined( \'MYSQL_CLIENT_FLAGS\' ) ? MYSQL_CLIENT_FLAGS : 0;\n\n		if ( $this-&gt;use_mysqli ) {\n			$this-&gt;dbh = mysqli_init();\n\n			$host    = $this-&gt;dbhost;\n			$port    = null;\n			$socket  = null;\n			$is_ipv6 = false;\n\n			if ( $host_data = $this-&gt;parse_db_host( $this-&gt;dbhost ) ) {\n				list( $host, $port, $socket, $is_ipv6 ) = $host_data;\n			}\n\n			/*\n			 * If using the `mysqlnd` library, the IPv6 address needs to be\n			 * enclosed in square brackets, whereas it doesn\'t while using the\n			 * `libmysqlclient` library.\n			 * @see https://bugs.php.net/bug.php?id=67563\n			 */\n			if ( $is_ipv6 &amp;&amp; extension_loaded( \'mysqlnd\' ) ) {\n				$host = \"[$host]\";\n			}\n\n			if ( WP_DEBUG ) {\n				mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			} else {\n				@mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			}\n\n			if ( $this-&gt;dbh-&gt;connect_errno ) {\n				$this-&gt;dbh = null;\n\n				/*\n				 * ext / mysqliの設定が間違っている可能性があります。以下の場合、ext / mysqlにフォールバックしてください。\n				  *  - We haven\'t previously connected, and\n				  *  - WP_USE_EXT_MYSQL isn\'t set to false, and\n				  *  - ext/mysql is loaded.\n				  */\n				$attempt_fallback = true;\n\n				if ( $this-&gt;has_connected ) {\n					$attempt_fallback = false;\n				} elseif ( defined( \'WP_USE_EXT_MYSQL\' ) &amp;&amp; ! WP_USE_EXT_MYSQL ) {\n					$attempt_fallback = false;\n				} elseif ( ! function_exists( \'mysql_connect\' ) ) {\n					$attempt_fallback = false;\n				}\n\n				if ( $attempt_fallback ) {\n					$this-&gt;use_mysqli = false;\n					return $this-&gt;db_connect( $allow_bail );\n				}\n			}\n		} else {\n			if ( WP_DEBUG ) {\n				$this-&gt;dbh = mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			} else {\n				$this-&gt;dbh = @mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			}\n		}\n\n		if ( ! $this-&gt;dbh &amp;&amp; $allow_bail ) {\n			wp_load_translations_early();\n\n			// Load custom DB error template, if present.\n			if ( file_exists( WP_CONTENT_DIR . \'/db-error.php\' ) ) {\n				require_once( WP_CONTENT_DIR . \'/db-error.php\' );\n				die();\n			}\n\n			$message = \'&lt;h1&gt;\' . __( \'Error establishing a database connection\' ) . \"&lt;/h1&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: 1: wp-config.php, 2: database host */\n				__( \'This either means that the username and password information in your %1$s file is incorrect or we can&amp;#8217;t contact the database server at %2$s. This could mean your host&amp;#8217;s database server is down.\' ),\n				\'&lt;code&gt;wp-config.php&lt;/code&gt;\',\n				\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n			) . \"&lt;/p&gt;\\n\";\n\n			$message .= \"&lt;ul&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure you have the correct username and password?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that you have typed the correct hostname?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \"&lt;/ul&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: %s: support forums URL */\n				__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n				__( \'https://wordpress.org/support/\' )\n			) . \"&lt;/p&gt;\\n\";\n\n			$this-&gt;bail( $message, \'db_connect_fail\' );\n\n			return false;\n		} elseif ( $this-&gt;dbh ) {\n			if ( ! $this-&gt;has_connected ) {\n				$this-&gt;init_charset();\n			}\n\n			$this-&gt;has_connected = true;\n\n			$this-&gt;set_charset( $this-&gt;dbh );\n\n			$this-&gt;ready = true;\n			$this-&gt;set_sql_mode();\n			$this-&gt;select( $this-&gt;dbname, $this-&gt;dbh );\n\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Parse the DB_HOST setting to interpret it for mysqli_real_connect.\n	 *\n	 * mysqli_real_connect doesn\'t support the host param including a port or\n	 * socket like mysql_connect does. This duplicates how mysql_connect detects\n	 * a port and/or socket file.\n	 *\n	 * @since 4.9.0\n	 *\n	 * @param string $host The DB_HOST setting to parse.\n	 * @return array|bool Array containing the host, the port, the socket and whether\n	 *                    it is an IPv6 address, in that order. If $host couldn\'t be parsed,\n	 *                    returns false.\n	 */\n	public function parse_db_host( $host ) {\n		$port    = null;\n		$socket  = null;\n		$is_ipv6 = false;\n\n		// First peel off the socket parameter from the right, if it exists.\n		$socket_pos = strpos( $host, \':/\' );\n		if ( $socket_pos !== false ) {\n			$socket = substr( $host, $socket_pos + 1 );\n			$host   = substr( $host, 0, $socket_pos );\n		}\n\n		// We need to check for an IPv6 address first.\n		// An IPv6 address will always contain at least two colons.\n		if ( substr_count( $host, \':\' ) &gt; 1 ) {\n			$pattern = \'#^(?:\\[)?(?P&lt;host&gt;[0-9a-fA-F:]+)(?:\\]:(?P&lt;port&gt;[\\d]+))?#\';\n			$is_ipv6 = true;\n		} else {\n			// We seem to be dealing with an IPv4 address.\n			$pattern = \'#^(?P&lt;host&gt;[^:/]*)(?::(?P&lt;port&gt;[\\d]+))?#\';\n		}\n\n		$matches = array();\n		$result  = preg_match( $pattern, $host, $matches );\n\n		if ( 1 !== $result ) {\n			// Couldn\'t parse the address, bail.\n			return false;\n		}\n\n		$host = \'\';\n		foreach ( array( \'host\', \'port\' ) as $component ) {\n			if ( ! empty( $matches[ $component ] ) ) {\n				$$component = $matches[ $component ];\n			}\n		}\n\n		return array( $host, $port, $socket, $is_ipv6 );\n	}\n\n	/**\n	 * Checks that the connection to the database is still up. If not, try to reconnect.\n	 *\n	 * If this function is unable to reconnect, it will forcibly die, or if after the\n	 * the {@see \'template_redirect\'} hook has been fired, return false instead.\n	 *\n	 * If $allow_bail is false, the lack of database connection will need\n	 * to be handled manually.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param bool $allow_bail Optional. Allows the function to bail. Default true.\n	 * @return bool|void True if the connection is up.\n	 */\n	public function check_connection( $allow_bail = true ) {\n		if ( $this-&gt;use_mysqli ) {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysqli_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		} else {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysql_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		}\n\n		$error_reporting = false;\n\n		// Disable warnings, as we don\'t want to see a multitude of \"unable to connect\" messages\n		if ( WP_DEBUG ) {\n			$error_reporting = error_reporting();\n			error_reporting( $error_reporting &amp; ~E_WARNING );\n		}\n\n		for ( $tries = 1; $tries &lt;= $this-&gt;reconnect_retries; $tries++ ) {\n			// On the last try, re-enable warnings. We want to see a single instance of the\n			// \"unable to connect\" message on the bail() screen, if it appears.\n			if ( $this-&gt;reconnect_retries === $tries &amp;&amp; WP_DEBUG ) {\n				error_reporting( $error_reporting );\n			}\n\n			if ( $this-&gt;db_connect( false ) ) {\n				if ( $error_reporting ) {\n					error_reporting( $error_reporting );\n				}\n\n				return true;\n			}\n\n			sleep( 1 );\n		}\n\n		// If template_redirect has already happened, it\'s too late for wp_die()/dead_db().\n		// Let\'s just return and hope for the best.\n		if ( did_action( \'template_redirect\' ) ) {\n			return false;\n		}\n\n		if ( ! $allow_bail ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		$message = \'&lt;h1&gt;\' . __( \'Error reconnecting to the database\' ) . \"&lt;/h1&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: database host */\n			__( \'This means that we lost contact with the database server at %s. This could mean your host&amp;#8217;s database server is down.\' ),\n			\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n		) . \"&lt;/p&gt;\\n\";\n\n		$message .= \"&lt;ul&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is not under particularly heavy load?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \"&lt;/ul&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: support forums URL */\n			__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n			__( \'https://wordpress.org/support/\' )\n		) . \"&lt;/p&gt;\\n\";\n\n		// We weren\'t able to reconnect, so we better bail.\n		$this-&gt;bail( $message, \'db_connect_fail\' );\n\n		// Call dead_db() if bail didn\'t die, because this database is no more. It has ceased to be (at least temporarily).\n		dead_db();\n	}\n\n	/**\n	 * 現在のデータベース接続を使用して、MySQLデータベースクエリを実行します。\n	 *\n	 * より詳しい情報はコーデックスページにあります。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query Database query\n	 * @return int|bool Boolean true for CREATE, ALTER, TRUNCATE and DROP queries. Number of rows\n	 *                  affected/selected for all other queries. Boolean false on error.\n	 */\n	public function query( $query ) {\n		if ( ! $this-&gt;ready ) {\n			$this-&gt;check_current_query = true;\n			return false;\n		}\n\n		/**\n		 * データベースクエリをフィルタリングします。\n		 *\n		 * プラグインがロードされる前にいくつかの問い合わせが行われます。\n		 * and thus cannot be filtered with this method.\n		 *\n		 * @since 2.1.0\n		 *\n		 * @param string $query Database query.\n		 */\n		$query = apply_filters( \'query\', $query );\n\n		$this-&gt;flush();\n\n		// Log how the function was called\n		$this-&gt;func_call = \"\\$db-&gt;query(\\\"$query\\\")\";\n\n		// If we\'re writing to the database, make sure the query will write safely.\n		if ( $this-&gt;check_current_query &amp;&amp; ! $this-&gt;check_ascii( $query ) ) {\n			$stripped_query = $this-&gt;strip_invalid_text_from_query( $query );\n			// strip_invalid_text_from_query() can perform queries, so we need\n			// to flush again, just to make sure everything is clear.\n			$this-&gt;flush();\n			if ( $stripped_query !== $query ) {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		$this-&gt;check_current_query = true;\n\n		// Keep track of the last query for debug.\n		$this-&gt;last_query = $query;\n\n		$this-&gt;_do_query( $query );\n\n		// MySQL server has gone away, try to reconnect.\n		$mysql_errno = 0;\n		if ( ! empty( $this-&gt;dbh ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$mysql_errno = mysqli_errno( $this-&gt;dbh );\n				} else {\n					// $dbh is defined, but isn\'t a real connection.\n					// Something has gone horribly wrong, let\'s try a reconnect.\n					$mysql_errno = 2006;\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$mysql_errno = mysql_errno( $this-&gt;dbh );\n				} else {\n					$mysql_errno = 2006;\n				}\n			}\n		}\n\n		if ( empty( $this-&gt;dbh ) || 2006 == $mysql_errno ) {\n			if ( $this-&gt;check_connection() ) {\n				$this-&gt;_do_query( $query );\n			} else {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		// If there is an error then take note of it.\n		if ( $this-&gt;use_mysqli ) {\n			if ( $this-&gt;dbh instanceof mysqli ) {\n				$this-&gt;last_error = mysqli_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		} else {\n			if ( is_resource( $this-&gt;dbh ) ) {\n				$this-&gt;last_error = mysql_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		}\n\n		if ( $this-&gt;last_error ) {\n			// Clear insert_id on a subsequent failed insert.\n			if ( $this-&gt;insert_id &amp;&amp; preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				$this-&gt;insert_id = 0;\n			}\n\n			$this-&gt;print_error();\n			return false;\n		}\n\n		if ( preg_match( \'/^\\s*(create|alter|truncate|drop)\\s/i\', $query ) ) {\n			$return_val = $this-&gt;result;\n		} elseif ( preg_match( \'/^\\s*(insert|delete|update|replace)\\s/i\', $query ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$this-&gt;rows_affected = mysqli_affected_rows( $this-&gt;dbh );\n			} else {\n				$this-&gt;rows_affected = mysql_affected_rows( $this-&gt;dbh );\n			}\n			// Take note of the insert_id\n			if ( preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				if ( $this-&gt;use_mysqli ) {\n					$this-&gt;insert_id = mysqli_insert_id( $this-&gt;dbh );\n				} else {\n					$this-&gt;insert_id = mysql_insert_id( $this-&gt;dbh );\n				}\n			}\n			// Return number of rows affected\n			$return_val = $this-&gt;rows_affected;\n		} else {\n			$num_rows = 0;\n			if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n				while ( $row = mysqli_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			} elseif ( is_resource( $this-&gt;result ) ) {\n				while ( $row = mysql_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			}\n\n			// Log number of rows the query returned\n			// and return number of rows selected\n			$this-&gt;num_rows = $num_rows;\n			$return_val     = $num_rows;\n		}\n\n		return $return_val;\n	}\n\n	/**\n	 * Internal function to perform the mysql_query() call.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @see wpdb::query()\n	 *\n	 * @param string $query The query to run.\n	 */\n	private function _do_query( $query ) {\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;timer_start();\n		}\n\n		if ( ! empty( $this-&gt;dbh ) &amp;&amp; $this-&gt;use_mysqli ) {\n			$this-&gt;result = mysqli_query( $this-&gt;dbh, $query );\n		} elseif ( ! empty( $this-&gt;dbh ) ) {\n			$this-&gt;result = mysql_query( $query, $this-&gt;dbh );\n		}\n		$this-&gt;num_queries++;\n\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;queries[] = array(\n				$query,\n				$this-&gt;timer_stop(),\n				$this-&gt;get_caller(),\n				$this-&gt;time_start,\n			);\n		}\n	}\n\n	/**\n	 * Generates and returns a placeholder escape string for use in queries returned by ::prepare().\n	 *\n	 * @since 4.8.3\n	 *\n	 * @return string String to escape placeholders.\n	 */\n	public function placeholder_escape() {\n		static $placeholder;\n\n		if ( ! $placeholder ) {\n			// If ext/hash is not present, compat.php\'s hash_hmac() does not support sha256.\n			$algo = function_exists( \'hash\' ) ? \'sha256\' : \'sha1\';\n			// Old WP installs may not have AUTH_SALT defined.\n			$salt = defined( \'AUTH_SALT\' ) &amp;&amp; AUTH_SALT ? AUTH_SALT : (string) rand();\n\n			$placeholder = \'{\' . hash_hmac( $algo, uniqid( $salt, true ), $salt ) . \'}\';\n		}\n\n		/*\n		 * レースホルダエスケープを削除するために、フィルタを追加します。優先順位0を使用します。\n		 * そのため、このフィルタに関連付けられている他のものはすべて、プレースホルダ文字列が削除されたクエリを受け取ります\n		 */\n		if ( ! has_filter( \'query\', array( $this, \'remove_placeholder_escape\' ) ) ) {\n			add_filter( \'query\', array( $this, \'remove_placeholder_escape\' ), 0 );\n		}\n\n		return $placeholder;\n	}\n\n	/**\n	 * printf（）のプレースホルダーに似たものをエスケープするために、プレースホルダーのエスケープ文字列を追加します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query to escape.\n	 * @return string 必要に応じてプレースホルダエスケープ文字列が挿入されたクエリ。\n	 */\n	public function add_placeholder_escape( $query ) {\n		/*\n		 * 漠然とプレースホルダーに似ているものでさえも返すことを防ぐために、私たちは見つけることが\n		 * できるあらゆる％をつぶします。\n		 */\n		return str_replace( \'%\', $this-&gt;placeholder_escape(), $query );\n	}\n\n	/**\n	 * クエリからプレースホルダエスケープ文字列を削除します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query from which the placeholder will be removed.\n	 * @return string The query with the placeholder removed.\n	 */\n	public function remove_placeholder_escape( $query ) {\n		return str_replace( $this-&gt;placeholder_escape(), \'%\', $query );\n	}\n\n	/**\n	 * Insert a row into a table.\n	 *\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows inserted, or false on error.\n	 */\n	public function insert( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'INSERT\' );\n	}\n\n	/**\n	 * Replace a row into a table.\n	 *\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	public function replace( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'REPLACE\' );\n	}\n\n	/**\n	 * Helper function for insert and replace.\n	 *\n	 * Runs an insert or replace query based on $type argument.\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param string $type         Optional. What type of operation is this? INSERT or REPLACE. Defaults to INSERT.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	function _insert_replace_helper( $table, $data, $format = null, $type = \'INSERT\' ) {\n		$this-&gt;insert_id = 0;\n\n		if ( ! in_array( strtoupper( $type ), array( \'REPLACE\', \'INSERT\' ) ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$formats = $values = array();\n		foreach ( $data as $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$formats[] = \'NULL\';\n				continue;\n			}\n\n			$formats[] = $value[\'format\'];\n			$values[]  = $value[\'value\'];\n		}\n\n		$fields  = \'`\' . implode( \'`, `\', array_keys( $data ) ) . \'`\';\n		$formats = implode( \', \', $formats );\n\n		$sql = \"$type INTO `$table` ($fields) VALUES ($formats)\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Update a row in the table\n	 *\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ), array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'ID\' =&gt; 1 ), array( \'%s\', \'%d\' ), array( \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $data         Data to update (in column =&gt; value pairs).\n	 *            Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *            Sending a null value will cause the column to be set to NULL - the corresponding\n	 *            format is ignored in this case.\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $format       Optional. An array of formats to be mapped to each of the values in $data.\n	 *            If string, that format will be used for all of the values in $data.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function update( $table, $data, $where, $format = null, $where_format = null ) {\n		if ( ! is_array( $data ) || ! is_array( $where ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$fields = $conditions = $values = array();\n		foreach ( $data as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$fields[] = \"`$field` = NULL\";\n				continue;\n			}\n\n			$fields[] = \"`$field` = \" . $value[\'format\'];\n			$values[] = $value[\'value\'];\n		}\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$fields     = implode( \', \', $fields );\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"UPDATE `$table` SET $fields WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Delete a row in the table\n	 *\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ), array( \'%d\' ) )\n	 *\n	 * @since 3.4.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function delete( $table, $where, $where_format = null ) {\n		if ( ! is_array( $where ) ) {\n			return false;\n		}\n\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$conditions = $values = array();\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"DELETE FROM `$table` WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Processes arrays of field/value pairs and field formats.\n	 *\n	 * This is a helper method for wpdb\'s CRUD methods, which take field/value\n	 * pairs for inserts, updates, and where clauses. This method first pairs\n	 * each value with a format. Then it determines the charset of that field,\n	 * using that to determine if any invalid text would be stripped. If text is\n	 * stripped, then field processing is rejected and the query fails.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param array  $data   Field/value pair.\n	 * @param mixed  $format Format for each field.\n	 * @return array|false Returns an array of fields that contain paired values\n	 *                    and formats. Returns false for invalid values.\n	 */\n	protected function process_fields( $table, $data, $format ) {\n		$data = $this-&gt;process_field_formats( $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_charsets( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_lengths( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$converted_data = $this-&gt;strip_invalid_text( $data );\n\n		if ( $data !== $converted_data ) {\n			return false;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Prepares arrays of value/format pairs as passed to wpdb CRUD methods.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data   Array of fields to values.\n	 * @param mixed $format Formats to be mapped to the values in $data.\n	 * @return array Array, keyed by field names with values being an array\n	 *               of \'value\' and \'format\' keys.\n	 */\n	protected function process_field_formats( $data, $format ) {\n		$formats = $original_formats = (array) $format;\n\n		foreach ( $data as $field =&gt; $value ) {\n			$value = array(\n				\'value\'  =&gt; $value,\n				\'format\' =&gt; \'%s\',\n			);\n\n			if ( ! empty( $format ) ) {\n				$value[\'format\'] = array_shift( $formats );\n				if ( ! $value[\'format\'] ) {\n					$value[\'format\'] = reset( $original_formats );\n				}\n			} elseif ( isset( $this-&gt;field_types[ $field ] ) ) {\n				$value[\'format\'] = $this-&gt;field_types[ $field ];\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Adds field charsets to field/value/format arrays generated by\n	 * the wpdb::process_field_formats() method.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_formats() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'charset\' keys.\n	 */\n	protected function process_field_charsets( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'charset\'] = false;\n			} else {\n				$value[\'charset\'] = $this-&gt;get_col_charset( $table, $field );\n				if ( is_wp_error( $value[\'charset\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * For string fields, record the maximum string length that field can safely save.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_charsets() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'length\' keys, or false if\n	 *                     any of the values were too long for their corresponding field.\n	 */\n	protected function process_field_lengths( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'length\'] = false;\n			} else {\n				$value[\'length\'] = $this-&gt;get_col_length( $table, $field );\n				if ( is_wp_error( $value[\'length\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Retrieve one variable from the database.\n	 *\n	 * Executes a SQL query and returns the value from the SQL result.\n	 * If the SQL result contains more than one column and/or more than one row, this function returns the value in the column and row specified.\n	 * If $query is null, this function returns the value in the specified column and row from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to null, use the result from the previous query.\n	 * @param int         $x     Optional. Column of value to return. Indexed from 0.\n	 * @param int         $y     Optional. Row of value to return. Indexed from 0.\n	 * @return string|null Database query result (as string), or null on failure\n	 */\n	public function get_var( $query = null, $x = 0, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_var(\\\"$query\\\", $x, $y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		// Extract var out of cached results based x,y vals\n		if ( ! empty( $this-&gt;last_result[ $y ] ) ) {\n			$values = array_values( get_object_vars( $this-&gt;last_result[ $y ] ) );\n		}\n\n		// If there is a value return it else return null\n		return ( isset( $values[ $x ] ) &amp;&amp; $values[ $x ] !== \'\' ) ? $values[ $x ] : null;\n	}\n\n	/**\n	 * Retrieve one row from the database.\n	 *\n	 * Executes a SQL query and returns the row from the SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query  SQL query.\n	 * @param string      $output Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which correspond to\n	 *     an stdClass object, an associative array, or a numeric array, respectively. Default OBJECT.\n	 * @param int         $y      Optional. Row to return. Indexed from 0.\n	 * @return array|object|null|void Database query result in format specified by $output or null on failure\n	 */\n	public function get_row( $query = null, $output = OBJECT, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_row(\\\"$query\\\",$output,$y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		if ( ! isset( $this-&gt;last_result[ $y ] ) ) {\n			return null;\n		}\n\n		if ( $output == OBJECT ) {\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} elseif ( $output == ARRAY_A ) {\n			return $this-&gt;last_result[ $y ] ? get_object_vars( $this-&gt;last_result[ $y ] ) : null;\n		} elseif ( $output == ARRAY_N ) {\n			return $this-&gt;last_result[ $y ] ? array_values( get_object_vars( $this-&gt;last_result[ $y ] ) ) : null;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} else {\n			$this-&gt;print_error( \' $db-&gt;get_row(string query, output type, int offset) -- Output type must be one of: OBJECT, ARRAY_A, ARRAY_N\' );\n		}\n	}\n\n	/**\n	 * Retrieve one column from the database.\n	 *\n	 * Executes a SQL query and returns the column from the SQL result.\n	 * If the SQL result contains more than one column, this function returns the column specified.\n	 * If $query is null, this function returns the specified column from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to previous query.\n	 * @param int         $x     Optional. Column to return. Indexed from 0.\n	 * @return array Database query result. Array indexed from 0 by SQL result row number.\n	 */\n	public function get_col( $query = null, $x = 0 ) {\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		$new_array = array();\n		// Extract the column values\n		if ( $this-&gt;last_result ) {\n			for ( $i = 0, $j = count( $this-&gt;last_result ); $i &lt; $j; $i++ ) {\n				$new_array[ $i ] = $this-&gt;get_var( null, $x, $i );\n			}\n		}\n		return $new_array;\n	}\n\n	/**\n	 * データベースからSQL結果セット全体（つまり多数の行）を取得します。\n	 *\n	 * SQLクエリを実行し、SQL結果全体を返します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query  SQL query.\n	 * @param string $output Optional. Any of ARRAY_A | ARRAY_N | OBJECT | OBJECT_K constants.\n	 *最初の3つのうちの1つでは、SQL結果の行番号によって0からインデックスされた行の配列を返します。\n	 *各行は連想配列（column =&gt; value、...）、数値インデックス配列（0 =&gt; value、...）、またはオブジェクトです。 （ - &gt; column = value）\n	 *OBJECT_Kを使用すると、各行の最初の列の値によってキー設定された行オブジェクトの連想配列を返します。\n	 *重複したキーは破棄されます。\n	 * @return 配列|オブジェクト|null データベースクエリ結果\n	 */\n	public function get_results( $query = null, $output = OBJECT ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_results(\\\"$query\\\", $output)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		$new_array = array();\n		if ( $output == OBJECT ) {\n			// Return an integer-keyed array of row objects\n			return $this-&gt;last_result;\n		} elseif ( $output == OBJECT_K ) {\n			// Return an array of row objects with keys from column 1\n			// (Duplicates are discarded)\n			if ( $this-&gt;last_result ) {\n				foreach ( $this-&gt;last_result as $row ) {\n					$var_by_ref = get_object_vars( $row );\n					$key        = array_shift( $var_by_ref );\n					if ( ! isset( $new_array[ $key ] ) ) {\n						$new_array[ $key ] = $row;\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( $output == ARRAY_A || $output == ARRAY_N ) {\n			// Return an integer-keyed array of...\n			if ( $this-&gt;last_result ) {\n				foreach ( (array) $this-&gt;last_result as $row ) {\n					if ( $output == ARRAY_N ) {\n						// ...integer-keyed row arrays\n						$new_array[] = array_values( get_object_vars( $row ) );\n					} else {\n						// ...column name-keyed row arrays\n						$new_array[] = get_object_vars( $row );\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result;\n		}\n		return null;\n	}\n\n	/**\n	 * Retrieves the character set for the given table.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table Table name.\n	 * @return string|WP_Error Table character set, WP_Error object if it couldn\'t be found.\n	 */\n	protected function get_table_charset( $table ) {\n		$tablekey = strtolower( $table );\n\n		/**\n		 * Filters the table charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will effectively short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 */\n		$charset = apply_filters( \'pre_get_table_charset\', null, $table );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		if ( isset( $this-&gt;table_charset[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		$charsets = $columns = array();\n\n		$table_parts = explode( \'.\', $table );\n		$table       = \'`\' . implode( \'`.`\', $table_parts ) . \'`\';\n		$results     = $this-&gt;get_results( \"SHOW FULL COLUMNS FROM $table\" );\n		if ( ! $results ) {\n			return new WP_Error( \'wpdb_get_table_charset_failure\' );\n		}\n\n		foreach ( $results as $column ) {\n			$columns[ strtolower( $column-&gt;Field ) ] = $column;\n		}\n\n		$this-&gt;col_meta[ $tablekey ] = $columns;\n\n		foreach ( $columns as $column ) {\n			if ( ! empty( $column-&gt;Collation ) ) {\n				list( $charset ) = explode( \'_\', $column-&gt;Collation );\n\n				// If the current connection can\'t support utf8mb4 characters, let\'s only send 3-byte utf8 characters.\n				if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n					$charset = \'utf8\';\n				}\n\n				$charsets[ strtolower( $charset ) ] = true;\n			}\n\n			list( $type ) = explode( \'(\', $column-&gt;Type );\n\n			// A binary/blob means the whole query gets treated like this.\n			if ( in_array( strtoupper( $type ), array( \'BINARY\', \'VARBINARY\', \'TINYBLOB\', \'MEDIUMBLOB\', \'BLOB\', \'LONGBLOB\' ) ) ) {\n				$this-&gt;table_charset[ $tablekey ] = \'binary\';\n				return \'binary\';\n			}\n		}\n\n		// utf8mb3 is an alias for utf8.\n		if ( isset( $charsets[\'utf8mb3\'] ) ) {\n			$charsets[\'utf8\'] = true;\n			unset( $charsets[\'utf8mb3\'] );\n		}\n\n		// Check if we have more than one charset in play.\n		$count = count( $charsets );\n		if ( 1 === $count ) {\n			$charset = key( $charsets );\n		} elseif ( 0 === $count ) {\n			// No charsets, assume this table can store whatever.\n			$charset = false;\n		} else {\n			// More than one charset. Remove latin1 if present and recalculate.\n			unset( $charsets[\'latin1\'] );\n			$count = count( $charsets );\n			if ( 1 === $count ) {\n				// Only one charset (besides latin1).\n				$charset = key( $charsets );\n			} elseif ( 2 === $count &amp;&amp; isset( $charsets[\'utf8\'], $charsets[\'utf8mb4\'] ) ) {\n				// Two charsets, but they\'re utf8 and utf8mb4, use utf8.\n				$charset = \'utf8\';\n			} else {\n				// Two mixed character sets. ascii.\n				$charset = \'ascii\';\n			}\n		}\n\n		$this-&gt;table_charset[ $tablekey ] = $charset;\n		return $charset;\n	}\n\n	/**\n	 * Retrieves the character set for the given column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return string|false|WP_Error Column character set as a string. False if the column has no\n	 *        character set. WP_Error object if there was an error.\n	 */\n	public function get_col_charset( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		/**\n		 * Filters the column charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 * @param string $column  The name of the column being checked.\n		 */\n		$charset = apply_filters( \'pre_get_col_charset\', null, $table, $column );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;table_charset[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		// If still no column information, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// If this column doesn\'t exist, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// Return false when it\'s not a string column.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation ) ) {\n			return false;\n		}\n\n		list( $charset ) = explode( \'_\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation );\n		return $charset;\n	}\n\n	/**\n	 * Retrieve the maximum string length allowed in a given column.\n	 * The length may either be specified as a byte length or a character length.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return array|false|WP_Error array( \'length\' =&gt; (int), \'type\' =&gt; \'byte\' | \'char\' )\n	 *       false if the column has no length (for example, numeric column)\n	 *       WP_Error object if there was an error.\n	 */\n	public function get_col_length( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return false;\n		}\n\n		$typeinfo = explode( \'(\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Type );\n\n		$type = strtolower( $typeinfo[0] );\n		if ( ! empty( $typeinfo[1] ) ) {\n			$length = trim( $typeinfo[1], \')\' );\n		} else {\n			$length = false;\n		}\n\n		switch ( $type ) {\n			case \'char\':\n			case \'varchar\':\n				return array(\n					\'type\'   =&gt; \'char\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'binary\':\n			case \'varbinary\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'tinyblob\':\n			case \'tinytext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 255,        // 2^8 - 1\n				);\n\n			case \'blob\':\n			case \'text\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 65535,      // 2^16 - 1\n				);\n\n			case \'mediumblob\':\n			case \'mediumtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 167772,   // 2^24 - 1\n				);\n\n			case \'longblob\':\n			case \'longtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 4294967295, // 2^32 - 1\n				);\n\n			default:\n				return false;\n		}\n	}\n\n	/**\n	 * Check if a string is ASCII.\n	 *\n	 * The negative regex is faster for non-ASCII strings, as it allows\n	 * the search to finish as soon as it encounters a non-ASCII character.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $string String to check.\n	 * @return bool True if ASCII, false if not.\n	 */\n	protected function check_ascii( $string ) {\n		if ( function_exists( \'mb_check_encoding\' ) ) {\n			if ( mb_check_encoding( $string, \'ASCII\' ) ) {\n				return true;\n			}\n		} elseif ( ! preg_match( \'/[^\\x00-\\x7F]/\', $string ) ) {\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Check if the query is accessing a collation considered safe on the current version of MySQL.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to check.\n	 * @return bool True if the collation is safe, false if it isn\'t.\n	 */\n	protected function check_safe_collation( $query ) {\n		if ( $this-&gt;checking_collation ) {\n			return true;\n		}\n\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $query ) ) {\n			return true;\n		}\n\n		// All-ASCII queries don\'t need extra checking.\n		if ( $this-&gt;check_ascii( $query ) ) {\n			return true;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( ! $table ) {\n			return false;\n		}\n\n		$this-&gt;checking_collation = true;\n		$collation                = $this-&gt;get_table_charset( $table );\n		$this-&gt;checking_collation = false;\n\n		// Tables with no collation, or latin1 only, don\'t need extra checking.\n		if ( false === $collation || \'latin1\' === $collation ) {\n			return true;\n		}\n\n		$table = strtolower( $table );\n		if ( empty( $this-&gt;col_meta[ $table ] ) ) {\n			return false;\n		}\n\n		// If any of the columns don\'t have one of these collations, it needs more sanity checking.\n		foreach ( $this-&gt;col_meta[ $table ] as $col ) {\n			if ( empty( $col-&gt;Collation ) ) {\n				continue;\n			}\n\n			if ( ! in_array( $col-&gt;Collation, array( \'utf8_general_ci\', \'utf8_bin\', \'utf8mb4_general_ci\', \'utf8mb4_bin\' ), true ) ) {\n				return false;\n			}\n		}\n\n		return true;\n	}\n\n	/**\n	 * Strips any invalid characters based on value/charset pairs.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data Array of value arrays. Each value array has the keys\n	 *                    \'value\' and \'charset\'. An optional \'ascii\' key can be\n	 *                    set to false to avoid redundant ASCII checks.\n	 * @return array|WP_Error The $data parameter, with invalid characters removed from\n	 * each value. This works as a passthrough: any additional keys\n	 * such as \'field\' are retained in each value array. If we cannot\n	 * remove invalid characters, a WP_Error object is returned.\n	 */\n	protected function strip_invalid_text( $data ) {\n		$db_check_string = false;\n\n		foreach ( $data as &amp;$value ) {\n			$charset = $value[\'charset\'];\n\n			if ( is_array( $value[\'length\'] ) ) {\n				$length                  = $value[\'length\'][\'length\'];\n				$truncate_by_byte_length = \'byte\' === $value[\'length\'][\'type\'];\n			} else {\n				$length = false;\n				// Since we have no length, we\'ll never truncate.\n				// Initialize the variable to false. true would take us\n				// through an unnecessary (for this case) codepath below.\n				$truncate_by_byte_length = false;\n			}\n\n			// There\'s no charset to work with.\n			if ( false === $charset ) {\n				continue;\n			}\n\n			// Column isn\'t a string.\n			if ( ! is_string( $value[\'value\'] ) ) {\n				continue;\n			}\n\n			$needs_validation = true;\n			if (\n				// latin1 can store any byte sequence\n				\'latin1\' === $charset\n			||\n				// ASCII is always OK.\n				( ! isset( $value[\'ascii\'] ) &amp;&amp; $this-&gt;check_ascii( $value[\'value\'] ) )\n			) {\n				$truncate_by_byte_length = true;\n				$needs_validation        = false;\n			}\n\n			if ( $truncate_by_byte_length ) {\n				mbstring_binary_safe_encoding();\n				if ( false !== $length &amp;&amp; strlen( $value[\'value\'] ) &gt; $length ) {\n					$value[\'value\'] = substr( $value[\'value\'], 0, $length );\n				}\n				reset_mbstring_encoding();\n\n				if ( ! $needs_validation ) {\n					continue;\n				}\n			}\n\n			// utf8 can be handled by regex, which is a bunch faster than a DB lookup.\n			if ( ( \'utf8\' === $charset || \'utf8mb3\' === $charset || \'utf8mb4\' === $charset ) &amp;&amp; function_exists( \'mb_strlen\' ) ) {\n				$regex = \'/\n					(\n						(?: [\\x00-\\x7F]                  # single-byte sequences   0xxxxxxx\n						|   [\\xC2-\\xDF][\\x80-\\xBF]       # double-byte sequences   110xxxxx 10xxxxxx\n						|   \\xE0[\\xA0-\\xBF][\\x80-\\xBF]   # triple-byte sequences   1110xxxx 10xxxxxx * 2\n						|   [\\xE1-\\xEC][\\x80-\\xBF]{2}\n						|   \\xED[\\x80-\\x9F][\\x80-\\xBF]\n						|   [\\xEE-\\xEF][\\x80-\\xBF]{2}\';\n\n				if ( \'utf8mb4\' === $charset ) {\n					$regex .= \'\n						|    \\xF0[\\x90-\\xBF][\\x80-\\xBF]{2} # four-byte sequences   11110xxx 10xxxxxx * 3\n						|    [\\xF1-\\xF3][\\x80-\\xBF]{3}\n						|    \\xF4[\\x80-\\x8F][\\x80-\\xBF]{2}\n					\';\n				}\n\n				$regex         .= \'){1,40}   # ...one or more times\n					)\n					| .           # anything else\n					/x\';\n				$value[\'value\'] = preg_replace( $regex, \'$1\', $value[\'value\'] );\n\n				if ( false !== $length &amp;&amp; mb_strlen( $value[\'value\'], \'UTF-8\' ) &gt; $length ) {\n					$value[\'value\'] = mb_substr( $value[\'value\'], 0, $length, \'UTF-8\' );\n				}\n				continue;\n			}\n\n			// We couldn\'t use any local conversions, send it to the DB.\n			$value[\'db\'] = $db_check_string = true;\n		}\n		unset( $value ); // Remove by reference.\n\n		if ( $db_check_string ) {\n			$queries = array();\n			foreach ( $data as $col =&gt; $value ) {\n				if ( ! empty( $value[\'db\'] ) ) {\n					// We\'re going to need to truncate by characters or bytes, depending on the length value we have.\n					if ( \'byte\' === $value[\'length\'][\'type\'] ) {\n						// Using binary causes LEFT() to truncate by bytes.\n						$charset = \'binary\';\n					} else {\n						$charset = $value[\'charset\'];\n					}\n\n					if ( $this-&gt;charset ) {\n						$connection_charset = $this-&gt;charset;\n					} else {\n						if ( $this-&gt;use_mysqli ) {\n							$connection_charset = mysqli_character_set_name( $this-&gt;dbh );\n						} else {\n							$connection_charset = mysql_client_encoding();\n						}\n					}\n\n					if ( is_array( $value[\'length\'] ) ) {\n						$length          = sprintf( \'%.0f\', $value[\'length\'][\'length\'] );\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( LEFT( CONVERT( %s USING $charset ), $length ) USING $connection_charset )\", $value[\'value\'] );\n					} elseif ( \'binary\' !== $charset ) {\n						// If we don\'t have a length, there\'s no need to convert binary - it will always return the same result.\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( CONVERT( %s USING $charset ) USING $connection_charset )\", $value[\'value\'] );\n					}\n\n					unset( $data[ $col ][\'db\'] );\n				}\n			}\n\n			$sql = array();\n			foreach ( $queries as $column =&gt; $query ) {\n				if ( ! $query ) {\n					continue;\n				}\n\n				$sql[] = $query . \" AS x_$column\";\n			}\n\n			$this-&gt;check_current_query = false;\n			$row= $this-&gt;get_row( \'SELECT \' . implode( \', \', $sql ), ARRAY_A );\n			if ( ! $row ) {\n				return new WP_Error( \'wpdb_strip_invalid_text_failure\' );\n			}\n\n			foreach ( array_keys( $data ) as $column ) {\n				if ( isset( $row[ \"x_$column\" ] ) ) {\n					$data[ $column ][\'value\'] = $row[ \"x_$column\" ];\n				}\n			}\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Strips any invalid characters from the query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query Query to convert.\n	 * @return string|WP_Error The converted query, or a WP_Error object if the conversion fails.\n	 */\n	protected function strip_invalid_text_from_query( $query ) {\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$trimmed_query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $trimmed_query ) ) {\n			return $query;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( $table ) {\n			$charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $charset ) ) {\n				return $charset;\n			}\n\n			// We can\'t reliably strip text from tables containing binary/blob columns\n			if ( \'binary\' === $charset ) {\n				return $query;\n			}\n		} else {\n			$charset = $this-&gt;charset;\n		}\n\n		$data = array(\n			\'value\'   =&gt; $query,\n			\'charset\' =&gt; $charset,\n			\'ascii\'   =&gt; false,\n			\'length\'  =&gt; false,\n		);\n\n		$data = $this-&gt;strip_invalid_text( array( $data ) );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[0][\'value\'];\n	}\n\n	/**\n	 * Strips any invalid characters from the string for a given table and column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @param string $value  The text to check.\n	 * @return string|WP_Error The converted string, or a WP_Error object if the conversion fails.\n	 */\n	public function strip_invalid_text_for_column( $table, $column, $value ) {\n		if ( ! is_string( $value ) ) {\n			return $value;\n		}\n\n		$charset = $this-&gt;get_col_charset( $table, $column );\n		if ( ! $charset ) {\n			// Not a string column.\n			return $value;\n		} elseif ( is_wp_error( $charset ) ) {\n			// Bail on real errors.\n			return $charset;\n		}\n\n		$data = array(\n			$column =&gt; array(\n				\'value\'   =&gt; $value,\n				\'charset\' =&gt; $charset,\n				\'length\'  =&gt; $this-&gt;get_col_length( $table, $column ),\n			),\n		);\n\n		$data = $this-&gt;strip_invalid_text( $data );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[ $column ][\'value\'];\n	}\n\n	/**\n	 * Find the first table name referenced in a query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to search.\n	 * @return string|false $table The table name found, or false if a table couldn\'t be found.\n	 */\n	protected function get_table_from_query( $query ) {\n		// Remove characters that can legally trail the table name.\n		$query = rtrim( $query, \';/-#\' );\n\n		// Allow (select...) union [...] style queries. Use the first query\'s table name.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n\n		// Strip everything between parentheses except nested selects.\n		$query = preg_replace( \'/\\((?!\\s*select)[^(]*?\\)/is\', \'()\', $query );\n\n		// Quickly match most common queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'SELECT.*?\\s+FROM\'\n				. \'|INSERT(?:\\s+LOW_PRIORITY|\\s+DELAYED|\\s+HIGH_PRIORITY)?(?:\\s+IGNORE)?(?:\\s+INTO)?\'\n				. \'|REPLACE(?:\\s+LOW_PRIORITY|\\s+DELAYED)?(?:\\s+INTO)?\'\n				. \'|UPDATE(?:\\s+LOW_PRIORITY)?(?:\\s+IGNORE)?\'\n				. \'|DELETE(?:\\s+LOW_PRIORITY|\\s+QUICK|\\s+IGNORE)*(?:.+?FROM)?\'\n			. \')\\s+((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		// SHOW TABLE STATUS and SHOW TABLES WHERE Name = \'wp_posts\'\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES).+WHERE\\s+Name\\s*=\\s*(\"|\\\')((?:[0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\\\1/is\', $query, $maybe ) ) {\n			return $maybe[2];\n		}\n\n		// SHOW TABLE STATUS LIKE and SHOW TABLES LIKE \'wp\\_3\\_%\'\n		// This quoted LIKE operand seldom holds a full table name.\n		// It is usually a pattern for matching a prefix so we just\n		// strip the trailing % and unescape the _ to get \'wp_3_\'\n		// which drop-ins can use for routing these SQL statements.\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES)\\s+(?:WHERE\\s+Name\\s+)?LIKE\\s*(\"|\\\')((?:[\\\\\\\\0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)%?\\\\1/is\', $query, $maybe ) ) {\n			return str_replace( \'\\\\_\', \'_\', $maybe[2] );\n		}\n\n		// Big pattern for the rest of the table-related queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'(?:EXPLAIN\\s+(?:EXTENDED\\s+)?)?SELECT.*?\\s+FROM\'\n				. \'|DESCRIBE|DESC|EXPLAIN|HANDLER\'\n				. \'|(?:LOCK|UNLOCK)\\s+TABLE(?:S)?\'\n				. \'|(?:RENAME|OPTIMIZE|BACKUP|RESTORE|CHECK|CHECKSUM|ANALYZE|REPAIR).*\\s+TABLE\'\n				. \'|TRUNCATE(?:\\s+TABLE)?\'\n				. \'|CREATE(?:\\s+TEMPORARY)?\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\'\n				. \'|ALTER(?:\\s+IGNORE)?\\s+TABLE\'\n				. \'|DROP\\s+TABLE(?:\\s+IF\\s+EXISTS)?\'\n				. \'|CREATE(?:\\s+\\w+)?\\s+INDEX.*\\s+ON\'\n				. \'|DROP\\s+INDEX.*\\s+ON\'\n				. \'|LOAD\\s+DATA.*INFILE.*INTO\\s+TABLE\'\n				. \'|(?:GRANT|REVOKE).*ON\\s+TABLE\'\n				. \'|SHOW\\s+(?:.*FROM|.*TABLE)\'\n			. \')\\s+\\(*\\s*((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\s*\\)*/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		return false;\n	}\n\n	/**\n	 * Load the column metadata from the last query.\n	 *\n	 * @since 3.5.0\n	 */\n	protected function load_col_info() {\n		if ( $this-&gt;col_info ) {\n			return;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$num_fields = mysqli_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysqli_fetch_field( $this-&gt;result );\n			}\n		} else {\n			$num_fields = mysql_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysql_fetch_field( $this-&gt;result, $i );\n			}\n		}\n	}\n\n	/**\n	 * Retrieve column metadata from the last query.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $info_type  Optional. Type one of name, table, def, max_length, not_null, primary_key, multiple_key, unique_key, numeric, blob, type, unsigned, zerofill\n	 * @param int    $col_offset Optional. 0: col name. 1: which table the col\'s in. 2: col\'s max length. 3: if the col is numeric. 4: col\'s type\n	 * @return mixed Column Results\n	 */\n	public function get_col_info( $info_type = \'name\', $col_offset = -1 ) {\n		$this-&gt;load_col_info();\n\n		if ( $this-&gt;col_info ) {\n			if ( $col_offset == -1 ) {\n				$i         = 0;\n				$new_array = array();\n				foreach ( (array) $this-&gt;col_info as $col ) {\n					$new_array[ $i ] = $col-&gt;{$info_type};\n					$i++;\n				}\n				return $new_array;\n			} else {\n				return $this-&gt;col_info[ $col_offset ]-&gt;{$info_type};\n			}\n		}\n	}\n\n	/**\n	 * Starts the timer, for debugging purposes.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return true\n	 */\n	public function timer_start() {\n		$this-&gt;time_start = microtime( true );\n		return true;\n	}\n\n	/**\n	 * Stops the debugging timer.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return float Total time spent on the query, in seconds\n	 */\n	public function timer_stop() {\n		return ( microtime( true ) - $this-&gt;time_start );\n	}\n\n	/**\n	 * エラーを素敵なヘッダーとフッターにラップして終わります。\n	 *\n	 * wpdb :: $ show_errorsがfalseであれば死にません。\n	 *\n	 * @since 1.5.0\n	 *\n	 * @param string $message    The Error message\n	 * @param string $error_code Optional. エラーを識別するためのコンピュータ可読文字列。\n	 * @return false|void\n	 */\n	public function bail( $message, $error_code = \'500\' ) {\n		if ( $this-&gt;show_errors ) {\n			$error = \'\';\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$error = mysqli_error( $this-&gt;dbh );\n				} elseif ( mysqli_connect_errno() ) {\n					$error = mysqli_connect_error();\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$error = mysql_error( $this-&gt;dbh );\n				} else {\n					$error = mysql_error();\n				}\n			}\n\n			if ( $error ) {\n				$message = \'&lt;p&gt;&lt;code&gt;\' . $error . \"&lt;/code&gt;&lt;/p&gt;\\n\" . $message;\n			}\n\n			wp_die( $message );\n		} else {\n			if ( class_exists( \'WP_Error\', false ) ) {\n				$this-&gt;error = new WP_Error( $error_code, $message );\n			} else {\n				$this-&gt;error = $message;\n			}\n\n			return false;\n		}\n	}\n\n\n	/**\n	 * 現在のデータベース接続を閉じます。\n	 *\n	 * @since 4.5.0\n	 *\n	 * @return bool True if the connection was successfully closed, false if it wasn\'t,\n	 *              or the connection doesn\'t exist.\n	 */\n	public function close() {\n		if ( ! $this-&gt;dbh ) {\n			return false;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$closed = mysqli_close( $this-&gt;dbh );\n		} else {\n			$closed = mysql_close( $this-&gt;dbh );\n		}\n\n		if ( $closed ) {\n			$this-&gt;dbh           = null;\n			$this-&gt;ready         = false;\n			$this-&gt;has_connected = false;\n		}\n\n		return $closed;\n	}\n\n	/**\n	 * MySQLデータベースが最低限必要な最小バージョンかどうか\n	 *\n	 * @since 2.5.0\n	 *\n	 * @global string $wp_version\n	 * @global string $required_mysql_version\n	 *\n	 * @return WP_Error|void\n	 */\n	public function check_database_version() {\n		global $wp_version, $required_mysql_version;\n		// サーバーに必要なMySQLバージョンがあることを確認してください。\n		if ( version_compare( $this-&gt;db_version(), $required_mysql_version, \'&lt;\' ) ) {\n			/* translators: 1: WordPress version number, 2: Minimum required MySQL version number */\n			return new WP_Error( \'database_version\', sprintf( __( \'&lt;strong&gt;ERROR&lt;/strong&gt;: WordPress %1$s requires MySQL %2$s or higher\' ), $wp_version, $required_mysql_version ) );\n		}\n	}\n\n	/**\n	 * データベースが照合をサポートしているかどうか\n	 *\n	 * WordPressがテーブルスキームを生成しているときに呼び出されます。\n	 *\n	 * Use `wpdb::has_cap( \'collation\' )`.\n	 *\n	 * @since 2.5.0\n	 * @deprecated 3.5.0 Use wpdb::has_cap()\n	 *\n	 * @return bool True if collation is supported, false if version does not\n	 */\n	public function supports_collation() {\n		_deprecated_function( __FUNCTION__, \'3.5.0\', \'wpdb::has_cap( \\\'collation\\\' )\' );\n		return $this-&gt;has_cap( \'collation\' );\n	}\n\n	/**\n	 * データベース文字の照合\n	 *\n	 * @since 3.5.0\n	 *\n	 * @return string The database character collate.\n	 */\n	public function get_charset_collate() {\n		$charset_collate = \'\';\n\n		if ( ! empty( $this-&gt;charset ) ) {\n			$charset_collate = \"DEFAULT CHARACTER SET $this-&gt;charset\";\n		}\n		if ( ! empty( $this-&gt;collate ) ) {\n			$charset_collate .= \" COLLATE $this-&gt;collate\";\n		}\n\n		return $charset_collate;\n	}\n\n	/**\n	 * データベースが特定の機能をサポートしているかどうかを確認します。\n	 *\n	 * @since 2.7.0\n	 * @since 4.1.0 Added support for the \'utf8mb4\' feature.\n	 * @since 4.6.0 Added support for the \'utf8mb4_520\' feature.\n	 *\n	 * @see wpdb::db_version()\n	 *\n	 * @param string $db_cap The feature to check for. Accepts \'collation\',\n	 *\'group_concat\', \'subqueries\', \'set_charset\',\n	 *\'utf8mb4\', or \'utf8mb4_520\'.\n	 * @return int|false Whether the database feature is supported, false otherwise.\n	 */\n	public function has_cap( $db_cap ) {\n		$version = $this-&gt;db_version();\n\n		switch ( strtolower( $db_cap ) ) {\n			case \'collation\':    // @since 2.5.0\n			case \'group_concat\': // @since 2.7.0\n			case \'subqueries\':   // @since 2.7.0\n				return version_compare( $version, \'4.1\', \'&gt;=\' );\n			case \'set_charset\':\n				return version_compare( $version, \'5.0.7\', \'&gt;=\' );\n			case \'utf8mb4\':      // @since 4.1.0\n				if ( version_compare( $version, \'5.5.3\', \'&lt;\' ) ) {\n					return false;\n				}\n				if ( $this-&gt;use_mysqli ) {\n					$client_version = mysqli_get_client_info();\n				} else {\n					$client_version = mysql_get_client_info();\n				}\n\n				/*\n				 * libmysql has supported utf8mb4 since 5.5.3, same as the MySQL server.\n				 * mysqlnd has supported utf8mb4 since 5.0.9.\n				 */\n				if ( false !== strpos( $client_version, \'mysqlnd\' ) ) {\n					$client_version = preg_replace( \'/^\\D+([\\d.]+).*/\', \'$1\', $client_version );\n					return version_compare( $client_version, \'5.0.9\', \'&gt;=\' );\n				} else {\n					return version_compare( $client_version, \'5.5.3\', \'&gt;=\' );\n				}\n			case \'utf8mb4_520\': // @since 4.6.0\n				return version_compare( $version, \'5.6\', \'&gt;=\' );\n		}\n\n		return false;\n	}\n\n	/**\n	 * wpdbを呼び出した関数の名前を取得してください。\n	 *\n	 * Searches up the list of functions until it reaches\n	 * the one that would most logically had called this method.\n	 *\n	 * @since 2.5.0\n	 *\n	 * @return string Comma separated list of the calling functions.\n	 */\n	public function get_caller() {\n		return wp_debug_backtrace_summary( __CLASS__ );\n	}\n\n	/**\n	 * MySQLサーバーのバージョンを取得します。\n	 *\n	 * @since 2.7.0\n	 *\n	 * @return null|string Null on failure, version number on success.\n	 */\n	public function db_version() {\n		if ( $this-&gt;use_mysqli ) {\n			$server_info = mysqli_get_server_info( $this-&gt;dbh );\n		} else {\n			$server_info = mysql_get_server_info( $this-&gt;dbh );\n		}\n		return preg_replace( \'/[^0-9.].*/\', \'\', $server_info );\n	}\n}\n</pre>\n<p> </p>','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-04 18:41:30','2019-06-04 09:41:30','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2480,1,'2019-06-11 13:29:57','2019-06-11 04:29:57','<p>このファイルはデータベースに接続してデータを取得したりインサートするファイルになります。</p>\n<p>MVCモデルで言うとmodelにあたるような役割をこのファイルで行っています。</p>\n<p>なお、このファイルは全部で(コメント込みで)3500行ほどあるので分割して読んでいきます。</p>\n<p> </p>\n<pre class=\"lang:php decode:true \" title=\"wp-db.php\">&lt;?php\n/**\n * WordPress DBクラス\n *\n * 元のコード  {@link http://php.justinvincent.com Justin Vincent (justin@visunet.ie)}\n *\n * @package WordPress\n * @subpackage Database\n * @since 0.71\n */\n\n/**\n * @since 0.71\n */\ndefine( \'EZSQL_VERSION\', \'WP1.25\' );\n\n/**\n * @since 0.71\n */\ndefine( \'OBJECT\', \'OBJECT\' );\n// phpcs:ignore Generic.NamingConventions.UpperCaseConstantName.ConstantNotUpperCase\ndefine( \'object\', \'OBJECT\' ); // Back compat.\n\n/**\n * @since 2.5.0\n */\ndefine( \'OBJECT_K\', \'OBJECT_K\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_A\', \'ARRAY_A\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_N\', \'ARRAY_N\' );\n\n/**\n * WordPressデータベースアクセス抽象化オブジェクト\n *\n * wp-content / db.phpファイルの$ wpdbグローバル変数を\n * あなたのクラスに設定することで、このクラスをあなた自身のクラスに\n * 置き換えることが可能です。\n *\n * @link https://codex.wordpress.org/Function_Reference/wpdb_Class\n *\n * @since 0.71\n */\nclass wpdb {\n\n	/**\n	 * SQL / DBエラーを表示するかどうか\n	 *\n	 * デフォルトの動作では、WP_DEBUGとWP_DEBUG_DISPLAYの両方がtrueと評価された場合に\n	 * エラーを表示します。\n	 *\n	 * @since 0.71\n	 * @var bool\n	 */\n	var $show_errors = false;\n\n	/**\n	 * DBブートストラップ中のエラーを抑制するかどうか。\n	 *\n	 * @since 2.5.0\n	 * @var bool\n	 */\n	var $suppress_errors = false;\n\n	/**\n	 * クエリ中の最後のエラー\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $last_error = \'\';\n\n	/**\n	 * 行われたクエリの量\n	 *\n	 * @since 1.2.0\n	 * @var int\n	 */\n	public $num_queries = 0;\n\n	/**\n	 * 前のクエリによって返された行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $num_rows = 0;\n\n	/**\n	 * 前の照会による影響を受けた行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	var $rows_affected = 0;\n\n	/**\n	 * 前回のクエリによってAUTO_INCREMENTカラムに対して生成されたID（通常はINSERT）。\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $insert_id = 0;\n\n	/**\n	 * 最後に行われたクエリ\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	var $last_query;\n\n	/**\n	 * 最後に行われたクエリの結果\n	 *\n	 * @since 0.71\n	 * @var array|null\n	 */\n	var $last_result;\n\n	/**\n	 * MySQLの結果。これはリソースまたはブール値です。\n	 *\n	 * @since 0.71\n	 * @var mixed\n	 */\n	protected $result;\n\n	/**\n	 * 挿入前のサニティチェックデータ用のキャッシュされた列情報\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $col_meta = array();\n\n	/**\n	 * テーブルの計算文字セット\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $table_charset = array();\n\n	/**\n	 * 現在のクエリのテキストフィールドを健全性チェックする必要があるかどうか。\n	 *\n	 * @since 4.2.0\n	 * @var bool\n	 */\n	protected $check_current_query = true;\n\n	/**\n	 * 照合をチェックするときに再帰問題に遭遇しないようにするためのフラグ。\n	 *\n	 * @since 4.2.0\n	 * @see wpdb::check_safe_collation()\n	 * @var bool\n	 */\n	private $checking_collation = false;\n\n	/**\n	 * テーブルカラムに保存された情報\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	protected $col_info;\n\n	/**\n	 * デバッグ目的で実行されたクエリのログ。\n	 *\n	 * @since 1.5.0\n	 * @since 2.5.0 各クエリログの3番目の要素は、呼び出し元の関数を記録するために追加されました。\n	 * @since 5.1.0 各クエリログの4番目の要素は、開始時刻を記録するために追加されました。\n	 *\n	 * @var array[] {\n	 *     実行されたクエリの配列。\n	 *\n	 *     @type array ...$0 {\n	 *         Data for each query.\n	 *\n	 *         @type string $0 The query\'s SQL.\n	 *         @type float  $1 照会に費やした合計時間（秒単位）。\n	 *         @type string $2 呼び出し側関数のコンマ区切りリスト。\n	 *         @type float  $3 問い合わせの開始時のUnixタイムスタンプ。\n	 *     }\n	 * }\n	 */\n	var $queries;\n\n	/**\n	 * 死ぬまでに再接続を再試行する回数\n	 *\n	 * @since 3.9.0\n	 * @see wpdb::check_connection()\n	 * @var int\n	 */\n	protected $reconnect_retries = 5;\n\n	/**\n	 * WordPressのテーブルプレフィックス\n	 *\n	 * 単一のデータベースに複数のWordPressをインストールするように設定できます。\n	 * 2番目の理由は、考えられるセキュリティ上の予防策です。\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $prefix = \'\';\n\n	/**\n	 * WordPressのベーステーブルプレフィックス。\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $base_prefix;\n\n	/**\n	 * Whether the database queries are ready to start executing.\n	 *\n	 * @since 2.3.2\n	 * @var bool\n	 */\n	var $ready = false;\n\n	/**\n	 * Blog ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $blogid = 0;\n\n	/**\n	 * Site ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $siteid = 0;\n\n	/**\n	 * ブログ毎のWordPress一覧表\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $tables = array(\n		\'posts\',\n		\'comments\',\n		\'links\',\n		\'options\',\n		\'postmeta\',\n		\'terms\',\n		\'term_taxonomy\',\n		\'term_relationships\',\n		\'termmeta\',\n		\'commentmeta\',\n	);\n\n	/**\n	 * 廃止予定のWordPressテーブルのリスト\n	 *\n	 * categories、post2cat、およびlink2catは、2.3.0、dbバージョン5539で非推奨となりました。\n	 *\n	 * @since 2.9.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $old_tables = array( \'categories\', \'post2cat\', \'link2cat\' );\n\n	/**\n	 * WordPressグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $global_tables = array( \'users\', \'usermeta\' );\n\n	/**\n	 * マルチサイトグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $ms_global_tables = array(\n		\'blogs\',\n		\'blogmeta\',\n		\'signups\',\n		\'site\',\n		\'sitemeta\',\n		\'sitecategories\',\n		\'registration_log\',\n		\'blog_versions\',\n	);\n\n	/**\n	 * WordPress Comments table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $comments;\n\n	/**\n	 * WordPress Comment Metadata table\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	public $commentmeta;\n\n	/**\n	 * WordPress Links table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $links;\n\n	/**\n	 * WordPress Options table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $options;\n\n	/**\n	 * WordPress Post Metadata table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $postmeta;\n\n	/**\n	 * WordPress Posts table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $posts;\n\n	/**\n	 * WordPress Terms table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $terms;\n\n	/**\n	 * WordPress Term Relationships table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_relationships;\n\n	/**\n	 * WordPress Term Taxonomy table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_taxonomy;\n\n	/**\n	 * WordPress Term Meta table.\n	 *\n	 * @since 4.4.0\n	 * @var string\n	 */\n	public $termmeta;\n\n	//\n	// Global and Multisite tables\n	//\n\n	/**\n	 * WordPress User Metadata table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $usermeta;\n\n	/**\n	 * WordPress Users table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $users;\n\n	/**\n	 * Multisite Blogs table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blogs;\n\n	/**\n	 * Multisite Blog Metadata table\n	 *\n	 * @since 5.1.0\n	 * @var string\n	 */\n	public $blogmeta;\n\n	/**\n	 * Multisite Blog Versions table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blog_versions;\n\n	/**\n	 * Multisite Registration Log table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $registration_log;\n\n	/**\n	 * Multisite Signups table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $signups;\n\n	/**\n	 * Multisite Sites table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $site;\n\n	/**\n	 * Multisite Sitewide Terms table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitecategories;\n\n	/**\n	 * Multisite Site Metadata table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitemeta;\n\n	/**\n	 * DB列のフォーマット指定子ここにリストされていない列は、デフォルトで％sになります。WPロード中に初期化されました。\n	 *\n	 * キーはカラム名、値はフォーマットタイプです。 \'ID\' =&gt; \'％d\'\n	 *\n	 * @since 2.8.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::insert()\n	 * @see wpdb::update()\n	 * @see wpdb::delete()\n	 * @see wp_set_wpdb_vars()\n	 * @var array\n	 */\n	public $field_types = array();\n\n	/**\n	 * Database table columns charset\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $charset;\n\n	/**\n	 * Database table columns collate\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $collate;\n\n	/**\n	 * Database Username\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	protected $dbuser;\n\n	/**\n	 * Database Password\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbpassword;\n\n	/**\n	 * Database Name\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbname;\n\n	/**\n	 * Database Host\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbhost;\n\n	/**\n	 * Database Handle\n	 *\n	 * @since 0.71\n	 * @var string\n	 */\n	protected $dbh;\n\n	/**\n	 * 最後のクエリ/ get_row / get_var呼び出しの説明文\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $func_call;\n\n	/**\n	 * MySQLがデータベースエンジンとして使用されているかどうか。\n	 *\n	 * デフォルトでは、WPDB :: db_connect（）をtrueに設定します。 \n	 * これはWordPressに必要なMySQLバージョンをチェックするときに使われます。 \n	 * 通常、置換データベースドロップイン（db.php）はこれらのチェックをスキップしますが、\n	 * これをtrueに設定するとチェックを強制的に実行させます。\n	 *\n	 * @since 3.3.0\n	 * @var bool\n	 */\n	public $is_mysql = null;\n\n	/**\n	 * 互換性のないSQLモードのリスト。\n	 *\n	 * @since 3.9.0\n	 * @var array\n	 */\n	protected $incompatible_modes = array(\n		\'NO_ZERO_DATE\',\n		\'ONLY_FULL_GROUP_BY\',\n		\'STRICT_TRANS_TABLES\',\n		\'STRICT_ALL_TABLES\',\n		\'TRADITIONAL\',\n	);\n\n	/**\n	 * mysql上でmysqliを使用するかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $use_mysqli = false;\n\n	/**\n	 * ある時点でうまく接続できたかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $has_connected = false;\n\n	/**\n	 * データベースサーバーに接続してデータベースを選択する\n	 *\n	 * PPHP 5との互換性のためのHP 5スタイルのコンストラクタ。 Does\n	 * クラスプロパティの実際の設定とデータベースへの接続を行います。\n	 * \n	 *\n	 * @link https://core.trac.wordpress.org/ticket/3354\n	 * @since 2.0.8\n	 *\n	 * @global string $wp_version\n	 *\n	 * @param string $dbuser     MySQL database user\n	 * @param string $dbpassword MySQL database password\n	 * @param string $dbname     MySQL database name\n	 * @param string $dbhost     MySQL database host\n	 */\n	public function __construct( $dbuser, $dbpassword, $dbname, $dbhost ) {\n		register_shutdown_function( array( $this, \'__destruct\' ) );\n\n		if ( WP_DEBUG &amp;&amp; WP_DEBUG_DISPLAY ) {\n			$this-&gt;show_errors();\n		}\n\n		// WP_USE_EXT_MYSQLがtrueとして定義されていない限り、存在する場合はext / mysqliを使用\n		if ( function_exists( \'mysqli_connect\' ) ) {\n			$this-&gt;use_mysqli = true;\n\n			if ( defined( \'WP_USE_EXT_MYSQL\' ) ) {\n				$this-&gt;use_mysqli = ! WP_USE_EXT_MYSQL;\n			}\n		}\n\n		$this-&gt;dbuser     = $dbuser;\n		$this-&gt;dbpassword = $dbpassword;\n		$this-&gt;dbname     = $dbname;\n		$this-&gt;dbhost     = $dbhost;\n\n		// wp-config.phpの作成は準備ができたら手動で接続します。\n		if ( defined( \'WP_SETUP_CONFIG\' ) ) {\n			return;\n		}\n\n		$this-&gt;db_connect();\n	}\n\n	/**\n	 * PHP 5スタイルのデストラクタで、データベースオブジェクトが破棄されたときに実行されます。\n	 *\n	 * @see wpdb::__construct()\n	 * @since 2.0.8\n	 * @return true\n	 */\n	public function __destruct() {\n		return true;\n	}\n\n	/**\n	 * 下位互換性のためにプライベートプロパティを読み取り可能にします\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name The private member to get, and optionally process\n	 * @return mixed The private member\n	 */\n	public function __get( $name ) {\n		if ( \'col_info\' === $name ) {\n			$this-&gt;load_col_info();\n		}\n\n		return $this-&gt;$name;\n	}\n\n	/**\n	 *プライベートプロパティを下位互換性のために設定可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to set\n	 * @param mixed  $value The value to set\n	 */\n	public function __set( $name, $value ) {\n		$protected_members = array(\n			\'col_meta\',\n			\'table_charset\',\n			\'check_current_query\',\n		);\n		if ( in_array( $name, $protected_members, true ) ) {\n			return;\n		}\n		$this-&gt;$name = $value;\n	}\n\n	/**\n	 * プライベートプロパティを下位互換性のためにチェック可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to check\n	 *\n	 * @return bool If the member is set or not\n	 */\n	public function __isset( $name ) {\n		return isset( $this-&gt;$name );\n	}\n\n	/**\n	 * Makes private properties un-settable for backward compatibility.\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to unset\n	 */\n	public function __unset( $name ) {\n		unset( $this-&gt;$name );\n	}\n\n	/**\n	 * Set $this-&gt;charset and $this-&gt;collate\n	 *\n	 * @since 3.1.0\n	 */\n	public function init_charset() {\n		$charset = \'\';\n		$collate = \'\';\n\n		if ( function_exists( \'is_multisite\' ) &amp;&amp; is_multisite() ) {\n			$charset = \'utf8\';\n			if ( defined( \'DB_COLLATE\' ) &amp;&amp; DB_COLLATE ) {\n				$collate = DB_COLLATE;\n			} else {\n				$collate = \'utf8_general_ci\';\n			}\n		} elseif ( defined( \'DB_COLLATE\' ) ) {\n			$collate = DB_COLLATE;\n		}\n\n		if ( defined( \'DB_CHARSET\' ) ) {\n			$charset = DB_CHARSET;\n		}\n\n		$charset_collate = $this-&gt;determine_charset( $charset, $collate );\n\n		$this-&gt;charset = $charset_collate[\'charset\'];\n		$this-&gt;collate = $charset_collate[\'collate\'];\n	}\n\n	/**\n	 * 与えられた文字セットと照合順序を使用して、使用するのに最適な文字セットと照合順序を決定します。\n	 *\n	 * たとえば、可能であれば、utf8の代わりにutf8mb4を使用する必要があります。\n	 *\n	 * @since 4.6.0\n	 *\n	 * @param string $charset The character set to check.\n	 * @param string $collate The collation to check.\n	 * @return array The most appropriate character set and collation to use.\n	 */\n	public function determine_charset( $charset, $collate ) {\n		if ( ( $this-&gt;use_mysqli &amp;&amp; ! ( $this-&gt;dbh instanceof mysqli ) ) || empty( $this-&gt;dbh ) ) {\n			return compact( \'charset\', \'collate\' );\n		}\n\n		if ( \'utf8\' === $charset &amp;&amp; $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8mb4\';\n		}\n\n		if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8\';\n			$collate = str_replace( \'utf8mb4_\', \'utf8_\', $collate );\n		}\n\n		if ( \'utf8mb4\' === $charset ) {\n			// _general_ is outdated, so we can upgrade it to _unicode_, instead.\n			if ( ! $collate || \'utf8_general_ci\' === $collate ) {\n				$collate = \'utf8mb4_unicode_ci\';\n			} else {\n				$collate = str_replace( \'utf8_\', \'utf8mb4_\', $collate );\n			}\n		}\n\n		// _unicode_520_ is a better collation, we should use that when it\'s available.\n		if ( $this-&gt;has_cap( \'utf8mb4_520\' ) &amp;&amp; \'utf8mb4_unicode_ci\' === $collate ) {\n			$collate = \'utf8mb4_unicode_520_ci\';\n		}\n\n		return compact( \'charset\', \'collate\' );\n	}\n\n	/**\n	 * 接続の文字セットを設定します。\n	 *\n	 * @since 3.1.0\n	 *\n	 * @param resource $dbh     The resource given by mysql_connect\n	 * @param string   $charset Optional. The character set. Default null.\n	 * @param string   $collate Optional. The collation. Default null.\n	 */\n	public function set_charset( $dbh, $charset = null, $collate = null ) {\n		if ( ! isset( $charset ) ) {\n			$charset = $this-&gt;charset;\n		}\n		if ( ! isset( $collate ) ) {\n			$collate = $this-&gt;collate;\n		}\n		if ( $this-&gt;has_cap( \'collation\' ) &amp;&amp; ! empty( $charset ) ) {\n			$set_charset_succeeded = true;\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( function_exists( \'mysqli_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysqli_set_charset( $dbh, $charset );\n				}\n\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysqli_query( $dbh, $query );\n				}\n			} else {\n				if ( function_exists( \'mysql_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysql_set_charset( $charset, $dbh );\n				}\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysql_query( $query, $dbh );\n				}\n			}\n		}\n	}\n\n	/**\n	 * 現在のSQLモードを変更し、そのWordPress互換性を確認してください。\n	 *\n	 * If no modes are passed, it will ensure the current MySQL server\n	 * modes are compatible.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param array $modes Optional. A list of SQL modes to set.\n	 */\n	public function set_sql_mode( $modes = array() ) {\n		if ( empty( $modes ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$res = mysqli_query( $this-&gt;dbh, \'SELECT @@SESSION.sql_mode\' );\n			} else {\n				$res = mysql_query( \'SELECT @@SESSION.sql_mode\', $this-&gt;dbh );\n			}\n\n			if ( empty( $res ) ) {\n				return;\n			}\n\n			if ( $this-&gt;use_mysqli ) {\n				$modes_array = mysqli_fetch_array( $res );\n				if ( empty( $modes_array[0] ) ) {\n					return;\n				}\n				$modes_str = $modes_array[0];\n			} else {\n				$modes_str = mysql_result( $res, 0 );\n			}\n\n			if ( empty( $modes_str ) ) {\n				return;\n			}\n\n			$modes = explode( \',\', $modes_str );\n		}\n\n		$modes = array_change_key_case( $modes, CASE_UPPER );\n\n		/**\n		 * Filters the list of incompatible SQL modes to exclude.\n		 *\n		 * @since 3.9.0\n		 *\n		 * @param array $incompatible_modes An array of incompatible modes.\n		 */\n		$incompatible_modes = (array) apply_filters( \'incompatible_sql_modes\', $this-&gt;incompatible_modes );\n\n		foreach ( $modes as $i =&gt; $mode ) {\n			if ( in_array( $mode, $incompatible_modes ) ) {\n				unset( $modes[ $i ] );\n			}\n		}\n\n		$modes_str = implode( \',\', $modes );\n\n		if ( $this-&gt;use_mysqli ) {\n			mysqli_query( $this-&gt;dbh, \"SET SESSION sql_mode=\'$modes_str\'\" );\n		} else {\n			mysql_query( \"SET SESSION sql_mode=\'$modes_str\'\", $this-&gt;dbh );\n		}\n	}\n\n	/**\n	 * WordPressテーブルのテーブルプレフィックスを設定します。\n	 *\n	 * @since 2.5.0\n	 *\n	 * @param string $prefix          Alphanumeric name for the new prefix.\n	 * @param bool   $set_table_names Optional. Whether the table names, e.g. wpdb::$posts, should be updated or not.\n	 * @return string|WP_Error Old prefix or WP_Error on error\n	 */\n	public function set_prefix( $prefix, $set_table_names = true ) {\n\n		if ( preg_match( \'|[^a-z0-9_]|i\', $prefix ) ) {\n			return new WP_Error( \'invalid_db_prefix\', \'Invalid database prefix\' );\n		}\n\n		$old_prefix = is_multisite() ? \'\' : $prefix;\n\n		if ( isset( $this-&gt;base_prefix ) ) {\n			$old_prefix = $this-&gt;base_prefix;\n		}\n\n		$this-&gt;base_prefix = $prefix;\n\n		if ( $set_table_names ) {\n			foreach ( $this-&gt;tables( \'global\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			if ( is_multisite() &amp;&amp; empty( $this-&gt;blogid ) ) {\n				return $old_prefix;\n			}\n\n			$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n			foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n		}\n		return $old_prefix;\n	}\n\n	/**\n	 * ブログIDを設定する\n	 *\n	 * @since 3.0.0\n	 *\n	 * @param int $blog_id\n	 * @param int $network_id Optional.\n	 * @return int previous blog id\n	 */\n	public function set_blog_id( $blog_id, $network_id = 0 ) {\n		if ( ! empty( $network_id ) ) {\n			$this-&gt;siteid = $network_id;\n		}\n\n		$old_blog_id  = $this-&gt;blogid;\n		$this-&gt;blogid = $blog_id;\n\n		$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n		foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		return $old_blog_id;\n	}\n\n	/**\n	 * Gets blog prefix.\n	 *\n	 * @since 3.0.0\n	 * @param int $blog_id Optional.\n	 * @return string Blog prefix.\n	 */\n	public function get_blog_prefix( $blog_id = null ) {\n		if ( is_multisite() ) {\n			if ( null === $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_id = (int) $blog_id;\n			if ( defined( \'MULTISITE\' ) &amp;&amp; ( 0 == $blog_id || 1 == $blog_id ) ) {\n				return $this-&gt;base_prefix;\n			} else {\n				return $this-&gt;base_prefix . $blog_id . \'_\';\n			}\n		} else {\n			return $this-&gt;base_prefix;\n		}\n	}\n\n	/**\n	 * WordPressテーブルの配列を返します。\n	 *\n	 * またCUSTOM_USER_TABLEとCUSTOM_USER_META_TABLEがWordPressユーザーと\n	 * usermetaテーブルを上書きすることを可能にします。そうでなければプレフィックスによって決定されます。\n	 *\n	 * scope引数は、以下のいずれかを取ります。\n	 *\n	 * \'all\' - \'all\'および \'global\'テーブルを返します。古いテーブルは返されません。\n	 * \'blog\' - 照会されたブログのブログレベルのテーブルを返します。\n	 * \'global\'インストール用のグローバルテーブルを返します。マルチサイトを実行している場合にのみマルチサイトテーブルを返します。\n	 * \'ms_global\' - 現在のインストールがマルチサイトかどうかにかかわらず、マルチサイトグローバルテーブルを返します。\n	 * \'old\' - 廃止予定のテーブルを返します。\n	 *\n	 * @since 3.0.0\n	 * @uses wpdb::$tables\n	 * @uses wpdb::$old_tables\n	 * @uses wpdb::$global_tables\n	 * @uses wpdb::$ms_global_tables\n	 *\n	 * @param string $scope  オプションです。 all、global、ms_global、blog、または古いテーブルにすることができます。デフォルトはallです。\n	 * @param bool   $ prefixオプション。テーブルプレフィックスを含めるかどうか。ブログならデフォルトはtrueです。\n	 * 接頭辞が要求されると、カスタムユーザーとusermetaテーブルがマッピングされます。\n	 * @param int    $blog_id Optional. The blog_id to prefix. Defaults to wpdb::$blogid. Used only when prefix is requested.\n	 * @return array Table names. When a prefix is requested, the key is the unprefixed table name.\n	 */\n	public function tables( $scope = \'all\', $prefix = true, $blog_id = 0 ) {\n		switch ( $scope ) {\n			case \'all\':\n				$tables = array_merge( $this-&gt;global_tables, $this-&gt;tables );\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'blog\':\n				$tables = $this-&gt;tables;\n				break;\n			case \'global\':\n				$tables = $this-&gt;global_tables;\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'ms_global\':\n				$tables = $this-&gt;ms_global_tables;\n				break;\n			case \'old\':\n				$tables = $this-&gt;old_tables;\n				break;\n			default:\n				return array();\n		}\n\n		if ( $prefix ) {\n			if ( ! $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_prefix   = $this-&gt;get_blog_prefix( $blog_id );\n			$base_prefix   = $this-&gt;base_prefix;\n			$global_tables = array_merge( $this-&gt;global_tables, $this-&gt;ms_global_tables );\n			foreach ( $tables as $k =&gt; $table ) {\n				if ( in_array( $table, $global_tables ) ) {\n					$tables[ $table ] = $base_prefix . $table;\n				} else {\n					$tables[ $table ] = $blog_prefix . $table;\n				}\n				unset( $tables[ $k ] );\n			}\n\n			if ( isset( $tables[\'users\'] ) &amp;&amp; defined( \'CUSTOM_USER_TABLE\' ) ) {\n				$tables[\'users\'] = CUSTOM_USER_TABLE;\n			}\n\n			if ( isset( $tables[\'usermeta\'] ) &amp;&amp; defined( \'CUSTOM_USER_META_TABLE\' ) ) {\n				$tables[\'usermeta\'] = CUSTOM_USER_META_TABLE;\n			}\n		}\n\n		return $tables;\n	}\n\n	/**\n	 * 現在のデータベース接続を使用してデータベースを選択します。\n	 *\n	 * データベース名は現在のデータベース接続に基づいて変更されます。\n	 * 失敗すると、実行は停止し、DBエラーを表示します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string        $db  MySQL database name\n	 * @param resource|null $dbh Optional link identifier.\n	 */\n	public function select( $db, $dbh = null ) {\n		if ( is_null( $dbh ) ) {\n			$dbh = $this-&gt;dbh;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$success = mysqli_select_db( $dbh, $db );\n		} else {\n			$success = mysql_select_db( $db, $dbh );\n		}\n		if ( ! $success ) {\n			$this-&gt;ready = false;\n			if ( ! did_action( \'template_redirect\' ) ) {\n				wp_load_translations_early();\n\n				$message = \'&lt;h1&gt;\' . __( \'Can&amp;#8217;t select database\' ) . \"&lt;/h1&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'We were able to connect to the database server (which means your username and password is okay) but not able to select the %s database.\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/p&gt;\\n\";\n\n				$message .= \"&lt;ul&gt;\\n\";\n				$message .= \'&lt;li&gt;\' . __( \'Are you sure it exists?\' ) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: 1: database user, 2: database name */\n					__( \'Does the user %1$s have permission to use the %2$s database?\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbuser, ENT_QUOTES ) . \'&lt;/code&gt;\',\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'On some systems the name of your database is prefixed with your username, so it would be like &lt;code&gt;username_%1$s&lt;/code&gt;. Could that be the problem?\' ),\n					htmlspecialchars( $db, ENT_QUOTES )\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \"&lt;/ul&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: support forums URL */\n					__( \'If you don&amp;#8217;t know how to set up a database you should &lt;strong&gt;contact your host&lt;/strong&gt;. If all else fails you may find help at the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n					__( \'https://wordpress.org/support/\' )\n				) . \"&lt;/p&gt;\\n\";\n\n				$this-&gt;bail( $message, \'db_select_fail\' );\n			}\n		}\n	}\n\n	/**\n	 * 使用しないでください、廃止予定です。\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 2.8.0\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare\n	 * @see esc_sql()\n	 *\n	 * @param string $string\n	 * @return string\n	 */\n	function _weak_escape( $string ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		return addslashes( $string );\n	}\n\n	/**\n	 * Real escape, using mysqli_real_escape_string() or mysql_real_escape_string()\n	 *\n	 * @see mysqli_real_escape_string()\n	 * @see mysql_real_escape_string()\n	 * @since 2.8.0\n	 *\n	 * @param  string $string to escape\n	 * @return string escaped\n	 */\n	function _real_escape( $string ) {\n		if ( $this-&gt;dbh ) {\n			if ( $this-&gt;use_mysqli ) {\n				$escaped = mysqli_real_escape_string( $this-&gt;dbh, $string );\n			} else {\n				$escaped = mysql_real_escape_string( $string, $this-&gt;dbh );\n			}\n		} else {\n			$class = get_class( $this );\n			if ( function_exists( \'__\' ) ) {\n				/* translators: %s: database access abstraction class, usually wpdb or a class extending wpdb */\n				_doing_it_wrong( $class, sprintf( __( \'%s must set a database connection for use with escaping.\' ), $class ), \'3.6.0\' );\n			} else {\n				_doing_it_wrong( $class, sprintf( \'%s must set a database connection for use with escaping.\', $class ), \'3.6.0\' );\n			}\n			$escaped = addslashes( $string );\n		}\n\n		return $this-&gt;add_placeholder_escape( $escaped );\n	}\n\n	/**\n	 * Escape data. Works on arrays.\n	 *\n	 * @uses wpdb::_real_escape()\n	 * @since  2.8.0\n	 *\n	 * @param  string|array $data\n	 * @return string|array escaped\n	 */\n	public function _escape( $data ) {\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;_escape( $v );\n				} else {\n					$data[ $k ] = $this-&gt;_real_escape( $v );\n				}\n			}\n		} else {\n			$data = $this-&gt;_real_escape( $data );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Do not use, deprecated.\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 0.71\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare()\n	 * @see esc_sql()\n	 *\n	 * @param mixed $data\n	 * @return mixed\n	 */\n	public function escape( $data ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;escape( $v, \'recursive\' );\n				} else {\n					$data[ $k ] = $this-&gt;_weak_escape( $v, \'internal\' );\n				}\n			}\n		} else {\n			$data = $this-&gt;_weak_escape( $data, \'internal\' );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Escapes content by reference for insertion into the database, for security\n	 *\n	 * @uses wpdb::_real_escape()\n	 *\n	 * @since 2.3.0\n	 *\n	 * @param string $string to escape\n	 */\n	public function escape_by_ref( &amp;$string ) {\n		if ( ! is_float( $string ) ) {\n			$string = $this-&gt;_real_escape( $string );\n		}\n	}\n\n	/**\n	 * 安全に実行できるようにSQLクエリを準備します。sprintf（）に似た構文を使用。\n	 *\n	 * クエリ文字列では、次のプレースホルダを使用できます。\n	 *   %d (integer)数字\n	 *   %f (float)\n	 *   %s (string)　文字列\n	 *\n	 * すべてのプレースホルダは、クエリ文字列では引用符で囲まないでおく必要があります。各プレースホルダーに対応する引数を渡す必要があります。\n	 *\n	 * 古い振る舞いとの互換性のために、番号付きまたはフォーマットされた文字列プレースホルダー（例えば、％1 $ s、％5s）は引用符を含みません\n	 * この関数によって追加されたので、あなたの使用法のためにそれらを囲む適切な引用符で渡されるべきです。\n	 *\n	 * エリ文字列内のリテラルパーセント記号（％）は、%%として記述する必要があります。 （たとえばLIKE構文で使用するため）\n	 * ワイルドカードパーセンテージは、完全なLIKE文字列を含む置換引数を介して渡す必要があります。\n	 * これらは、クエリ文字列に直接挿入することはできません。  {@see wpdb :: esc_like（）}もご覧ください。\n	 *\n	 * 引数は、メソッドへの個々の引数として渡すことも、すべての引数を含む単一の配列として渡すこともできます。\n	 * この2つの組み合わせはサポートされていません。\n	 *\n	 * 例えば\n	 *     $wpdb-&gt;prepare( \"SELECT * FROM `table` WHERE `column` = %s AND `field` = %d OR `other_field` LIKE %s\", array( \'foo\', 37, \'%bar\' ) );\n	 *     $wpdb-&gt;prepare( \"SELECT DATE_FORMAT(`field`, \'%%c\') FROM `table` WHERE `column` = %s\", \'foo\' );\n	 *\n	 * @link https://secure.php.net/sprintf Description of syntax.\n	 * @since 2.3.0\n	 *\n	 * @param string      $query    Query statement with sprintf()-like placeholders\n	 * @param array|mixed $args     The array of variables to substitute into the query\'s placeholders if being called with an array of arguments,\n	 *       or the first variable to substitute into the query\'s placeholders if being called with individual arguments.\n	 * @param mixed       $args,... further variables to substitute into the query\'s placeholders if being called wih individual arguments.\n	 * @return string|void Sanitized query string, if there is a query to prepare.\n	 */\n	public function prepare( $query, $args ) {\n		if ( is_null( $query ) ) {\n			return;\n		}\n\n		// これは絶対に確実というわけではないが明らかに誤った用法を捕らえるでしょう.\n		if ( strpos( $query, \'%\' ) === false ) {\n			wp_load_translations_early();\n			_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'The query argument of %s must have a placeholder.\' ), \'wpdb::prepare()\' ), \'3.9.0\' );\n		}\n\n		$args = func_get_args();\n		array_shift( $args );\n\n		// 引数が（vsprintfのように）配列として渡された場合は、それらを上に移動します。\n		$passed_as_array = false;\n		if ( is_array( $args[0] ) &amp;&amp; count( $args ) == 1 ) {\n			$passed_as_array = true;\n			$args            = $args[0];\n		}\n\n		foreach ( $args as $arg ) {\n			if ( ! is_scalar( $arg ) &amp;&amp; ! is_null( $arg ) ) {\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'Unsupported value type (%s).\' ), gettype( $arg ) ), \'4.8.2\' );\n			}\n		}\n\n		/*\n		 * プレースホルダで許可されている書式設定を指定します。以下が許可されています。\n		 *\n		 * - Sign specifier. eg, $+d\n		 * - Numbered placeholders. eg, %1$s\n		 * - Padding specifier, including custom padding characters. eg, %05s, %\'#5s\n		 * - Alignment specifier. eg, %05-s\n		 * - Precision specifier. eg, %.2f\n		 */\n		$allowed_format = \'(?:[1-9][0-9]*[$])?[-+0-9]*(?: |0|\\\'.)?[-+0-9]*(?:\\.[0-9]+)?\';\n\n		/*\n		 * ％sプレースホルダの周囲に引用符が既にある場合は、既存の引用符を削除してそれらを再挿入\n		 * すると、引用符の整合性が保証されます。\n		 *\n		 * 下位互換性のために、これは％sにのみ適用され、長い文字列の途中で頻繁に使用される％1 $ sなどのプレースホルダ、またはテーブル名プレースホルダには適用されません。\n		 */\n		$query = str_replace( \"\'%s\'\", \'%s\', $query ); // 既存の一重引用符を削除します。\n		$query = str_replace( \'\"%s\"\', \'%s\', $query ); // 既存の二重引用符を削除します。\n\n		// %% sのようなエスケープ文字列を避けて、文字列を引用符で囲みます。\n		$query = preg_replace( \'/(?&lt;!%)%s/\', \"\'%s\'\", $query );\n\n		 // フロートをロケールに気付かないようにします。\n		$query = preg_replace( \"/(?&lt;!%)(%($allowed_format)?f)/\", \'%\\\\2F\', $query ); \n\n		$query = preg_replace( \"/%(?:%|$|(?!($allowed_format)?[sdF]))/\", \'%%\\\\1\', $query ); // エスケープされていないパーセントをエスケープします。\n\n		// クエリ内の有効なプレースホルダの数を数えます。\n		$placeholders = preg_match_all( \"/(^|[^%]|(%%)+)%($allowed_format)?[sdF]/\", $query, $matches );\n\n		if ( count( $args ) !== $placeholders ) {\n			if ( 1 === $placeholders &amp;&amp; $passed_as_array ) {\n				// If the passed query only expected one argument, but the wrong number of arguments were sent as an array, bail.\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', __( \'The query only expected one placeholder, but an array of multiple placeholders was sent.\' ), \'4.9.0\' );\n\n				return;\n			} else {\n				/*\n				 * 適切な数のプレースホルダがなくても、それらが個別の引数として渡された場合、\n				 * または配列内に複数の引数があることが予想される場合は、警告をスローします。\n				 */\n				wp_load_translations_early();\n				_doing_it_wrong(\n					\'wpdb::prepare\',\n					/* translators: 1: number of placeholders, 2: number of arguments passed */\n					sprintf(\n						__( \'The query does not contain the correct number of placeholders (%1$d) for the number of arguments passed (%2$d).\' ),\n						$placeholders,\n						count( $args )\n					),\n					\'4.8.3\'\n				);\n			}\n		}\n\n		array_walk( $args, array( $this, \'escape_by_ref\' ) );\n		$query = @vsprintf( $query, $args );\n\n		return $this-&gt;add_placeholder_escape( $query );\n	}\n\n	/**\n	 * MySQLの準備の前にLIKE特殊文字％と_をエスケープする前半。\n	 *\n	 * これはwpdb ::prepare（）またはesc_sql（）の前にのみ使用してください。順序を逆にすると、セキュリティが非常に悪くなります。\n	 *\n	 * 準備済みステートメントの例：\n	 *\n	 *     $wild = \'%\';\n	 *     $find = \'only 43% of planets\';\n	 *     $like = $wild . $wpdb-&gt;esc_like( $find ) . $wild;\n	 *     $sql  = $wpdb-&gt;prepare( \"SELECT * FROM $wpdb-&gt;posts WHERE post_content LIKE %s\", $like );\n	 *\n	 * Example Escape Chain:\n	 *\n	 *     $sql  = esc_sql( $wpdb-&gt;esc_like( $input ) );\n	 *\n	 * @since 4.0.0\n	 *\n	 * @param string $text The raw text to be escaped. The input typed by the user should have no\n	 *                     extra or deleted slashes.\n	 * @return string Text in the form of a LIKE phrase. The output is not SQL safe. Call $wpdb::prepare()\n	 *                or real_escape next.\n	 */\n	public function esc_like( $text ) {\n		return addcslashes( $text, \'_%\\\\\' );\n	}\n\n	/**\n	 * Print SQL/DB error.\n	 *\n	 * @since 0.71\n	 * @global array $EZSQL_ERROR Stores error information of query and error string\n	 *\n	 * @param string $str The error to display\n	 * @return false|void False if the showing of errors is disabled.\n	 */\n	public function print_error( $str = \'\' ) {\n		global $EZSQL_ERROR;\n\n		if ( ! $str ) {\n			if ( $this-&gt;use_mysqli ) {\n				$str = mysqli_error( $this-&gt;dbh );\n			} else {\n				$str = mysql_error( $this-&gt;dbh );\n			}\n		}\n		$EZSQL_ERROR[] = array(\n			\'query\'     =&gt; $this-&gt;last_query,\n			\'error_str\' =&gt; $str,\n		);\n\n		if ( $this-&gt;suppress_errors ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		if ( $caller = $this-&gt;get_caller() ) {\n			/* translators: 1: Database error message, 2: SQL query, 3: Name of the calling function */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s made by %3$s\' ), $str, $this-&gt;last_query, $caller );\n		} else {\n			/* translators: 1: Database error message, 2: SQL query */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s\' ), $str, $this-&gt;last_query );\n		}\n\n		error_log( $error_str );\n\n		// Are we showing errors?\n		if ( ! $this-&gt;show_errors ) {\n			return false;\n		}\n\n		// If there is an error then take note of it\n		if ( is_multisite() ) {\n			$msg = sprintf(\n				\"%s [%s]\\n%s\\n\",\n				__( \'WordPress database error:\' ),\n				$str,\n				$this-&gt;last_query\n			);\n\n			if ( defined( \'ERRORLOGFILE\' ) ) {\n				error_log( $msg, 3, ERRORLOGFILE );\n			}\n			if ( defined( \'DIEONDBERROR\' ) ) {\n				wp_die( $msg );\n			}\n		} else {\n			$str   = htmlspecialchars( $str, ENT_QUOTES );\n			$query = htmlspecialchars( $this-&gt;last_query, ENT_QUOTES );\n\n			printf(\n				\'&lt;div id=\"error\"&gt;&lt;p class=\"wpdberror\"&gt;&lt;strong&gt;%s&lt;/strong&gt; [%s]&lt;br /&gt;&lt;code&gt;%s&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;\',\n				__( \'WordPress database error:\' ),\n				$str,\n				$query\n			);\n		}\n	}\n\n	/**\n	 * データベースエラーの表示を有効にします。\n	 *\n	 * この機能はエラーの表示を可能にするためだけに使用されるべきです。\n	 * wpdb::hide_errors() should be used instead for hiding of errors. However,\n	 * this function can be used to enable and disable showing of database\n	 * errors.\n	 *\n	 * @since 0.71\n	 * @see wpdb::hide_errors()\n	 *\n	 * @param bool $show Whether to show or hide errors\n	 * @return bool Old value for showing errors.\n	 */\n	public function show_errors( $show = true ) {\n		$errors            = $this-&gt;show_errors;\n		$this-&gt;show_errors = $show;\n		return $errors;\n	}\n\n	/**\n	 * Disables showing of database errors.\n	 *\n	 * By default database errors are not shown.\n	 *\n	 * @since 0.71\n	 * @see wpdb::show_errors()\n	 *\n	 * @return bool Whether showing of errors was active\n	 */\n	public function hide_errors() {\n		$show              = $this-&gt;show_errors;\n		$this-&gt;show_errors = false;\n		return $show;\n	}\n\n	/**\n	 * Whether to suppress database errors.\n	 *\n	 * By default database errors are suppressed, with a simple\n	 * call to this function they can be enabled.\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::hide_errors()\n	 * @param bool $suppress Optional. New value. Defaults to true.\n	 * @return bool Old value\n	 */\n	public function suppress_errors( $suppress = true ) {\n		$errors                = $this-&gt;suppress_errors;\n		$this-&gt;suppress_errors = (bool) $suppress;\n		return $errors;\n	}\n\n	/**\n	 * Kill cached query results.\n	 *\n	 * @since 0.71\n	 */\n	public function flush() {\n		$this-&gt;last_result   = array();\n		$this-&gt;col_info      = null;\n		$this-&gt;last_query    = null;\n		$this-&gt;rows_affected = $this-&gt;num_rows = 0;\n		$this-&gt;last_error    = \'\';\n\n		if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n			mysqli_free_result( $this-&gt;result );\n			$this-&gt;result = null;\n\n			// Sanity check before using the handle\n			if ( empty( $this-&gt;dbh ) || ! ( $this-&gt;dbh instanceof mysqli ) ) {\n				return;\n			}\n\n			// Clear out any results from a multi-query\n			while ( mysqli_more_results( $this-&gt;dbh ) ) {\n				mysqli_next_result( $this-&gt;dbh );\n			}\n		} elseif ( is_resource( $this-&gt;result ) ) {\n			mysql_free_result( $this-&gt;result );\n		}\n	}\n\n	/**\n	 * データベースに接続して選択します。\n	 *\n	 * $ allow_bailがfalseの場合、データベース接続の欠如は手動で処理する必要があります。.\n	 *\n	 * @since 3.0.0\n	 * @since 3.9.0 $allow_bail parameter added.\n	 *\n	 * @param bool $ allow_bailオプション。機能を保釈することを許可します。デフォルトはtrueです。\n	 * @return 成功した場合はtrue、失敗した場合はfalse。\n	 */\n	public function db_connect( $allow_bail = true ) {\n		$this-&gt;is_mysql = true;\n\n		/*\n		 * MySQLiを使用している場合は3.9以降では非推奨です。同等のものはありません\n		 * mysqli_ *関数には$ new_linkパラメータがあります。\n		 */\n		$new_link     = defined( \'MYSQL_NEW_LINK\' ) ? MYSQL_NEW_LINK : true;\n		$client_flags = defined( \'MYSQL_CLIENT_FLAGS\' ) ? MYSQL_CLIENT_FLAGS : 0;\n\n		if ( $this-&gt;use_mysqli ) {\n			$this-&gt;dbh = mysqli_init();\n\n			$host    = $this-&gt;dbhost;\n			$port    = null;\n			$socket  = null;\n			$is_ipv6 = false;\n\n			if ( $host_data = $this-&gt;parse_db_host( $this-&gt;dbhost ) ) {\n				list( $host, $port, $socket, $is_ipv6 ) = $host_data;\n			}\n\n			/*\n			 * If using the `mysqlnd` library, the IPv6 address needs to be\n			 * enclosed in square brackets, whereas it doesn\'t while using the\n			 * `libmysqlclient` library.\n			 * @see https://bugs.php.net/bug.php?id=67563\n			 */\n			if ( $is_ipv6 &amp;&amp; extension_loaded( \'mysqlnd\' ) ) {\n				$host = \"[$host]\";\n			}\n\n			if ( WP_DEBUG ) {\n				mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			} else {\n				@mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			}\n\n			if ( $this-&gt;dbh-&gt;connect_errno ) {\n				$this-&gt;dbh = null;\n\n				/*\n				 * ext / mysqliの設定が間違っている可能性があります。以下の場合、ext / mysqlにフォールバックしてください。\n				  *  - We haven\'t previously connected, and\n				  *  - WP_USE_EXT_MYSQL isn\'t set to false, and\n				  *  - ext/mysql is loaded.\n				  */\n				$attempt_fallback = true;\n\n				if ( $this-&gt;has_connected ) {\n					$attempt_fallback = false;\n				} elseif ( defined( \'WP_USE_EXT_MYSQL\' ) &amp;&amp; ! WP_USE_EXT_MYSQL ) {\n					$attempt_fallback = false;\n				} elseif ( ! function_exists( \'mysql_connect\' ) ) {\n					$attempt_fallback = false;\n				}\n\n				if ( $attempt_fallback ) {\n					$this-&gt;use_mysqli = false;\n					return $this-&gt;db_connect( $allow_bail );\n				}\n			}\n		} else {\n			if ( WP_DEBUG ) {\n				$this-&gt;dbh = mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			} else {\n				$this-&gt;dbh = @mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			}\n		}\n\n		if ( ! $this-&gt;dbh &amp;&amp; $allow_bail ) {\n			wp_load_translations_early();\n\n			// Load custom DB error template, if present.\n			if ( file_exists( WP_CONTENT_DIR . \'/db-error.php\' ) ) {\n				require_once( WP_CONTENT_DIR . \'/db-error.php\' );\n				die();\n			}\n\n			$message = \'&lt;h1&gt;\' . __( \'Error establishing a database connection\' ) . \"&lt;/h1&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: 1: wp-config.php, 2: database host */\n				__( \'This either means that the username and password information in your %1$s file is incorrect or we can&amp;#8217;t contact the database server at %2$s. This could mean your host&amp;#8217;s database server is down.\' ),\n				\'&lt;code&gt;wp-config.php&lt;/code&gt;\',\n				\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n			) . \"&lt;/p&gt;\\n\";\n\n			$message .= \"&lt;ul&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure you have the correct username and password?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that you have typed the correct hostname?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \"&lt;/ul&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: %s: support forums URL */\n				__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n				__( \'https://wordpress.org/support/\' )\n			) . \"&lt;/p&gt;\\n\";\n\n			$this-&gt;bail( $message, \'db_connect_fail\' );\n\n			return false;\n		} elseif ( $this-&gt;dbh ) {\n			if ( ! $this-&gt;has_connected ) {\n				$this-&gt;init_charset();\n			}\n\n			$this-&gt;has_connected = true;\n\n			$this-&gt;set_charset( $this-&gt;dbh );\n\n			$this-&gt;ready = true;\n			$this-&gt;set_sql_mode();\n			$this-&gt;select( $this-&gt;dbname, $this-&gt;dbh );\n\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Parse the DB_HOST setting to interpret it for mysqli_real_connect.\n	 *\n	 * mysqli_real_connect doesn\'t support the host param including a port or\n	 * socket like mysql_connect does. This duplicates how mysql_connect detects\n	 * a port and/or socket file.\n	 *\n	 * @since 4.9.0\n	 *\n	 * @param string $host The DB_HOST setting to parse.\n	 * @return array|bool Array containing the host, the port, the socket and whether\n	 *                    it is an IPv6 address, in that order. If $host couldn\'t be parsed,\n	 *                    returns false.\n	 */\n	public function parse_db_host( $host ) {\n		$port    = null;\n		$socket  = null;\n		$is_ipv6 = false;\n\n		// First peel off the socket parameter from the right, if it exists.\n		$socket_pos = strpos( $host, \':/\' );\n		if ( $socket_pos !== false ) {\n			$socket = substr( $host, $socket_pos + 1 );\n			$host   = substr( $host, 0, $socket_pos );\n		}\n\n		// We need to check for an IPv6 address first.\n		// An IPv6 address will always contain at least two colons.\n		if ( substr_count( $host, \':\' ) &gt; 1 ) {\n			$pattern = \'#^(?:\\[)?(?P&lt;host&gt;[0-9a-fA-F:]+)(?:\\]:(?P&lt;port&gt;[\\d]+))?#\';\n			$is_ipv6 = true;\n		} else {\n			// We seem to be dealing with an IPv4 address.\n			$pattern = \'#^(?P&lt;host&gt;[^:/]*)(?::(?P&lt;port&gt;[\\d]+))?#\';\n		}\n\n		$matches = array();\n		$result  = preg_match( $pattern, $host, $matches );\n\n		if ( 1 !== $result ) {\n			// Couldn\'t parse the address, bail.\n			return false;\n		}\n\n		$host = \'\';\n		foreach ( array( \'host\', \'port\' ) as $component ) {\n			if ( ! empty( $matches[ $component ] ) ) {\n				$component = $matches[ $component ];\n			}\n		}\n\n		return array( $host, $port, $socket, $is_ipv6 );\n	}\n\n	/**\n	 * Checks that the connection to the database is still up. If not, try to reconnect.\n	 *\n	 * If this function is unable to reconnect, it will forcibly die, or if after the\n	 * the {@see \'template_redirect\'} hook has been fired, return false instead.\n	 *\n	 * If $allow_bail is false, the lack of database connection will need\n	 * to be handled manually.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param bool $allow_bail Optional. Allows the function to bail. Default true.\n	 * @return bool|void True if the connection is up.\n	 */\n	public function check_connection( $allow_bail = true ) {\n		if ( $this-&gt;use_mysqli ) {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysqli_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		} else {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysql_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		}\n\n		$error_reporting = false;\n\n		// Disable warnings, as we don\'t want to see a multitude of \"unable to connect\" messages\n		if ( WP_DEBUG ) {\n			$error_reporting = error_reporting();\n			error_reporting( $error_reporting &amp; ~E_WARNING );\n		}\n\n		for ( $tries = 1; $tries &lt;= $this-&gt;reconnect_retries; $tries++ ) {\n			// On the last try, re-enable warnings. We want to see a single instance of the\n			// \"unable to connect\" message on the bail() screen, if it appears.\n			if ( $this-&gt;reconnect_retries === $tries &amp;&amp; WP_DEBUG ) {\n				error_reporting( $error_reporting );\n			}\n\n			if ( $this-&gt;db_connect( false ) ) {\n				if ( $error_reporting ) {\n					error_reporting( $error_reporting );\n				}\n\n				return true;\n			}\n\n			sleep( 1 );\n		}\n\n		// If template_redirect has already happened, it\'s too late for wp_die()/dead_db().\n		// Let\'s just return and hope for the best.\n		if ( did_action( \'template_redirect\' ) ) {\n			return false;\n		}\n\n		if ( ! $allow_bail ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		$message = \'&lt;h1&gt;\' . __( \'Error reconnecting to the database\' ) . \"&lt;/h1&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: database host */\n			__( \'This means that we lost contact with the database server at %s. This could mean your host&amp;#8217;s database server is down.\' ),\n			\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n		) . \"&lt;/p&gt;\\n\";\n\n		$message .= \"&lt;ul&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is not under particularly heavy load?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \"&lt;/ul&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: support forums URL */\n			__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n			__( \'https://wordpress.org/support/\' )\n		) . \"&lt;/p&gt;\\n\";\n\n		// We weren\'t able to reconnect, so we better bail.\n		$this-&gt;bail( $message, \'db_connect_fail\' );\n\n		// Call dead_db() if bail didn\'t die, because this database is no more. It has ceased to be (at least temporarily).\n		dead_db();\n	}\n\n	/**\n	 * 現在のデータベース接続を使用して、MySQLデータベースクエリを実行します。\n	 *\n	 * より詳しい情報はコーデックスページにあります。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query Database query\n	 * @return int|bool Boolean true for CREATE, ALTER, TRUNCATE and DROP queries. Number of rows\n	 *                  affected/selected for all other queries. Boolean false on error.\n	 */\n	public function query( $query ) {\n		if ( ! $this-&gt;ready ) {\n			$this-&gt;check_current_query = true;\n			return false;\n		}\n\n		/**\n		 * データベースクエリをフィルタリングします。\n		 *\n		 * プラグインがロードされる前にいくつかの問い合わせが行われます。\n		 * and thus cannot be filtered with this method.\n		 *\n		 * @since 2.1.0\n		 *\n		 * @param string $query Database query.\n		 */\n		$query = apply_filters( \'query\', $query );\n\n		$this-&gt;flush();\n\n		// Log how the function was called\n		$this-&gt;func_call = \"\\$db-&gt;query(\\\"$query\\\")\";\n\n		// If we\'re writing to the database, make sure the query will write safely.\n		if ( $this-&gt;check_current_query &amp;&amp; ! $this-&gt;check_ascii( $query ) ) {\n			$stripped_query = $this-&gt;strip_invalid_text_from_query( $query );\n			// strip_invalid_text_from_query() can perform queries, so we need\n			// to flush again, just to make sure everything is clear.\n			$this-&gt;flush();\n			if ( $stripped_query !== $query ) {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		$this-&gt;check_current_query = true;\n\n		// Keep track of the last query for debug.\n		$this-&gt;last_query = $query;\n\n		$this-&gt;_do_query( $query );\n\n		// MySQL server has gone away, try to reconnect.\n		$mysql_errno = 0;\n		if ( ! empty( $this-&gt;dbh ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$mysql_errno = mysqli_errno( $this-&gt;dbh );\n				} else {\n					// $dbh is defined, but isn\'t a real connection.\n					// Something has gone horribly wrong, let\'s try a reconnect.\n					$mysql_errno = 2006;\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$mysql_errno = mysql_errno( $this-&gt;dbh );\n				} else {\n					$mysql_errno = 2006;\n				}\n			}\n		}\n\n		if ( empty( $this-&gt;dbh ) || 2006 == $mysql_errno ) {\n			if ( $this-&gt;check_connection() ) {\n				$this-&gt;_do_query( $query );\n			} else {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		// If there is an error then take note of it.\n		if ( $this-&gt;use_mysqli ) {\n			if ( $this-&gt;dbh instanceof mysqli ) {\n				$this-&gt;last_error = mysqli_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		} else {\n			if ( is_resource( $this-&gt;dbh ) ) {\n				$this-&gt;last_error = mysql_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		}\n\n		if ( $this-&gt;last_error ) {\n			// Clear insert_id on a subsequent failed insert.\n			if ( $this-&gt;insert_id &amp;&amp; preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				$this-&gt;insert_id = 0;\n			}\n\n			$this-&gt;print_error();\n			return false;\n		}\n\n		if ( preg_match( \'/^\\s*(create|alter|truncate|drop)\\s/i\', $query ) ) {\n			$return_val = $this-&gt;result;\n		} elseif ( preg_match( \'/^\\s*(insert|delete|update|replace)\\s/i\', $query ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$this-&gt;rows_affected = mysqli_affected_rows( $this-&gt;dbh );\n			} else {\n				$this-&gt;rows_affected = mysql_affected_rows( $this-&gt;dbh );\n			}\n			// Take note of the insert_id\n			if ( preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				if ( $this-&gt;use_mysqli ) {\n					$this-&gt;insert_id = mysqli_insert_id( $this-&gt;dbh );\n				} else {\n					$this-&gt;insert_id = mysql_insert_id( $this-&gt;dbh );\n				}\n			}\n			// Return number of rows affected\n			$return_val = $this-&gt;rows_affected;\n		} else {\n			$num_rows = 0;\n			if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n				while ( $row = mysqli_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			} elseif ( is_resource( $this-&gt;result ) ) {\n				while ( $row = mysql_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			}\n\n			// Log number of rows the query returned\n			// and return number of rows selected\n			$this-&gt;num_rows = $num_rows;\n			$return_val     = $num_rows;\n		}\n\n		return $return_val;\n	}\n\n	/**\n	 * Internal function to perform the mysql_query() call.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @see wpdb::query()\n	 *\n	 * @param string $query The query to run.\n	 */\n	private function _do_query( $query ) {\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;timer_start();\n		}\n\n		if ( ! empty( $this-&gt;dbh ) &amp;&amp; $this-&gt;use_mysqli ) {\n			$this-&gt;result = mysqli_query( $this-&gt;dbh, $query );\n		} elseif ( ! empty( $this-&gt;dbh ) ) {\n			$this-&gt;result = mysql_query( $query, $this-&gt;dbh );\n		}\n		$this-&gt;num_queries++;\n\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;queries[] = array(\n				$query,\n				$this-&gt;timer_stop(),\n				$this-&gt;get_caller(),\n				$this-&gt;time_start,\n			);\n		}\n	}\n\n	/**\n	 * Generates and returns a placeholder escape string for use in queries returned by ::prepare().\n	 *\n	 * @since 4.8.3\n	 *\n	 * @return string String to escape placeholders.\n	 */\n	public function placeholder_escape() {\n		static $placeholder;\n\n		if ( ! $placeholder ) {\n			// If ext/hash is not present, compat.php\'s hash_hmac() does not support sha256.\n			$algo = function_exists( \'hash\' ) ? \'sha256\' : \'sha1\';\n			// Old WP installs may not have AUTH_SALT defined.\n			$salt = defined( \'AUTH_SALT\' ) &amp;&amp; AUTH_SALT ? AUTH_SALT : (string) rand();\n\n			$placeholder = \'{\' . hash_hmac( $algo, uniqid( $salt, true ), $salt ) . \'}\';\n		}\n\n		/*\n		 * レースホルダエスケープを削除するために、フィルタを追加します。優先順位0を使用します。\n		 * そのため、このフィルタに関連付けられている他のものはすべて、プレースホルダ文字列が削除されたクエリを受け取ります\n		 */\n		if ( ! has_filter( \'query\', array( $this, \'remove_placeholder_escape\' ) ) ) {\n			add_filter( \'query\', array( $this, \'remove_placeholder_escape\' ), 0 );\n		}\n\n		return $placeholder;\n	}\n\n	/**\n	 * printf（）のプレースホルダーに似たものをエスケープするために、プレースホルダーのエスケープ文字列を追加します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query to escape.\n	 * @return string 必要に応じてプレースホルダエスケープ文字列が挿入されたクエリ。\n	 */\n	public function add_placeholder_escape( $query ) {\n		/*\n		 * 漠然とプレースホルダーに似ているものでさえも返すことを防ぐために、私たちは見つけることが\n		 * できるあらゆる％をつぶします。\n		 */\n		return str_replace( \'%\', $this-&gt;placeholder_escape(), $query );\n	}\n\n	/**\n	 * クエリからプレースホルダエスケープ文字列を削除します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query from which the placeholder will be removed.\n	 * @return string The query with the placeholder removed.\n	 */\n	public function remove_placeholder_escape( $query ) {\n		return str_replace( $this-&gt;placeholder_escape(), \'%\', $query );\n	}\n\n	/**\n	 * Insert a row into a table.\n	 *\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows inserted, or false on error.\n	 */\n	public function insert( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'INSERT\' );\n	}\n\n	/**\n	 * Replace a row into a table.\n	 *\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	public function replace( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'REPLACE\' );\n	}\n\n	/**\n	 * Helper function for insert and replace.\n	 *\n	 * Runs an insert or replace query based on $type argument.\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param string $type         Optional. What type of operation is this? INSERT or REPLACE. Defaults to INSERT.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	function _insert_replace_helper( $table, $data, $format = null, $type = \'INSERT\' ) {\n		$this-&gt;insert_id = 0;\n\n		if ( ! in_array( strtoupper( $type ), array( \'REPLACE\', \'INSERT\' ) ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$formats = $values = array();\n		foreach ( $data as $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$formats[] = \'NULL\';\n				continue;\n			}\n\n			$formats[] = $value[\'format\'];\n			$values[]  = $value[\'value\'];\n		}\n\n		$fields  = \'`\' . implode( \'`, `\', array_keys( $data ) ) . \'`\';\n		$formats = implode( \', \', $formats );\n\n		$sql = \"$type INTO `$table` ($fields) VALUES ($formats)\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Update a row in the table\n	 *\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ), array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'ID\' =&gt; 1 ), array( \'%s\', \'%d\' ), array( \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $data         Data to update (in column =&gt; value pairs).\n	 *            Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *            Sending a null value will cause the column to be set to NULL - the corresponding\n	 *            format is ignored in this case.\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $format       Optional. An array of formats to be mapped to each of the values in $data.\n	 *            If string, that format will be used for all of the values in $data.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function update( $table, $data, $where, $format = null, $where_format = null ) {\n		if ( ! is_array( $data ) || ! is_array( $where ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$fields = $conditions = $values = array();\n		foreach ( $data as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$fields[] = \"`$field` = NULL\";\n				continue;\n			}\n\n			$fields[] = \"`$field` = \" . $value[\'format\'];\n			$values[] = $value[\'value\'];\n		}\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$fields     = implode( \', \', $fields );\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"UPDATE `$table` SET $fields WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Delete a row in the table\n	 *\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ), array( \'%d\' ) )\n	 *\n	 * @since 3.4.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function delete( $table, $where, $where_format = null ) {\n		if ( ! is_array( $where ) ) {\n			return false;\n		}\n\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$conditions = $values = array();\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"DELETE FROM `$table` WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Processes arrays of field/value pairs and field formats.\n	 *\n	 * This is a helper method for wpdb\'s CRUD methods, which take field/value\n	 * pairs for inserts, updates, and where clauses. This method first pairs\n	 * each value with a format. Then it determines the charset of that field,\n	 * using that to determine if any invalid text would be stripped. If text is\n	 * stripped, then field processing is rejected and the query fails.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param array  $data   Field/value pair.\n	 * @param mixed  $format Format for each field.\n	 * @return array|false Returns an array of fields that contain paired values\n	 *                    and formats. Returns false for invalid values.\n	 */\n	protected function process_fields( $table, $data, $format ) {\n		$data = $this-&gt;process_field_formats( $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_charsets( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_lengths( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$converted_data = $this-&gt;strip_invalid_text( $data );\n\n		if ( $data !== $converted_data ) {\n			return false;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Prepares arrays of value/format pairs as passed to wpdb CRUD methods.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data   Array of fields to values.\n	 * @param mixed $format Formats to be mapped to the values in $data.\n	 * @return array Array, keyed by field names with values being an array\n	 *               of \'value\' and \'format\' keys.\n	 */\n	protected function process_field_formats( $data, $format ) {\n		$formats = $original_formats = (array) $format;\n\n		foreach ( $data as $field =&gt; $value ) {\n			$value = array(\n				\'value\'  =&gt; $value,\n				\'format\' =&gt; \'%s\',\n			);\n\n			if ( ! empty( $format ) ) {\n				$value[\'format\'] = array_shift( $formats );\n				if ( ! $value[\'format\'] ) {\n					$value[\'format\'] = reset( $original_formats );\n				}\n			} elseif ( isset( $this-&gt;field_types[ $field ] ) ) {\n				$value[\'format\'] = $this-&gt;field_types[ $field ];\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Adds field charsets to field/value/format arrays generated by\n	 * the wpdb::process_field_formats() method.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_formats() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'charset\' keys.\n	 */\n	protected function process_field_charsets( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'charset\'] = false;\n			} else {\n				$value[\'charset\'] = $this-&gt;get_col_charset( $table, $field );\n				if ( is_wp_error( $value[\'charset\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * For string fields, record the maximum string length that field can safely save.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_charsets() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'length\' keys, or false if\n	 *                     any of the values were too long for their corresponding field.\n	 */\n	protected function process_field_lengths( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'length\'] = false;\n			} else {\n				$value[\'length\'] = $this-&gt;get_col_length( $table, $field );\n				if ( is_wp_error( $value[\'length\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Retrieve one variable from the database.\n	 *\n	 * Executes a SQL query and returns the value from the SQL result.\n	 * If the SQL result contains more than one column and/or more than one row, this function returns the value in the column and row specified.\n	 * If $query is null, this function returns the value in the specified column and row from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to null, use the result from the previous query.\n	 * @param int         $x     Optional. Column of value to return. Indexed from 0.\n	 * @param int         $y     Optional. Row of value to return. Indexed from 0.\n	 * @return string|null Database query result (as string), or null on failure\n	 */\n	public function get_var( $query = null, $x = 0, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_var(\\\"$query\\\", $x, $y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		// Extract var out of cached results based x,y vals\n		if ( ! empty( $this-&gt;last_result[ $y ] ) ) {\n			$values = array_values( get_object_vars( $this-&gt;last_result[ $y ] ) );\n		}\n\n		// If there is a value return it else return null\n		return ( isset( $values[ $x ] ) &amp;&amp; $values[ $x ] !== \'\' ) ? $values[ $x ] : null;\n	}\n\n	/**\n	 * Retrieve one row from the database.\n	 *\n	 * Executes a SQL query and returns the row from the SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query  SQL query.\n	 * @param string      $output Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which correspond to\n	 *     an stdClass object, an associative array, or a numeric array, respectively. Default OBJECT.\n	 * @param int         $y      Optional. Row to return. Indexed from 0.\n	 * @return array|object|null|void Database query result in format specified by $output or null on failure\n	 */\n	public function get_row( $query = null, $output = OBJECT, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_row(\\\"$query\\\",$output,$y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		if ( ! isset( $this-&gt;last_result[ $y ] ) ) {\n			return null;\n		}\n\n		if ( $output == OBJECT ) {\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} elseif ( $output == ARRAY_A ) {\n			return $this-&gt;last_result[ $y ] ? get_object_vars( $this-&gt;last_result[ $y ] ) : null;\n		} elseif ( $output == ARRAY_N ) {\n			return $this-&gt;last_result[ $y ] ? array_values( get_object_vars( $this-&gt;last_result[ $y ] ) ) : null;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} else {\n			$this-&gt;print_error( \' $db-&gt;get_row(string query, output type, int offset) -- Output type must be one of: OBJECT, ARRAY_A, ARRAY_N\' );\n		}\n	}\n\n	/**\n	 * Retrieve one column from the database.\n	 *\n	 * Executes a SQL query and returns the column from the SQL result.\n	 * If the SQL result contains more than one column, this function returns the column specified.\n	 * If $query is null, this function returns the specified column from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to previous query.\n	 * @param int         $x     Optional. Column to return. Indexed from 0.\n	 * @return array Database query result. Array indexed from 0 by SQL result row number.\n	 */\n	public function get_col( $query = null, $x = 0 ) {\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		$new_array = array();\n		// Extract the column values\n		if ( $this-&gt;last_result ) {\n			for ( $i = 0, $j = count( $this-&gt;last_result ); $i &lt; $j; $i++ ) {\n				$new_array[ $i ] = $this-&gt;get_var( null, $x, $i );\n			}\n		}\n		return $new_array;\n	}\n\n	/**\n	 * データベースからSQL結果セット全体（つまり多数の行）を取得します。\n	 *\n	 * SQLクエリを実行し、SQL結果全体を返します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query  SQL query.\n	 * @param string $output Optional. Any of ARRAY_A | ARRAY_N | OBJECT | OBJECT_K constants.\n	 *最初の3つのうちの1つでは、SQL結果の行番号によって0からインデックスされた行の配列を返します。\n	 *各行は連想配列（column =&gt; value、...）、数値インデックス配列（0 =&gt; value、...）、またはオブジェクトです。 （ - &gt; column = value）\n	 *OBJECT_Kを使用すると、各行の最初の列の値によってキー設定された行オブジェクトの連想配列を返します。\n	 *重複したキーは破棄されます。\n	 * @return 配列|オブジェクト|null データベースクエリ結果\n	 */\n	public function get_results( $query = null, $output = OBJECT ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_results(\\\"$query\\\", $output)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		$new_array = array();\n		if ( $output == OBJECT ) {\n			// Return an integer-keyed array of row objects\n			return $this-&gt;last_result;\n		} elseif ( $output == OBJECT_K ) {\n			// Return an array of row objects with keys from column 1\n			// (Duplicates are discarded)\n			if ( $this-&gt;last_result ) {\n				foreach ( $this-&gt;last_result as $row ) {\n					$var_by_ref = get_object_vars( $row );\n					$key        = array_shift( $var_by_ref );\n					if ( ! isset( $new_array[ $key ] ) ) {\n						$new_array[ $key ] = $row;\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( $output == ARRAY_A || $output == ARRAY_N ) {\n			// Return an integer-keyed array of...\n			if ( $this-&gt;last_result ) {\n				foreach ( (array) $this-&gt;last_result as $row ) {\n					if ( $output == ARRAY_N ) {\n						// ...integer-keyed row arrays\n						$new_array[] = array_values( get_object_vars( $row ) );\n					} else {\n						// ...column name-keyed row arrays\n						$new_array[] = get_object_vars( $row );\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result;\n		}\n		return null;\n	}\n\n	/**\n	 * Retrieves the character set for the given table.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table Table name.\n	 * @return string|WP_Error Table character set, WP_Error object if it couldn\'t be found.\n	 */\n	protected function get_table_charset( $table ) {\n		$tablekey = strtolower( $table );\n\n		/**\n		 * Filters the table charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will effectively short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 */\n		$charset = apply_filters( \'pre_get_table_charset\', null, $table );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		if ( isset( $this-&gt;table_charset[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		$charsets = $columns = array();\n\n		$table_parts = explode( \'.\', $table );\n		$table       = \'`\' . implode( \'`.`\', $table_parts ) . \'`\';\n		$results     = $this-&gt;get_results( \"SHOW FULL COLUMNS FROM $table\" );\n		if ( ! $results ) {\n			return new WP_Error( \'wpdb_get_table_charset_failure\' );\n		}\n\n		foreach ( $results as $column ) {\n			$columns[ strtolower( $column-&gt;Field ) ] = $column;\n		}\n\n		$this-&gt;col_meta[ $tablekey ] = $columns;\n\n		foreach ( $columns as $column ) {\n			if ( ! empty( $column-&gt;Collation ) ) {\n				list( $charset ) = explode( \'_\', $column-&gt;Collation );\n\n				// If the current connection can\'t support utf8mb4 characters, let\'s only send 3-byte utf8 characters.\n				if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n					$charset = \'utf8\';\n				}\n\n				$charsets[ strtolower( $charset ) ] = true;\n			}\n\n			list( $type ) = explode( \'(\', $column-&gt;Type );\n\n			// A binary/blob means the whole query gets treated like this.\n			if ( in_array( strtoupper( $type ), array( \'BINARY\', \'VARBINARY\', \'TINYBLOB\', \'MEDIUMBLOB\', \'BLOB\', \'LONGBLOB\' ) ) ) {\n				$this-&gt;table_charset[ $tablekey ] = \'binary\';\n				return \'binary\';\n			}\n		}\n\n		// utf8mb3 is an alias for utf8.\n		if ( isset( $charsets[\'utf8mb3\'] ) ) {\n			$charsets[\'utf8\'] = true;\n			unset( $charsets[\'utf8mb3\'] );\n		}\n\n		// Check if we have more than one charset in play.\n		$count = count( $charsets );\n		if ( 1 === $count ) {\n			$charset = key( $charsets );\n		} elseif ( 0 === $count ) {\n			// No charsets, assume this table can store whatever.\n			$charset = false;\n		} else {\n			// More than one charset. Remove latin1 if present and recalculate.\n			unset( $charsets[\'latin1\'] );\n			$count = count( $charsets );\n			if ( 1 === $count ) {\n				// Only one charset (besides latin1).\n				$charset = key( $charsets );\n			} elseif ( 2 === $count &amp;&amp; isset( $charsets[\'utf8\'], $charsets[\'utf8mb4\'] ) ) {\n				// Two charsets, but they\'re utf8 and utf8mb4, use utf8.\n				$charset = \'utf8\';\n			} else {\n				// Two mixed character sets. ascii.\n				$charset = \'ascii\';\n			}\n		}\n\n		$this-&gt;table_charset[ $tablekey ] = $charset;\n		return $charset;\n	}\n\n	/**\n	 * Retrieves the character set for the given column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return string|false|WP_Error Column character set as a string. False if the column has no\n	 *        character set. WP_Error object if there was an error.\n	 */\n	public function get_col_charset( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		/**\n		 * Filters the column charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 * @param string $column  The name of the column being checked.\n		 */\n		$charset = apply_filters( \'pre_get_col_charset\', null, $table, $column );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;table_charset[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		// If still no column information, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// If this column doesn\'t exist, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// Return false when it\'s not a string column.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation ) ) {\n			return false;\n		}\n\n		list( $charset ) = explode( \'_\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation );\n		return $charset;\n	}\n\n	/**\n	 * Retrieve the maximum string length allowed in a given column.\n	 * The length may either be specified as a byte length or a character length.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return array|false|WP_Error array( \'length\' =&gt; (int), \'type\' =&gt; \'byte\' | \'char\' )\n	 *       false if the column has no length (for example, numeric column)\n	 *       WP_Error object if there was an error.\n	 */\n	public function get_col_length( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return false;\n		}\n\n		$typeinfo = explode( \'(\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Type );\n\n		$type = strtolower( $typeinfo[0] );\n		if ( ! empty( $typeinfo[1] ) ) {\n			$length = trim( $typeinfo[1], \')\' );\n		} else {\n			$length = false;\n		}\n\n		switch ( $type ) {\n			case \'char\':\n			case \'varchar\':\n				return array(\n					\'type\'   =&gt; \'char\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'binary\':\n			case \'varbinary\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'tinyblob\':\n			case \'tinytext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 255,        // 2^8 - 1\n				);\n\n			case \'blob\':\n			case \'text\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 65535,      // 2^16 - 1\n				);\n\n			case \'mediumblob\':\n			case \'mediumtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 167772,   // 2^24 - 1\n				);\n\n			case \'longblob\':\n			case \'longtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 4294967295, // 2^32 - 1\n				);\n\n			default:\n				return false;\n		}\n	}\n\n	/**\n	 * Check if a string is ASCII.\n	 *\n	 * The negative regex is faster for non-ASCII strings, as it allows\n	 * the search to finish as soon as it encounters a non-ASCII character.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $string String to check.\n	 * @return bool True if ASCII, false if not.\n	 */\n	protected function check_ascii( $string ) {\n		if ( function_exists( \'mb_check_encoding\' ) ) {\n			if ( mb_check_encoding( $string, \'ASCII\' ) ) {\n				return true;\n			}\n		} elseif ( ! preg_match( \'/[^\\x00-\\x7F]/\', $string ) ) {\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Check if the query is accessing a collation considered safe on the current version of MySQL.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to check.\n	 * @return bool True if the collation is safe, false if it isn\'t.\n	 */\n	protected function check_safe_collation( $query ) {\n		if ( $this-&gt;checking_collation ) {\n			return true;\n		}\n\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $query ) ) {\n			return true;\n		}\n\n		// All-ASCII queries don\'t need extra checking.\n		if ( $this-&gt;check_ascii( $query ) ) {\n			return true;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( ! $table ) {\n			return false;\n		}\n\n		$this-&gt;checking_collation = true;\n		$collation                = $this-&gt;get_table_charset( $table );\n		$this-&gt;checking_collation = false;\n\n		// Tables with no collation, or latin1 only, don\'t need extra checking.\n		if ( false === $collation || \'latin1\' === $collation ) {\n			return true;\n		}\n\n		$table = strtolower( $table );\n		if ( empty( $this-&gt;col_meta[ $table ] ) ) {\n			return false;\n		}\n\n		// If any of the columns don\'t have one of these collations, it needs more sanity checking.\n		foreach ( $this-&gt;col_meta[ $table ] as $col ) {\n			if ( empty( $col-&gt;Collation ) ) {\n				continue;\n			}\n\n			if ( ! in_array( $col-&gt;Collation, array( \'utf8_general_ci\', \'utf8_bin\', \'utf8mb4_general_ci\', \'utf8mb4_bin\' ), true ) ) {\n				return false;\n			}\n		}\n\n		return true;\n	}\n\n	/**\n	 * Strips any invalid characters based on value/charset pairs.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data Array of value arrays. Each value array has the keys\n	 *                    \'value\' and \'charset\'. An optional \'ascii\' key can be\n	 *                    set to false to avoid redundant ASCII checks.\n	 * @return array|WP_Error The $data parameter, with invalid characters removed from\n	 * each value. This works as a passthrough: any additional keys\n	 * such as \'field\' are retained in each value array. If we cannot\n	 * remove invalid characters, a WP_Error object is returned.\n	 */\n	protected function strip_invalid_text( $data ) {\n		$db_check_string = false;\n\n		foreach ( $data as &amp;$value ) {\n			$charset = $value[\'charset\'];\n\n			if ( is_array( $value[\'length\'] ) ) {\n				$length                  = $value[\'length\'][\'length\'];\n				$truncate_by_byte_length = \'byte\' === $value[\'length\'][\'type\'];\n			} else {\n				$length = false;\n				// Since we have no length, we\'ll never truncate.\n				// Initialize the variable to false. true would take us\n				// through an unnecessary (for this case) codepath below.\n				$truncate_by_byte_length = false;\n			}\n\n			// There\'s no charset to work with.\n			if ( false === $charset ) {\n				continue;\n			}\n\n			// Column isn\'t a string.\n			if ( ! is_string( $value[\'value\'] ) ) {\n				continue;\n			}\n\n			$needs_validation = true;\n			if (\n				// latin1 can store any byte sequence\n				\'latin1\' === $charset\n			||\n				// ASCII is always OK.\n				( ! isset( $value[\'ascii\'] ) &amp;&amp; $this-&gt;check_ascii( $value[\'value\'] ) )\n			) {\n				$truncate_by_byte_length = true;\n				$needs_validation        = false;\n			}\n\n			if ( $truncate_by_byte_length ) {\n				mbstring_binary_safe_encoding();\n				if ( false !== $length &amp;&amp; strlen( $value[\'value\'] ) &gt; $length ) {\n					$value[\'value\'] = substr( $value[\'value\'], 0, $length );\n				}\n				reset_mbstring_encoding();\n\n				if ( ! $needs_validation ) {\n					continue;\n				}\n			}\n\n			// utf8 can be handled by regex, which is a bunch faster than a DB lookup.\n			if ( ( \'utf8\' === $charset || \'utf8mb3\' === $charset || \'utf8mb4\' === $charset ) &amp;&amp; function_exists( \'mb_strlen\' ) ) {\n				$regex = \'/\n					(\n						(?: [\\x00-\\x7F]                  # single-byte sequences   0xxxxxxx\n						|   [\\xC2-\\xDF][\\x80-\\xBF]       # double-byte sequences   110xxxxx 10xxxxxx\n						|   \\xE0[\\xA0-\\xBF][\\x80-\\xBF]   # triple-byte sequences   1110xxxx 10xxxxxx * 2\n						|   [\\xE1-\\xEC][\\x80-\\xBF]{2}\n						|   \\xED[\\x80-\\x9F][\\x80-\\xBF]\n						|   [\\xEE-\\xEF][\\x80-\\xBF]{2}\';\n\n				if ( \'utf8mb4\' === $charset ) {\n					$regex .= \'\n						|    \\xF0[\\x90-\\xBF][\\x80-\\xBF]{2} # four-byte sequences   11110xxx 10xxxxxx * 3\n						|    [\\xF1-\\xF3][\\x80-\\xBF]{3}\n						|    \\xF4[\\x80-\\x8F][\\x80-\\xBF]{2}\n					\';\n				}\n\n				$regex         .= \'){1,40}   # ...one or more times\n					)\n					| .           # anything else\n					/x\';\n				$value[\'value\'] = preg_replace( $regex, \'$1\', $value[\'value\'] );\n\n				if ( false !== $length &amp;&amp; mb_strlen( $value[\'value\'], \'UTF-8\' ) &gt; $length ) {\n					$value[\'value\'] = mb_substr( $value[\'value\'], 0, $length, \'UTF-8\' );\n				}\n				continue;\n			}\n\n			// We couldn\'t use any local conversions, send it to the DB.\n			$value[\'db\'] = $db_check_string = true;\n		}\n		unset( $value ); // Remove by reference.\n\n		if ( $db_check_string ) {\n			$queries = array();\n			foreach ( $data as $col =&gt; $value ) {\n				if ( ! empty( $value[\'db\'] ) ) {\n					// We\'re going to need to truncate by characters or bytes, depending on the length value we have.\n					if ( \'byte\' === $value[\'length\'][\'type\'] ) {\n						// Using binary causes LEFT() to truncate by bytes.\n						$charset = \'binary\';\n					} else {\n						$charset = $value[\'charset\'];\n					}\n\n					if ( $this-&gt;charset ) {\n						$connection_charset = $this-&gt;charset;\n					} else {\n						if ( $this-&gt;use_mysqli ) {\n							$connection_charset = mysqli_character_set_name( $this-&gt;dbh );\n						} else {\n							$connection_charset = mysql_client_encoding();\n						}\n					}\n\n					if ( is_array( $value[\'length\'] ) ) {\n						$length          = sprintf( \'%.0f\', $value[\'length\'][\'length\'] );\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( LEFT( CONVERT( %s USING $charset ), $length ) USING $connection_charset )\", $value[\'value\'] );\n					} elseif ( \'binary\' !== $charset ) {\n						// If we don\'t have a length, there\'s no need to convert binary - it will always return the same result.\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( CONVERT( %s USING $charset ) USING $connection_charset )\", $value[\'value\'] );\n					}\n\n					unset( $data[ $col ][\'db\'] );\n				}\n			}\n\n			$sql = array();\n			foreach ( $queries as $column =&gt; $query ) {\n				if ( ! $query ) {\n					continue;\n				}\n\n				$sql[] = $query . \" AS x_$column\";\n			}\n\n			$this-&gt;check_current_query = false;\n			$row= $this-&gt;get_row( \'SELECT \' . implode( \', \', $sql ), ARRAY_A );\n			if ( ! $row ) {\n				return new WP_Error( \'wpdb_strip_invalid_text_failure\' );\n			}\n\n			foreach ( array_keys( $data ) as $column ) {\n				if ( isset( $row[ \"x_$column\" ] ) ) {\n					$data[ $column ][\'value\'] = $row[ \"x_$column\" ];\n				}\n			}\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Strips any invalid characters from the query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query Query to convert.\n	 * @return string|WP_Error The converted query, or a WP_Error object if the conversion fails.\n	 */\n	protected function strip_invalid_text_from_query( $query ) {\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$trimmed_query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $trimmed_query ) ) {\n			return $query;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( $table ) {\n			$charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $charset ) ) {\n				return $charset;\n			}\n\n			// We can\'t reliably strip text from tables containing binary/blob columns\n			if ( \'binary\' === $charset ) {\n				return $query;\n			}\n		} else {\n			$charset = $this-&gt;charset;\n		}\n\n		$data = array(\n			\'value\'   =&gt; $query,\n			\'charset\' =&gt; $charset,\n			\'ascii\'   =&gt; false,\n			\'length\'  =&gt; false,\n		);\n\n		$data = $this-&gt;strip_invalid_text( array( $data ) );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[0][\'value\'];\n	}\n\n	/**\n	 * Strips any invalid characters from the string for a given table and column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @param string $value  The text to check.\n	 * @return string|WP_Error The converted string, or a WP_Error object if the conversion fails.\n	 */\n	public function strip_invalid_text_for_column( $table, $column, $value ) {\n		if ( ! is_string( $value ) ) {\n			return $value;\n		}\n\n		$charset = $this-&gt;get_col_charset( $table, $column );\n		if ( ! $charset ) {\n			// Not a string column.\n			return $value;\n		} elseif ( is_wp_error( $charset ) ) {\n			// Bail on real errors.\n			return $charset;\n		}\n\n		$data = array(\n			$column =&gt; array(\n				\'value\'   =&gt; $value,\n				\'charset\' =&gt; $charset,\n				\'length\'  =&gt; $this-&gt;get_col_length( $table, $column ),\n			),\n		);\n\n		$data = $this-&gt;strip_invalid_text( $data );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[ $column ][\'value\'];\n	}\n\n	/**\n	 * Find the first table name referenced in a query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to search.\n	 * @return string|false $table The table name found, or false if a table couldn\'t be found.\n	 */\n	protected function get_table_from_query( $query ) {\n		// Remove characters that can legally trail the table name.\n		$query = rtrim( $query, \';/-#\' );\n\n		// Allow (select...) union [...] style queries. Use the first query\'s table name.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n\n		// Strip everything between parentheses except nested selects.\n		$query = preg_replace( \'/\\((?!\\s*select)[^(]*?\\)/is\', \'()\', $query );\n\n		// Quickly match most common queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'SELECT.*?\\s+FROM\'\n				. \'|INSERT(?:\\s+LOW_PRIORITY|\\s+DELAYED|\\s+HIGH_PRIORITY)?(?:\\s+IGNORE)?(?:\\s+INTO)?\'\n				. \'|REPLACE(?:\\s+LOW_PRIORITY|\\s+DELAYED)?(?:\\s+INTO)?\'\n				. \'|UPDATE(?:\\s+LOW_PRIORITY)?(?:\\s+IGNORE)?\'\n				. \'|DELETE(?:\\s+LOW_PRIORITY|\\s+QUICK|\\s+IGNORE)*(?:.+?FROM)?\'\n			. \')\\s+((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		// SHOW TABLE STATUS and SHOW TABLES WHERE Name = \'wp_posts\'\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES).+WHERE\\s+Name\\s*=\\s*(\"|\\\')((?:[0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\\\1/is\', $query, $maybe ) ) {\n			return $maybe[2];\n		}\n\n		// SHOW TABLE STATUS LIKE and SHOW TABLES LIKE \'wp\\_3\\_%\'\n		// This quoted LIKE operand seldom holds a full table name.\n		// It is usually a pattern for matching a prefix so we just\n		// strip the trailing % and unescape the _ to get \'wp_3_\'\n		// which drop-ins can use for routing these SQL statements.\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES)\\s+(?:WHERE\\s+Name\\s+)?LIKE\\s*(\"|\\\')((?:[\\\\\\\\0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)%?\\\\1/is\', $query, $maybe ) ) {\n			return str_replace( \'\\\\_\', \'_\', $maybe[2] );\n		}\n\n		// Big pattern for the rest of the table-related queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'(?:EXPLAIN\\s+(?:EXTENDED\\s+)?)?SELECT.*?\\s+FROM\'\n				. \'|DESCRIBE|DESC|EXPLAIN|HANDLER\'\n				. \'|(?:LOCK|UNLOCK)\\s+TABLE(?:S)?\'\n				. \'|(?:RENAME|OPTIMIZE|BACKUP|RESTORE|CHECK|CHECKSUM|ANALYZE|REPAIR).*\\s+TABLE\'\n				. \'|TRUNCATE(?:\\s+TABLE)?\'\n				. \'|CREATE(?:\\s+TEMPORARY)?\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\'\n				. \'|ALTER(?:\\s+IGNORE)?\\s+TABLE\'\n				. \'|DROP\\s+TABLE(?:\\s+IF\\s+EXISTS)?\'\n				. \'|CREATE(?:\\s+\\w+)?\\s+INDEX.*\\s+ON\'\n				. \'|DROP\\s+INDEX.*\\s+ON\'\n				. \'|LOAD\\s+DATA.*INFILE.*INTO\\s+TABLE\'\n				. \'|(?:GRANT|REVOKE).*ON\\s+TABLE\'\n				. \'|SHOW\\s+(?:.*FROM|.*TABLE)\'\n			. \')\\s+\\(*\\s*((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\s*\\)*/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		return false;\n	}\n\n	/**\n	 * Load the column metadata from the last query.\n	 *\n	 * @since 3.5.0\n	 */\n	protected function load_col_info() {\n		if ( $this-&gt;col_info ) {\n			return;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$num_fields = mysqli_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysqli_fetch_field( $this-&gt;result );\n			}\n		} else {\n			$num_fields = mysql_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysql_fetch_field( $this-&gt;result, $i );\n			}\n		}\n	}\n\n	/**\n	 * Retrieve column metadata from the last query.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $info_type  Optional. Type one of name, table, def, max_length, not_null, primary_key, multiple_key, unique_key, numeric, blob, type, unsigned, zerofill\n	 * @param int    $col_offset Optional. 0: col name. 1: which table the col\'s in. 2: col\'s max length. 3: if the col is numeric. 4: col\'s type\n	 * @return mixed Column Results\n	 */\n	public function get_col_info( $info_type = \'name\', $col_offset = -1 ) {\n		$this-&gt;load_col_info();\n\n		if ( $this-&gt;col_info ) {\n			if ( $col_offset == -1 ) {\n				$i         = 0;\n				$new_array = array();\n				foreach ( (array) $this-&gt;col_info as $col ) {\n					$new_array[ $i ] = $col-&gt;{$info_type};\n					$i++;\n				}\n				return $new_array;\n			} else {\n				return $this-&gt;col_info[ $col_offset ]-&gt;{$info_type};\n			}\n		}\n	}\n\n	/**\n	 * Starts the timer, for debugging purposes.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return true\n	 */\n	public function timer_start() {\n		$this-&gt;time_start = microtime( true );\n		return true;\n	}\n\n	/**\n	 * Stops the debugging timer.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return float Total time spent on the query, in seconds\n	 */\n	public function timer_stop() {\n		return ( microtime( true ) - $this-&gt;time_start );\n	}\n\n	/**\n	 * エラーを素敵なヘッダーとフッターにラップして終わります。\n	 *\n	 * wpdb :: $ show_errorsがfalseであれば死にません。\n	 *\n	 * @since 1.5.0\n	 *\n	 * @param string $message    The Error message\n	 * @param string $error_code Optional. エラーを識別するためのコンピュータ可読文字列。\n	 * @return false|void\n	 */\n	public function bail( $message, $error_code = \'500\' ) {\n		if ( $this-&gt;show_errors ) {\n			$error = \'\';\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$error = mysqli_error( $this-&gt;dbh );\n				} elseif ( mysqli_connect_errno() ) {\n					$error = mysqli_connect_error();\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$error = mysql_error( $this-&gt;dbh );\n				} else {\n					$error = mysql_error();\n				}\n			}\n\n			if ( $error ) {\n				$message = \'&lt;p&gt;&lt;code&gt;\' . $error . \"&lt;/code&gt;&lt;/p&gt;\\n\" . $message;\n			}\n\n			wp_die( $message );\n		} else {\n			if ( class_exists( \'WP_Error\', false ) ) {\n				$this-&gt;error = new WP_Error( $error_code, $message );\n			} else {\n				$this-&gt;error = $message;\n			}\n\n			return false;\n		}\n	}\n\n\n	/**\n	 * 現在のデータベース接続を閉じます。\n	 *\n	 * @since 4.5.0\n	 *\n	 * @return bool True if the connection was successfully closed, false if it wasn\'t,\n	 *              or the connection doesn\'t exist.\n	 */\n	public function close() {\n		if ( ! $this-&gt;dbh ) {\n			return false;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$closed = mysqli_close( $this-&gt;dbh );\n		} else {\n			$closed = mysql_close( $this-&gt;dbh );\n		}\n\n		if ( $closed ) {\n			$this-&gt;dbh           = null;\n			$this-&gt;ready         = false;\n			$this-&gt;has_connected = false;\n		}\n\n		return $closed;\n	}\n\n	/**\n	 * MySQLデータベースが最低限必要な最小バージョンかどうか\n	 *\n	 * @since 2.5.0\n	 *\n	 * @global string $wp_version\n	 * @global string $required_mysql_version\n	 *\n	 * @return WP_Error|void\n	 */\n	public function check_database_version() {\n		global $wp_version, $required_mysql_version;\n		// サーバーに必要なMySQLバージョンがあることを確認してください。\n		if ( version_compare( $this-&gt;db_version(), $required_mysql_version, \'&lt;\' ) ) {\n			/* translators: 1: WordPress version number, 2: Minimum required MySQL version number */\n			return new WP_Error( \'database_version\', sprintf( __( \'&lt;strong&gt;ERROR&lt;/strong&gt;: WordPress %1$s requires MySQL %2$s or higher\' ), $wp_version, $required_mysql_version ) );\n		}\n	}\n\n	/**\n	 * データベースが照合をサポートしているかどうか\n	 *\n	 * WordPressがテーブルスキームを生成しているときに呼び出されます。\n	 *\n	 * Use `wpdb::has_cap( \'collation\' )`.\n	 *\n	 * @since 2.5.0\n	 * @deprecated 3.5.0 Use wpdb::has_cap()\n	 *\n	 * @return bool True if collation is supported, false if version does not\n	 */\n	public function supports_collation() {\n		_deprecated_function( __FUNCTION__, \'3.5.0\', \'wpdb::has_cap( \\\'collation\\\' )\' );\n		return $this-&gt;has_cap( \'collation\' );\n	}\n\n	/**\n	 * データベース文字の照合\n	 *\n	 * @since 3.5.0\n	 *\n	 * @return string The database character collate.\n	 */\n	public function get_charset_collate() {\n		$charset_collate = \'\';\n\n		if ( ! empty( $this-&gt;charset ) ) {\n			$charset_collate = \"DEFAULT CHARACTER SET $this-&gt;charset\";\n		}\n		if ( ! empty( $this-&gt;collate ) ) {\n			$charset_collate .= \" COLLATE $this-&gt;collate\";\n		}\n\n		return $charset_collate;\n	}\n\n	/**\n	 * データベースが特定の機能をサポートしているかどうかを確認します。\n	 *\n	 * @since 2.7.0\n	 * @since 4.1.0 Added support for the \'utf8mb4\' feature.\n	 * @since 4.6.0 Added support for the \'utf8mb4_520\' feature.\n	 *\n	 * @see wpdb::db_version()\n	 *\n	 * @param string $db_cap The feature to check for. Accepts \'collation\',\n	 *\'group_concat\', \'subqueries\', \'set_charset\',\n	 *\'utf8mb4\', or \'utf8mb4_520\'.\n	 * @return int|false Whether the database feature is supported, false otherwise.\n	 */\n	public function has_cap( $db_cap ) {\n		$version = $this-&gt;db_version();\n\n		switch ( strtolower( $db_cap ) ) {\n			case \'collation\':    // @since 2.5.0\n			case \'group_concat\': // @since 2.7.0\n			case \'subqueries\':   // @since 2.7.0\n				return version_compare( $version, \'4.1\', \'&gt;=\' );\n			case \'set_charset\':\n				return version_compare( $version, \'5.0.7\', \'&gt;=\' );\n			case \'utf8mb4\':      // @since 4.1.0\n				if ( version_compare( $version, \'5.5.3\', \'&lt;\' ) ) {\n					return false;\n				}\n				if ( $this-&gt;use_mysqli ) {\n					$client_version = mysqli_get_client_info();\n				} else {\n					$client_version = mysql_get_client_info();\n				}\n\n				/*\n				 * libmysql has supported utf8mb4 since 5.5.3, same as the MySQL server.\n				 * mysqlnd has supported utf8mb4 since 5.0.9.\n				 */\n				if ( false !== strpos( $client_version, \'mysqlnd\' ) ) {\n					$client_version = preg_replace( \'/^\\D+([\\d.]+).*/\', \'$1\', $client_version );\n					return version_compare( $client_version, \'5.0.9\', \'&gt;=\' );\n				} else {\n					return version_compare( $client_version, \'5.5.3\', \'&gt;=\' );\n				}\n			case \'utf8mb4_520\': // @since 4.6.0\n				return version_compare( $version, \'5.6\', \'&gt;=\' );\n		}\n\n		return false;\n	}\n\n	/**\n	 * wpdbを呼び出した関数の名前を取得してください。\n	 *\n	 * Searches up the list of functions until it reaches\n	 * the one that would most logically had called this method.\n	 *\n	 * @since 2.5.0\n	 *\n	 * @return string Comma separated list of the calling functions.\n	 */\n	public function get_caller() {\n		return wp_debug_backtrace_summary( __CLASS__ );\n	}\n\n	/**\n	 * MySQLサーバーのバージョンを取得します。\n	 *\n	 * @since 2.7.0\n	 *\n	 * @return null|string Null on failure, version number on success.\n	 */\n	public function db_version() {\n		if ( $this-&gt;use_mysqli ) {\n			$server_info = mysqli_get_server_info( $this-&gt;dbh );\n		} else {\n			$server_info = mysql_get_server_info( $this-&gt;dbh );\n		}\n		return preg_replace( \'/[^0-9.].*/\', \'\', $server_info );\n	}\n}\n</pre>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function __construct～__unset</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>文字セット設定　init_charset～</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>SQLモードの確認</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>テーブルにつけるプレフィックスを設定</h3>\n<!-- /wp:heading -->\n\n<p>wp-config.phpで設定してるやつです。</p>\n<p>wordpressのデフォルトのテーブル12個にはいずれも頭にwp_とついてますが、テーブル名をここで決めています。</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-11 13:29:57','2019-06-11 04:29:57','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2482,1,'2019-06-11 13:36:27','2019-06-11 04:36:27','<p>このファイルはデータベースに接続してデータを取得したりインサートするファイルになります。</p>\n<p>MVCモデルで言うとmodelにあたるような役割をこのファイルで行っています。</p>\n<p>なお、このファイルは全部で(コメント込みで)3500行ほどあるので分割して読んでいきます。</p>\n<p> </p>\n<pre class=\"lang:php decode:true \" title=\"wp-db.php\">&lt;?php\n/**\n * WordPress DBクラス\n *\n * 元のコード  {@link http://php.justinvincent.com Justin Vincent (justin@visunet.ie)}\n *\n * @package WordPress\n * @subpackage Database\n * @since 0.71\n */\n\n/**\n * @since 0.71\n */\ndefine( \'EZSQL_VERSION\', \'WP1.25\' );\n\n/**\n * @since 0.71\n */\ndefine( \'OBJECT\', \'OBJECT\' );\n// phpcs:ignore Generic.NamingConventions.UpperCaseConstantName.ConstantNotUpperCase\ndefine( \'object\', \'OBJECT\' ); // Back compat.\n\n/**\n * @since 2.5.0\n */\ndefine( \'OBJECT_K\', \'OBJECT_K\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_A\', \'ARRAY_A\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_N\', \'ARRAY_N\' );\n\n/**\n * WordPressデータベースアクセス抽象化オブジェクト\n *\n * wp-content / db.phpファイルの$ wpdbグローバル変数を\n * あなたのクラスに設定することで、このクラスをあなた自身のクラスに\n * 置き換えることが可能です。\n *\n * @link https://codex.wordpress.org/Function_Reference/wpdb_Class\n *\n * @since 0.71\n */\nclass wpdb {\n\n	/**\n	 * SQL / DBエラーを表示するかどうか\n	 *\n	 * デフォルトの動作では、WP_DEBUGとWP_DEBUG_DISPLAYの両方がtrueと評価された場合に\n	 * エラーを表示します。\n	 *\n	 * @since 0.71\n	 * @var bool\n	 */\n	var $show_errors = false;\n\n	/**\n	 * DBブートストラップ中のエラーを抑制するかどうか。\n	 *\n	 * @since 2.5.0\n	 * @var bool\n	 */\n	var $suppress_errors = false;\n\n	/**\n	 * クエリ中の最後のエラー\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $last_error = \'\';\n\n	/**\n	 * 行われたクエリの量\n	 *\n	 * @since 1.2.0\n	 * @var int\n	 */\n	public $num_queries = 0;\n\n	/**\n	 * 前のクエリによって返された行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $num_rows = 0;\n\n	/**\n	 * 前の照会による影響を受けた行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	var $rows_affected = 0;\n\n	/**\n	 * 前回のクエリによってAUTO_INCREMENTカラムに対して生成されたID（通常はINSERT）。\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $insert_id = 0;\n\n	/**\n	 * 最後に行われたクエリ\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	var $last_query;\n\n	/**\n	 * 最後に行われたクエリの結果\n	 *\n	 * @since 0.71\n	 * @var array|null\n	 */\n	var $last_result;\n\n	/**\n	 * MySQLの結果。これはリソースまたはブール値です。\n	 *\n	 * @since 0.71\n	 * @var mixed\n	 */\n	protected $result;\n\n	/**\n	 * 挿入前のサニティチェックデータ用のキャッシュされた列情報\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $col_meta = array();\n\n	/**\n	 * テーブルの計算文字セット\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $table_charset = array();\n\n	/**\n	 * 現在のクエリのテキストフィールドを健全性チェックする必要があるかどうか。\n	 *\n	 * @since 4.2.0\n	 * @var bool\n	 */\n	protected $check_current_query = true;\n\n	/**\n	 * 照合をチェックするときに再帰問題に遭遇しないようにするためのフラグ。\n	 *\n	 * @since 4.2.0\n	 * @see wpdb::check_safe_collation()\n	 * @var bool\n	 */\n	private $checking_collation = false;\n\n	/**\n	 * テーブルカラムに保存された情報\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	protected $col_info;\n\n	/**\n	 * デバッグ目的で実行されたクエリのログ。\n	 *\n	 * @since 1.5.0\n	 * @since 2.5.0 各クエリログの3番目の要素は、呼び出し元の関数を記録するために追加されました。\n	 * @since 5.1.0 各クエリログの4番目の要素は、開始時刻を記録するために追加されました。\n	 *\n	 * @var array[] {\n	 *     実行されたクエリの配列。\n	 *\n	 *     @type array ...$0 {\n	 *         Data for each query.\n	 *\n	 *         @type string $0 The query\'s SQL.\n	 *         @type float  $1 照会に費やした合計時間（秒単位）。\n	 *         @type string $2 呼び出し側関数のコンマ区切りリスト。\n	 *         @type float  $3 問い合わせの開始時のUnixタイムスタンプ。\n	 *     }\n	 * }\n	 */\n	var $queries;\n\n	/**\n	 * 死ぬまでに再接続を再試行する回数\n	 *\n	 * @since 3.9.0\n	 * @see wpdb::check_connection()\n	 * @var int\n	 */\n	protected $reconnect_retries = 5;\n\n	/**\n	 * WordPressのテーブルプレフィックス\n	 *\n	 * 単一のデータベースに複数のWordPressをインストールするように設定できます。\n	 * 2番目の理由は、考えられるセキュリティ上の予防策です。\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $prefix = \'\';\n\n	/**\n	 * WordPressのベーステーブルプレフィックス。\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $base_prefix;\n\n	/**\n	 * Whether the database queries are ready to start executing.\n	 *\n	 * @since 2.3.2\n	 * @var bool\n	 */\n	var $ready = false;\n\n	/**\n	 * Blog ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $blogid = 0;\n\n	/**\n	 * Site ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $siteid = 0;\n\n	/**\n	 * ブログ毎のWordPress一覧表\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $tables = array(\n		\'posts\',\n		\'comments\',\n		\'links\',\n		\'options\',\n		\'postmeta\',\n		\'terms\',\n		\'term_taxonomy\',\n		\'term_relationships\',\n		\'termmeta\',\n		\'commentmeta\',\n	);\n\n	/**\n	 * 廃止予定のWordPressテーブルのリスト\n	 *\n	 * categories、post2cat、およびlink2catは、2.3.0、dbバージョン5539で非推奨となりました。\n	 *\n	 * @since 2.9.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $old_tables = array( \'categories\', \'post2cat\', \'link2cat\' );\n\n	/**\n	 * WordPressグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $global_tables = array( \'users\', \'usermeta\' );\n\n	/**\n	 * マルチサイトグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $ms_global_tables = array(\n		\'blogs\',\n		\'blogmeta\',\n		\'signups\',\n		\'site\',\n		\'sitemeta\',\n		\'sitecategories\',\n		\'registration_log\',\n		\'blog_versions\',\n	);\n\n	/**\n	 * WordPress Comments table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $comments;\n\n	/**\n	 * WordPress Comment Metadata table\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	public $commentmeta;\n\n	/**\n	 * WordPress Links table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $links;\n\n	/**\n	 * WordPress Options table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $options;\n\n	/**\n	 * WordPress Post Metadata table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $postmeta;\n\n	/**\n	 * WordPress Posts table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $posts;\n\n	/**\n	 * WordPress Terms table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $terms;\n\n	/**\n	 * WordPress Term Relationships table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_relationships;\n\n	/**\n	 * WordPress Term Taxonomy table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_taxonomy;\n\n	/**\n	 * WordPress Term Meta table.\n	 *\n	 * @since 4.4.0\n	 * @var string\n	 */\n	public $termmeta;\n\n	//\n	// Global and Multisite tables\n	//\n\n	/**\n	 * WordPress User Metadata table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $usermeta;\n\n	/**\n	 * WordPress Users table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $users;\n\n	/**\n	 * Multisite Blogs table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blogs;\n\n	/**\n	 * Multisite Blog Metadata table\n	 *\n	 * @since 5.1.0\n	 * @var string\n	 */\n	public $blogmeta;\n\n	/**\n	 * Multisite Blog Versions table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blog_versions;\n\n	/**\n	 * Multisite Registration Log table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $registration_log;\n\n	/**\n	 * Multisite Signups table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $signups;\n\n	/**\n	 * Multisite Sites table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $site;\n\n	/**\n	 * Multisite Sitewide Terms table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitecategories;\n\n	/**\n	 * Multisite Site Metadata table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitemeta;\n\n	/**\n	 * DB列のフォーマット指定子ここにリストされていない列は、デフォルトで％sになります。WPロード中に初期化されました。\n	 *\n	 * キーはカラム名、値はフォーマットタイプです。 \'ID\' =&gt; \'％d\'\n	 *\n	 * @since 2.8.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::insert()\n	 * @see wpdb::update()\n	 * @see wpdb::delete()\n	 * @see wp_set_wpdb_vars()\n	 * @var array\n	 */\n	public $field_types = array();\n\n	/**\n	 * Database table columns charset\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $charset;\n\n	/**\n	 * Database table columns collate\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $collate;\n\n	/**\n	 * Database Username\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	protected $dbuser;\n\n	/**\n	 * Database Password\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbpassword;\n\n	/**\n	 * Database Name\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbname;\n\n	/**\n	 * Database Host\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbhost;\n\n	/**\n	 * Database Handle\n	 *\n	 * @since 0.71\n	 * @var string\n	 */\n	protected $dbh;\n\n	/**\n	 * 最後のクエリ/ get_row / get_var呼び出しの説明文\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $func_call;\n\n	/**\n	 * MySQLがデータベースエンジンとして使用されているかどうか。\n	 *\n	 * デフォルトでは、WPDB :: db_connect（）をtrueに設定します。 \n	 * これはWordPressに必要なMySQLバージョンをチェックするときに使われます。 \n	 * 通常、置換データベースドロップイン（db.php）はこれらのチェックをスキップしますが、\n	 * これをtrueに設定するとチェックを強制的に実行させます。\n	 *\n	 * @since 3.3.0\n	 * @var bool\n	 */\n	public $is_mysql = null;\n\n	/**\n	 * 互換性のないSQLモードのリスト。\n	 *\n	 * @since 3.9.0\n	 * @var array\n	 */\n	protected $incompatible_modes = array(\n		\'NO_ZERO_DATE\',\n		\'ONLY_FULL_GROUP_BY\',\n		\'STRICT_TRANS_TABLES\',\n		\'STRICT_ALL_TABLES\',\n		\'TRADITIONAL\',\n	);\n\n	/**\n	 * mysql上でmysqliを使用するかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $use_mysqli = false;\n\n	/**\n	 * ある時点でうまく接続できたかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $has_connected = false;\n\n	/**\n	 * データベースサーバーに接続してデータベースを選択する\n	 *\n	 * PPHP 5との互換性のためのHP 5スタイルのコンストラクタ。 Does\n	 * クラスプロパティの実際の設定とデータベースへの接続を行います。\n	 * \n	 *\n	 * @link https://core.trac.wordpress.org/ticket/3354\n	 * @since 2.0.8\n	 *\n	 * @global string $wp_version\n	 *\n	 * @param string $dbuser     MySQL database user\n	 * @param string $dbpassword MySQL database password\n	 * @param string $dbname     MySQL database name\n	 * @param string $dbhost     MySQL database host\n	 */\n	public function __construct( $dbuser, $dbpassword, $dbname, $dbhost ) {\n		register_shutdown_function( array( $this, \'__destruct\' ) );\n\n		if ( WP_DEBUG &amp;&amp; WP_DEBUG_DISPLAY ) {\n			$this-&gt;show_errors();\n		}\n\n		// WP_USE_EXT_MYSQLがtrueとして定義されていない限り、存在する場合はext / mysqliを使用\n		if ( function_exists( \'mysqli_connect\' ) ) {\n			$this-&gt;use_mysqli = true;\n\n			if ( defined( \'WP_USE_EXT_MYSQL\' ) ) {\n				$this-&gt;use_mysqli = ! WP_USE_EXT_MYSQL;\n			}\n		}\n\n		$this-&gt;dbuser     = $dbuser;\n		$this-&gt;dbpassword = $dbpassword;\n		$this-&gt;dbname     = $dbname;\n		$this-&gt;dbhost     = $dbhost;\n\n		// wp-config.phpの作成は準備ができたら手動で接続します。\n		if ( defined( \'WP_SETUP_CONFIG\' ) ) {\n			return;\n		}\n\n		$this-&gt;db_connect();\n	}\n\n	/**\n	 * PHP 5スタイルのデストラクタで、データベースオブジェクトが破棄されたときに実行されます。\n	 *\n	 * @see wpdb::__construct()\n	 * @since 2.0.8\n	 * @return true\n	 */\n	public function __destruct() {\n		return true;\n	}\n\n	/**\n	 * 下位互換性のためにプライベートプロパティを読み取り可能にします\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name The private member to get, and optionally process\n	 * @return mixed The private member\n	 */\n	public function __get( $name ) {\n		if ( \'col_info\' === $name ) {\n			$this-&gt;load_col_info();\n		}\n\n		return $this-&gt;$name;\n	}\n\n	/**\n	 *プライベートプロパティを下位互換性のために設定可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to set\n	 * @param mixed  $value The value to set\n	 */\n	public function __set( $name, $value ) {\n		$protected_members = array(\n			\'col_meta\',\n			\'table_charset\',\n			\'check_current_query\',\n		);\n		if ( in_array( $name, $protected_members, true ) ) {\n			return;\n		}\n		$this-&gt;$name = $value;\n	}\n\n	/**\n	 * プライベートプロパティを下位互換性のためにチェック可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to check\n	 *\n	 * @return bool If the member is set or not\n	 */\n	public function __isset( $name ) {\n		return isset( $this-&gt;$name );\n	}\n\n	/**\n	 * Makes private properties un-settable for backward compatibility.\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to unset\n	 */\n	public function __unset( $name ) {\n		unset( $this-&gt;$name );\n	}\n\n	/**\n	 * Set $this-&gt;charset and $this-&gt;collate\n	 *\n	 * @since 3.1.0\n	 */\n	public function init_charset() {\n		$charset = \'\';\n		$collate = \'\';\n\n		if ( function_exists( \'is_multisite\' ) &amp;&amp; is_multisite() ) {\n			$charset = \'utf8\';\n			if ( defined( \'DB_COLLATE\' ) &amp;&amp; DB_COLLATE ) {\n				$collate = DB_COLLATE;\n			} else {\n				$collate = \'utf8_general_ci\';\n			}\n		} elseif ( defined( \'DB_COLLATE\' ) ) {\n			$collate = DB_COLLATE;\n		}\n\n		if ( defined( \'DB_CHARSET\' ) ) {\n			$charset = DB_CHARSET;\n		}\n\n		$charset_collate = $this-&gt;determine_charset( $charset, $collate );\n\n		$this-&gt;charset = $charset_collate[\'charset\'];\n		$this-&gt;collate = $charset_collate[\'collate\'];\n	}\n\n	/**\n	 * 与えられた文字セットと照合順序を使用して、使用するのに最適な文字セットと照合順序を決定します。\n	 *\n	 * たとえば、可能であれば、utf8の代わりにutf8mb4を使用する必要があります。\n	 *\n	 * @since 4.6.0\n	 *\n	 * @param string $charset The character set to check.\n	 * @param string $collate The collation to check.\n	 * @return array The most appropriate character set and collation to use.\n	 */\n	public function determine_charset( $charset, $collate ) {\n		if ( ( $this-&gt;use_mysqli &amp;&amp; ! ( $this-&gt;dbh instanceof mysqli ) ) || empty( $this-&gt;dbh ) ) {\n			return compact( \'charset\', \'collate\' );\n		}\n\n		if ( \'utf8\' === $charset &amp;&amp; $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8mb4\';\n		}\n\n		if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8\';\n			$collate = str_replace( \'utf8mb4_\', \'utf8_\', $collate );\n		}\n\n		if ( \'utf8mb4\' === $charset ) {\n			// _general_ is outdated, so we can upgrade it to _unicode_, instead.\n			if ( ! $collate || \'utf8_general_ci\' === $collate ) {\n				$collate = \'utf8mb4_unicode_ci\';\n			} else {\n				$collate = str_replace( \'utf8_\', \'utf8mb4_\', $collate );\n			}\n		}\n\n		// _unicode_520_ is a better collation, we should use that when it\'s available.\n		if ( $this-&gt;has_cap( \'utf8mb4_520\' ) &amp;&amp; \'utf8mb4_unicode_ci\' === $collate ) {\n			$collate = \'utf8mb4_unicode_520_ci\';\n		}\n\n		return compact( \'charset\', \'collate\' );\n	}\n\n	/**\n	 * 接続の文字セットを設定します。\n	 *\n	 * @since 3.1.0\n	 *\n	 * @param resource $dbh     The resource given by mysql_connect\n	 * @param string   $charset Optional. The character set. Default null.\n	 * @param string   $collate Optional. The collation. Default null.\n	 */\n	public function set_charset( $dbh, $charset = null, $collate = null ) {\n		if ( ! isset( $charset ) ) {\n			$charset = $this-&gt;charset;\n		}\n		if ( ! isset( $collate ) ) {\n			$collate = $this-&gt;collate;\n		}\n		if ( $this-&gt;has_cap( \'collation\' ) &amp;&amp; ! empty( $charset ) ) {\n			$set_charset_succeeded = true;\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( function_exists( \'mysqli_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysqli_set_charset( $dbh, $charset );\n				}\n\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysqli_query( $dbh, $query );\n				}\n			} else {\n				if ( function_exists( \'mysql_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysql_set_charset( $charset, $dbh );\n				}\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysql_query( $query, $dbh );\n				}\n			}\n		}\n	}\n\n	/**\n	 * 現在のSQLモードを変更し、そのWordPress互換性を確認してください。\n	 *\n	 * If no modes are passed, it will ensure the current MySQL server\n	 * modes are compatible.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param array $modes Optional. A list of SQL modes to set.\n	 */\n	public function set_sql_mode( $modes = array() ) {\n		if ( empty( $modes ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$res = mysqli_query( $this-&gt;dbh, \'SELECT @@SESSION.sql_mode\' );\n			} else {\n				$res = mysql_query( \'SELECT @@SESSION.sql_mode\', $this-&gt;dbh );\n			}\n\n			if ( empty( $res ) ) {\n				return;\n			}\n\n			if ( $this-&gt;use_mysqli ) {\n				$modes_array = mysqli_fetch_array( $res );\n				if ( empty( $modes_array[0] ) ) {\n					return;\n				}\n				$modes_str = $modes_array[0];\n			} else {\n				$modes_str = mysql_result( $res, 0 );\n			}\n\n			if ( empty( $modes_str ) ) {\n				return;\n			}\n\n			$modes = explode( \',\', $modes_str );\n		}\n\n		$modes = array_change_key_case( $modes, CASE_UPPER );\n\n		/**\n		 * Filters the list of incompatible SQL modes to exclude.\n		 *\n		 * @since 3.9.0\n		 *\n		 * @param array $incompatible_modes An array of incompatible modes.\n		 */\n		$incompatible_modes = (array) apply_filters( \'incompatible_sql_modes\', $this-&gt;incompatible_modes );\n\n		foreach ( $modes as $i =&gt; $mode ) {\n			if ( in_array( $mode, $incompatible_modes ) ) {\n				unset( $modes[ $i ] );\n			}\n		}\n\n		$modes_str = implode( \',\', $modes );\n\n		if ( $this-&gt;use_mysqli ) {\n			mysqli_query( $this-&gt;dbh, \"SET SESSION sql_mode=\'$modes_str\'\" );\n		} else {\n			mysql_query( \"SET SESSION sql_mode=\'$modes_str\'\", $this-&gt;dbh );\n		}\n	}\n\n	/**\n	 * WordPressテーブルのテーブルプレフィックスを設定します。\n	 *\n	 * @since 2.5.0\n	 *\n	 * @param string $prefix          Alphanumeric name for the new prefix.\n	 * @param bool   $set_table_names Optional. Whether the table names, e.g. wpdb::$posts, should be updated or not.\n	 * @return string|WP_Error Old prefix or WP_Error on error\n	 */\n	public function set_prefix( $prefix, $set_table_names = true ) {\n\n		if ( preg_match( \'|[^a-z0-9_]|i\', $prefix ) ) {\n			return new WP_Error( \'invalid_db_prefix\', \'Invalid database prefix\' );\n		}\n\n		$old_prefix = is_multisite() ? \'\' : $prefix;\n\n		if ( isset( $this-&gt;base_prefix ) ) {\n			$old_prefix = $this-&gt;base_prefix;\n		}\n\n		$this-&gt;base_prefix = $prefix;\n\n		if ( $set_table_names ) {\n			foreach ( $this-&gt;tables( \'global\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			if ( is_multisite() &amp;&amp; empty( $this-&gt;blogid ) ) {\n				return $old_prefix;\n			}\n\n			$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n			foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n		}\n		return $old_prefix;\n	}\n\n	/**\n	 * ブログIDを設定する\n	 *\n	 * @since 3.0.0\n	 *\n	 * @param int $blog_id\n	 * @param int $network_id Optional.\n	 * @return int previous blog id\n	 */\n	public function set_blog_id( $blog_id, $network_id = 0 ) {\n		if ( ! empty( $network_id ) ) {\n			$this-&gt;siteid = $network_id;\n		}\n\n		$old_blog_id  = $this-&gt;blogid;\n		$this-&gt;blogid = $blog_id;\n\n		$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n		foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		return $old_blog_id;\n	}\n\n	/**\n	 * Gets blog prefix.\n	 *\n	 * @since 3.0.0\n	 * @param int $blog_id Optional.\n	 * @return string Blog prefix.\n	 */\n	public function get_blog_prefix( $blog_id = null ) {\n		if ( is_multisite() ) {\n			if ( null === $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_id = (int) $blog_id;\n			if ( defined( \'MULTISITE\' ) &amp;&amp; ( 0 == $blog_id || 1 == $blog_id ) ) {\n				return $this-&gt;base_prefix;\n			} else {\n				return $this-&gt;base_prefix . $blog_id . \'_\';\n			}\n		} else {\n			return $this-&gt;base_prefix;\n		}\n	}\n\n	/**\n	 * WordPressテーブルの配列を返します。\n	 *\n	 * またCUSTOM_USER_TABLEとCUSTOM_USER_META_TABLEがWordPressユーザーと\n	 * usermetaテーブルを上書きすることを可能にします。そうでなければプレフィックスによって決定されます。\n	 *\n	 * scope引数は、以下のいずれかを取ります。\n	 *\n	 * \'all\' - \'all\'および \'global\'テーブルを返します。古いテーブルは返されません。\n	 * \'blog\' - 照会されたブログのブログレベルのテーブルを返します。\n	 * \'global\'インストール用のグローバルテーブルを返します。マルチサイトを実行している場合にのみマルチサイトテーブルを返します。\n	 * \'ms_global\' - 現在のインストールがマルチサイトかどうかにかかわらず、マルチサイトグローバルテーブルを返します。\n	 * \'old\' - 廃止予定のテーブルを返します。\n	 *\n	 * @since 3.0.0\n	 * @uses wpdb::$tables\n	 * @uses wpdb::$old_tables\n	 * @uses wpdb::$global_tables\n	 * @uses wpdb::$ms_global_tables\n	 *\n	 * @param string $scope  オプションです。 all、global、ms_global、blog、または古いテーブルにすることができます。デフォルトはallです。\n	 * @param bool   $ prefixオプション。テーブルプレフィックスを含めるかどうか。ブログならデフォルトはtrueです。\n	 * 接頭辞が要求されると、カスタムユーザーとusermetaテーブルがマッピングされます。\n	 * @param int    $blog_id Optional. The blog_id to prefix. Defaults to wpdb::$blogid. Used only when prefix is requested.\n	 * @return array Table names. When a prefix is requested, the key is the unprefixed table name.\n	 */\n	public function tables( $scope = \'all\', $prefix = true, $blog_id = 0 ) {\n		switch ( $scope ) {\n			case \'all\':\n				$tables = array_merge( $this-&gt;global_tables, $this-&gt;tables );\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'blog\':\n				$tables = $this-&gt;tables;\n				break;\n			case \'global\':\n				$tables = $this-&gt;global_tables;\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'ms_global\':\n				$tables = $this-&gt;ms_global_tables;\n				break;\n			case \'old\':\n				$tables = $this-&gt;old_tables;\n				break;\n			default:\n				return array();\n		}\n\n		if ( $prefix ) {\n			if ( ! $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_prefix   = $this-&gt;get_blog_prefix( $blog_id );\n			$base_prefix   = $this-&gt;base_prefix;\n			$global_tables = array_merge( $this-&gt;global_tables, $this-&gt;ms_global_tables );\n			foreach ( $tables as $k =&gt; $table ) {\n				if ( in_array( $table, $global_tables ) ) {\n					$tables[ $table ] = $base_prefix . $table;\n				} else {\n					$tables[ $table ] = $blog_prefix . $table;\n				}\n				unset( $tables[ $k ] );\n			}\n\n			if ( isset( $tables[\'users\'] ) &amp;&amp; defined( \'CUSTOM_USER_TABLE\' ) ) {\n				$tables[\'users\'] = CUSTOM_USER_TABLE;\n			}\n\n			if ( isset( $tables[\'usermeta\'] ) &amp;&amp; defined( \'CUSTOM_USER_META_TABLE\' ) ) {\n				$tables[\'usermeta\'] = CUSTOM_USER_META_TABLE;\n			}\n		}\n\n		return $tables;\n	}\n\n	/**\n	 * 現在のデータベース接続を使用してデータベースを選択します。\n	 *\n	 * データベース名は現在のデータベース接続に基づいて変更されます。\n	 * 失敗すると、実行は停止し、DBエラーを表示します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string        $db  MySQL database name\n	 * @param resource|null $dbh Optional link identifier.\n	 */\n	public function select( $db, $dbh = null ) {\n		if ( is_null( $dbh ) ) {\n			$dbh = $this-&gt;dbh;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$success = mysqli_select_db( $dbh, $db );\n		} else {\n			$success = mysql_select_db( $db, $dbh );\n		}\n		if ( ! $success ) {\n			$this-&gt;ready = false;\n			if ( ! did_action( \'template_redirect\' ) ) {\n				wp_load_translations_early();\n\n				$message = \'&lt;h1&gt;\' . __( \'Can&amp;#8217;t select database\' ) . \"&lt;/h1&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'We were able to connect to the database server (which means your username and password is okay) but not able to select the %s database.\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/p&gt;\\n\";\n\n				$message .= \"&lt;ul&gt;\\n\";\n				$message .= \'&lt;li&gt;\' . __( \'Are you sure it exists?\' ) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: 1: database user, 2: database name */\n					__( \'Does the user %1$s have permission to use the %2$s database?\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbuser, ENT_QUOTES ) . \'&lt;/code&gt;\',\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'On some systems the name of your database is prefixed with your username, so it would be like &lt;code&gt;username_%1$s&lt;/code&gt;. Could that be the problem?\' ),\n					htmlspecialchars( $db, ENT_QUOTES )\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \"&lt;/ul&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: support forums URL */\n					__( \'If you don&amp;#8217;t know how to set up a database you should &lt;strong&gt;contact your host&lt;/strong&gt;. If all else fails you may find help at the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n					__( \'https://wordpress.org/support/\' )\n				) . \"&lt;/p&gt;\\n\";\n\n				$this-&gt;bail( $message, \'db_select_fail\' );\n			}\n		}\n	}\n\n	/**\n	 * 使用しないでください、廃止予定です。\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 2.8.0\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare\n	 * @see esc_sql()\n	 *\n	 * @param string $string\n	 * @return string\n	 */\n	function _weak_escape( $string ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		return addslashes( $string );\n	}\n\n	/**\n	 * Real escape, using mysqli_real_escape_string() or mysql_real_escape_string()\n	 *\n	 * @see mysqli_real_escape_string()\n	 * @see mysql_real_escape_string()\n	 * @since 2.8.0\n	 *\n	 * @param  string $string to escape\n	 * @return string escaped\n	 */\n	function _real_escape( $string ) {\n		if ( $this-&gt;dbh ) {\n			if ( $this-&gt;use_mysqli ) {\n				$escaped = mysqli_real_escape_string( $this-&gt;dbh, $string );\n			} else {\n				$escaped = mysql_real_escape_string( $string, $this-&gt;dbh );\n			}\n		} else {\n			$class = get_class( $this );\n			if ( function_exists( \'__\' ) ) {\n				/* translators: %s: database access abstraction class, usually wpdb or a class extending wpdb */\n				_doing_it_wrong( $class, sprintf( __( \'%s must set a database connection for use with escaping.\' ), $class ), \'3.6.0\' );\n			} else {\n				_doing_it_wrong( $class, sprintf( \'%s must set a database connection for use with escaping.\', $class ), \'3.6.0\' );\n			}\n			$escaped = addslashes( $string );\n		}\n\n		return $this-&gt;add_placeholder_escape( $escaped );\n	}\n\n	/**\n	 * Escape data. Works on arrays.\n	 *\n	 * @uses wpdb::_real_escape()\n	 * @since  2.8.0\n	 *\n	 * @param  string|array $data\n	 * @return string|array escaped\n	 */\n	public function _escape( $data ) {\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;_escape( $v );\n				} else {\n					$data[ $k ] = $this-&gt;_real_escape( $v );\n				}\n			}\n		} else {\n			$data = $this-&gt;_real_escape( $data );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Do not use, deprecated.\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 0.71\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare()\n	 * @see esc_sql()\n	 *\n	 * @param mixed $data\n	 * @return mixed\n	 */\n	public function escape( $data ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;escape( $v, \'recursive\' );\n				} else {\n					$data[ $k ] = $this-&gt;_weak_escape( $v, \'internal\' );\n				}\n			}\n		} else {\n			$data = $this-&gt;_weak_escape( $data, \'internal\' );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Escapes content by reference for insertion into the database, for security\n	 *\n	 * @uses wpdb::_real_escape()\n	 *\n	 * @since 2.3.0\n	 *\n	 * @param string $string to escape\n	 */\n	public function escape_by_ref( &amp;$string ) {\n		if ( ! is_float( $string ) ) {\n			$string = $this-&gt;_real_escape( $string );\n		}\n	}\n\n	/**\n	 * 安全に実行できるようにSQLクエリを準備します。sprintf（）に似た構文を使用。\n	 *\n	 * クエリ文字列では、次のプレースホルダを使用できます。\n	 *   %d (integer)数字\n	 *   %f (float)\n	 *   %s (string)　文字列\n	 *\n	 * すべてのプレースホルダは、クエリ文字列では引用符で囲まないでおく必要があります。各プレースホルダーに対応する引数を渡す必要があります。\n	 *\n	 * 古い振る舞いとの互換性のために、番号付きまたはフォーマットされた文字列プレースホルダー（例えば、％1 $ s、％5s）は引用符を含みません\n	 * この関数によって追加されたので、あなたの使用法のためにそれらを囲む適切な引用符で渡されるべきです。\n	 *\n	 * エリ文字列内のリテラルパーセント記号（％）は、%%として記述する必要があります。 （たとえばLIKE構文で使用するため）\n	 * ワイルドカードパーセンテージは、完全なLIKE文字列を含む置換引数を介して渡す必要があります。\n	 * これらは、クエリ文字列に直接挿入することはできません。  {@see wpdb :: esc_like（）}もご覧ください。\n	 *\n	 * 引数は、メソッドへの個々の引数として渡すことも、すべての引数を含む単一の配列として渡すこともできます。\n	 * この2つの組み合わせはサポートされていません。\n	 *\n	 * 例えば\n	 *     $wpdb-&gt;prepare( \"SELECT * FROM `table` WHERE `column` = %s AND `field` = %d OR `other_field` LIKE %s\", array( \'foo\', 37, \'%bar\' ) );\n	 *     $wpdb-&gt;prepare( \"SELECT DATE_FORMAT(`field`, \'%%c\') FROM `table` WHERE `column` = %s\", \'foo\' );\n	 *\n	 * @link https://secure.php.net/sprintf Description of syntax.\n	 * @since 2.3.0\n	 *\n	 * @param string      $query    Query statement with sprintf()-like placeholders\n	 * @param array|mixed $args     The array of variables to substitute into the query\'s placeholders if being called with an array of arguments,\n	 *       or the first variable to substitute into the query\'s placeholders if being called with individual arguments.\n	 * @param mixed       $args,... further variables to substitute into the query\'s placeholders if being called wih individual arguments.\n	 * @return string|void Sanitized query string, if there is a query to prepare.\n	 */\n	public function prepare( $query, $args ) {\n		if ( is_null( $query ) ) {\n			return;\n		}\n\n		// これは絶対に確実というわけではないが明らかに誤った用法を捕らえるでしょう.\n		if ( strpos( $query, \'%\' ) === false ) {\n			wp_load_translations_early();\n			_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'The query argument of %s must have a placeholder.\' ), \'wpdb::prepare()\' ), \'3.9.0\' );\n		}\n\n		$args = func_get_args();\n		array_shift( $args );\n\n		// 引数が（vsprintfのように）配列として渡された場合は、それらを上に移動します。\n		$passed_as_array = false;\n		if ( is_array( $args[0] ) &amp;&amp; count( $args ) == 1 ) {\n			$passed_as_array = true;\n			$args            = $args[0];\n		}\n\n		foreach ( $args as $arg ) {\n			if ( ! is_scalar( $arg ) &amp;&amp; ! is_null( $arg ) ) {\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'Unsupported value type (%s).\' ), gettype( $arg ) ), \'4.8.2\' );\n			}\n		}\n\n		/*\n		 * プレースホルダで許可されている書式設定を指定します。以下が許可されています。\n		 *\n		 * - Sign specifier. eg, $+d\n		 * - Numbered placeholders. eg, %1$s\n		 * - Padding specifier, including custom padding characters. eg, %05s, %\'#5s\n		 * - Alignment specifier. eg, %05-s\n		 * - Precision specifier. eg, %.2f\n		 */\n		$allowed_format = \'(?:[1-9][0-9]*[$])?[-+0-9]*(?: |0|\\\'.)?[-+0-9]*(?:\\.[0-9]+)?\';\n\n		/*\n		 * ％sプレースホルダの周囲に引用符が既にある場合は、既存の引用符を削除してそれらを再挿入\n		 * すると、引用符の整合性が保証されます。\n		 *\n		 * 下位互換性のために、これは％sにのみ適用され、長い文字列の途中で頻繁に使用される％1 $ sなどのプレースホルダ、またはテーブル名プレースホルダには適用されません。\n		 */\n		$query = str_replace( \"\'%s\'\", \'%s\', $query ); // 既存の一重引用符を削除します。\n		$query = str_replace( \'\"%s\"\', \'%s\', $query ); // 既存の二重引用符を削除します。\n\n		// %% sのようなエスケープ文字列を避けて、文字列を引用符で囲みます。\n		$query = preg_replace( \'/(?&lt;!%)%s/\', \"\'%s\'\", $query );\n\n		 // フロートをロケールに気付かないようにします。\n		$query = preg_replace( \"/(?&lt;!%)(%($allowed_format)?f)/\", \'%\\\\2F\', $query ); \n\n		$query = preg_replace( \"/%(?:%|$|(?!($allowed_format)?[sdF]))/\", \'%%\\\\1\', $query ); // エスケープされていないパーセントをエスケープします。\n\n		// クエリ内の有効なプレースホルダの数を数えます。\n		$placeholders = preg_match_all( \"/(^|[^%]|(%%)+)%($allowed_format)?[sdF]/\", $query, $matches );\n\n		if ( count( $args ) !== $placeholders ) {\n			if ( 1 === $placeholders &amp;&amp; $passed_as_array ) {\n				// If the passed query only expected one argument, but the wrong number of arguments were sent as an array, bail.\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', __( \'The query only expected one placeholder, but an array of multiple placeholders was sent.\' ), \'4.9.0\' );\n\n				return;\n			} else {\n				/*\n				 * 適切な数のプレースホルダがなくても、それらが個別の引数として渡された場合、\n				 * または配列内に複数の引数があることが予想される場合は、警告をスローします。\n				 */\n				wp_load_translations_early();\n				_doing_it_wrong(\n					\'wpdb::prepare\',\n					/* translators: 1: number of placeholders, 2: number of arguments passed */\n					sprintf(\n						__( \'The query does not contain the correct number of placeholders (%1$d) for the number of arguments passed (%2$d).\' ),\n						$placeholders,\n						count( $args )\n					),\n					\'4.8.3\'\n				);\n			}\n		}\n\n		array_walk( $args, array( $this, \'escape_by_ref\' ) );\n		$query = @vsprintf( $query, $args );\n\n		return $this-&gt;add_placeholder_escape( $query );\n	}\n\n	/**\n	 * MySQLの準備の前にLIKE特殊文字％と_をエスケープする前半。\n	 *\n	 * これはwpdb ::prepare（）またはesc_sql（）の前にのみ使用してください。順序を逆にすると、セキュリティが非常に悪くなります。\n	 *\n	 * 準備済みステートメントの例：\n	 *\n	 *     $wild = \'%\';\n	 *     $find = \'only 43% of planets\';\n	 *     $like = $wild . $wpdb-&gt;esc_like( $find ) . $wild;\n	 *     $sql  = $wpdb-&gt;prepare( \"SELECT * FROM $wpdb-&gt;posts WHERE post_content LIKE %s\", $like );\n	 *\n	 * Example Escape Chain:\n	 *\n	 *     $sql  = esc_sql( $wpdb-&gt;esc_like( $input ) );\n	 *\n	 * @since 4.0.0\n	 *\n	 * @param string $text The raw text to be escaped. The input typed by the user should have no\n	 *                     extra or deleted slashes.\n	 * @return string Text in the form of a LIKE phrase. The output is not SQL safe. Call $wpdb::prepare()\n	 *                or real_escape next.\n	 */\n	public function esc_like( $text ) {\n		return addcslashes( $text, \'_%\\\\\' );\n	}\n\n	/**\n	 * Print SQL/DB error.\n	 *\n	 * @since 0.71\n	 * @global array $EZSQL_ERROR Stores error information of query and error string\n	 *\n	 * @param string $str The error to display\n	 * @return false|void False if the showing of errors is disabled.\n	 */\n	public function print_error( $str = \'\' ) {\n		global $EZSQL_ERROR;\n\n		if ( ! $str ) {\n			if ( $this-&gt;use_mysqli ) {\n				$str = mysqli_error( $this-&gt;dbh );\n			} else {\n				$str = mysql_error( $this-&gt;dbh );\n			}\n		}\n		$EZSQL_ERROR[] = array(\n			\'query\'     =&gt; $this-&gt;last_query,\n			\'error_str\' =&gt; $str,\n		);\n\n		if ( $this-&gt;suppress_errors ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		if ( $caller = $this-&gt;get_caller() ) {\n			/* translators: 1: Database error message, 2: SQL query, 3: Name of the calling function */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s made by %3$s\' ), $str, $this-&gt;last_query, $caller );\n		} else {\n			/* translators: 1: Database error message, 2: SQL query */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s\' ), $str, $this-&gt;last_query );\n		}\n\n		error_log( $error_str );\n\n		// Are we showing errors?\n		if ( ! $this-&gt;show_errors ) {\n			return false;\n		}\n\n		// If there is an error then take note of it\n		if ( is_multisite() ) {\n			$msg = sprintf(\n				\"%s [%s]\\n%s\\n\",\n				__( \'WordPress database error:\' ),\n				$str,\n				$this-&gt;last_query\n			);\n\n			if ( defined( \'ERRORLOGFILE\' ) ) {\n				error_log( $msg, 3, ERRORLOGFILE );\n			}\n			if ( defined( \'DIEONDBERROR\' ) ) {\n				wp_die( $msg );\n			}\n		} else {\n			$str   = htmlspecialchars( $str, ENT_QUOTES );\n			$query = htmlspecialchars( $this-&gt;last_query, ENT_QUOTES );\n\n			printf(\n				\'&lt;div id=\"error\"&gt;&lt;p class=\"wpdberror\"&gt;&lt;strong&gt;%s&lt;/strong&gt; [%s]&lt;br /&gt;&lt;code&gt;%s&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;\',\n				__( \'WordPress database error:\' ),\n				$str,\n				$query\n			);\n		}\n	}\n\n	/**\n	 * データベースエラーの表示を有効にします。\n	 *\n	 * この機能はエラーの表示を可能にするためだけに使用されるべきです。\n	 * wpdb::hide_errors() should be used instead for hiding of errors. However,\n	 * this function can be used to enable and disable showing of database\n	 * errors.\n	 *\n	 * @since 0.71\n	 * @see wpdb::hide_errors()\n	 *\n	 * @param bool $show Whether to show or hide errors\n	 * @return bool Old value for showing errors.\n	 */\n	public function show_errors( $show = true ) {\n		$errors            = $this-&gt;show_errors;\n		$this-&gt;show_errors = $show;\n		return $errors;\n	}\n\n	/**\n	 * Disables showing of database errors.\n	 *\n	 * By default database errors are not shown.\n	 *\n	 * @since 0.71\n	 * @see wpdb::show_errors()\n	 *\n	 * @return bool Whether showing of errors was active\n	 */\n	public function hide_errors() {\n		$show              = $this-&gt;show_errors;\n		$this-&gt;show_errors = false;\n		return $show;\n	}\n\n	/**\n	 * Whether to suppress database errors.\n	 *\n	 * By default database errors are suppressed, with a simple\n	 * call to this function they can be enabled.\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::hide_errors()\n	 * @param bool $suppress Optional. New value. Defaults to true.\n	 * @return bool Old value\n	 */\n	public function suppress_errors( $suppress = true ) {\n		$errors                = $this-&gt;suppress_errors;\n		$this-&gt;suppress_errors = (bool) $suppress;\n		return $errors;\n	}\n\n	/**\n	 * Kill cached query results.\n	 *\n	 * @since 0.71\n	 */\n	public function flush() {\n		$this-&gt;last_result   = array();\n		$this-&gt;col_info      = null;\n		$this-&gt;last_query    = null;\n		$this-&gt;rows_affected = $this-&gt;num_rows = 0;\n		$this-&gt;last_error    = \'\';\n\n		if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n			mysqli_free_result( $this-&gt;result );\n			$this-&gt;result = null;\n\n			// Sanity check before using the handle\n			if ( empty( $this-&gt;dbh ) || ! ( $this-&gt;dbh instanceof mysqli ) ) {\n				return;\n			}\n\n			// Clear out any results from a multi-query\n			while ( mysqli_more_results( $this-&gt;dbh ) ) {\n				mysqli_next_result( $this-&gt;dbh );\n			}\n		} elseif ( is_resource( $this-&gt;result ) ) {\n			mysql_free_result( $this-&gt;result );\n		}\n	}\n\n	/**\n	 * データベースに接続して選択します。\n	 *\n	 * $ allow_bailがfalseの場合、データベース接続の欠如は手動で処理する必要があります。.\n	 *\n	 * @since 3.0.0\n	 * @since 3.9.0 $allow_bail parameter added.\n	 *\n	 * @param bool $ allow_bailオプション。機能を保釈することを許可します。デフォルトはtrueです。\n	 * @return 成功した場合はtrue、失敗した場合はfalse。\n	 */\n	public function db_connect( $allow_bail = true ) {\n		$this-&gt;is_mysql = true;\n\n		/*\n		 * MySQLiを使用している場合は3.9以降では非推奨です。同等のものはありません\n		 * mysqli_ *関数には$ new_linkパラメータがあります。\n		 */\n		$new_link     = defined( \'MYSQL_NEW_LINK\' ) ? MYSQL_NEW_LINK : true;\n		$client_flags = defined( \'MYSQL_CLIENT_FLAGS\' ) ? MYSQL_CLIENT_FLAGS : 0;\n\n		if ( $this-&gt;use_mysqli ) {\n			$this-&gt;dbh = mysqli_init();\n\n			$host    = $this-&gt;dbhost;\n			$port    = null;\n			$socket  = null;\n			$is_ipv6 = false;\n\n			if ( $host_data = $this-&gt;parse_db_host( $this-&gt;dbhost ) ) {\n				list( $host, $port, $socket, $is_ipv6 ) = $host_data;\n			}\n\n			/*\n			 * If using the `mysqlnd` library, the IPv6 address needs to be\n			 * enclosed in square brackets, whereas it doesn\'t while using the\n			 * `libmysqlclient` library.\n			 * @see https://bugs.php.net/bug.php?id=67563\n			 */\n			if ( $is_ipv6 &amp;&amp; extension_loaded( \'mysqlnd\' ) ) {\n				$host = \"[$host]\";\n			}\n\n			if ( WP_DEBUG ) {\n				mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			} else {\n				@mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			}\n\n			if ( $this-&gt;dbh-&gt;connect_errno ) {\n				$this-&gt;dbh = null;\n\n				/*\n				 * ext / mysqliの設定が間違っている可能性があります。以下の場合、ext / mysqlにフォールバックしてください。\n				  *  - We haven\'t previously connected, and\n				  *  - WP_USE_EXT_MYSQL isn\'t set to false, and\n				  *  - ext/mysql is loaded.\n				  */\n				$attempt_fallback = true;\n\n				if ( $this-&gt;has_connected ) {\n					$attempt_fallback = false;\n				} elseif ( defined( \'WP_USE_EXT_MYSQL\' ) &amp;&amp; ! WP_USE_EXT_MYSQL ) {\n					$attempt_fallback = false;\n				} elseif ( ! function_exists( \'mysql_connect\' ) ) {\n					$attempt_fallback = false;\n				}\n\n				if ( $attempt_fallback ) {\n					$this-&gt;use_mysqli = false;\n					return $this-&gt;db_connect( $allow_bail );\n				}\n			}\n		} else {\n			if ( WP_DEBUG ) {\n				$this-&gt;dbh = mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			} else {\n				$this-&gt;dbh = @mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			}\n		}\n\n		if ( ! $this-&gt;dbh &amp;&amp; $allow_bail ) {\n			wp_load_translations_early();\n\n			// Load custom DB error template, if present.\n			if ( file_exists( WP_CONTENT_DIR . \'/db-error.php\' ) ) {\n				require_once( WP_CONTENT_DIR . \'/db-error.php\' );\n				die();\n			}\n\n			$message = \'&lt;h1&gt;\' . __( \'Error establishing a database connection\' ) . \"&lt;/h1&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: 1: wp-config.php, 2: database host */\n				__( \'This either means that the username and password information in your %1$s file is incorrect or we can&amp;#8217;t contact the database server at %2$s. This could mean your host&amp;#8217;s database server is down.\' ),\n				\'&lt;code&gt;wp-config.php&lt;/code&gt;\',\n				\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n			) . \"&lt;/p&gt;\\n\";\n\n			$message .= \"&lt;ul&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure you have the correct username and password?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that you have typed the correct hostname?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \"&lt;/ul&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: %s: support forums URL */\n				__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n				__( \'https://wordpress.org/support/\' )\n			) . \"&lt;/p&gt;\\n\";\n\n			$this-&gt;bail( $message, \'db_connect_fail\' );\n\n			return false;\n		} elseif ( $this-&gt;dbh ) {\n			if ( ! $this-&gt;has_connected ) {\n				$this-&gt;init_charset();\n			}\n\n			$this-&gt;has_connected = true;\n\n			$this-&gt;set_charset( $this-&gt;dbh );\n\n			$this-&gt;ready = true;\n			$this-&gt;set_sql_mode();\n			$this-&gt;select( $this-&gt;dbname, $this-&gt;dbh );\n\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Parse the DB_HOST setting to interpret it for mysqli_real_connect.\n	 *\n	 * mysqli_real_connect doesn\'t support the host param including a port or\n	 * socket like mysql_connect does. This duplicates how mysql_connect detects\n	 * a port and/or socket file.\n	 *\n	 * @since 4.9.0\n	 *\n	 * @param string $host The DB_HOST setting to parse.\n	 * @return array|bool Array containing the host, the port, the socket and whether\n	 *                    it is an IPv6 address, in that order. If $host couldn\'t be parsed,\n	 *                    returns false.\n	 */\n	public function parse_db_host( $host ) {\n		$port    = null;\n		$socket  = null;\n		$is_ipv6 = false;\n\n		// First peel off the socket parameter from the right, if it exists.\n		$socket_pos = strpos( $host, \':/\' );\n		if ( $socket_pos !== false ) {\n			$socket = substr( $host, $socket_pos + 1 );\n			$host   = substr( $host, 0, $socket_pos );\n		}\n\n		// We need to check for an IPv6 address first.\n		// An IPv6 address will always contain at least two colons.\n		if ( substr_count( $host, \':\' ) &gt; 1 ) {\n			$pattern = \'#^(?:\\[)?(?P&lt;host&gt;[0-9a-fA-F:]+)(?:\\]:(?P&lt;port&gt;[\\d]+))?#\';\n			$is_ipv6 = true;\n		} else {\n			// We seem to be dealing with an IPv4 address.\n			$pattern = \'#^(?P&lt;host&gt;[^:/]*)(?::(?P&lt;port&gt;[\\d]+))?#\';\n		}\n\n		$matches = array();\n		$result  = preg_match( $pattern, $host, $matches );\n\n		if ( 1 !== $result ) {\n			// Couldn\'t parse the address, bail.\n			return false;\n		}\n\n		$host = \'\';\n		foreach ( array( \'host\', \'port\' ) as $component ) {\n			if ( ! empty( $matches[ $component ] ) ) {\n				$component = $matches[ $component ];\n			}\n		}\n\n		return array( $host, $port, $socket, $is_ipv6 );\n	}\n\n	/**\n	 * Checks that the connection to the database is still up. If not, try to reconnect.\n	 *\n	 * If this function is unable to reconnect, it will forcibly die, or if after the\n	 * the {@see \'template_redirect\'} hook has been fired, return false instead.\n	 *\n	 * If $allow_bail is false, the lack of database connection will need\n	 * to be handled manually.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param bool $allow_bail Optional. Allows the function to bail. Default true.\n	 * @return bool|void True if the connection is up.\n	 */\n	public function check_connection( $allow_bail = true ) {\n		if ( $this-&gt;use_mysqli ) {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysqli_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		} else {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysql_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		}\n\n		$error_reporting = false;\n\n		// Disable warnings, as we don\'t want to see a multitude of \"unable to connect\" messages\n		if ( WP_DEBUG ) {\n			$error_reporting = error_reporting();\n			error_reporting( $error_reporting &amp; ~E_WARNING );\n		}\n\n		for ( $tries = 1; $tries &lt;= $this-&gt;reconnect_retries; $tries++ ) {\n			// On the last try, re-enable warnings. We want to see a single instance of the\n			// \"unable to connect\" message on the bail() screen, if it appears.\n			if ( $this-&gt;reconnect_retries === $tries &amp;&amp; WP_DEBUG ) {\n				error_reporting( $error_reporting );\n			}\n\n			if ( $this-&gt;db_connect( false ) ) {\n				if ( $error_reporting ) {\n					error_reporting( $error_reporting );\n				}\n\n				return true;\n			}\n\n			sleep( 1 );\n		}\n\n		// If template_redirect has already happened, it\'s too late for wp_die()/dead_db().\n		// Let\'s just return and hope for the best.\n		if ( did_action( \'template_redirect\' ) ) {\n			return false;\n		}\n\n		if ( ! $allow_bail ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		$message = \'&lt;h1&gt;\' . __( \'Error reconnecting to the database\' ) . \"&lt;/h1&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: database host */\n			__( \'This means that we lost contact with the database server at %s. This could mean your host&amp;#8217;s database server is down.\' ),\n			\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n		) . \"&lt;/p&gt;\\n\";\n\n		$message .= \"&lt;ul&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is not under particularly heavy load?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \"&lt;/ul&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: support forums URL */\n			__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n			__( \'https://wordpress.org/support/\' )\n		) . \"&lt;/p&gt;\\n\";\n\n		// We weren\'t able to reconnect, so we better bail.\n		$this-&gt;bail( $message, \'db_connect_fail\' );\n\n		// Call dead_db() if bail didn\'t die, because this database is no more. It has ceased to be (at least temporarily).\n		dead_db();\n	}\n\n	/**\n	 * 現在のデータベース接続を使用して、MySQLデータベースクエリを実行します。\n	 *\n	 * より詳しい情報はコーデックスページにあります。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query Database query\n	 * @return int|bool Boolean true for CREATE, ALTER, TRUNCATE and DROP queries. Number of rows\n	 *                  affected/selected for all other queries. Boolean false on error.\n	 */\n	public function query( $query ) {\n		if ( ! $this-&gt;ready ) {\n			$this-&gt;check_current_query = true;\n			return false;\n		}\n\n		/**\n		 * データベースクエリをフィルタリングします。\n		 *\n		 * プラグインがロードされる前にいくつかの問い合わせが行われます。\n		 * and thus cannot be filtered with this method.\n		 *\n		 * @since 2.1.0\n		 *\n		 * @param string $query Database query.\n		 */\n		$query = apply_filters( \'query\', $query );\n\n		$this-&gt;flush();\n\n		// Log how the function was called\n		$this-&gt;func_call = \"\\$db-&gt;query(\\\"$query\\\")\";\n\n		// If we\'re writing to the database, make sure the query will write safely.\n		if ( $this-&gt;check_current_query &amp;&amp; ! $this-&gt;check_ascii( $query ) ) {\n			$stripped_query = $this-&gt;strip_invalid_text_from_query( $query );\n			// strip_invalid_text_from_query() can perform queries, so we need\n			// to flush again, just to make sure everything is clear.\n			$this-&gt;flush();\n			if ( $stripped_query !== $query ) {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		$this-&gt;check_current_query = true;\n\n		// Keep track of the last query for debug.\n		$this-&gt;last_query = $query;\n\n		$this-&gt;_do_query( $query );\n\n		// MySQL server has gone away, try to reconnect.\n		$mysql_errno = 0;\n		if ( ! empty( $this-&gt;dbh ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$mysql_errno = mysqli_errno( $this-&gt;dbh );\n				} else {\n					// $dbh is defined, but isn\'t a real connection.\n					// Something has gone horribly wrong, let\'s try a reconnect.\n					$mysql_errno = 2006;\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$mysql_errno = mysql_errno( $this-&gt;dbh );\n				} else {\n					$mysql_errno = 2006;\n				}\n			}\n		}\n\n		if ( empty( $this-&gt;dbh ) || 2006 == $mysql_errno ) {\n			if ( $this-&gt;check_connection() ) {\n				$this-&gt;_do_query( $query );\n			} else {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		// If there is an error then take note of it.\n		if ( $this-&gt;use_mysqli ) {\n			if ( $this-&gt;dbh instanceof mysqli ) {\n				$this-&gt;last_error = mysqli_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		} else {\n			if ( is_resource( $this-&gt;dbh ) ) {\n				$this-&gt;last_error = mysql_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		}\n\n		if ( $this-&gt;last_error ) {\n			// Clear insert_id on a subsequent failed insert.\n			if ( $this-&gt;insert_id &amp;&amp; preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				$this-&gt;insert_id = 0;\n			}\n\n			$this-&gt;print_error();\n			return false;\n		}\n\n		if ( preg_match( \'/^\\s*(create|alter|truncate|drop)\\s/i\', $query ) ) {\n			$return_val = $this-&gt;result;\n		} elseif ( preg_match( \'/^\\s*(insert|delete|update|replace)\\s/i\', $query ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$this-&gt;rows_affected = mysqli_affected_rows( $this-&gt;dbh );\n			} else {\n				$this-&gt;rows_affected = mysql_affected_rows( $this-&gt;dbh );\n			}\n			// Take note of the insert_id\n			if ( preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				if ( $this-&gt;use_mysqli ) {\n					$this-&gt;insert_id = mysqli_insert_id( $this-&gt;dbh );\n				} else {\n					$this-&gt;insert_id = mysql_insert_id( $this-&gt;dbh );\n				}\n			}\n			// Return number of rows affected\n			$return_val = $this-&gt;rows_affected;\n		} else {\n			$num_rows = 0;\n			if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n				while ( $row = mysqli_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			} elseif ( is_resource( $this-&gt;result ) ) {\n				while ( $row = mysql_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			}\n\n			// Log number of rows the query returned\n			// and return number of rows selected\n			$this-&gt;num_rows = $num_rows;\n			$return_val     = $num_rows;\n		}\n\n		return $return_val;\n	}\n\n	/**\n	 * Internal function to perform the mysql_query() call.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @see wpdb::query()\n	 *\n	 * @param string $query The query to run.\n	 */\n	private function _do_query( $query ) {\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;timer_start();\n		}\n\n		if ( ! empty( $this-&gt;dbh ) &amp;&amp; $this-&gt;use_mysqli ) {\n			$this-&gt;result = mysqli_query( $this-&gt;dbh, $query );\n		} elseif ( ! empty( $this-&gt;dbh ) ) {\n			$this-&gt;result = mysql_query( $query, $this-&gt;dbh );\n		}\n		$this-&gt;num_queries++;\n\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;queries[] = array(\n				$query,\n				$this-&gt;timer_stop(),\n				$this-&gt;get_caller(),\n				$this-&gt;time_start,\n			);\n		}\n	}\n\n	/**\n	 * Generates and returns a placeholder escape string for use in queries returned by ::prepare().\n	 *\n	 * @since 4.8.3\n	 *\n	 * @return string String to escape placeholders.\n	 */\n	public function placeholder_escape() {\n		static $placeholder;\n\n		if ( ! $placeholder ) {\n			// If ext/hash is not present, compat.php\'s hash_hmac() does not support sha256.\n			$algo = function_exists( \'hash\' ) ? \'sha256\' : \'sha1\';\n			// Old WP installs may not have AUTH_SALT defined.\n			$salt = defined( \'AUTH_SALT\' ) &amp;&amp; AUTH_SALT ? AUTH_SALT : (string) rand();\n\n			$placeholder = \'{\' . hash_hmac( $algo, uniqid( $salt, true ), $salt ) . \'}\';\n		}\n\n		/*\n		 * レースホルダエスケープを削除するために、フィルタを追加します。優先順位0を使用します。\n		 * そのため、このフィルタに関連付けられている他のものはすべて、プレースホルダ文字列が削除されたクエリを受け取ります\n		 */\n		if ( ! has_filter( \'query\', array( $this, \'remove_placeholder_escape\' ) ) ) {\n			add_filter( \'query\', array( $this, \'remove_placeholder_escape\' ), 0 );\n		}\n\n		return $placeholder;\n	}\n\n	/**\n	 * printf（）のプレースホルダーに似たものをエスケープするために、プレースホルダーのエスケープ文字列を追加します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query to escape.\n	 * @return string 必要に応じてプレースホルダエスケープ文字列が挿入されたクエリ。\n	 */\n	public function add_placeholder_escape( $query ) {\n		/*\n		 * 漠然とプレースホルダーに似ているものでさえも返すことを防ぐために、私たちは見つけることが\n		 * できるあらゆる％をつぶします。\n		 */\n		return str_replace( \'%\', $this-&gt;placeholder_escape(), $query );\n	}\n\n	/**\n	 * クエリからプレースホルダエスケープ文字列を削除します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query from which the placeholder will be removed.\n	 * @return string The query with the placeholder removed.\n	 */\n	public function remove_placeholder_escape( $query ) {\n		return str_replace( $this-&gt;placeholder_escape(), \'%\', $query );\n	}\n\n	/**\n	 * Insert a row into a table.\n	 *\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows inserted, or false on error.\n	 */\n	public function insert( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'INSERT\' );\n	}\n\n	/**\n	 * Replace a row into a table.\n	 *\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	public function replace( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'REPLACE\' );\n	}\n\n	/**\n	 * Helper function for insert and replace.\n	 *\n	 * Runs an insert or replace query based on $type argument.\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param string $type         Optional. What type of operation is this? INSERT or REPLACE. Defaults to INSERT.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	function _insert_replace_helper( $table, $data, $format = null, $type = \'INSERT\' ) {\n		$this-&gt;insert_id = 0;\n\n		if ( ! in_array( strtoupper( $type ), array( \'REPLACE\', \'INSERT\' ) ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$formats = $values = array();\n		foreach ( $data as $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$formats[] = \'NULL\';\n				continue;\n			}\n\n			$formats[] = $value[\'format\'];\n			$values[]  = $value[\'value\'];\n		}\n\n		$fields  = \'`\' . implode( \'`, `\', array_keys( $data ) ) . \'`\';\n		$formats = implode( \', \', $formats );\n\n		$sql = \"$type INTO `$table` ($fields) VALUES ($formats)\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Update a row in the table\n	 *\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ), array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'ID\' =&gt; 1 ), array( \'%s\', \'%d\' ), array( \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $data         Data to update (in column =&gt; value pairs).\n	 *            Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *            Sending a null value will cause the column to be set to NULL - the corresponding\n	 *            format is ignored in this case.\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $format       Optional. An array of formats to be mapped to each of the values in $data.\n	 *            If string, that format will be used for all of the values in $data.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function update( $table, $data, $where, $format = null, $where_format = null ) {\n		if ( ! is_array( $data ) || ! is_array( $where ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$fields = $conditions = $values = array();\n		foreach ( $data as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$fields[] = \"`$field` = NULL\";\n				continue;\n			}\n\n			$fields[] = \"`$field` = \" . $value[\'format\'];\n			$values[] = $value[\'value\'];\n		}\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$fields     = implode( \', \', $fields );\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"UPDATE `$table` SET $fields WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Delete a row in the table\n	 *\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ), array( \'%d\' ) )\n	 *\n	 * @since 3.4.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function delete( $table, $where, $where_format = null ) {\n		if ( ! is_array( $where ) ) {\n			return false;\n		}\n\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$conditions = $values = array();\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"DELETE FROM `$table` WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Processes arrays of field/value pairs and field formats.\n	 *\n	 * This is a helper method for wpdb\'s CRUD methods, which take field/value\n	 * pairs for inserts, updates, and where clauses. This method first pairs\n	 * each value with a format. Then it determines the charset of that field,\n	 * using that to determine if any invalid text would be stripped. If text is\n	 * stripped, then field processing is rejected and the query fails.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param array  $data   Field/value pair.\n	 * @param mixed  $format Format for each field.\n	 * @return array|false Returns an array of fields that contain paired values\n	 *                    and formats. Returns false for invalid values.\n	 */\n	protected function process_fields( $table, $data, $format ) {\n		$data = $this-&gt;process_field_formats( $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_charsets( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_lengths( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$converted_data = $this-&gt;strip_invalid_text( $data );\n\n		if ( $data !== $converted_data ) {\n			return false;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Prepares arrays of value/format pairs as passed to wpdb CRUD methods.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data   Array of fields to values.\n	 * @param mixed $format Formats to be mapped to the values in $data.\n	 * @return array Array, keyed by field names with values being an array\n	 *               of \'value\' and \'format\' keys.\n	 */\n	protected function process_field_formats( $data, $format ) {\n		$formats = $original_formats = (array) $format;\n\n		foreach ( $data as $field =&gt; $value ) {\n			$value = array(\n				\'value\'  =&gt; $value,\n				\'format\' =&gt; \'%s\',\n			);\n\n			if ( ! empty( $format ) ) {\n				$value[\'format\'] = array_shift( $formats );\n				if ( ! $value[\'format\'] ) {\n					$value[\'format\'] = reset( $original_formats );\n				}\n			} elseif ( isset( $this-&gt;field_types[ $field ] ) ) {\n				$value[\'format\'] = $this-&gt;field_types[ $field ];\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Adds field charsets to field/value/format arrays generated by\n	 * the wpdb::process_field_formats() method.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_formats() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'charset\' keys.\n	 */\n	protected function process_field_charsets( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'charset\'] = false;\n			} else {\n				$value[\'charset\'] = $this-&gt;get_col_charset( $table, $field );\n				if ( is_wp_error( $value[\'charset\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * For string fields, record the maximum string length that field can safely save.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_charsets() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'length\' keys, or false if\n	 *                     any of the values were too long for their corresponding field.\n	 */\n	protected function process_field_lengths( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'length\'] = false;\n			} else {\n				$value[\'length\'] = $this-&gt;get_col_length( $table, $field );\n				if ( is_wp_error( $value[\'length\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Retrieve one variable from the database.\n	 *\n	 * Executes a SQL query and returns the value from the SQL result.\n	 * If the SQL result contains more than one column and/or more than one row, this function returns the value in the column and row specified.\n	 * If $query is null, this function returns the value in the specified column and row from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to null, use the result from the previous query.\n	 * @param int         $x     Optional. Column of value to return. Indexed from 0.\n	 * @param int         $y     Optional. Row of value to return. Indexed from 0.\n	 * @return string|null Database query result (as string), or null on failure\n	 */\n	public function get_var( $query = null, $x = 0, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_var(\\\"$query\\\", $x, $y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		// Extract var out of cached results based x,y vals\n		if ( ! empty( $this-&gt;last_result[ $y ] ) ) {\n			$values = array_values( get_object_vars( $this-&gt;last_result[ $y ] ) );\n		}\n\n		// If there is a value return it else return null\n		return ( isset( $values[ $x ] ) &amp;&amp; $values[ $x ] !== \'\' ) ? $values[ $x ] : null;\n	}\n\n	/**\n	 * Retrieve one row from the database.\n	 *\n	 * Executes a SQL query and returns the row from the SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query  SQL query.\n	 * @param string      $output Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which correspond to\n	 *     an stdClass object, an associative array, or a numeric array, respectively. Default OBJECT.\n	 * @param int         $y      Optional. Row to return. Indexed from 0.\n	 * @return array|object|null|void Database query result in format specified by $output or null on failure\n	 */\n	public function get_row( $query = null, $output = OBJECT, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_row(\\\"$query\\\",$output,$y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		if ( ! isset( $this-&gt;last_result[ $y ] ) ) {\n			return null;\n		}\n\n		if ( $output == OBJECT ) {\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} elseif ( $output == ARRAY_A ) {\n			return $this-&gt;last_result[ $y ] ? get_object_vars( $this-&gt;last_result[ $y ] ) : null;\n		} elseif ( $output == ARRAY_N ) {\n			return $this-&gt;last_result[ $y ] ? array_values( get_object_vars( $this-&gt;last_result[ $y ] ) ) : null;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} else {\n			$this-&gt;print_error( \' $db-&gt;get_row(string query, output type, int offset) -- Output type must be one of: OBJECT, ARRAY_A, ARRAY_N\' );\n		}\n	}\n\n	/**\n	 * Retrieve one column from the database.\n	 *\n	 * Executes a SQL query and returns the column from the SQL result.\n	 * If the SQL result contains more than one column, this function returns the column specified.\n	 * If $query is null, this function returns the specified column from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to previous query.\n	 * @param int         $x     Optional. Column to return. Indexed from 0.\n	 * @return array Database query result. Array indexed from 0 by SQL result row number.\n	 */\n	public function get_col( $query = null, $x = 0 ) {\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		$new_array = array();\n		// Extract the column values\n		if ( $this-&gt;last_result ) {\n			for ( $i = 0, $j = count( $this-&gt;last_result ); $i &lt; $j; $i++ ) {\n				$new_array[ $i ] = $this-&gt;get_var( null, $x, $i );\n			}\n		}\n		return $new_array;\n	}\n\n	/**\n	 * データベースからSQL結果セット全体（つまり多数の行）を取得します。\n	 *\n	 * SQLクエリを実行し、SQL結果全体を返します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query  SQL query.\n	 * @param string $output Optional. Any of ARRAY_A | ARRAY_N | OBJECT | OBJECT_K constants.\n	 *最初の3つのうちの1つでは、SQL結果の行番号によって0からインデックスされた行の配列を返します。\n	 *各行は連想配列（column =&gt; value、...）、数値インデックス配列（0 =&gt; value、...）、またはオブジェクトです。 （ - &gt; column = value）\n	 *OBJECT_Kを使用すると、各行の最初の列の値によってキー設定された行オブジェクトの連想配列を返します。\n	 *重複したキーは破棄されます。\n	 * @return 配列|オブジェクト|null データベースクエリ結果\n	 */\n	public function get_results( $query = null, $output = OBJECT ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_results(\\\"$query\\\", $output)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		$new_array = array();\n		if ( $output == OBJECT ) {\n			// Return an integer-keyed array of row objects\n			return $this-&gt;last_result;\n		} elseif ( $output == OBJECT_K ) {\n			// Return an array of row objects with keys from column 1\n			// (Duplicates are discarded)\n			if ( $this-&gt;last_result ) {\n				foreach ( $this-&gt;last_result as $row ) {\n					$var_by_ref = get_object_vars( $row );\n					$key        = array_shift( $var_by_ref );\n					if ( ! isset( $new_array[ $key ] ) ) {\n						$new_array[ $key ] = $row;\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( $output == ARRAY_A || $output == ARRAY_N ) {\n			// Return an integer-keyed array of...\n			if ( $this-&gt;last_result ) {\n				foreach ( (array) $this-&gt;last_result as $row ) {\n					if ( $output == ARRAY_N ) {\n						// ...integer-keyed row arrays\n						$new_array[] = array_values( get_object_vars( $row ) );\n					} else {\n						// ...column name-keyed row arrays\n						$new_array[] = get_object_vars( $row );\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result;\n		}\n		return null;\n	}\n\n	/**\n	 * Retrieves the character set for the given table.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table Table name.\n	 * @return string|WP_Error Table character set, WP_Error object if it couldn\'t be found.\n	 */\n	protected function get_table_charset( $table ) {\n		$tablekey = strtolower( $table );\n\n		/**\n		 * Filters the table charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will effectively short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 */\n		$charset = apply_filters( \'pre_get_table_charset\', null, $table );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		if ( isset( $this-&gt;table_charset[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		$charsets = $columns = array();\n\n		$table_parts = explode( \'.\', $table );\n		$table       = \'`\' . implode( \'`.`\', $table_parts ) . \'`\';\n		$results     = $this-&gt;get_results( \"SHOW FULL COLUMNS FROM $table\" );\n		if ( ! $results ) {\n			return new WP_Error( \'wpdb_get_table_charset_failure\' );\n		}\n\n		foreach ( $results as $column ) {\n			$columns[ strtolower( $column-&gt;Field ) ] = $column;\n		}\n\n		$this-&gt;col_meta[ $tablekey ] = $columns;\n\n		foreach ( $columns as $column ) {\n			if ( ! empty( $column-&gt;Collation ) ) {\n				list( $charset ) = explode( \'_\', $column-&gt;Collation );\n\n				// If the current connection can\'t support utf8mb4 characters, let\'s only send 3-byte utf8 characters.\n				if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n					$charset = \'utf8\';\n				}\n\n				$charsets[ strtolower( $charset ) ] = true;\n			}\n\n			list( $type ) = explode( \'(\', $column-&gt;Type );\n\n			// A binary/blob means the whole query gets treated like this.\n			if ( in_array( strtoupper( $type ), array( \'BINARY\', \'VARBINARY\', \'TINYBLOB\', \'MEDIUMBLOB\', \'BLOB\', \'LONGBLOB\' ) ) ) {\n				$this-&gt;table_charset[ $tablekey ] = \'binary\';\n				return \'binary\';\n			}\n		}\n\n		// utf8mb3 is an alias for utf8.\n		if ( isset( $charsets[\'utf8mb3\'] ) ) {\n			$charsets[\'utf8\'] = true;\n			unset( $charsets[\'utf8mb3\'] );\n		}\n\n		// Check if we have more than one charset in play.\n		$count = count( $charsets );\n		if ( 1 === $count ) {\n			$charset = key( $charsets );\n		} elseif ( 0 === $count ) {\n			// No charsets, assume this table can store whatever.\n			$charset = false;\n		} else {\n			// More than one charset. Remove latin1 if present and recalculate.\n			unset( $charsets[\'latin1\'] );\n			$count = count( $charsets );\n			if ( 1 === $count ) {\n				// Only one charset (besides latin1).\n				$charset = key( $charsets );\n			} elseif ( 2 === $count &amp;&amp; isset( $charsets[\'utf8\'], $charsets[\'utf8mb4\'] ) ) {\n				// Two charsets, but they\'re utf8 and utf8mb4, use utf8.\n				$charset = \'utf8\';\n			} else {\n				// Two mixed character sets. ascii.\n				$charset = \'ascii\';\n			}\n		}\n\n		$this-&gt;table_charset[ $tablekey ] = $charset;\n		return $charset;\n	}\n\n	/**\n	 * Retrieves the character set for the given column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return string|false|WP_Error Column character set as a string. False if the column has no\n	 *        character set. WP_Error object if there was an error.\n	 */\n	public function get_col_charset( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		/**\n		 * Filters the column charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 * @param string $column  The name of the column being checked.\n		 */\n		$charset = apply_filters( \'pre_get_col_charset\', null, $table, $column );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;table_charset[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		// If still no column information, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// If this column doesn\'t exist, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// Return false when it\'s not a string column.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation ) ) {\n			return false;\n		}\n\n		list( $charset ) = explode( \'_\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation );\n		return $charset;\n	}\n\n	/**\n	 * Retrieve the maximum string length allowed in a given column.\n	 * The length may either be specified as a byte length or a character length.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return array|false|WP_Error array( \'length\' =&gt; (int), \'type\' =&gt; \'byte\' | \'char\' )\n	 *       false if the column has no length (for example, numeric column)\n	 *       WP_Error object if there was an error.\n	 */\n	public function get_col_length( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return false;\n		}\n\n		$typeinfo = explode( \'(\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Type );\n\n		$type = strtolower( $typeinfo[0] );\n		if ( ! empty( $typeinfo[1] ) ) {\n			$length = trim( $typeinfo[1], \')\' );\n		} else {\n			$length = false;\n		}\n\n		switch ( $type ) {\n			case \'char\':\n			case \'varchar\':\n				return array(\n					\'type\'   =&gt; \'char\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'binary\':\n			case \'varbinary\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'tinyblob\':\n			case \'tinytext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 255,        // 2^8 - 1\n				);\n\n			case \'blob\':\n			case \'text\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 65535,      // 2^16 - 1\n				);\n\n			case \'mediumblob\':\n			case \'mediumtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 167772,   // 2^24 - 1\n				);\n\n			case \'longblob\':\n			case \'longtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 4294967295, // 2^32 - 1\n				);\n\n			default:\n				return false;\n		}\n	}\n\n	/**\n	 * Check if a string is ASCII.\n	 *\n	 * The negative regex is faster for non-ASCII strings, as it allows\n	 * the search to finish as soon as it encounters a non-ASCII character.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $string String to check.\n	 * @return bool True if ASCII, false if not.\n	 */\n	protected function check_ascii( $string ) {\n		if ( function_exists( \'mb_check_encoding\' ) ) {\n			if ( mb_check_encoding( $string, \'ASCII\' ) ) {\n				return true;\n			}\n		} elseif ( ! preg_match( \'/[^\\x00-\\x7F]/\', $string ) ) {\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Check if the query is accessing a collation considered safe on the current version of MySQL.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to check.\n	 * @return bool True if the collation is safe, false if it isn\'t.\n	 */\n	protected function check_safe_collation( $query ) {\n		if ( $this-&gt;checking_collation ) {\n			return true;\n		}\n\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $query ) ) {\n			return true;\n		}\n\n		// All-ASCII queries don\'t need extra checking.\n		if ( $this-&gt;check_ascii( $query ) ) {\n			return true;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( ! $table ) {\n			return false;\n		}\n\n		$this-&gt;checking_collation = true;\n		$collation                = $this-&gt;get_table_charset( $table );\n		$this-&gt;checking_collation = false;\n\n		// Tables with no collation, or latin1 only, don\'t need extra checking.\n		if ( false === $collation || \'latin1\' === $collation ) {\n			return true;\n		}\n\n		$table = strtolower( $table );\n		if ( empty( $this-&gt;col_meta[ $table ] ) ) {\n			return false;\n		}\n\n		// If any of the columns don\'t have one of these collations, it needs more sanity checking.\n		foreach ( $this-&gt;col_meta[ $table ] as $col ) {\n			if ( empty( $col-&gt;Collation ) ) {\n				continue;\n			}\n\n			if ( ! in_array( $col-&gt;Collation, array( \'utf8_general_ci\', \'utf8_bin\', \'utf8mb4_general_ci\', \'utf8mb4_bin\' ), true ) ) {\n				return false;\n			}\n		}\n\n		return true;\n	}\n\n	/**\n	 * Strips any invalid characters based on value/charset pairs.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data Array of value arrays. Each value array has the keys\n	 *                    \'value\' and \'charset\'. An optional \'ascii\' key can be\n	 *                    set to false to avoid redundant ASCII checks.\n	 * @return array|WP_Error The $data parameter, with invalid characters removed from\n	 * each value. This works as a passthrough: any additional keys\n	 * such as \'field\' are retained in each value array. If we cannot\n	 * remove invalid characters, a WP_Error object is returned.\n	 */\n	protected function strip_invalid_text( $data ) {\n		$db_check_string = false;\n\n		foreach ( $data as &amp;$value ) {\n			$charset = $value[\'charset\'];\n\n			if ( is_array( $value[\'length\'] ) ) {\n				$length                  = $value[\'length\'][\'length\'];\n				$truncate_by_byte_length = \'byte\' === $value[\'length\'][\'type\'];\n			} else {\n				$length = false;\n				// Since we have no length, we\'ll never truncate.\n				// Initialize the variable to false. true would take us\n				// through an unnecessary (for this case) codepath below.\n				$truncate_by_byte_length = false;\n			}\n\n			// There\'s no charset to work with.\n			if ( false === $charset ) {\n				continue;\n			}\n\n			// Column isn\'t a string.\n			if ( ! is_string( $value[\'value\'] ) ) {\n				continue;\n			}\n\n			$needs_validation = true;\n			if (\n				// latin1 can store any byte sequence\n				\'latin1\' === $charset\n			||\n				// ASCII is always OK.\n				( ! isset( $value[\'ascii\'] ) &amp;&amp; $this-&gt;check_ascii( $value[\'value\'] ) )\n			) {\n				$truncate_by_byte_length = true;\n				$needs_validation        = false;\n			}\n\n			if ( $truncate_by_byte_length ) {\n				mbstring_binary_safe_encoding();\n				if ( false !== $length &amp;&amp; strlen( $value[\'value\'] ) &gt; $length ) {\n					$value[\'value\'] = substr( $value[\'value\'], 0, $length );\n				}\n				reset_mbstring_encoding();\n\n				if ( ! $needs_validation ) {\n					continue;\n				}\n			}\n\n			// utf8 can be handled by regex, which is a bunch faster than a DB lookup.\n			if ( ( \'utf8\' === $charset || \'utf8mb3\' === $charset || \'utf8mb4\' === $charset ) &amp;&amp; function_exists( \'mb_strlen\' ) ) {\n				$regex = \'/\n					(\n						(?: [\\x00-\\x7F]                  # single-byte sequences   0xxxxxxx\n						|   [\\xC2-\\xDF][\\x80-\\xBF]       # double-byte sequences   110xxxxx 10xxxxxx\n						|   \\xE0[\\xA0-\\xBF][\\x80-\\xBF]   # triple-byte sequences   1110xxxx 10xxxxxx * 2\n						|   [\\xE1-\\xEC][\\x80-\\xBF]{2}\n						|   \\xED[\\x80-\\x9F][\\x80-\\xBF]\n						|   [\\xEE-\\xEF][\\x80-\\xBF]{2}\';\n\n				if ( \'utf8mb4\' === $charset ) {\n					$regex .= \'\n						|    \\xF0[\\x90-\\xBF][\\x80-\\xBF]{2} # four-byte sequences   11110xxx 10xxxxxx * 3\n						|    [\\xF1-\\xF3][\\x80-\\xBF]{3}\n						|    \\xF4[\\x80-\\x8F][\\x80-\\xBF]{2}\n					\';\n				}\n\n				$regex         .= \'){1,40}   # ...one or more times\n					)\n					| .           # anything else\n					/x\';\n				$value[\'value\'] = preg_replace( $regex, \'$1\', $value[\'value\'] );\n\n				if ( false !== $length &amp;&amp; mb_strlen( $value[\'value\'], \'UTF-8\' ) &gt; $length ) {\n					$value[\'value\'] = mb_substr( $value[\'value\'], 0, $length, \'UTF-8\' );\n				}\n				continue;\n			}\n\n			// We couldn\'t use any local conversions, send it to the DB.\n			$value[\'db\'] = $db_check_string = true;\n		}\n		unset( $value ); // Remove by reference.\n\n		if ( $db_check_string ) {\n			$queries = array();\n			foreach ( $data as $col =&gt; $value ) {\n				if ( ! empty( $value[\'db\'] ) ) {\n					// We\'re going to need to truncate by characters or bytes, depending on the length value we have.\n					if ( \'byte\' === $value[\'length\'][\'type\'] ) {\n						// Using binary causes LEFT() to truncate by bytes.\n						$charset = \'binary\';\n					} else {\n						$charset = $value[\'charset\'];\n					}\n\n					if ( $this-&gt;charset ) {\n						$connection_charset = $this-&gt;charset;\n					} else {\n						if ( $this-&gt;use_mysqli ) {\n							$connection_charset = mysqli_character_set_name( $this-&gt;dbh );\n						} else {\n							$connection_charset = mysql_client_encoding();\n						}\n					}\n\n					if ( is_array( $value[\'length\'] ) ) {\n						$length          = sprintf( \'%.0f\', $value[\'length\'][\'length\'] );\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( LEFT( CONVERT( %s USING $charset ), $length ) USING $connection_charset )\", $value[\'value\'] );\n					} elseif ( \'binary\' !== $charset ) {\n						// If we don\'t have a length, there\'s no need to convert binary - it will always return the same result.\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( CONVERT( %s USING $charset ) USING $connection_charset )\", $value[\'value\'] );\n					}\n\n					unset( $data[ $col ][\'db\'] );\n				}\n			}\n\n			$sql = array();\n			foreach ( $queries as $column =&gt; $query ) {\n				if ( ! $query ) {\n					continue;\n				}\n\n				$sql[] = $query . \" AS x_$column\";\n			}\n\n			$this-&gt;check_current_query = false;\n			$row= $this-&gt;get_row( \'SELECT \' . implode( \', \', $sql ), ARRAY_A );\n			if ( ! $row ) {\n				return new WP_Error( \'wpdb_strip_invalid_text_failure\' );\n			}\n\n			foreach ( array_keys( $data ) as $column ) {\n				if ( isset( $row[ \"x_$column\" ] ) ) {\n					$data[ $column ][\'value\'] = $row[ \"x_$column\" ];\n				}\n			}\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Strips any invalid characters from the query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query Query to convert.\n	 * @return string|WP_Error The converted query, or a WP_Error object if the conversion fails.\n	 */\n	protected function strip_invalid_text_from_query( $query ) {\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$trimmed_query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $trimmed_query ) ) {\n			return $query;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( $table ) {\n			$charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $charset ) ) {\n				return $charset;\n			}\n\n			// We can\'t reliably strip text from tables containing binary/blob columns\n			if ( \'binary\' === $charset ) {\n				return $query;\n			}\n		} else {\n			$charset = $this-&gt;charset;\n		}\n\n		$data = array(\n			\'value\'   =&gt; $query,\n			\'charset\' =&gt; $charset,\n			\'ascii\'   =&gt; false,\n			\'length\'  =&gt; false,\n		);\n\n		$data = $this-&gt;strip_invalid_text( array( $data ) );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[0][\'value\'];\n	}\n\n	/**\n	 * Strips any invalid characters from the string for a given table and column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @param string $value  The text to check.\n	 * @return string|WP_Error The converted string, or a WP_Error object if the conversion fails.\n	 */\n	public function strip_invalid_text_for_column( $table, $column, $value ) {\n		if ( ! is_string( $value ) ) {\n			return $value;\n		}\n\n		$charset = $this-&gt;get_col_charset( $table, $column );\n		if ( ! $charset ) {\n			// Not a string column.\n			return $value;\n		} elseif ( is_wp_error( $charset ) ) {\n			// Bail on real errors.\n			return $charset;\n		}\n\n		$data = array(\n			$column =&gt; array(\n				\'value\'   =&gt; $value,\n				\'charset\' =&gt; $charset,\n				\'length\'  =&gt; $this-&gt;get_col_length( $table, $column ),\n			),\n		);\n\n		$data = $this-&gt;strip_invalid_text( $data );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[ $column ][\'value\'];\n	}\n\n	/**\n	 * Find the first table name referenced in a query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to search.\n	 * @return string|false $table The table name found, or false if a table couldn\'t be found.\n	 */\n	protected function get_table_from_query( $query ) {\n		// Remove characters that can legally trail the table name.\n		$query = rtrim( $query, \';/-#\' );\n\n		// Allow (select...) union [...] style queries. Use the first query\'s table name.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n\n		// Strip everything between parentheses except nested selects.\n		$query = preg_replace( \'/\\((?!\\s*select)[^(]*?\\)/is\', \'()\', $query );\n\n		// Quickly match most common queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'SELECT.*?\\s+FROM\'\n				. \'|INSERT(?:\\s+LOW_PRIORITY|\\s+DELAYED|\\s+HIGH_PRIORITY)?(?:\\s+IGNORE)?(?:\\s+INTO)?\'\n				. \'|REPLACE(?:\\s+LOW_PRIORITY|\\s+DELAYED)?(?:\\s+INTO)?\'\n				. \'|UPDATE(?:\\s+LOW_PRIORITY)?(?:\\s+IGNORE)?\'\n				. \'|DELETE(?:\\s+LOW_PRIORITY|\\s+QUICK|\\s+IGNORE)*(?:.+?FROM)?\'\n			. \')\\s+((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		// SHOW TABLE STATUS and SHOW TABLES WHERE Name = \'wp_posts\'\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES).+WHERE\\s+Name\\s*=\\s*(\"|\\\')((?:[0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\\\1/is\', $query, $maybe ) ) {\n			return $maybe[2];\n		}\n\n		// SHOW TABLE STATUS LIKE and SHOW TABLES LIKE \'wp\\_3\\_%\'\n		// This quoted LIKE operand seldom holds a full table name.\n		// It is usually a pattern for matching a prefix so we just\n		// strip the trailing % and unescape the _ to get \'wp_3_\'\n		// which drop-ins can use for routing these SQL statements.\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES)\\s+(?:WHERE\\s+Name\\s+)?LIKE\\s*(\"|\\\')((?:[\\\\\\\\0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)%?\\\\1/is\', $query, $maybe ) ) {\n			return str_replace( \'\\\\_\', \'_\', $maybe[2] );\n		}\n\n		// Big pattern for the rest of the table-related queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'(?:EXPLAIN\\s+(?:EXTENDED\\s+)?)?SELECT.*?\\s+FROM\'\n				. \'|DESCRIBE|DESC|EXPLAIN|HANDLER\'\n				. \'|(?:LOCK|UNLOCK)\\s+TABLE(?:S)?\'\n				. \'|(?:RENAME|OPTIMIZE|BACKUP|RESTORE|CHECK|CHECKSUM|ANALYZE|REPAIR).*\\s+TABLE\'\n				. \'|TRUNCATE(?:\\s+TABLE)?\'\n				. \'|CREATE(?:\\s+TEMPORARY)?\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\'\n				. \'|ALTER(?:\\s+IGNORE)?\\s+TABLE\'\n				. \'|DROP\\s+TABLE(?:\\s+IF\\s+EXISTS)?\'\n				. \'|CREATE(?:\\s+\\w+)?\\s+INDEX.*\\s+ON\'\n				. \'|DROP\\s+INDEX.*\\s+ON\'\n				. \'|LOAD\\s+DATA.*INFILE.*INTO\\s+TABLE\'\n				. \'|(?:GRANT|REVOKE).*ON\\s+TABLE\'\n				. \'|SHOW\\s+(?:.*FROM|.*TABLE)\'\n			. \')\\s+\\(*\\s*((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\s*\\)*/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		return false;\n	}\n\n	/**\n	 * Load the column metadata from the last query.\n	 *\n	 * @since 3.5.0\n	 */\n	protected function load_col_info() {\n		if ( $this-&gt;col_info ) {\n			return;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$num_fields = mysqli_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysqli_fetch_field( $this-&gt;result );\n			}\n		} else {\n			$num_fields = mysql_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysql_fetch_field( $this-&gt;result, $i );\n			}\n		}\n	}\n\n	/**\n	 * Retrieve column metadata from the last query.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $info_type  Optional. Type one of name, table, def, max_length, not_null, primary_key, multiple_key, unique_key, numeric, blob, type, unsigned, zerofill\n	 * @param int    $col_offset Optional. 0: col name. 1: which table the col\'s in. 2: col\'s max length. 3: if the col is numeric. 4: col\'s type\n	 * @return mixed Column Results\n	 */\n	public function get_col_info( $info_type = \'name\', $col_offset = -1 ) {\n		$this-&gt;load_col_info();\n\n		if ( $this-&gt;col_info ) {\n			if ( $col_offset == -1 ) {\n				$i         = 0;\n				$new_array = array();\n				foreach ( (array) $this-&gt;col_info as $col ) {\n					$new_array[ $i ] = $col-&gt;{$info_type};\n					$i++;\n				}\n				return $new_array;\n			} else {\n				return $this-&gt;col_info[ $col_offset ]-&gt;{$info_type};\n			}\n		}\n	}\n\n	/**\n	 * Starts the timer, for debugging purposes.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return true\n	 */\n	public function timer_start() {\n		$this-&gt;time_start = microtime( true );\n		return true;\n	}\n\n	/**\n	 * Stops the debugging timer.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return float Total time spent on the query, in seconds\n	 */\n	public function timer_stop() {\n		return ( microtime( true ) - $this-&gt;time_start );\n	}\n\n	/**\n	 * エラーを素敵なヘッダーとフッターにラップして終わります。\n	 *\n	 * wpdb :: $ show_errorsがfalseであれば死にません。\n	 *\n	 * @since 1.5.0\n	 *\n	 * @param string $message    The Error message\n	 * @param string $error_code Optional. エラーを識別するためのコンピュータ可読文字列。\n	 * @return false|void\n	 */\n	public function bail( $message, $error_code = \'500\' ) {\n		if ( $this-&gt;show_errors ) {\n			$error = \'\';\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$error = mysqli_error( $this-&gt;dbh );\n				} elseif ( mysqli_connect_errno() ) {\n					$error = mysqli_connect_error();\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$error = mysql_error( $this-&gt;dbh );\n				} else {\n					$error = mysql_error();\n				}\n			}\n\n			if ( $error ) {\n				$message = \'&lt;p&gt;&lt;code&gt;\' . $error . \"&lt;/code&gt;&lt;/p&gt;\\n\" . $message;\n			}\n\n			wp_die( $message );\n		} else {\n			if ( class_exists( \'WP_Error\', false ) ) {\n				$this-&gt;error = new WP_Error( $error_code, $message );\n			} else {\n				$this-&gt;error = $message;\n			}\n\n			return false;\n		}\n	}\n\n\n	/**\n	 * 現在のデータベース接続を閉じます。\n	 *\n	 * @since 4.5.0\n	 *\n	 * @return bool True if the connection was successfully closed, false if it wasn\'t,\n	 *              or the connection doesn\'t exist.\n	 */\n	public function close() {\n		if ( ! $this-&gt;dbh ) {\n			return false;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$closed = mysqli_close( $this-&gt;dbh );\n		} else {\n			$closed = mysql_close( $this-&gt;dbh );\n		}\n\n		if ( $closed ) {\n			$this-&gt;dbh           = null;\n			$this-&gt;ready         = false;\n			$this-&gt;has_connected = false;\n		}\n\n		return $closed;\n	}\n\n	/**\n	 * MySQLデータベースが最低限必要な最小バージョンかどうか\n	 *\n	 * @since 2.5.0\n	 *\n	 * @global string $wp_version\n	 * @global string $required_mysql_version\n	 *\n	 * @return WP_Error|void\n	 */\n	public function check_database_version() {\n		global $wp_version, $required_mysql_version;\n		// サーバーに必要なMySQLバージョンがあることを確認してください。\n		if ( version_compare( $this-&gt;db_version(), $required_mysql_version, \'&lt;\' ) ) {\n			/* translators: 1: WordPress version number, 2: Minimum required MySQL version number */\n			return new WP_Error( \'database_version\', sprintf( __( \'&lt;strong&gt;ERROR&lt;/strong&gt;: WordPress %1$s requires MySQL %2$s or higher\' ), $wp_version, $required_mysql_version ) );\n		}\n	}\n\n	/**\n	 * データベースが照合をサポートしているかどうか\n	 *\n	 * WordPressがテーブルスキームを生成しているときに呼び出されます。\n	 *\n	 * Use `wpdb::has_cap( \'collation\' )`.\n	 *\n	 * @since 2.5.0\n	 * @deprecated 3.5.0 Use wpdb::has_cap()\n	 *\n	 * @return bool True if collation is supported, false if version does not\n	 */\n	public function supports_collation() {\n		_deprecated_function( __FUNCTION__, \'3.5.0\', \'wpdb::has_cap( \\\'collation\\\' )\' );\n		return $this-&gt;has_cap( \'collation\' );\n	}\n\n	/**\n	 * データベース文字の照合\n	 *\n	 * @since 3.5.0\n	 *\n	 * @return string The database character collate.\n	 */\n	public function get_charset_collate() {\n		$charset_collate = \'\';\n\n		if ( ! empty( $this-&gt;charset ) ) {\n			$charset_collate = \"DEFAULT CHARACTER SET $this-&gt;charset\";\n		}\n		if ( ! empty( $this-&gt;collate ) ) {\n			$charset_collate .= \" COLLATE $this-&gt;collate\";\n		}\n\n		return $charset_collate;\n	}\n\n	/**\n	 * データベースが特定の機能をサポートしているかどうかを確認します。\n	 *\n	 * @since 2.7.0\n	 * @since 4.1.0 Added support for the \'utf8mb4\' feature.\n	 * @since 4.6.0 Added support for the \'utf8mb4_520\' feature.\n	 *\n	 * @see wpdb::db_version()\n	 *\n	 * @param string $db_cap The feature to check for. Accepts \'collation\',\n	 *\'group_concat\', \'subqueries\', \'set_charset\',\n	 *\'utf8mb4\', or \'utf8mb4_520\'.\n	 * @return int|false Whether the database feature is supported, false otherwise.\n	 */\n	public function has_cap( $db_cap ) {\n		$version = $this-&gt;db_version();\n\n		switch ( strtolower( $db_cap ) ) {\n			case \'collation\':    // @since 2.5.0\n			case \'group_concat\': // @since 2.7.0\n			case \'subqueries\':   // @since 2.7.0\n				return version_compare( $version, \'4.1\', \'&gt;=\' );\n			case \'set_charset\':\n				return version_compare( $version, \'5.0.7\', \'&gt;=\' );\n			case \'utf8mb4\':      // @since 4.1.0\n				if ( version_compare( $version, \'5.5.3\', \'&lt;\' ) ) {\n					return false;\n				}\n				if ( $this-&gt;use_mysqli ) {\n					$client_version = mysqli_get_client_info();\n				} else {\n					$client_version = mysql_get_client_info();\n				}\n\n				/*\n				 * libmysql has supported utf8mb4 since 5.5.3, same as the MySQL server.\n				 * mysqlnd has supported utf8mb4 since 5.0.9.\n				 */\n				if ( false !== strpos( $client_version, \'mysqlnd\' ) ) {\n					$client_version = preg_replace( \'/^\\D+([\\d.]+).*/\', \'$1\', $client_version );\n					return version_compare( $client_version, \'5.0.9\', \'&gt;=\' );\n				} else {\n					return version_compare( $client_version, \'5.5.3\', \'&gt;=\' );\n				}\n			case \'utf8mb4_520\': // @since 4.6.0\n				return version_compare( $version, \'5.6\', \'&gt;=\' );\n		}\n\n		return false;\n	}\n\n	/**\n	 * wpdbを呼び出した関数の名前を取得してください。\n	 *\n	 * Searches up the list of functions until it reaches\n	 * the one that would most logically had called this method.\n	 *\n	 * @since 2.5.0\n	 *\n	 * @return string Comma separated list of the calling functions.\n	 */\n	public function get_caller() {\n		return wp_debug_backtrace_summary( __CLASS__ );\n	}\n\n	/**\n	 * MySQLサーバーのバージョンを取得します。\n	 *\n	 * @since 2.7.0\n	 *\n	 * @return null|string Null on failure, version number on success.\n	 */\n	public function db_version() {\n		if ( $this-&gt;use_mysqli ) {\n			$server_info = mysqli_get_server_info( $this-&gt;dbh );\n		} else {\n			$server_info = mysql_get_server_info( $this-&gt;dbh );\n		}\n		return preg_replace( \'/[^0-9.].*/\', \'\', $server_info );\n	}\n}\n</pre>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function __construct～__unset</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>文字セット設定　init_charset～</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>SQLモードの確認</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>テーブルにつけるプレフィックスを設定</h3>\n<!-- /wp:heading -->\n\n<p>wp-config.phpで設定してるやつです。</p>\n<p>wordpressのデフォルトのテーブル12個にはいずれも頭にwp_とついてますが、テーブル名をここで決めています。</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ブログID,ブログプレフィックスを取得</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function tables</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function select</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>安全に実行できるようにSQLクエリを準備するpublic function prepare</h3>\n<!-- /wp:heading -->','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-11 13:36:27','2019-06-11 04:36:27','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2483,1,'2019-06-11 13:54:34','2019-06-11 04:54:34','<p>このファイルはデータベースに接続してデータを取得したりインサートするファイルになります。</p>\n<p>MVCモデルで言うとmodelにあたるような役割をこのファイルで行っています。</p>\n<p>なお、このファイルは全部で(コメント込みで)3500行ほどあるので分割して読んでいきます。</p>\n<p> </p>\n<pre class=\"lang:php decode:true \" title=\"wp-db.php\">&lt;?php\n/**\n * WordPress DBクラス\n *\n * 元のコード  {@link http://php.justinvincent.com Justin Vincent (justin@visunet.ie)}\n *\n * @package WordPress\n * @subpackage Database\n * @since 0.71\n */\n\n/**\n * @since 0.71\n */\ndefine( \'EZSQL_VERSION\', \'WP1.25\' );\n\n/**\n * @since 0.71\n */\ndefine( \'OBJECT\', \'OBJECT\' );\n// phpcs:ignore Generic.NamingConventions.UpperCaseConstantName.ConstantNotUpperCase\ndefine( \'object\', \'OBJECT\' ); // Back compat.\n\n/**\n * @since 2.5.0\n */\ndefine( \'OBJECT_K\', \'OBJECT_K\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_A\', \'ARRAY_A\' );\n\n/**\n * @since 0.71\n */\ndefine( \'ARRAY_N\', \'ARRAY_N\' );\n\n/**\n * WordPressデータベースアクセス抽象化オブジェクト\n *\n * wp-content / db.phpファイルの$ wpdbグローバル変数を\n * あなたのクラスに設定することで、このクラスをあなた自身のクラスに\n * 置き換えることが可能です。\n *\n * @link https://codex.wordpress.org/Function_Reference/wpdb_Class\n *\n * @since 0.71\n */\nclass wpdb {\n\n	/**\n	 * SQL / DBエラーを表示するかどうか\n	 *\n	 * デフォルトの動作では、WP_DEBUGとWP_DEBUG_DISPLAYの両方がtrueと評価された場合に\n	 * エラーを表示します。\n	 *\n	 * @since 0.71\n	 * @var bool\n	 */\n	var $show_errors = false;\n\n	/**\n	 * DBブートストラップ中のエラーを抑制するかどうか。\n	 *\n	 * @since 2.5.0\n	 * @var bool\n	 */\n	var $suppress_errors = false;\n\n	/**\n	 * クエリ中の最後のエラー\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $last_error = \'\';\n\n	/**\n	 * 行われたクエリの量\n	 *\n	 * @since 1.2.0\n	 * @var int\n	 */\n	public $num_queries = 0;\n\n	/**\n	 * 前のクエリによって返された行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $num_rows = 0;\n\n	/**\n	 * 前の照会による影響を受けた行数\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	var $rows_affected = 0;\n\n	/**\n	 * 前回のクエリによってAUTO_INCREMENTカラムに対して生成されたID（通常はINSERT）。\n	 *\n	 * @since 0.71\n	 * @var int\n	 */\n	public $insert_id = 0;\n\n	/**\n	 * 最後に行われたクエリ\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	var $last_query;\n\n	/**\n	 * 最後に行われたクエリの結果\n	 *\n	 * @since 0.71\n	 * @var array|null\n	 */\n	var $last_result;\n\n	/**\n	 * MySQLの結果。これはリソースまたはブール値です。\n	 *\n	 * @since 0.71\n	 * @var mixed\n	 */\n	protected $result;\n\n	/**\n	 * 挿入前のサニティチェックデータ用のキャッシュされた列情報\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $col_meta = array();\n\n	/**\n	 * テーブルの計算文字セット\n	 *\n	 * @since 4.2.0\n	 * @var array\n	 */\n	protected $table_charset = array();\n\n	/**\n	 * 現在のクエリのテキストフィールドを健全性チェックする必要があるかどうか。\n	 *\n	 * @since 4.2.0\n	 * @var bool\n	 */\n	protected $check_current_query = true;\n\n	/**\n	 * 照合をチェックするときに再帰問題に遭遇しないようにするためのフラグ。\n	 *\n	 * @since 4.2.0\n	 * @see wpdb::check_safe_collation()\n	 * @var bool\n	 */\n	private $checking_collation = false;\n\n	/**\n	 * テーブルカラムに保存された情報\n	 *\n	 * @since 0.71\n	 * @var array\n	 */\n	protected $col_info;\n\n	/**\n	 * デバッグ目的で実行されたクエリのログ。\n	 *\n	 * @since 1.5.0\n	 * @since 2.5.0 各クエリログの3番目の要素は、呼び出し元の関数を記録するために追加されました。\n	 * @since 5.1.0 各クエリログの4番目の要素は、開始時刻を記録するために追加されました。\n	 *\n	 * @var array[] {\n	 *     実行されたクエリの配列。\n	 *\n	 *     @type array ...$0 {\n	 *         Data for each query.\n	 *\n	 *         @type string $0 The query\'s SQL.\n	 *         @type float  $1 照会に費やした合計時間（秒単位）。\n	 *         @type string $2 呼び出し側関数のコンマ区切りリスト。\n	 *         @type float  $3 問い合わせの開始時のUnixタイムスタンプ。\n	 *     }\n	 * }\n	 */\n	var $queries;\n\n	/**\n	 * 死ぬまでに再接続を再試行する回数\n	 *\n	 * @since 3.9.0\n	 * @see wpdb::check_connection()\n	 * @var int\n	 */\n	protected $reconnect_retries = 5;\n\n	/**\n	 * WordPressのテーブルプレフィックス\n	 *\n	 * 単一のデータベースに複数のWordPressをインストールするように設定できます。\n	 * 2番目の理由は、考えられるセキュリティ上の予防策です。\n	 *\n	 * @since 2.5.0\n	 * @var string\n	 */\n	public $prefix = \'\';\n\n	/**\n	 * WordPressのベーステーブルプレフィックス。\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $base_prefix;\n\n	/**\n	 * Whether the database queries are ready to start executing.\n	 *\n	 * @since 2.3.2\n	 * @var bool\n	 */\n	var $ready = false;\n\n	/**\n	 * Blog ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $blogid = 0;\n\n	/**\n	 * Site ID.\n	 *\n	 * @since 3.0.0\n	 * @var int\n	 */\n	public $siteid = 0;\n\n	/**\n	 * ブログ毎のWordPress一覧表\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $tables = array(\n		\'posts\',\n		\'comments\',\n		\'links\',\n		\'options\',\n		\'postmeta\',\n		\'terms\',\n		\'term_taxonomy\',\n		\'term_relationships\',\n		\'termmeta\',\n		\'commentmeta\',\n	);\n\n	/**\n	 * 廃止予定のWordPressテーブルのリスト\n	 *\n	 * categories、post2cat、およびlink2catは、2.3.0、dbバージョン5539で非推奨となりました。\n	 *\n	 * @since 2.9.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $old_tables = array( \'categories\', \'post2cat\', \'link2cat\' );\n\n	/**\n	 * WordPressグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $global_tables = array( \'users\', \'usermeta\' );\n\n	/**\n	 * マルチサイトグローバルテーブルのリスト\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::tables()\n	 * @var array\n	 */\n	var $ms_global_tables = array(\n		\'blogs\',\n		\'blogmeta\',\n		\'signups\',\n		\'site\',\n		\'sitemeta\',\n		\'sitecategories\',\n		\'registration_log\',\n		\'blog_versions\',\n	);\n\n	/**\n	 * WordPress Comments table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $comments;\n\n	/**\n	 * WordPress Comment Metadata table\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	public $commentmeta;\n\n	/**\n	 * WordPress Links table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $links;\n\n	/**\n	 * WordPress Options table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $options;\n\n	/**\n	 * WordPress Post Metadata table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $postmeta;\n\n	/**\n	 * WordPress Posts table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $posts;\n\n	/**\n	 * WordPress Terms table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $terms;\n\n	/**\n	 * WordPress Term Relationships table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_relationships;\n\n	/**\n	 * WordPress Term Taxonomy table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $term_taxonomy;\n\n	/**\n	 * WordPress Term Meta table.\n	 *\n	 * @since 4.4.0\n	 * @var string\n	 */\n	public $termmeta;\n\n	//\n	// Global and Multisite tables\n	//\n\n	/**\n	 * WordPress User Metadata table\n	 *\n	 * @since 2.3.0\n	 * @var string\n	 */\n	public $usermeta;\n\n	/**\n	 * WordPress Users table\n	 *\n	 * @since 1.5.0\n	 * @var string\n	 */\n	public $users;\n\n	/**\n	 * Multisite Blogs table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blogs;\n\n	/**\n	 * Multisite Blog Metadata table\n	 *\n	 * @since 5.1.0\n	 * @var string\n	 */\n	public $blogmeta;\n\n	/**\n	 * Multisite Blog Versions table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $blog_versions;\n\n	/**\n	 * Multisite Registration Log table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $registration_log;\n\n	/**\n	 * Multisite Signups table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $signups;\n\n	/**\n	 * Multisite Sites table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $site;\n\n	/**\n	 * Multisite Sitewide Terms table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitecategories;\n\n	/**\n	 * Multisite Site Metadata table\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $sitemeta;\n\n	/**\n	 * DB列のフォーマット指定子ここにリストされていない列は、デフォルトで％sになります。WPロード中に初期化されました。\n	 *\n	 * キーはカラム名、値はフォーマットタイプです。 \'ID\' =&gt; \'％d\'\n	 *\n	 * @since 2.8.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::insert()\n	 * @see wpdb::update()\n	 * @see wpdb::delete()\n	 * @see wp_set_wpdb_vars()\n	 * @var array\n	 */\n	public $field_types = array();\n\n	/**\n	 * Database table columns charset\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $charset;\n\n	/**\n	 * Database table columns collate\n	 *\n	 * @since 2.2.0\n	 * @var string\n	 */\n	public $collate;\n\n	/**\n	 * Database Username\n	 *\n	 * @since 2.9.0\n	 * @var string\n	 */\n	protected $dbuser;\n\n	/**\n	 * Database Password\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbpassword;\n\n	/**\n	 * Database Name\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbname;\n\n	/**\n	 * Database Host\n	 *\n	 * @since 3.1.0\n	 * @var string\n	 */\n	protected $dbhost;\n\n	/**\n	 * Database Handle\n	 *\n	 * @since 0.71\n	 * @var string\n	 */\n	protected $dbh;\n\n	/**\n	 * 最後のクエリ/ get_row / get_var呼び出しの説明文\n	 *\n	 * @since 3.0.0\n	 * @var string\n	 */\n	public $func_call;\n\n	/**\n	 * MySQLがデータベースエンジンとして使用されているかどうか。\n	 *\n	 * デフォルトでは、WPDB :: db_connect（）をtrueに設定します。 \n	 * これはWordPressに必要なMySQLバージョンをチェックするときに使われます。 \n	 * 通常、置換データベースドロップイン（db.php）はこれらのチェックをスキップしますが、\n	 * これをtrueに設定するとチェックを強制的に実行させます。\n	 *\n	 * @since 3.3.0\n	 * @var bool\n	 */\n	public $is_mysql = null;\n\n	/**\n	 * 互換性のないSQLモードのリスト。\n	 *\n	 * @since 3.9.0\n	 * @var array\n	 */\n	protected $incompatible_modes = array(\n		\'NO_ZERO_DATE\',\n		\'ONLY_FULL_GROUP_BY\',\n		\'STRICT_TRANS_TABLES\',\n		\'STRICT_ALL_TABLES\',\n		\'TRADITIONAL\',\n	);\n\n	/**\n	 * mysql上でmysqliを使用するかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $use_mysqli = false;\n\n	/**\n	 * ある時点でうまく接続できたかどうか\n	 *\n	 * @since 3.9.0\n	 * @var bool\n	 */\n	private $has_connected = false;\n\n	/**\n	 * データベースサーバーに接続してデータベースを選択する\n	 *\n	 * PPHP 5との互換性のためのHP 5スタイルのコンストラクタ。 Does\n	 * クラスプロパティの実際の設定とデータベースへの接続を行います。\n	 * \n	 *\n	 * @link https://core.trac.wordpress.org/ticket/3354\n	 * @since 2.0.8\n	 *\n	 * @global string $wp_version\n	 *\n	 * @param string $dbuser     MySQL database user\n	 * @param string $dbpassword MySQL database password\n	 * @param string $dbname     MySQL database name\n	 * @param string $dbhost     MySQL database host\n	 */\n	public function __construct( $dbuser, $dbpassword, $dbname, $dbhost ) {\n		register_shutdown_function( array( $this, \'__destruct\' ) );\n\n		if ( WP_DEBUG &amp;&amp; WP_DEBUG_DISPLAY ) {\n			$this-&gt;show_errors();\n		}\n\n		// WP_USE_EXT_MYSQLがtrueとして定義されていない限り、存在する場合はext / mysqliを使用\n		if ( function_exists( \'mysqli_connect\' ) ) {\n			$this-&gt;use_mysqli = true;\n\n			if ( defined( \'WP_USE_EXT_MYSQL\' ) ) {\n				$this-&gt;use_mysqli = ! WP_USE_EXT_MYSQL;\n			}\n		}\n\n		$this-&gt;dbuser     = $dbuser;\n		$this-&gt;dbpassword = $dbpassword;\n		$this-&gt;dbname     = $dbname;\n		$this-&gt;dbhost     = $dbhost;\n\n		// wp-config.phpの作成は準備ができたら手動で接続します。\n		if ( defined( \'WP_SETUP_CONFIG\' ) ) {\n			return;\n		}\n\n		$this-&gt;db_connect();\n	}\n\n	/**\n	 * PHP 5スタイルのデストラクタで、データベースオブジェクトが破棄されたときに実行されます。\n	 *\n	 * @see wpdb::__construct()\n	 * @since 2.0.8\n	 * @return true\n	 */\n	public function __destruct() {\n		return true;\n	}\n\n	/**\n	 * 下位互換性のためにプライベートプロパティを読み取り可能にします\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name The private member to get, and optionally process\n	 * @return mixed The private member\n	 */\n	public function __get( $name ) {\n		if ( \'col_info\' === $name ) {\n			$this-&gt;load_col_info();\n		}\n\n		return $this-&gt;$name;\n	}\n\n	/**\n	 *プライベートプロパティを下位互換性のために設定可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to set\n	 * @param mixed  $value The value to set\n	 */\n	public function __set( $name, $value ) {\n		$protected_members = array(\n			\'col_meta\',\n			\'table_charset\',\n			\'check_current_query\',\n		);\n		if ( in_array( $name, $protected_members, true ) ) {\n			return;\n		}\n		$this-&gt;$name = $value;\n	}\n\n	/**\n	 * プライベートプロパティを下位互換性のためにチェック可能にします。\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to check\n	 *\n	 * @return bool If the member is set or not\n	 */\n	public function __isset( $name ) {\n		return isset( $this-&gt;$name );\n	}\n\n	/**\n	 * Makes private properties un-settable for backward compatibility.\n	 *\n	 * @since 3.5.0\n	 *\n	 * @param string $name  The private member to unset\n	 */\n	public function __unset( $name ) {\n		unset( $this-&gt;$name );\n	}\n\n	/**\n	 * Set $this-&gt;charset and $this-&gt;collate\n	 *\n	 * @since 3.1.0\n	 */\n	public function init_charset() {\n		$charset = \'\';\n		$collate = \'\';\n\n		if ( function_exists( \'is_multisite\' ) &amp;&amp; is_multisite() ) {\n			$charset = \'utf8\';\n			if ( defined( \'DB_COLLATE\' ) &amp;&amp; DB_COLLATE ) {\n				$collate = DB_COLLATE;\n			} else {\n				$collate = \'utf8_general_ci\';\n			}\n		} elseif ( defined( \'DB_COLLATE\' ) ) {\n			$collate = DB_COLLATE;\n		}\n\n		if ( defined( \'DB_CHARSET\' ) ) {\n			$charset = DB_CHARSET;\n		}\n\n		$charset_collate = $this-&gt;determine_charset( $charset, $collate );\n\n		$this-&gt;charset = $charset_collate[\'charset\'];\n		$this-&gt;collate = $charset_collate[\'collate\'];\n	}\n\n	/**\n	 * 与えられた文字セットと照合順序を使用して、使用するのに最適な文字セットと照合順序を決定します。\n	 *\n	 * たとえば、可能であれば、utf8の代わりにutf8mb4を使用する必要があります。\n	 *\n	 * @since 4.6.0\n	 *\n	 * @param string $charset The character set to check.\n	 * @param string $collate The collation to check.\n	 * @return array The most appropriate character set and collation to use.\n	 */\n	public function determine_charset( $charset, $collate ) {\n		if ( ( $this-&gt;use_mysqli &amp;&amp; ! ( $this-&gt;dbh instanceof mysqli ) ) || empty( $this-&gt;dbh ) ) {\n			return compact( \'charset\', \'collate\' );\n		}\n\n		if ( \'utf8\' === $charset &amp;&amp; $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8mb4\';\n		}\n\n		if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n			$charset = \'utf8\';\n			$collate = str_replace( \'utf8mb4_\', \'utf8_\', $collate );\n		}\n\n		if ( \'utf8mb4\' === $charset ) {\n			// _general_ is outdated, so we can upgrade it to _unicode_, instead.\n			if ( ! $collate || \'utf8_general_ci\' === $collate ) {\n				$collate = \'utf8mb4_unicode_ci\';\n			} else {\n				$collate = str_replace( \'utf8_\', \'utf8mb4_\', $collate );\n			}\n		}\n\n		// _unicode_520_ is a better collation, we should use that when it\'s available.\n		if ( $this-&gt;has_cap( \'utf8mb4_520\' ) &amp;&amp; \'utf8mb4_unicode_ci\' === $collate ) {\n			$collate = \'utf8mb4_unicode_520_ci\';\n		}\n\n		return compact( \'charset\', \'collate\' );\n	}\n\n	/**\n	 * 接続の文字セットを設定します。\n	 *\n	 * @since 3.1.0\n	 *\n	 * @param resource $dbh     The resource given by mysql_connect\n	 * @param string   $charset Optional. The character set. Default null.\n	 * @param string   $collate Optional. The collation. Default null.\n	 */\n	public function set_charset( $dbh, $charset = null, $collate = null ) {\n		if ( ! isset( $charset ) ) {\n			$charset = $this-&gt;charset;\n		}\n		if ( ! isset( $collate ) ) {\n			$collate = $this-&gt;collate;\n		}\n		if ( $this-&gt;has_cap( \'collation\' ) &amp;&amp; ! empty( $charset ) ) {\n			$set_charset_succeeded = true;\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( function_exists( \'mysqli_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysqli_set_charset( $dbh, $charset );\n				}\n\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysqli_query( $dbh, $query );\n				}\n			} else {\n				if ( function_exists( \'mysql_set_charset\' ) &amp;&amp; $this-&gt;has_cap( \'set_charset\' ) ) {\n					$set_charset_succeeded = mysql_set_charset( $charset, $dbh );\n				}\n				if ( $set_charset_succeeded ) {\n					$query = $this-&gt;prepare( \'SET NAMES %s\', $charset );\n					if ( ! empty( $collate ) ) {\n						$query .= $this-&gt;prepare( \' COLLATE %s\', $collate );\n					}\n					mysql_query( $query, $dbh );\n				}\n			}\n		}\n	}\n\n	/**\n	 * 現在のSQLモードを変更し、そのWordPress互換性を確認してください。\n	 *\n	 * If no modes are passed, it will ensure the current MySQL server\n	 * modes are compatible.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param array $modes Optional. A list of SQL modes to set.\n	 */\n	public function set_sql_mode( $modes = array() ) {\n		if ( empty( $modes ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$res = mysqli_query( $this-&gt;dbh, \'SELECT @@SESSION.sql_mode\' );\n			} else {\n				$res = mysql_query( \'SELECT @@SESSION.sql_mode\', $this-&gt;dbh );\n			}\n\n			if ( empty( $res ) ) {\n				return;\n			}\n\n			if ( $this-&gt;use_mysqli ) {\n				$modes_array = mysqli_fetch_array( $res );\n				if ( empty( $modes_array[0] ) ) {\n					return;\n				}\n				$modes_str = $modes_array[0];\n			} else {\n				$modes_str = mysql_result( $res, 0 );\n			}\n\n			if ( empty( $modes_str ) ) {\n				return;\n			}\n\n			$modes = explode( \',\', $modes_str );\n		}\n\n		$modes = array_change_key_case( $modes, CASE_UPPER );\n\n		/**\n		 * Filters the list of incompatible SQL modes to exclude.\n		 *\n		 * @since 3.9.0\n		 *\n		 * @param array $incompatible_modes An array of incompatible modes.\n		 */\n		$incompatible_modes = (array) apply_filters( \'incompatible_sql_modes\', $this-&gt;incompatible_modes );\n\n		foreach ( $modes as $i =&gt; $mode ) {\n			if ( in_array( $mode, $incompatible_modes ) ) {\n				unset( $modes[ $i ] );\n			}\n		}\n\n		$modes_str = implode( \',\', $modes );\n\n		if ( $this-&gt;use_mysqli ) {\n			mysqli_query( $this-&gt;dbh, \"SET SESSION sql_mode=\'$modes_str\'\" );\n		} else {\n			mysql_query( \"SET SESSION sql_mode=\'$modes_str\'\", $this-&gt;dbh );\n		}\n	}\n\n	/**\n	 * WordPressテーブルのテーブルプレフィックスを設定します。\n	 *\n	 * @since 2.5.0\n	 *\n	 * @param string $prefix          Alphanumeric name for the new prefix.\n	 * @param bool   $set_table_names Optional. Whether the table names, e.g. wpdb::$posts, should be updated or not.\n	 * @return string|WP_Error Old prefix or WP_Error on error\n	 */\n	public function set_prefix( $prefix, $set_table_names = true ) {\n\n		if ( preg_match( \'|[^a-z0-9_]|i\', $prefix ) ) {\n			return new WP_Error( \'invalid_db_prefix\', \'Invalid database prefix\' );\n		}\n\n		$old_prefix = is_multisite() ? \'\' : $prefix;\n\n		if ( isset( $this-&gt;base_prefix ) ) {\n			$old_prefix = $this-&gt;base_prefix;\n		}\n\n		$this-&gt;base_prefix = $prefix;\n\n		if ( $set_table_names ) {\n			foreach ( $this-&gt;tables( \'global\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			if ( is_multisite() &amp;&amp; empty( $this-&gt;blogid ) ) {\n				return $old_prefix;\n			}\n\n			$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n			foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n\n			foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n				$this-&gt;$table = $prefixed_table;\n			}\n		}\n		return $old_prefix;\n	}\n\n	/**\n	 * ブログIDを設定する\n	 *\n	 * @since 3.0.0\n	 *\n	 * @param int $blog_id\n	 * @param int $network_id Optional.\n	 * @return int previous blog id\n	 */\n	public function set_blog_id( $blog_id, $network_id = 0 ) {\n		if ( ! empty( $network_id ) ) {\n			$this-&gt;siteid = $network_id;\n		}\n\n		$old_blog_id  = $this-&gt;blogid;\n		$this-&gt;blogid = $blog_id;\n\n		$this-&gt;prefix = $this-&gt;get_blog_prefix();\n\n		foreach ( $this-&gt;tables( \'blog\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		foreach ( $this-&gt;tables( \'old\' ) as $table =&gt; $prefixed_table ) {\n			$this-&gt;$table = $prefixed_table;\n		}\n\n		return $old_blog_id;\n	}\n\n	/**\n	 * Gets blog prefix.\n	 *\n	 * @since 3.0.0\n	 * @param int $blog_id Optional.\n	 * @return string Blog prefix.\n	 */\n	public function get_blog_prefix( $blog_id = null ) {\n		if ( is_multisite() ) {\n			if ( null === $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_id = (int) $blog_id;\n			if ( defined( \'MULTISITE\' ) &amp;&amp; ( 0 == $blog_id || 1 == $blog_id ) ) {\n				return $this-&gt;base_prefix;\n			} else {\n				return $this-&gt;base_prefix . $blog_id . \'_\';\n			}\n		} else {\n			return $this-&gt;base_prefix;\n		}\n	}\n\n	/**\n	 * WordPressテーブルの配列を返します。\n	 *\n	 * またCUSTOM_USER_TABLEとCUSTOM_USER_META_TABLEがWordPressユーザーと\n	 * usermetaテーブルを上書きすることを可能にします。そうでなければプレフィックスによって決定されます。\n	 *\n	 * scope引数は、以下のいずれかを取ります。\n	 *\n	 * \'all\' - \'all\'および \'global\'テーブルを返します。古いテーブルは返されません。\n	 * \'blog\' - 照会されたブログのブログレベルのテーブルを返します。\n	 * \'global\'インストール用のグローバルテーブルを返します。マルチサイトを実行している場合にのみマルチサイトテーブルを返します。\n	 * \'ms_global\' - 現在のインストールがマルチサイトかどうかにかかわらず、マルチサイトグローバルテーブルを返します。\n	 * \'old\' - 廃止予定のテーブルを返します。\n	 *\n	 * @since 3.0.0\n	 * @uses wpdb::$tables\n	 * @uses wpdb::$old_tables\n	 * @uses wpdb::$global_tables\n	 * @uses wpdb::$ms_global_tables\n	 *\n	 * @param string $scope  オプションです。 all、global、ms_global、blog、または古いテーブルにすることができます。デフォルトはallです。\n	 * @param bool   $ prefixオプション。テーブルプレフィックスを含めるかどうか。ブログならデフォルトはtrueです。\n	 * 接頭辞が要求されると、カスタムユーザーとusermetaテーブルがマッピングされます。\n	 * @param int    $blog_id Optional. The blog_id to prefix. Defaults to wpdb::$blogid. Used only when prefix is requested.\n	 * @return array Table names. When a prefix is requested, the key is the unprefixed table name.\n	 */\n	public function tables( $scope = \'all\', $prefix = true, $blog_id = 0 ) {\n		switch ( $scope ) {\n			case \'all\':\n				$tables = array_merge( $this-&gt;global_tables, $this-&gt;tables );\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'blog\':\n				$tables = $this-&gt;tables;\n				break;\n			case \'global\':\n				$tables = $this-&gt;global_tables;\n				if ( is_multisite() ) {\n					$tables = array_merge( $tables, $this-&gt;ms_global_tables );\n				}\n				break;\n			case \'ms_global\':\n				$tables = $this-&gt;ms_global_tables;\n				break;\n			case \'old\':\n				$tables = $this-&gt;old_tables;\n				break;\n			default:\n				return array();\n		}\n\n		if ( $prefix ) {\n			if ( ! $blog_id ) {\n				$blog_id = $this-&gt;blogid;\n			}\n			$blog_prefix   = $this-&gt;get_blog_prefix( $blog_id );\n			$base_prefix   = $this-&gt;base_prefix;\n			$global_tables = array_merge( $this-&gt;global_tables, $this-&gt;ms_global_tables );\n			foreach ( $tables as $k =&gt; $table ) {\n				if ( in_array( $table, $global_tables ) ) {\n					$tables[ $table ] = $base_prefix . $table;\n				} else {\n					$tables[ $table ] = $blog_prefix . $table;\n				}\n				unset( $tables[ $k ] );\n			}\n\n			if ( isset( $tables[\'users\'] ) &amp;&amp; defined( \'CUSTOM_USER_TABLE\' ) ) {\n				$tables[\'users\'] = CUSTOM_USER_TABLE;\n			}\n\n			if ( isset( $tables[\'usermeta\'] ) &amp;&amp; defined( \'CUSTOM_USER_META_TABLE\' ) ) {\n				$tables[\'usermeta\'] = CUSTOM_USER_META_TABLE;\n			}\n		}\n\n		return $tables;\n	}\n\n	/**\n	 * 現在のデータベース接続を使用してデータベースを選択します。\n	 *\n	 * データベース名は現在のデータベース接続に基づいて変更されます。\n	 * 失敗すると、実行は停止し、DBエラーを表示します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string        $db  MySQL database name\n	 * @param resource|null $dbh Optional link identifier.\n	 */\n	public function select( $db, $dbh = null ) {\n		if ( is_null( $dbh ) ) {\n			$dbh = $this-&gt;dbh;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$success = mysqli_select_db( $dbh, $db );\n		} else {\n			$success = mysql_select_db( $db, $dbh );\n		}\n		if ( ! $success ) {\n			$this-&gt;ready = false;\n			if ( ! did_action( \'template_redirect\' ) ) {\n				wp_load_translations_early();\n\n				$message = \'&lt;h1&gt;\' . __( \'Can&amp;#8217;t select database\' ) . \"&lt;/h1&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'We were able to connect to the database server (which means your username and password is okay) but not able to select the %s database.\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/p&gt;\\n\";\n\n				$message .= \"&lt;ul&gt;\\n\";\n				$message .= \'&lt;li&gt;\' . __( \'Are you sure it exists?\' ) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: 1: database user, 2: database name */\n					__( \'Does the user %1$s have permission to use the %2$s database?\' ),\n					\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbuser, ENT_QUOTES ) . \'&lt;/code&gt;\',\n					\'&lt;code&gt;\' . htmlspecialchars( $db, ENT_QUOTES ) . \'&lt;/code&gt;\'\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \'&lt;li&gt;\' . sprintf(\n					/* translators: %s: database name */\n					__( \'On some systems the name of your database is prefixed with your username, so it would be like &lt;code&gt;username_%1$s&lt;/code&gt;. Could that be the problem?\' ),\n					htmlspecialchars( $db, ENT_QUOTES )\n				) . \"&lt;/li&gt;\\n\";\n\n				$message .= \"&lt;/ul&gt;\\n\";\n\n				$message .= \'&lt;p&gt;\' . sprintf(\n					/* translators: %s: support forums URL */\n					__( \'If you don&amp;#8217;t know how to set up a database you should &lt;strong&gt;contact your host&lt;/strong&gt;. If all else fails you may find help at the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n					__( \'https://wordpress.org/support/\' )\n				) . \"&lt;/p&gt;\\n\";\n\n				$this-&gt;bail( $message, \'db_select_fail\' );\n			}\n		}\n	}\n\n	/**\n	 * 使用しないでください、廃止予定です。\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 2.8.0\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare\n	 * @see esc_sql()\n	 *\n	 * @param string $string\n	 * @return string\n	 */\n	function _weak_escape( $string ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		return addslashes( $string );\n	}\n\n	/**\n	 * Real escape, using mysqli_real_escape_string() or mysql_real_escape_string()\n	 *\n	 * @see mysqli_real_escape_string()\n	 * @see mysql_real_escape_string()\n	 * @since 2.8.0\n	 *\n	 * @param  string $string to escape\n	 * @return string escaped\n	 */\n	function _real_escape( $string ) {\n		if ( $this-&gt;dbh ) {\n			if ( $this-&gt;use_mysqli ) {\n				$escaped = mysqli_real_escape_string( $this-&gt;dbh, $string );\n			} else {\n				$escaped = mysql_real_escape_string( $string, $this-&gt;dbh );\n			}\n		} else {\n			$class = get_class( $this );\n			if ( function_exists( \'__\' ) ) {\n				/* translators: %s: database access abstraction class, usually wpdb or a class extending wpdb */\n				_doing_it_wrong( $class, sprintf( __( \'%s must set a database connection for use with escaping.\' ), $class ), \'3.6.0\' );\n			} else {\n				_doing_it_wrong( $class, sprintf( \'%s must set a database connection for use with escaping.\', $class ), \'3.6.0\' );\n			}\n			$escaped = addslashes( $string );\n		}\n\n		return $this-&gt;add_placeholder_escape( $escaped );\n	}\n\n	/**\n	 * Escape data. Works on arrays.\n	 *\n	 * @uses wpdb::_real_escape()\n	 * @since  2.8.0\n	 *\n	 * @param  string|array $data\n	 * @return string|array escaped\n	 */\n	public function _escape( $data ) {\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;_escape( $v );\n				} else {\n					$data[ $k ] = $this-&gt;_real_escape( $v );\n				}\n			}\n		} else {\n			$data = $this-&gt;_real_escape( $data );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Do not use, deprecated.\n	 *\n	 * Use esc_sql() or wpdb::prepare() instead.\n	 *\n	 * @since 0.71\n	 * @deprecated 3.6.0 Use wpdb::prepare()\n	 * @see wpdb::prepare()\n	 * @see esc_sql()\n	 *\n	 * @param mixed $data\n	 * @return mixed\n	 */\n	public function escape( $data ) {\n		if ( func_num_args() === 1 &amp;&amp; function_exists( \'_deprecated_function\' ) ) {\n			_deprecated_function( __METHOD__, \'3.6.0\', \'wpdb::prepare() or esc_sql()\' );\n		}\n		if ( is_array( $data ) ) {\n			foreach ( $data as $k =&gt; $v ) {\n				if ( is_array( $v ) ) {\n					$data[ $k ] = $this-&gt;escape( $v, \'recursive\' );\n				} else {\n					$data[ $k ] = $this-&gt;_weak_escape( $v, \'internal\' );\n				}\n			}\n		} else {\n			$data = $this-&gt;_weak_escape( $data, \'internal\' );\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Escapes content by reference for insertion into the database, for security\n	 *\n	 * @uses wpdb::_real_escape()\n	 *\n	 * @since 2.3.0\n	 *\n	 * @param string $string to escape\n	 */\n	public function escape_by_ref( &amp;$string ) {\n		if ( ! is_float( $string ) ) {\n			$string = $this-&gt;_real_escape( $string );\n		}\n	}\n\n	/**\n	 * 安全に実行できるようにSQLクエリを準備します。sprintf（）に似た構文を使用。\n	 *\n	 * クエリ文字列では、次のプレースホルダを使用できます。\n	 *   %d (integer)数字\n	 *   %f (float)\n	 *   %s (string)　文字列\n	 *\n	 * すべてのプレースホルダは、クエリ文字列では引用符で囲まないでおく必要があります。各プレースホルダーに対応する引数を渡す必要があります。\n	 *\n	 * 古い振る舞いとの互換性のために、番号付きまたはフォーマットされた文字列プレースホルダー（例えば、％1 $ s、％5s）は引用符を含みません\n	 * この関数によって追加されたので、あなたの使用法のためにそれらを囲む適切な引用符で渡されるべきです。\n	 *\n	 * エリ文字列内のリテラルパーセント記号（％）は、%%として記述する必要があります。 （たとえばLIKE構文で使用するため）\n	 * ワイルドカードパーセンテージは、完全なLIKE文字列を含む置換引数を介して渡す必要があります。\n	 * これらは、クエリ文字列に直接挿入することはできません。  {@see wpdb :: esc_like（）}もご覧ください。\n	 *\n	 * 引数は、メソッドへの個々の引数として渡すことも、すべての引数を含む単一の配列として渡すこともできます。\n	 * この2つの組み合わせはサポートされていません。\n	 *\n	 * 例えば\n	 *     $wpdb-&gt;prepare( \"SELECT * FROM `table` WHERE `column` = %s AND `field` = %d OR `other_field` LIKE %s\", array( \'foo\', 37, \'%bar\' ) );\n	 *     $wpdb-&gt;prepare( \"SELECT DATE_FORMAT(`field`, \'%%c\') FROM `table` WHERE `column` = %s\", \'foo\' );\n	 *\n	 * @link https://secure.php.net/sprintf Description of syntax.\n	 * @since 2.3.0\n	 *\n	 * @param string      $query    Query statement with sprintf()-like placeholders\n	 * @param array|mixed $args     The array of variables to substitute into the query\'s placeholders if being called with an array of arguments,\n	 *       or the first variable to substitute into the query\'s placeholders if being called with individual arguments.\n	 * @param mixed       $args,... further variables to substitute into the query\'s placeholders if being called wih individual arguments.\n	 * @return string|void Sanitized query string, if there is a query to prepare.\n	 */\n	public function prepare( $query, $args ) {\n		if ( is_null( $query ) ) {\n			return;\n		}\n\n		// これは絶対に確実というわけではないが明らかに誤った用法を捕らえるでしょう.\n		if ( strpos( $query, \'%\' ) === false ) {\n			wp_load_translations_early();\n			_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'The query argument of %s must have a placeholder.\' ), \'wpdb::prepare()\' ), \'3.9.0\' );\n		}\n\n		$args = func_get_args();\n		array_shift( $args );\n\n		// 引数が（vsprintfのように）配列として渡された場合は、それらを上に移動します。\n		$passed_as_array = false;\n		if ( is_array( $args[0] ) &amp;&amp; count( $args ) == 1 ) {\n			$passed_as_array = true;\n			$args            = $args[0];\n		}\n\n		foreach ( $args as $arg ) {\n			if ( ! is_scalar( $arg ) &amp;&amp; ! is_null( $arg ) ) {\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', sprintf( __( \'Unsupported value type (%s).\' ), gettype( $arg ) ), \'4.8.2\' );\n			}\n		}\n\n		/*\n		 * プレースホルダで許可されている書式設定を指定します。以下が許可されています。\n		 *\n		 * - Sign specifier. eg, $+d\n		 * - Numbered placeholders. eg, %1$s\n		 * - Padding specifier, including custom padding characters. eg, %05s, %\'#5s\n		 * - Alignment specifier. eg, %05-s\n		 * - Precision specifier. eg, %.2f\n		 */\n		$allowed_format = \'(?:[1-9][0-9]*[$])?[-+0-9]*(?: |0|\\\'.)?[-+0-9]*(?:\\.[0-9]+)?\';\n\n		/*\n		 * ％sプレースホルダの周囲に引用符が既にある場合は、既存の引用符を削除してそれらを再挿入\n		 * すると、引用符の整合性が保証されます。\n		 *\n		 * 下位互換性のために、これは％sにのみ適用され、長い文字列の途中で頻繁に使用される％1 $ sなどのプレースホルダ、またはテーブル名プレースホルダには適用されません。\n		 */\n		$query = str_replace( \"\'%s\'\", \'%s\', $query ); // 既存の一重引用符を削除します。\n		$query = str_replace( \'\"%s\"\', \'%s\', $query ); // 既存の二重引用符を削除します。\n\n		// %% sのようなエスケープ文字列を避けて、文字列を引用符で囲みます。\n		$query = preg_replace( \'/(?&lt;!%)%s/\', \"\'%s\'\", $query );\n\n		 // フロートをロケールに気付かないようにします。\n		$query = preg_replace( \"/(?&lt;!%)(%($allowed_format)?f)/\", \'%\\\\2F\', $query ); \n\n		$query = preg_replace( \"/%(?:%|$|(?!($allowed_format)?[sdF]))/\", \'%%\\\\1\', $query ); // エスケープされていないパーセントをエスケープします。\n\n		// クエリ内の有効なプレースホルダの数を数えます。\n		$placeholders = preg_match_all( \"/(^|[^%]|(%%)+)%($allowed_format)?[sdF]/\", $query, $matches );\n\n		if ( count( $args ) !== $placeholders ) {\n			if ( 1 === $placeholders &amp;&amp; $passed_as_array ) {\n				// If the passed query only expected one argument, but the wrong number of arguments were sent as an array, bail.\n				wp_load_translations_early();\n				_doing_it_wrong( \'wpdb::prepare\', __( \'The query only expected one placeholder, but an array of multiple placeholders was sent.\' ), \'4.9.0\' );\n\n				return;\n			} else {\n				/*\n				 * 適切な数のプレースホルダがなくても、それらが個別の引数として渡された場合、\n				 * または配列内に複数の引数があることが予想される場合は、警告をスローします。\n				 */\n				wp_load_translations_early();\n				_doing_it_wrong(\n					\'wpdb::prepare\',\n					/* translators: 1: number of placeholders, 2: number of arguments passed */\n					sprintf(\n						__( \'The query does not contain the correct number of placeholders (%1$d) for the number of arguments passed (%2$d).\' ),\n						$placeholders,\n						count( $args )\n					),\n					\'4.8.3\'\n				);\n			}\n		}\n\n		array_walk( $args, array( $this, \'escape_by_ref\' ) );\n		$query = @vsprintf( $query, $args );\n\n		return $this-&gt;add_placeholder_escape( $query );\n	}\n\n	/**\n	 * MySQLの準備の前にLIKE特殊文字％と_をエスケープする前半。\n	 *\n	 * これはwpdb ::prepare（）またはesc_sql（）の前にのみ使用してください。順序を逆にすると、セキュリティが非常に悪くなります。\n	 *\n	 * 準備済みステートメントの例：\n	 *\n	 *     $wild = \'%\';\n	 *     $find = \'only 43% of planets\';\n	 *     $like = $wild . $wpdb-&gt;esc_like( $find ) . $wild;\n	 *     $sql  = $wpdb-&gt;prepare( \"SELECT * FROM $wpdb-&gt;posts WHERE post_content LIKE %s\", $like );\n	 *\n	 * Example Escape Chain:\n	 *\n	 *     $sql  = esc_sql( $wpdb-&gt;esc_like( $input ) );\n	 *\n	 * @since 4.0.0\n	 *\n	 * @param string $text The raw text to be escaped. The input typed by the user should have no\n	 *                     extra or deleted slashes.\n	 * @return string Text in the form of a LIKE phrase. The output is not SQL safe. Call $wpdb::prepare()\n	 *                or real_escape next.\n	 */\n	public function esc_like( $text ) {\n		return addcslashes( $text, \'_%\\\\\' );\n	}\n\n	/**\n	 * Print SQL/DB error.\n	 *\n	 * @since 0.71\n	 * @global array $EZSQL_ERROR Stores error information of query and error string\n	 *\n	 * @param string $str The error to display\n	 * @return false|void False if the showing of errors is disabled.\n	 */\n	public function print_error( $str = \'\' ) {\n		global $EZSQL_ERROR;\n\n		if ( ! $str ) {\n			if ( $this-&gt;use_mysqli ) {\n				$str = mysqli_error( $this-&gt;dbh );\n			} else {\n				$str = mysql_error( $this-&gt;dbh );\n			}\n		}\n		$EZSQL_ERROR[] = array(\n			\'query\'     =&gt; $this-&gt;last_query,\n			\'error_str\' =&gt; $str,\n		);\n\n		if ( $this-&gt;suppress_errors ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		if ( $caller = $this-&gt;get_caller() ) {\n			/* translators: 1: Database error message, 2: SQL query, 3: Name of the calling function */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s made by %3$s\' ), $str, $this-&gt;last_query, $caller );\n		} else {\n			/* translators: 1: Database error message, 2: SQL query */\n			$error_str = sprintf( __( \'WordPress database error %1$s for query %2$s\' ), $str, $this-&gt;last_query );\n		}\n\n		error_log( $error_str );\n\n		// Are we showing errors?\n		if ( ! $this-&gt;show_errors ) {\n			return false;\n		}\n\n		// If there is an error then take note of it\n		if ( is_multisite() ) {\n			$msg = sprintf(\n				\"%s [%s]\\n%s\\n\",\n				__( \'WordPress database error:\' ),\n				$str,\n				$this-&gt;last_query\n			);\n\n			if ( defined( \'ERRORLOGFILE\' ) ) {\n				error_log( $msg, 3, ERRORLOGFILE );\n			}\n			if ( defined( \'DIEONDBERROR\' ) ) {\n				wp_die( $msg );\n			}\n		} else {\n			$str   = htmlspecialchars( $str, ENT_QUOTES );\n			$query = htmlspecialchars( $this-&gt;last_query, ENT_QUOTES );\n\n			printf(\n				\'&lt;div id=\"error\"&gt;&lt;p class=\"wpdberror\"&gt;&lt;strong&gt;%s&lt;/strong&gt; [%s]&lt;br /&gt;&lt;code&gt;%s&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;\',\n				__( \'WordPress database error:\' ),\n				$str,\n				$query\n			);\n		}\n	}\n\n	/**\n	 * データベースエラーの表示を有効にします。\n	 *\n	 * この機能はエラーの表示を可能にするためだけに使用されるべきです。\n	 * wpdb::hide_errors() should be used instead for hiding of errors. However,\n	 * this function can be used to enable and disable showing of database\n	 * errors.\n	 *\n	 * @since 0.71\n	 * @see wpdb::hide_errors()\n	 *\n	 * @param bool $show Whether to show or hide errors\n	 * @return bool Old value for showing errors.\n	 */\n	public function show_errors( $show = true ) {\n		$errors            = $this-&gt;show_errors;\n		$this-&gt;show_errors = $show;\n		return $errors;\n	}\n\n	/**\n	 * Disables showing of database errors.\n	 *\n	 * By default database errors are not shown.\n	 *\n	 * @since 0.71\n	 * @see wpdb::show_errors()\n	 *\n	 * @return bool Whether showing of errors was active\n	 */\n	public function hide_errors() {\n		$show              = $this-&gt;show_errors;\n		$this-&gt;show_errors = false;\n		return $show;\n	}\n\n	/**\n	 * Whether to suppress database errors.\n	 *\n	 * By default database errors are suppressed, with a simple\n	 * call to this function they can be enabled.\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::hide_errors()\n	 * @param bool $suppress Optional. New value. Defaults to true.\n	 * @return bool Old value\n	 */\n	public function suppress_errors( $suppress = true ) {\n		$errors                = $this-&gt;suppress_errors;\n		$this-&gt;suppress_errors = (bool) $suppress;\n		return $errors;\n	}\n\n	/**\n	 * Kill cached query results.\n	 *\n	 * @since 0.71\n	 */\n	public function flush() {\n		$this-&gt;last_result   = array();\n		$this-&gt;col_info      = null;\n		$this-&gt;last_query    = null;\n		$this-&gt;rows_affected = $this-&gt;num_rows = 0;\n		$this-&gt;last_error    = \'\';\n\n		if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n			mysqli_free_result( $this-&gt;result );\n			$this-&gt;result = null;\n\n			// Sanity check before using the handle\n			if ( empty( $this-&gt;dbh ) || ! ( $this-&gt;dbh instanceof mysqli ) ) {\n				return;\n			}\n\n			// Clear out any results from a multi-query\n			while ( mysqli_more_results( $this-&gt;dbh ) ) {\n				mysqli_next_result( $this-&gt;dbh );\n			}\n		} elseif ( is_resource( $this-&gt;result ) ) {\n			mysql_free_result( $this-&gt;result );\n		}\n	}\n\n	/**\n	 * データベースに接続して選択します。\n	 *\n	 * $ allow_bailがfalseの場合、データベース接続の欠如は手動で処理する必要があります。.\n	 *\n	 * @since 3.0.0\n	 * @since 3.9.0 $allow_bail parameter added.\n	 *\n	 * @param bool $ allow_bailオプション。機能を保釈することを許可します。デフォルトはtrueです。\n	 * @return 成功した場合はtrue、失敗した場合はfalse。\n	 */\n	public function db_connect( $allow_bail = true ) {\n		$this-&gt;is_mysql = true;\n\n		/*\n		 * MySQLiを使用している場合は3.9以降では非推奨です。同等のものはありません\n		 * mysqli_ *関数には$ new_linkパラメータがあります。\n		 */\n		$new_link     = defined( \'MYSQL_NEW_LINK\' ) ? MYSQL_NEW_LINK : true;\n		$client_flags = defined( \'MYSQL_CLIENT_FLAGS\' ) ? MYSQL_CLIENT_FLAGS : 0;\n\n		if ( $this-&gt;use_mysqli ) {\n			$this-&gt;dbh = mysqli_init();\n\n			$host    = $this-&gt;dbhost;\n			$port    = null;\n			$socket  = null;\n			$is_ipv6 = false;\n\n			if ( $host_data = $this-&gt;parse_db_host( $this-&gt;dbhost ) ) {\n				list( $host, $port, $socket, $is_ipv6 ) = $host_data;\n			}\n\n			/*\n			 * If using the `mysqlnd` library, the IPv6 address needs to be\n			 * enclosed in square brackets, whereas it doesn\'t while using the\n			 * `libmysqlclient` library.\n			 * @see https://bugs.php.net/bug.php?id=67563\n			 */\n			if ( $is_ipv6 &amp;&amp; extension_loaded( \'mysqlnd\' ) ) {\n				$host = \"[$host]\";\n			}\n\n			if ( WP_DEBUG ) {\n				mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			} else {\n				@mysqli_real_connect( $this-&gt;dbh, $host, $this-&gt;dbuser, $this-&gt;dbpassword, null, $port, $socket, $client_flags );\n			}\n\n			if ( $this-&gt;dbh-&gt;connect_errno ) {\n				$this-&gt;dbh = null;\n\n				/*\n				 * ext / mysqliの設定が間違っている可能性があります。以下の場合、ext / mysqlにフォールバックしてください。\n				  *  - We haven\'t previously connected, and\n				  *  - WP_USE_EXT_MYSQL isn\'t set to false, and\n				  *  - ext/mysql is loaded.\n				  */\n				$attempt_fallback = true;\n\n				if ( $this-&gt;has_connected ) {\n					$attempt_fallback = false;\n				} elseif ( defined( \'WP_USE_EXT_MYSQL\' ) &amp;&amp; ! WP_USE_EXT_MYSQL ) {\n					$attempt_fallback = false;\n				} elseif ( ! function_exists( \'mysql_connect\' ) ) {\n					$attempt_fallback = false;\n				}\n\n				if ( $attempt_fallback ) {\n					$this-&gt;use_mysqli = false;\n					return $this-&gt;db_connect( $allow_bail );\n				}\n			}\n		} else {\n			if ( WP_DEBUG ) {\n				$this-&gt;dbh = mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			} else {\n				$this-&gt;dbh = @mysql_connect( $this-&gt;dbhost, $this-&gt;dbuser, $this-&gt;dbpassword, $new_link, $client_flags );\n			}\n		}\n\n		if ( ! $this-&gt;dbh &amp;&amp; $allow_bail ) {\n			wp_load_translations_early();\n\n			// Load custom DB error template, if present.\n			if ( file_exists( WP_CONTENT_DIR . \'/db-error.php\' ) ) {\n				require_once( WP_CONTENT_DIR . \'/db-error.php\' );\n				die();\n			}\n\n			$message = \'&lt;h1&gt;\' . __( \'Error establishing a database connection\' ) . \"&lt;/h1&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: 1: wp-config.php, 2: database host */\n				__( \'This either means that the username and password information in your %1$s file is incorrect or we can&amp;#8217;t contact the database server at %2$s. This could mean your host&amp;#8217;s database server is down.\' ),\n				\'&lt;code&gt;wp-config.php&lt;/code&gt;\',\n				\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n			) . \"&lt;/p&gt;\\n\";\n\n			$message .= \"&lt;ul&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure you have the correct username and password?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that you have typed the correct hostname?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n			$message .= \"&lt;/ul&gt;\\n\";\n\n			$message .= \'&lt;p&gt;\' . sprintf(\n				/* translators: %s: support forums URL */\n				__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n				__( \'https://wordpress.org/support/\' )\n			) . \"&lt;/p&gt;\\n\";\n\n			$this-&gt;bail( $message, \'db_connect_fail\' );\n\n			return false;\n		} elseif ( $this-&gt;dbh ) {\n			if ( ! $this-&gt;has_connected ) {\n				$this-&gt;init_charset();\n			}\n\n			$this-&gt;has_connected = true;\n\n			$this-&gt;set_charset( $this-&gt;dbh );\n\n			$this-&gt;ready = true;\n			$this-&gt;set_sql_mode();\n			$this-&gt;select( $this-&gt;dbname, $this-&gt;dbh );\n\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Parse the DB_HOST setting to interpret it for mysqli_real_connect.\n	 *\n	 * mysqli_real_connect doesn\'t support the host param including a port or\n	 * socket like mysql_connect does. This duplicates how mysql_connect detects\n	 * a port and/or socket file.\n	 *\n	 * @since 4.9.0\n	 *\n	 * @param string $host The DB_HOST setting to parse.\n	 * @return array|bool Array containing the host, the port, the socket and whether\n	 *                    it is an IPv6 address, in that order. If $host couldn\'t be parsed,\n	 *                    returns false.\n	 */\n	public function parse_db_host( $host ) {\n		$port    = null;\n		$socket  = null;\n		$is_ipv6 = false;\n\n		// First peel off the socket parameter from the right, if it exists.\n		$socket_pos = strpos( $host, \':/\' );\n		if ( $socket_pos !== false ) {\n			$socket = substr( $host, $socket_pos + 1 );\n			$host   = substr( $host, 0, $socket_pos );\n		}\n\n		// We need to check for an IPv6 address first.\n		// An IPv6 address will always contain at least two colons.\n		if ( substr_count( $host, \':\' ) &gt; 1 ) {\n			$pattern = \'#^(?:\\[)?(?P&lt;host&gt;[0-9a-fA-F:]+)(?:\\]:(?P&lt;port&gt;[\\d]+))?#\';\n			$is_ipv6 = true;\n		} else {\n			// We seem to be dealing with an IPv4 address.\n			$pattern = \'#^(?P&lt;host&gt;[^:/]*)(?::(?P&lt;port&gt;[\\d]+))?#\';\n		}\n\n		$matches = array();\n		$result  = preg_match( $pattern, $host, $matches );\n\n		if ( 1 !== $result ) {\n			// Couldn\'t parse the address, bail.\n			return false;\n		}\n\n		$host = \'\';\n		foreach ( array( \'host\', \'port\' ) as $component ) {\n			if ( ! empty( $matches[ $component ] ) ) {\n				$component = $matches[ $component ];\n			}\n		}\n\n		return array( $host, $port, $socket, $is_ipv6 );\n	}\n\n	/**\n	 * Checks that the connection to the database is still up. If not, try to reconnect.\n	 *\n	 * If this function is unable to reconnect, it will forcibly die, or if after the\n	 * the {@see \'template_redirect\'} hook has been fired, return false instead.\n	 *\n	 * If $allow_bail is false, the lack of database connection will need\n	 * to be handled manually.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @param bool $allow_bail Optional. Allows the function to bail. Default true.\n	 * @return bool|void True if the connection is up.\n	 */\n	public function check_connection( $allow_bail = true ) {\n		if ( $this-&gt;use_mysqli ) {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysqli_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		} else {\n			if ( ! empty( $this-&gt;dbh ) &amp;&amp; mysql_ping( $this-&gt;dbh ) ) {\n				return true;\n			}\n		}\n\n		$error_reporting = false;\n\n		// Disable warnings, as we don\'t want to see a multitude of \"unable to connect\" messages\n		if ( WP_DEBUG ) {\n			$error_reporting = error_reporting();\n			error_reporting( $error_reporting &amp; ~E_WARNING );\n		}\n\n		for ( $tries = 1; $tries &lt;= $this-&gt;reconnect_retries; $tries++ ) {\n			// On the last try, re-enable warnings. We want to see a single instance of the\n			// \"unable to connect\" message on the bail() screen, if it appears.\n			if ( $this-&gt;reconnect_retries === $tries &amp;&amp; WP_DEBUG ) {\n				error_reporting( $error_reporting );\n			}\n\n			if ( $this-&gt;db_connect( false ) ) {\n				if ( $error_reporting ) {\n					error_reporting( $error_reporting );\n				}\n\n				return true;\n			}\n\n			sleep( 1 );\n		}\n\n		// If template_redirect has already happened, it\'s too late for wp_die()/dead_db().\n		// Let\'s just return and hope for the best.\n		if ( did_action( \'template_redirect\' ) ) {\n			return false;\n		}\n\n		if ( ! $allow_bail ) {\n			return false;\n		}\n\n		wp_load_translations_early();\n\n		$message = \'&lt;h1&gt;\' . __( \'Error reconnecting to the database\' ) . \"&lt;/h1&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: database host */\n			__( \'This means that we lost contact with the database server at %s. This could mean your host&amp;#8217;s database server is down.\' ),\n			\'&lt;code&gt;\' . htmlspecialchars( $this-&gt;dbhost, ENT_QUOTES ) . \'&lt;/code&gt;\'\n		) . \"&lt;/p&gt;\\n\";\n\n		$message .= \"&lt;ul&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is running?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \'&lt;li&gt;\' . __( \'Are you sure that the database server is not under particularly heavy load?\' ) . \"&lt;/li&gt;\\n\";\n		$message .= \"&lt;/ul&gt;\\n\";\n\n		$message .= \'&lt;p&gt;\' . sprintf(\n			/* translators: %s: support forums URL */\n			__( \'If you&amp;#8217;re unsure what these terms mean you should probably contact your host. If you still need help you can always visit the &lt;a href=\"%s\"&gt;WordPress Support Forums&lt;/a&gt;.\' ),\n			__( \'https://wordpress.org/support/\' )\n		) . \"&lt;/p&gt;\\n\";\n\n		// We weren\'t able to reconnect, so we better bail.\n		$this-&gt;bail( $message, \'db_connect_fail\' );\n\n		// Call dead_db() if bail didn\'t die, because this database is no more. It has ceased to be (at least temporarily).\n		dead_db();\n	}\n\n	/**\n	 * 現在のデータベース接続を使用して、MySQLデータベースクエリを実行します。\n	 *\n	 * より詳しい情報はコーデックスページにあります。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query Database query\n	 * @return int|bool Boolean true for CREATE, ALTER, TRUNCATE and DROP queries. Number of rows\n	 *                  affected/selected for all other queries. Boolean false on error.\n	 */\n	public function query( $query ) {\n		if ( ! $this-&gt;ready ) {\n			$this-&gt;check_current_query = true;\n			return false;\n		}\n\n		/**\n		 * データベースクエリをフィルタリングします。\n		 *\n		 * プラグインがロードされる前にいくつかの問い合わせが行われます。\n		 * and thus cannot be filtered with this method.\n		 *\n		 * @since 2.1.0\n		 *\n		 * @param string $query Database query.\n		 */\n		$query = apply_filters( \'query\', $query );\n\n		$this-&gt;flush();\n\n		// Log how the function was called\n		$this-&gt;func_call = \"\\$db-&gt;query(\\\"$query\\\")\";\n\n		// If we\'re writing to the database, make sure the query will write safely.\n		if ( $this-&gt;check_current_query &amp;&amp; ! $this-&gt;check_ascii( $query ) ) {\n			$stripped_query = $this-&gt;strip_invalid_text_from_query( $query );\n			// strip_invalid_text_from_query() can perform queries, so we need\n			// to flush again, just to make sure everything is clear.\n			$this-&gt;flush();\n			if ( $stripped_query !== $query ) {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		$this-&gt;check_current_query = true;\n\n		// Keep track of the last query for debug.\n		$this-&gt;last_query = $query;\n\n		$this-&gt;_do_query( $query );\n\n		// MySQL server has gone away, try to reconnect.\n		$mysql_errno = 0;\n		if ( ! empty( $this-&gt;dbh ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$mysql_errno = mysqli_errno( $this-&gt;dbh );\n				} else {\n					// $dbh is defined, but isn\'t a real connection.\n					// Something has gone horribly wrong, let\'s try a reconnect.\n					$mysql_errno = 2006;\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$mysql_errno = mysql_errno( $this-&gt;dbh );\n				} else {\n					$mysql_errno = 2006;\n				}\n			}\n		}\n\n		if ( empty( $this-&gt;dbh ) || 2006 == $mysql_errno ) {\n			if ( $this-&gt;check_connection() ) {\n				$this-&gt;_do_query( $query );\n			} else {\n				$this-&gt;insert_id = 0;\n				return false;\n			}\n		}\n\n		// If there is an error then take note of it.\n		if ( $this-&gt;use_mysqli ) {\n			if ( $this-&gt;dbh instanceof mysqli ) {\n				$this-&gt;last_error = mysqli_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		} else {\n			if ( is_resource( $this-&gt;dbh ) ) {\n				$this-&gt;last_error = mysql_error( $this-&gt;dbh );\n			} else {\n				$this-&gt;last_error = __( \'Unable to retrieve the error message from MySQL\' );\n			}\n		}\n\n		if ( $this-&gt;last_error ) {\n			// Clear insert_id on a subsequent failed insert.\n			if ( $this-&gt;insert_id &amp;&amp; preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				$this-&gt;insert_id = 0;\n			}\n\n			$this-&gt;print_error();\n			return false;\n		}\n\n		if ( preg_match( \'/^\\s*(create|alter|truncate|drop)\\s/i\', $query ) ) {\n			$return_val = $this-&gt;result;\n		} elseif ( preg_match( \'/^\\s*(insert|delete|update|replace)\\s/i\', $query ) ) {\n			if ( $this-&gt;use_mysqli ) {\n				$this-&gt;rows_affected = mysqli_affected_rows( $this-&gt;dbh );\n			} else {\n				$this-&gt;rows_affected = mysql_affected_rows( $this-&gt;dbh );\n			}\n			// Take note of the insert_id\n			if ( preg_match( \'/^\\s*(insert|replace)\\s/i\', $query ) ) {\n				if ( $this-&gt;use_mysqli ) {\n					$this-&gt;insert_id = mysqli_insert_id( $this-&gt;dbh );\n				} else {\n					$this-&gt;insert_id = mysql_insert_id( $this-&gt;dbh );\n				}\n			}\n			// Return number of rows affected\n			$return_val = $this-&gt;rows_affected;\n		} else {\n			$num_rows = 0;\n			if ( $this-&gt;use_mysqli &amp;&amp; $this-&gt;result instanceof mysqli_result ) {\n				while ( $row = mysqli_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			} elseif ( is_resource( $this-&gt;result ) ) {\n				while ( $row = mysql_fetch_object( $this-&gt;result ) ) {\n					$this-&gt;last_result[ $num_rows ] = $row;\n					$num_rows++;\n				}\n			}\n\n			// Log number of rows the query returned\n			// and return number of rows selected\n			$this-&gt;num_rows = $num_rows;\n			$return_val     = $num_rows;\n		}\n\n		return $return_val;\n	}\n\n	/**\n	 * Internal function to perform the mysql_query() call.\n	 *\n	 * @since 3.9.0\n	 *\n	 * @see wpdb::query()\n	 *\n	 * @param string $query The query to run.\n	 */\n	private function _do_query( $query ) {\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;timer_start();\n		}\n\n		if ( ! empty( $this-&gt;dbh ) &amp;&amp; $this-&gt;use_mysqli ) {\n			$this-&gt;result = mysqli_query( $this-&gt;dbh, $query );\n		} elseif ( ! empty( $this-&gt;dbh ) ) {\n			$this-&gt;result = mysql_query( $query, $this-&gt;dbh );\n		}\n		$this-&gt;num_queries++;\n\n		if ( defined( \'SAVEQUERIES\' ) &amp;&amp; SAVEQUERIES ) {\n			$this-&gt;queries[] = array(\n				$query,\n				$this-&gt;timer_stop(),\n				$this-&gt;get_caller(),\n				$this-&gt;time_start,\n			);\n		}\n	}\n\n	/**\n	 * Generates and returns a placeholder escape string for use in queries returned by ::prepare().\n	 *\n	 * @since 4.8.3\n	 *\n	 * @return string String to escape placeholders.\n	 */\n	public function placeholder_escape() {\n		static $placeholder;\n\n		if ( ! $placeholder ) {\n			// If ext/hash is not present, compat.php\'s hash_hmac() does not support sha256.\n			$algo = function_exists( \'hash\' ) ? \'sha256\' : \'sha1\';\n			// Old WP installs may not have AUTH_SALT defined.\n			$salt = defined( \'AUTH_SALT\' ) &amp;&amp; AUTH_SALT ? AUTH_SALT : (string) rand();\n\n			$placeholder = \'{\' . hash_hmac( $algo, uniqid( $salt, true ), $salt ) . \'}\';\n		}\n\n		/*\n		 * レースホルダエスケープを削除するために、フィルタを追加します。優先順位0を使用します。\n		 * そのため、このフィルタに関連付けられている他のものはすべて、プレースホルダ文字列が削除されたクエリを受け取ります\n		 */\n		if ( ! has_filter( \'query\', array( $this, \'remove_placeholder_escape\' ) ) ) {\n			add_filter( \'query\', array( $this, \'remove_placeholder_escape\' ), 0 );\n		}\n\n		return $placeholder;\n	}\n\n	/**\n	 * printf（）のプレースホルダーに似たものをエスケープするために、プレースホルダーのエスケープ文字列を追加します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query to escape.\n	 * @return string 必要に応じてプレースホルダエスケープ文字列が挿入されたクエリ。\n	 */\n	public function add_placeholder_escape( $query ) {\n		/*\n		 * 漠然とプレースホルダーに似ているものでさえも返すことを防ぐために、私たちは見つけることが\n		 * できるあらゆる％をつぶします。\n		 */\n		return str_replace( \'%\', $this-&gt;placeholder_escape(), $query );\n	}\n\n	/**\n	 * クエリからプレースホルダエスケープ文字列を削除します。\n	 *\n	 * @since 4.8.3\n	 *\n	 * @param string $query The query from which the placeholder will be removed.\n	 * @return string The query with the placeholder removed.\n	 */\n	public function remove_placeholder_escape( $query ) {\n		return str_replace( $this-&gt;placeholder_escape(), \'%\', $query );\n	}\n\n	/**\n	 * Insert a row into a table.\n	 *\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::insert( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows inserted, or false on error.\n	 */\n	public function insert( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'INSERT\' );\n	}\n\n	/**\n	 * Replace a row into a table.\n	 *\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ) )\n	 *     wpdb::replace( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'%s\', \'%d\' ) )\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	public function replace( $table, $data, $format = null ) {\n		return $this-&gt;_insert_replace_helper( $table, $data, $format, \'REPLACE\' );\n	}\n\n	/**\n	 * Helper function for insert and replace.\n	 *\n	 * Runs an insert or replace query based on $type argument.\n	 *\n	 * @since 3.0.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table  Table name\n	 * @param array        $data   Data to insert (in column =&gt; value pairs).\n	 *      Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *      Sending a null value will cause the column to be set to NULL - the corresponding format is ignored in this case.\n	 * @param array|string $format Optional. An array of formats to be mapped to each of the value in $data.\n	 *      If string, that format will be used for all of the values in $data.\n	 *      A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *      If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param string $type         Optional. What type of operation is this? INSERT or REPLACE. Defaults to INSERT.\n	 * @return int|false The number of rows affected, or false on error.\n	 */\n	function _insert_replace_helper( $table, $data, $format = null, $type = \'INSERT\' ) {\n		$this-&gt;insert_id = 0;\n\n		if ( ! in_array( strtoupper( $type ), array( \'REPLACE\', \'INSERT\' ) ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$formats = $values = array();\n		foreach ( $data as $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$formats[] = \'NULL\';\n				continue;\n			}\n\n			$formats[] = $value[\'format\'];\n			$values[]  = $value[\'value\'];\n		}\n\n		$fields  = \'`\' . implode( \'`, `\', array_keys( $data ) ) . \'`\';\n		$formats = implode( \', \', $formats );\n\n		$sql = \"$type INTO `$table` ($fields) VALUES ($formats)\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Update a row in the table\n	 *\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; \'bar\' ), array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::update( \'table\', array( \'column\' =&gt; \'foo\', \'field\' =&gt; 37 ), array( \'ID\' =&gt; 1 ), array( \'%s\', \'%d\' ), array( \'%d\' ) )\n	 *\n	 * @since 2.5.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $data         Data to update (in column =&gt; value pairs).\n	 *            Both $data columns and $data values should be \"raw\" (neither should be SQL escaped).\n	 *            Sending a null value will cause the column to be set to NULL - the corresponding\n	 *            format is ignored in this case.\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $format       Optional. An array of formats to be mapped to each of the values in $data.\n	 *            If string, that format will be used for all of the values in $data.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $data will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function update( $table, $data, $where, $format = null, $where_format = null ) {\n		if ( ! is_array( $data ) || ! is_array( $where ) ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_fields( $table, $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$fields = $conditions = $values = array();\n		foreach ( $data as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$fields[] = \"`$field` = NULL\";\n				continue;\n			}\n\n			$fields[] = \"`$field` = \" . $value[\'format\'];\n			$values[] = $value[\'value\'];\n		}\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$fields     = implode( \', \', $fields );\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"UPDATE `$table` SET $fields WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Delete a row in the table\n	 *\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ) )\n	 *     wpdb::delete( \'table\', array( \'ID\' =&gt; 1 ), array( \'%d\' ) )\n	 *\n	 * @since 3.4.0\n	 * @see wpdb::prepare()\n	 * @see wpdb::$field_types\n	 * @see wp_set_wpdb_vars()\n	 *\n	 * @param string       $table        Table name\n	 * @param array        $where        A named array of WHERE clauses (in column =&gt; value pairs).\n	 *            Multiple clauses will be joined with ANDs.\n	 *            Both $where columns and $where values should be \"raw\".\n	 *            Sending a null value will create an IS NULL comparison - the corresponding format will be ignored in this case.\n	 * @param array|string $where_format Optional. An array of formats to be mapped to each of the values in $where.\n	 *            If string, that format will be used for all of the items in $where.\n	 *            A format is one of \'%d\', \'%f\', \'%s\' (integer, float, string).\n	 *            If omitted, all values in $where will be treated as strings unless otherwise specified in wpdb::$field_types.\n	 * @return int|false The number of rows updated, or false on error.\n	 */\n	public function delete( $table, $where, $where_format = null ) {\n		if ( ! is_array( $where ) ) {\n			return false;\n		}\n\n		$where = $this-&gt;process_fields( $table, $where, $where_format );\n		if ( false === $where ) {\n			return false;\n		}\n\n		$conditions = $values = array();\n		foreach ( $where as $field =&gt; $value ) {\n			if ( is_null( $value[\'value\'] ) ) {\n				$conditions[] = \"`$field` IS NULL\";\n				continue;\n			}\n\n			$conditions[] = \"`$field` = \" . $value[\'format\'];\n			$values[]     = $value[\'value\'];\n		}\n\n		$conditions = implode( \' AND \', $conditions );\n\n		$sql = \"DELETE FROM `$table` WHERE $conditions\";\n\n		$this-&gt;check_current_query = false;\n		return $this-&gt;query( $this-&gt;prepare( $sql, $values ) );\n	}\n\n	/**\n	 * Processes arrays of field/value pairs and field formats.\n	 *\n	 * This is a helper method for wpdb\'s CRUD methods, which take field/value\n	 * pairs for inserts, updates, and where clauses. This method first pairs\n	 * each value with a format. Then it determines the charset of that field,\n	 * using that to determine if any invalid text would be stripped. If text is\n	 * stripped, then field processing is rejected and the query fails.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param array  $data   Field/value pair.\n	 * @param mixed  $format Format for each field.\n	 * @return array|false Returns an array of fields that contain paired values\n	 *                    and formats. Returns false for invalid values.\n	 */\n	protected function process_fields( $table, $data, $format ) {\n		$data = $this-&gt;process_field_formats( $data, $format );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_charsets( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$data = $this-&gt;process_field_lengths( $data, $table );\n		if ( false === $data ) {\n			return false;\n		}\n\n		$converted_data = $this-&gt;strip_invalid_text( $data );\n\n		if ( $data !== $converted_data ) {\n			return false;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Prepares arrays of value/format pairs as passed to wpdb CRUD methods.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data   Array of fields to values.\n	 * @param mixed $format Formats to be mapped to the values in $data.\n	 * @return array Array, keyed by field names with values being an array\n	 *               of \'value\' and \'format\' keys.\n	 */\n	protected function process_field_formats( $data, $format ) {\n		$formats = $original_formats = (array) $format;\n\n		foreach ( $data as $field =&gt; $value ) {\n			$value = array(\n				\'value\'  =&gt; $value,\n				\'format\' =&gt; \'%s\',\n			);\n\n			if ( ! empty( $format ) ) {\n				$value[\'format\'] = array_shift( $formats );\n				if ( ! $value[\'format\'] ) {\n					$value[\'format\'] = reset( $original_formats );\n				}\n			} elseif ( isset( $this-&gt;field_types[ $field ] ) ) {\n				$value[\'format\'] = $this-&gt;field_types[ $field ];\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Adds field charsets to field/value/format arrays generated by\n	 * the wpdb::process_field_formats() method.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_formats() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'charset\' keys.\n	 */\n	protected function process_field_charsets( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'charset\'] = false;\n			} else {\n				$value[\'charset\'] = $this-&gt;get_col_charset( $table, $field );\n				if ( is_wp_error( $value[\'charset\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * For string fields, record the maximum string length that field can safely save.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param array  $data  As it comes from the wpdb::process_field_charsets() method.\n	 * @param string $table Table name.\n	 * @return array|false The same array as $data with additional \'length\' keys, or false if\n	 *                     any of the values were too long for their corresponding field.\n	 */\n	protected function process_field_lengths( $data, $table ) {\n		foreach ( $data as $field =&gt; $value ) {\n			if ( \'%d\' === $value[\'format\'] || \'%f\' === $value[\'format\'] ) {\n				/*\n				 * We can skip this field if we know it isn\'t a string.\n				 * This checks %d/%f versus ! %s because its sprintf() could take more.\n				 */\n				$value[\'length\'] = false;\n			} else {\n				$value[\'length\'] = $this-&gt;get_col_length( $table, $field );\n				if ( is_wp_error( $value[\'length\'] ) ) {\n					return false;\n				}\n			}\n\n			$data[ $field ] = $value;\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Retrieve one variable from the database.\n	 *\n	 * Executes a SQL query and returns the value from the SQL result.\n	 * If the SQL result contains more than one column and/or more than one row, this function returns the value in the column and row specified.\n	 * If $query is null, this function returns the value in the specified column and row from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to null, use the result from the previous query.\n	 * @param int         $x     Optional. Column of value to return. Indexed from 0.\n	 * @param int         $y     Optional. Row of value to return. Indexed from 0.\n	 * @return string|null Database query result (as string), or null on failure\n	 */\n	public function get_var( $query = null, $x = 0, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_var(\\\"$query\\\", $x, $y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		// Extract var out of cached results based x,y vals\n		if ( ! empty( $this-&gt;last_result[ $y ] ) ) {\n			$values = array_values( get_object_vars( $this-&gt;last_result[ $y ] ) );\n		}\n\n		// If there is a value return it else return null\n		return ( isset( $values[ $x ] ) &amp;&amp; $values[ $x ] !== \'\' ) ? $values[ $x ] : null;\n	}\n\n	/**\n	 * Retrieve one row from the database.\n	 *\n	 * Executes a SQL query and returns the row from the SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query  SQL query.\n	 * @param string      $output Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which correspond to\n	 *     an stdClass object, an associative array, or a numeric array, respectively. Default OBJECT.\n	 * @param int         $y      Optional. Row to return. Indexed from 0.\n	 * @return array|object|null|void Database query result in format specified by $output or null on failure\n	 */\n	public function get_row( $query = null, $output = OBJECT, $y = 0 ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_row(\\\"$query\\\",$output,$y)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		if ( ! isset( $this-&gt;last_result[ $y ] ) ) {\n			return null;\n		}\n\n		if ( $output == OBJECT ) {\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} elseif ( $output == ARRAY_A ) {\n			return $this-&gt;last_result[ $y ] ? get_object_vars( $this-&gt;last_result[ $y ] ) : null;\n		} elseif ( $output == ARRAY_N ) {\n			return $this-&gt;last_result[ $y ] ? array_values( get_object_vars( $this-&gt;last_result[ $y ] ) ) : null;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result[ $y ] ? $this-&gt;last_result[ $y ] : null;\n		} else {\n			$this-&gt;print_error( \' $db-&gt;get_row(string query, output type, int offset) -- Output type must be one of: OBJECT, ARRAY_A, ARRAY_N\' );\n		}\n	}\n\n	/**\n	 * Retrieve one column from the database.\n	 *\n	 * Executes a SQL query and returns the column from the SQL result.\n	 * If the SQL result contains more than one column, this function returns the column specified.\n	 * If $query is null, this function returns the specified column from the previous SQL result.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string|null $query Optional. SQL query. Defaults to previous query.\n	 * @param int         $x     Optional. Column to return. Indexed from 0.\n	 * @return array Database query result. Array indexed from 0 by SQL result row number.\n	 */\n	public function get_col( $query = null, $x = 0 ) {\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		}\n\n		$new_array = array();\n		// Extract the column values\n		if ( $this-&gt;last_result ) {\n			for ( $i = 0, $j = count( $this-&gt;last_result ); $i &lt; $j; $i++ ) {\n				$new_array[ $i ] = $this-&gt;get_var( null, $x, $i );\n			}\n		}\n		return $new_array;\n	}\n\n	/**\n	 * データベースからSQL結果セット全体（つまり多数の行）を取得します。\n	 *\n	 * SQLクエリを実行し、SQL結果全体を返します。\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $query  SQL query.\n	 * @param string $output Optional. Any of ARRAY_A | ARRAY_N | OBJECT | OBJECT_K constants.\n	 *最初の3つのうちの1つでは、SQL結果の行番号によって0からインデックスされた行の配列を返します。\n	 *各行は連想配列（column =&gt; value、...）、数値インデックス配列（0 =&gt; value、...）、またはオブジェクトです。 （ - &gt; column = value）\n	 *OBJECT_Kを使用すると、各行の最初の列の値によってキー設定された行オブジェクトの連想配列を返します。\n	 *重複したキーは破棄されます。\n	 * @return 配列|オブジェクト|null データベースクエリ結果\n	 */\n	public function get_results( $query = null, $output = OBJECT ) {\n		$this-&gt;func_call = \"\\$db-&gt;get_results(\\\"$query\\\", $output)\";\n\n		if ( $this-&gt;check_current_query &amp;&amp; $this-&gt;check_safe_collation( $query ) ) {\n			$this-&gt;check_current_query = false;\n		}\n\n		if ( $query ) {\n			$this-&gt;query( $query );\n		} else {\n			return null;\n		}\n\n		$new_array = array();\n		if ( $output == OBJECT ) {\n			// Return an integer-keyed array of row objects\n			return $this-&gt;last_result;\n		} elseif ( $output == OBJECT_K ) {\n			// Return an array of row objects with keys from column 1\n			// (Duplicates are discarded)\n			if ( $this-&gt;last_result ) {\n				foreach ( $this-&gt;last_result as $row ) {\n					$var_by_ref = get_object_vars( $row );\n					$key        = array_shift( $var_by_ref );\n					if ( ! isset( $new_array[ $key ] ) ) {\n						$new_array[ $key ] = $row;\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( $output == ARRAY_A || $output == ARRAY_N ) {\n			// Return an integer-keyed array of...\n			if ( $this-&gt;last_result ) {\n				foreach ( (array) $this-&gt;last_result as $row ) {\n					if ( $output == ARRAY_N ) {\n						// ...integer-keyed row arrays\n						$new_array[] = array_values( get_object_vars( $row ) );\n					} else {\n						// ...column name-keyed row arrays\n						$new_array[] = get_object_vars( $row );\n					}\n				}\n			}\n			return $new_array;\n		} elseif ( strtoupper( $output ) === OBJECT ) {\n			// Back compat for OBJECT being previously case insensitive.\n			return $this-&gt;last_result;\n		}\n		return null;\n	}\n\n	/**\n	 * Retrieves the character set for the given table.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table Table name.\n	 * @return string|WP_Error Table character set, WP_Error object if it couldn\'t be found.\n	 */\n	protected function get_table_charset( $table ) {\n		$tablekey = strtolower( $table );\n\n		/**\n		 * Filters the table charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will effectively short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 */\n		$charset = apply_filters( \'pre_get_table_charset\', null, $table );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		if ( isset( $this-&gt;table_charset[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		$charsets = $columns = array();\n\n		$table_parts = explode( \'.\', $table );\n		$table       = \'`\' . implode( \'`.`\', $table_parts ) . \'`\';\n		$results     = $this-&gt;get_results( \"SHOW FULL COLUMNS FROM $table\" );\n		if ( ! $results ) {\n			return new WP_Error( \'wpdb_get_table_charset_failure\' );\n		}\n\n		foreach ( $results as $column ) {\n			$columns[ strtolower( $column-&gt;Field ) ] = $column;\n		}\n\n		$this-&gt;col_meta[ $tablekey ] = $columns;\n\n		foreach ( $columns as $column ) {\n			if ( ! empty( $column-&gt;Collation ) ) {\n				list( $charset ) = explode( \'_\', $column-&gt;Collation );\n\n				// If the current connection can\'t support utf8mb4 characters, let\'s only send 3-byte utf8 characters.\n				if ( \'utf8mb4\' === $charset &amp;&amp; ! $this-&gt;has_cap( \'utf8mb4\' ) ) {\n					$charset = \'utf8\';\n				}\n\n				$charsets[ strtolower( $charset ) ] = true;\n			}\n\n			list( $type ) = explode( \'(\', $column-&gt;Type );\n\n			// A binary/blob means the whole query gets treated like this.\n			if ( in_array( strtoupper( $type ), array( \'BINARY\', \'VARBINARY\', \'TINYBLOB\', \'MEDIUMBLOB\', \'BLOB\', \'LONGBLOB\' ) ) ) {\n				$this-&gt;table_charset[ $tablekey ] = \'binary\';\n				return \'binary\';\n			}\n		}\n\n		// utf8mb3 is an alias for utf8.\n		if ( isset( $charsets[\'utf8mb3\'] ) ) {\n			$charsets[\'utf8\'] = true;\n			unset( $charsets[\'utf8mb3\'] );\n		}\n\n		// Check if we have more than one charset in play.\n		$count = count( $charsets );\n		if ( 1 === $count ) {\n			$charset = key( $charsets );\n		} elseif ( 0 === $count ) {\n			// No charsets, assume this table can store whatever.\n			$charset = false;\n		} else {\n			// More than one charset. Remove latin1 if present and recalculate.\n			unset( $charsets[\'latin1\'] );\n			$count = count( $charsets );\n			if ( 1 === $count ) {\n				// Only one charset (besides latin1).\n				$charset = key( $charsets );\n			} elseif ( 2 === $count &amp;&amp; isset( $charsets[\'utf8\'], $charsets[\'utf8mb4\'] ) ) {\n				// Two charsets, but they\'re utf8 and utf8mb4, use utf8.\n				$charset = \'utf8\';\n			} else {\n				// Two mixed character sets. ascii.\n				$charset = \'ascii\';\n			}\n		}\n\n		$this-&gt;table_charset[ $tablekey ] = $charset;\n		return $charset;\n	}\n\n	/**\n	 * Retrieves the character set for the given column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return string|false|WP_Error Column character set as a string. False if the column has no\n	 *        character set. WP_Error object if there was an error.\n	 */\n	public function get_col_charset( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		/**\n		 * Filters the column charset value before the DB is checked.\n		 *\n		 * Passing a non-null value to the filter will short-circuit\n		 * checking the DB for the charset, returning that value instead.\n		 *\n		 * @since 4.2.0\n		 *\n		 * @param string $charset The character set to use. Default null.\n		 * @param string $table   The name of the table being checked.\n		 * @param string $column  The name of the column being checked.\n		 */\n		$charset = apply_filters( \'pre_get_col_charset\', null, $table, $column );\n		if ( null !== $charset ) {\n			return $charset;\n		}\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;table_charset[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		// If still no column information, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// If this column doesn\'t exist, return the table charset.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return $this-&gt;table_charset[ $tablekey ];\n		}\n\n		// Return false when it\'s not a string column.\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation ) ) {\n			return false;\n		}\n\n		list( $charset ) = explode( \'_\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Collation );\n		return $charset;\n	}\n\n	/**\n	 * Retrieve the maximum string length allowed in a given column.\n	 * The length may either be specified as a byte length or a character length.\n	 *\n	 * @since 4.2.1\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @return array|false|WP_Error array( \'length\' =&gt; (int), \'type\' =&gt; \'byte\' | \'char\' )\n	 *       false if the column has no length (for example, numeric column)\n	 *       WP_Error object if there was an error.\n	 */\n	public function get_col_length( $table, $column ) {\n		$tablekey  = strtolower( $table );\n		$columnkey = strtolower( $column );\n\n		// Skip this entirely if this isn\'t a MySQL database.\n		if ( empty( $this-&gt;is_mysql ) ) {\n			return false;\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ] ) ) {\n			// This primes column information for us.\n			$table_charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $table_charset ) ) {\n				return $table_charset;\n			}\n		}\n\n		if ( empty( $this-&gt;col_meta[ $tablekey ][ $columnkey ] ) ) {\n			return false;\n		}\n\n		$typeinfo = explode( \'(\', $this-&gt;col_meta[ $tablekey ][ $columnkey ]-&gt;Type );\n\n		$type = strtolower( $typeinfo[0] );\n		if ( ! empty( $typeinfo[1] ) ) {\n			$length = trim( $typeinfo[1], \')\' );\n		} else {\n			$length = false;\n		}\n\n		switch ( $type ) {\n			case \'char\':\n			case \'varchar\':\n				return array(\n					\'type\'   =&gt; \'char\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'binary\':\n			case \'varbinary\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; (int) $length,\n				);\n\n			case \'tinyblob\':\n			case \'tinytext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 255,        // 2^8 - 1\n				);\n\n			case \'blob\':\n			case \'text\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 65535,      // 2^16 - 1\n				);\n\n			case \'mediumblob\':\n			case \'mediumtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 167772,   // 2^24 - 1\n				);\n\n			case \'longblob\':\n			case \'longtext\':\n				return array(\n					\'type\'   =&gt; \'byte\',\n					\'length\' =&gt; 4294967295, // 2^32 - 1\n				);\n\n			default:\n				return false;\n		}\n	}\n\n	/**\n	 * Check if a string is ASCII.\n	 *\n	 * The negative regex is faster for non-ASCII strings, as it allows\n	 * the search to finish as soon as it encounters a non-ASCII character.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $string String to check.\n	 * @return bool True if ASCII, false if not.\n	 */\n	protected function check_ascii( $string ) {\n		if ( function_exists( \'mb_check_encoding\' ) ) {\n			if ( mb_check_encoding( $string, \'ASCII\' ) ) {\n				return true;\n			}\n		} elseif ( ! preg_match( \'/[^\\x00-\\x7F]/\', $string ) ) {\n			return true;\n		}\n\n		return false;\n	}\n\n	/**\n	 * Check if the query is accessing a collation considered safe on the current version of MySQL.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to check.\n	 * @return bool True if the collation is safe, false if it isn\'t.\n	 */\n	protected function check_safe_collation( $query ) {\n		if ( $this-&gt;checking_collation ) {\n			return true;\n		}\n\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $query ) ) {\n			return true;\n		}\n\n		// All-ASCII queries don\'t need extra checking.\n		if ( $this-&gt;check_ascii( $query ) ) {\n			return true;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( ! $table ) {\n			return false;\n		}\n\n		$this-&gt;checking_collation = true;\n		$collation                = $this-&gt;get_table_charset( $table );\n		$this-&gt;checking_collation = false;\n\n		// Tables with no collation, or latin1 only, don\'t need extra checking.\n		if ( false === $collation || \'latin1\' === $collation ) {\n			return true;\n		}\n\n		$table = strtolower( $table );\n		if ( empty( $this-&gt;col_meta[ $table ] ) ) {\n			return false;\n		}\n\n		// If any of the columns don\'t have one of these collations, it needs more sanity checking.\n		foreach ( $this-&gt;col_meta[ $table ] as $col ) {\n			if ( empty( $col-&gt;Collation ) ) {\n				continue;\n			}\n\n			if ( ! in_array( $col-&gt;Collation, array( \'utf8_general_ci\', \'utf8_bin\', \'utf8mb4_general_ci\', \'utf8mb4_bin\' ), true ) ) {\n				return false;\n			}\n		}\n\n		return true;\n	}\n\n	/**\n	 * Strips any invalid characters based on value/charset pairs.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param array $data Array of value arrays. Each value array has the keys\n	 *                    \'value\' and \'charset\'. An optional \'ascii\' key can be\n	 *                    set to false to avoid redundant ASCII checks.\n	 * @return array|WP_Error The $data parameter, with invalid characters removed from\n	 * each value. This works as a passthrough: any additional keys\n	 * such as \'field\' are retained in each value array. If we cannot\n	 * remove invalid characters, a WP_Error object is returned.\n	 */\n	protected function strip_invalid_text( $data ) {\n		$db_check_string = false;\n\n		foreach ( $data as &amp;$value ) {\n			$charset = $value[\'charset\'];\n\n			if ( is_array( $value[\'length\'] ) ) {\n				$length                  = $value[\'length\'][\'length\'];\n				$truncate_by_byte_length = \'byte\' === $value[\'length\'][\'type\'];\n			} else {\n				$length = false;\n				// Since we have no length, we\'ll never truncate.\n				// Initialize the variable to false. true would take us\n				// through an unnecessary (for this case) codepath below.\n				$truncate_by_byte_length = false;\n			}\n\n			// There\'s no charset to work with.\n			if ( false === $charset ) {\n				continue;\n			}\n\n			// Column isn\'t a string.\n			if ( ! is_string( $value[\'value\'] ) ) {\n				continue;\n			}\n\n			$needs_validation = true;\n			if (\n				// latin1 can store any byte sequence\n				\'latin1\' === $charset\n			||\n				// ASCII is always OK.\n				( ! isset( $value[\'ascii\'] ) &amp;&amp; $this-&gt;check_ascii( $value[\'value\'] ) )\n			) {\n				$truncate_by_byte_length = true;\n				$needs_validation        = false;\n			}\n\n			if ( $truncate_by_byte_length ) {\n				mbstring_binary_safe_encoding();\n				if ( false !== $length &amp;&amp; strlen( $value[\'value\'] ) &gt; $length ) {\n					$value[\'value\'] = substr( $value[\'value\'], 0, $length );\n				}\n				reset_mbstring_encoding();\n\n				if ( ! $needs_validation ) {\n					continue;\n				}\n			}\n\n			// utf8 can be handled by regex, which is a bunch faster than a DB lookup.\n			if ( ( \'utf8\' === $charset || \'utf8mb3\' === $charset || \'utf8mb4\' === $charset ) &amp;&amp; function_exists( \'mb_strlen\' ) ) {\n				$regex = \'/\n					(\n						(?: [\\x00-\\x7F]                  # single-byte sequences   0xxxxxxx\n						|   [\\xC2-\\xDF][\\x80-\\xBF]       # double-byte sequences   110xxxxx 10xxxxxx\n						|   \\xE0[\\xA0-\\xBF][\\x80-\\xBF]   # triple-byte sequences   1110xxxx 10xxxxxx * 2\n						|   [\\xE1-\\xEC][\\x80-\\xBF]{2}\n						|   \\xED[\\x80-\\x9F][\\x80-\\xBF]\n						|   [\\xEE-\\xEF][\\x80-\\xBF]{2}\';\n\n				if ( \'utf8mb4\' === $charset ) {\n					$regex .= \'\n						|    \\xF0[\\x90-\\xBF][\\x80-\\xBF]{2} # four-byte sequences   11110xxx 10xxxxxx * 3\n						|    [\\xF1-\\xF3][\\x80-\\xBF]{3}\n						|    \\xF4[\\x80-\\x8F][\\x80-\\xBF]{2}\n					\';\n				}\n\n				$regex         .= \'){1,40}   # ...one or more times\n					)\n					| .           # anything else\n					/x\';\n				$value[\'value\'] = preg_replace( $regex, \'$1\', $value[\'value\'] );\n\n				if ( false !== $length &amp;&amp; mb_strlen( $value[\'value\'], \'UTF-8\' ) &gt; $length ) {\n					$value[\'value\'] = mb_substr( $value[\'value\'], 0, $length, \'UTF-8\' );\n				}\n				continue;\n			}\n\n			// We couldn\'t use any local conversions, send it to the DB.\n			$value[\'db\'] = $db_check_string = true;\n		}\n		unset( $value ); // Remove by reference.\n\n		if ( $db_check_string ) {\n			$queries = array();\n			foreach ( $data as $col =&gt; $value ) {\n				if ( ! empty( $value[\'db\'] ) ) {\n					// We\'re going to need to truncate by characters or bytes, depending on the length value we have.\n					if ( \'byte\' === $value[\'length\'][\'type\'] ) {\n						// Using binary causes LEFT() to truncate by bytes.\n						$charset = \'binary\';\n					} else {\n						$charset = $value[\'charset\'];\n					}\n\n					if ( $this-&gt;charset ) {\n						$connection_charset = $this-&gt;charset;\n					} else {\n						if ( $this-&gt;use_mysqli ) {\n							$connection_charset = mysqli_character_set_name( $this-&gt;dbh );\n						} else {\n							$connection_charset = mysql_client_encoding();\n						}\n					}\n\n					if ( is_array( $value[\'length\'] ) ) {\n						$length          = sprintf( \'%.0f\', $value[\'length\'][\'length\'] );\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( LEFT( CONVERT( %s USING $charset ), $length ) USING $connection_charset )\", $value[\'value\'] );\n					} elseif ( \'binary\' !== $charset ) {\n						// If we don\'t have a length, there\'s no need to convert binary - it will always return the same result.\n						$queries[ $col ] = $this-&gt;prepare( \"CONVERT( CONVERT( %s USING $charset ) USING $connection_charset )\", $value[\'value\'] );\n					}\n\n					unset( $data[ $col ][\'db\'] );\n				}\n			}\n\n			$sql = array();\n			foreach ( $queries as $column =&gt; $query ) {\n				if ( ! $query ) {\n					continue;\n				}\n\n				$sql[] = $query . \" AS x_$column\";\n			}\n\n			$this-&gt;check_current_query = false;\n			$row= $this-&gt;get_row( \'SELECT \' . implode( \', \', $sql ), ARRAY_A );\n			if ( ! $row ) {\n				return new WP_Error( \'wpdb_strip_invalid_text_failure\' );\n			}\n\n			foreach ( array_keys( $data ) as $column ) {\n				if ( isset( $row[ \"x_$column\" ] ) ) {\n					$data[ $column ][\'value\'] = $row[ \"x_$column\" ];\n				}\n			}\n		}\n\n		return $data;\n	}\n\n	/**\n	 * Strips any invalid characters from the query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query Query to convert.\n	 * @return string|WP_Error The converted query, or a WP_Error object if the conversion fails.\n	 */\n	protected function strip_invalid_text_from_query( $query ) {\n		// We don\'t need to check the collation for queries that don\'t read data.\n		$trimmed_query = ltrim( $query, \"\\r\\n\\t (\" );\n		if ( preg_match( \'/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i\', $trimmed_query ) ) {\n			return $query;\n		}\n\n		$table = $this-&gt;get_table_from_query( $query );\n		if ( $table ) {\n			$charset = $this-&gt;get_table_charset( $table );\n			if ( is_wp_error( $charset ) ) {\n				return $charset;\n			}\n\n			// We can\'t reliably strip text from tables containing binary/blob columns\n			if ( \'binary\' === $charset ) {\n				return $query;\n			}\n		} else {\n			$charset = $this-&gt;charset;\n		}\n\n		$data = array(\n			\'value\'   =&gt; $query,\n			\'charset\' =&gt; $charset,\n			\'ascii\'   =&gt; false,\n			\'length\'  =&gt; false,\n		);\n\n		$data = $this-&gt;strip_invalid_text( array( $data ) );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[0][\'value\'];\n	}\n\n	/**\n	 * Strips any invalid characters from the string for a given table and column.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $table  Table name.\n	 * @param string $column Column name.\n	 * @param string $value  The text to check.\n	 * @return string|WP_Error The converted string, or a WP_Error object if the conversion fails.\n	 */\n	public function strip_invalid_text_for_column( $table, $column, $value ) {\n		if ( ! is_string( $value ) ) {\n			return $value;\n		}\n\n		$charset = $this-&gt;get_col_charset( $table, $column );\n		if ( ! $charset ) {\n			// Not a string column.\n			return $value;\n		} elseif ( is_wp_error( $charset ) ) {\n			// Bail on real errors.\n			return $charset;\n		}\n\n		$data = array(\n			$column =&gt; array(\n				\'value\'   =&gt; $value,\n				\'charset\' =&gt; $charset,\n				\'length\'  =&gt; $this-&gt;get_col_length( $table, $column ),\n			),\n		);\n\n		$data = $this-&gt;strip_invalid_text( $data );\n		if ( is_wp_error( $data ) ) {\n			return $data;\n		}\n\n		return $data[ $column ][\'value\'];\n	}\n\n	/**\n	 * Find the first table name referenced in a query.\n	 *\n	 * @since 4.2.0\n	 *\n	 * @param string $query The query to search.\n	 * @return string|false $table The table name found, or false if a table couldn\'t be found.\n	 */\n	protected function get_table_from_query( $query ) {\n		// Remove characters that can legally trail the table name.\n		$query = rtrim( $query, \';/-#\' );\n\n		// Allow (select...) union [...] style queries. Use the first query\'s table name.\n		$query = ltrim( $query, \"\\r\\n\\t (\" );\n\n		// Strip everything between parentheses except nested selects.\n		$query = preg_replace( \'/\\((?!\\s*select)[^(]*?\\)/is\', \'()\', $query );\n\n		// Quickly match most common queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'SELECT.*?\\s+FROM\'\n				. \'|INSERT(?:\\s+LOW_PRIORITY|\\s+DELAYED|\\s+HIGH_PRIORITY)?(?:\\s+IGNORE)?(?:\\s+INTO)?\'\n				. \'|REPLACE(?:\\s+LOW_PRIORITY|\\s+DELAYED)?(?:\\s+INTO)?\'\n				. \'|UPDATE(?:\\s+LOW_PRIORITY)?(?:\\s+IGNORE)?\'\n				. \'|DELETE(?:\\s+LOW_PRIORITY|\\s+QUICK|\\s+IGNORE)*(?:.+?FROM)?\'\n			. \')\\s+((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		// SHOW TABLE STATUS and SHOW TABLES WHERE Name = \'wp_posts\'\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES).+WHERE\\s+Name\\s*=\\s*(\"|\\\')((?:[0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\\\1/is\', $query, $maybe ) ) {\n			return $maybe[2];\n		}\n\n		// SHOW TABLE STATUS LIKE and SHOW TABLES LIKE \'wp\\_3\\_%\'\n		// This quoted LIKE operand seldom holds a full table name.\n		// It is usually a pattern for matching a prefix so we just\n		// strip the trailing % and unescape the _ to get \'wp_3_\'\n		// which drop-ins can use for routing these SQL statements.\n		if ( preg_match( \'/^\\s*SHOW\\s+(?:TABLE\\s+STATUS|(?:FULL\\s+)?TABLES)\\s+(?:WHERE\\s+Name\\s+)?LIKE\\s*(\"|\\\')((?:[\\\\\\\\0-9a-zA-Z$_.-]|[\\xC2-\\xDF][\\x80-\\xBF])+)%?\\\\1/is\', $query, $maybe ) ) {\n			return str_replace( \'\\\\_\', \'_\', $maybe[2] );\n		}\n\n		// Big pattern for the rest of the table-related queries.\n		if ( preg_match(\n			\'/^\\s*(?:\'\n				. \'(?:EXPLAIN\\s+(?:EXTENDED\\s+)?)?SELECT.*?\\s+FROM\'\n				. \'|DESCRIBE|DESC|EXPLAIN|HANDLER\'\n				. \'|(?:LOCK|UNLOCK)\\s+TABLE(?:S)?\'\n				. \'|(?:RENAME|OPTIMIZE|BACKUP|RESTORE|CHECK|CHECKSUM|ANALYZE|REPAIR).*\\s+TABLE\'\n				. \'|TRUNCATE(?:\\s+TABLE)?\'\n				. \'|CREATE(?:\\s+TEMPORARY)?\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\'\n				. \'|ALTER(?:\\s+IGNORE)?\\s+TABLE\'\n				. \'|DROP\\s+TABLE(?:\\s+IF\\s+EXISTS)?\'\n				. \'|CREATE(?:\\s+\\w+)?\\s+INDEX.*\\s+ON\'\n				. \'|DROP\\s+INDEX.*\\s+ON\'\n				. \'|LOAD\\s+DATA.*INFILE.*INTO\\s+TABLE\'\n				. \'|(?:GRANT|REVOKE).*ON\\s+TABLE\'\n				. \'|SHOW\\s+(?:.*FROM|.*TABLE)\'\n			. \')\\s+\\(*\\s*((?:[0-9a-zA-Z$_.`-]|[\\xC2-\\xDF][\\x80-\\xBF])+)\\s*\\)*/is\',\n			$query,\n			$maybe\n		) ) {\n			return str_replace( \'`\', \'\', $maybe[1] );\n		}\n\n		return false;\n	}\n\n	/**\n	 * Load the column metadata from the last query.\n	 *\n	 * @since 3.5.0\n	 */\n	protected function load_col_info() {\n		if ( $this-&gt;col_info ) {\n			return;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$num_fields = mysqli_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysqli_fetch_field( $this-&gt;result );\n			}\n		} else {\n			$num_fields = mysql_num_fields( $this-&gt;result );\n			for ( $i = 0; $i &lt; $num_fields; $i++ ) {\n				$this-&gt;col_info[ $i ] = mysql_fetch_field( $this-&gt;result, $i );\n			}\n		}\n	}\n\n	/**\n	 * Retrieve column metadata from the last query.\n	 *\n	 * @since 0.71\n	 *\n	 * @param string $info_type  Optional. Type one of name, table, def, max_length, not_null, primary_key, multiple_key, unique_key, numeric, blob, type, unsigned, zerofill\n	 * @param int    $col_offset Optional. 0: col name. 1: which table the col\'s in. 2: col\'s max length. 3: if the col is numeric. 4: col\'s type\n	 * @return mixed Column Results\n	 */\n	public function get_col_info( $info_type = \'name\', $col_offset = -1 ) {\n		$this-&gt;load_col_info();\n\n		if ( $this-&gt;col_info ) {\n			if ( $col_offset == -1 ) {\n				$i         = 0;\n				$new_array = array();\n				foreach ( (array) $this-&gt;col_info as $col ) {\n					$new_array[ $i ] = $col-&gt;{$info_type};\n					$i++;\n				}\n				return $new_array;\n			} else {\n				return $this-&gt;col_info[ $col_offset ]-&gt;{$info_type};\n			}\n		}\n	}\n\n	/**\n	 * Starts the timer, for debugging purposes.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return true\n	 */\n	public function timer_start() {\n		$this-&gt;time_start = microtime( true );\n		return true;\n	}\n\n	/**\n	 * Stops the debugging timer.\n	 *\n	 * @since 1.5.0\n	 *\n	 * @return float Total time spent on the query, in seconds\n	 */\n	public function timer_stop() {\n		return ( microtime( true ) - $this-&gt;time_start );\n	}\n\n	/**\n	 * エラーを素敵なヘッダーとフッターにラップして終わります。\n	 *\n	 * wpdb :: $ show_errorsがfalseであれば死にません。\n	 *\n	 * @since 1.5.0\n	 *\n	 * @param string $message    The Error message\n	 * @param string $error_code Optional. エラーを識別するためのコンピュータ可読文字列。\n	 * @return false|void\n	 */\n	public function bail( $message, $error_code = \'500\' ) {\n		if ( $this-&gt;show_errors ) {\n			$error = \'\';\n\n			if ( $this-&gt;use_mysqli ) {\n				if ( $this-&gt;dbh instanceof mysqli ) {\n					$error = mysqli_error( $this-&gt;dbh );\n				} elseif ( mysqli_connect_errno() ) {\n					$error = mysqli_connect_error();\n				}\n			} else {\n				if ( is_resource( $this-&gt;dbh ) ) {\n					$error = mysql_error( $this-&gt;dbh );\n				} else {\n					$error = mysql_error();\n				}\n			}\n\n			if ( $error ) {\n				$message = \'&lt;p&gt;&lt;code&gt;\' . $error . \"&lt;/code&gt;&lt;/p&gt;\\n\" . $message;\n			}\n\n			wp_die( $message );\n		} else {\n			if ( class_exists( \'WP_Error\', false ) ) {\n				$this-&gt;error = new WP_Error( $error_code, $message );\n			} else {\n				$this-&gt;error = $message;\n			}\n\n			return false;\n		}\n	}\n\n\n	/**\n	 * 現在のデータベース接続を閉じます。\n	 *\n	 * @since 4.5.0\n	 *\n	 * @return bool True if the connection was successfully closed, false if it wasn\'t,\n	 *              or the connection doesn\'t exist.\n	 */\n	public function close() {\n		if ( ! $this-&gt;dbh ) {\n			return false;\n		}\n\n		if ( $this-&gt;use_mysqli ) {\n			$closed = mysqli_close( $this-&gt;dbh );\n		} else {\n			$closed = mysql_close( $this-&gt;dbh );\n		}\n\n		if ( $closed ) {\n			$this-&gt;dbh           = null;\n			$this-&gt;ready         = false;\n			$this-&gt;has_connected = false;\n		}\n\n		return $closed;\n	}\n\n	/**\n	 * MySQLデータベースが最低限必要な最小バージョンかどうか\n	 *\n	 * @since 2.5.0\n	 *\n	 * @global string $wp_version\n	 * @global string $required_mysql_version\n	 *\n	 * @return WP_Error|void\n	 */\n	public function check_database_version() {\n		global $wp_version, $required_mysql_version;\n		// サーバーに必要なMySQLバージョンがあることを確認してください。\n		if ( version_compare( $this-&gt;db_version(), $required_mysql_version, \'&lt;\' ) ) {\n			/* translators: 1: WordPress version number, 2: Minimum required MySQL version number */\n			return new WP_Error( \'database_version\', sprintf( __( \'&lt;strong&gt;ERROR&lt;/strong&gt;: WordPress %1$s requires MySQL %2$s or higher\' ), $wp_version, $required_mysql_version ) );\n		}\n	}\n\n	/**\n	 * データベースが照合をサポートしているかどうか\n	 *\n	 * WordPressがテーブルスキームを生成しているときに呼び出されます。\n	 *\n	 * Use `wpdb::has_cap( \'collation\' )`.\n	 *\n	 * @since 2.5.0\n	 * @deprecated 3.5.0 Use wpdb::has_cap()\n	 *\n	 * @return bool True if collation is supported, false if version does not\n	 */\n	public function supports_collation() {\n		_deprecated_function( __FUNCTION__, \'3.5.0\', \'wpdb::has_cap( \\\'collation\\\' )\' );\n		return $this-&gt;has_cap( \'collation\' );\n	}\n\n	/**\n	 * データベース文字の照合\n	 *\n	 * @since 3.5.0\n	 *\n	 * @return string The database character collate.\n	 */\n	public function get_charset_collate() {\n		$charset_collate = \'\';\n\n		if ( ! empty( $this-&gt;charset ) ) {\n			$charset_collate = \"DEFAULT CHARACTER SET $this-&gt;charset\";\n		}\n		if ( ! empty( $this-&gt;collate ) ) {\n			$charset_collate .= \" COLLATE $this-&gt;collate\";\n		}\n\n		return $charset_collate;\n	}\n\n	/**\n	 * データベースが特定の機能をサポートしているかどうかを確認します。\n	 *\n	 * @since 2.7.0\n	 * @since 4.1.0 Added support for the \'utf8mb4\' feature.\n	 * @since 4.6.0 Added support for the \'utf8mb4_520\' feature.\n	 *\n	 * @see wpdb::db_version()\n	 *\n	 * @param string $db_cap The feature to check for. Accepts \'collation\',\n	 *\'group_concat\', \'subqueries\', \'set_charset\',\n	 *\'utf8mb4\', or \'utf8mb4_520\'.\n	 * @return int|false Whether the database feature is supported, false otherwise.\n	 */\n	public function has_cap( $db_cap ) {\n		$version = $this-&gt;db_version();\n\n		switch ( strtolower( $db_cap ) ) {\n			case \'collation\':    // @since 2.5.0\n			case \'group_concat\': // @since 2.7.0\n			case \'subqueries\':   // @since 2.7.0\n				return version_compare( $version, \'4.1\', \'&gt;=\' );\n			case \'set_charset\':\n				return version_compare( $version, \'5.0.7\', \'&gt;=\' );\n			case \'utf8mb4\':      // @since 4.1.0\n				if ( version_compare( $version, \'5.5.3\', \'&lt;\' ) ) {\n					return false;\n				}\n				if ( $this-&gt;use_mysqli ) {\n					$client_version = mysqli_get_client_info();\n				} else {\n					$client_version = mysql_get_client_info();\n				}\n\n				/*\n				 * libmysql has supported utf8mb4 since 5.5.3, same as the MySQL server.\n				 * mysqlnd has supported utf8mb4 since 5.0.9.\n				 */\n				if ( false !== strpos( $client_version, \'mysqlnd\' ) ) {\n					$client_version = preg_replace( \'/^\\D+([\\d.]+).*/\', \'$1\', $client_version );\n					return version_compare( $client_version, \'5.0.9\', \'&gt;=\' );\n				} else {\n					return version_compare( $client_version, \'5.5.3\', \'&gt;=\' );\n				}\n			case \'utf8mb4_520\': // @since 4.6.0\n				return version_compare( $version, \'5.6\', \'&gt;=\' );\n		}\n\n		return false;\n	}\n\n	/**\n	 * wpdbを呼び出した関数の名前を取得してください。\n	 *\n	 * Searches up the list of functions until it reaches\n	 * the one that would most logically had called this method.\n	 *\n	 * @since 2.5.0\n	 *\n	 * @return string Comma separated list of the calling functions.\n	 */\n	public function get_caller() {\n		return wp_debug_backtrace_summary( __CLASS__ );\n	}\n\n	/**\n	 * MySQLサーバーのバージョンを取得します。\n	 *\n	 * @since 2.7.0\n	 *\n	 * @return null|string Null on failure, version number on success.\n	 */\n	public function db_version() {\n		if ( $this-&gt;use_mysqli ) {\n			$server_info = mysqli_get_server_info( $this-&gt;dbh );\n		} else {\n			$server_info = mysql_get_server_info( $this-&gt;dbh );\n		}\n		return preg_replace( \'/[^0-9.].*/\', \'\', $server_info );\n	}\n}\n</pre>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function __construct～__unset</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>文字セット設定　init_charset～</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>SQLモードの確認</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>テーブルにつけるプレフィックスを設定</h3>\n<!-- /wp:heading -->\n\n<p>wp-config.phpで設定してるやつです。</p>\n<p>wordpressのデフォルトのテーブル12個にはいずれも頭にwp_とついてますが、テーブル名をここで決めています。</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ブログID,ブログプレフィックスを取得</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function tables</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>public function select</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>安全に実行できるようにSQLクエリを準備するpublic function prepare</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>print_error,show_errors,hide_errors</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>キャッシュされたクエリ結果を強制終了する。flush</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>データベースに接続して選択するdb_connect</h3>\n<!-- /wp:heading -->','wp-include/wp-db.phpを解読してみた','数あるwordpressのコアファイルの中でもテーブルに接続しているwp-db.phpを読んでみました。','inherit','closed','closed','','2067-revision-v1','','','2019-06-11 13:54:34','2019-06-11 04:54:34','',2067,'https://tech.embodyer.com/anothor/2067-revision-v1',0,'revision','',0),(2485,1,'2019-06-13 13:27:40','2019-06-13 04:27:40','<p>wordpressのコアファイルを読んでる途中で、global宣言と$GLOBALS[変数名]が出てきたのですが、ちょっとあやふやなとこがあったので、今更ながらphpの基礎から確認してみました。</p>\n\n<!-- wp:heading -->\n<h2>変数の宣言とスコープ</h2>\n<!-- /wp:heading -->\n\n<p>phpでは</p>\n<p>$なんとか = 値;</p>\n<p>と言う形で変数を宣言して、値をいれますよね。</p>\n<p>そして代入した値を呼び出す際はechoとかprintrなどで変数を呼び出す訳ですが、ここで関係してくるのが<strong>「<span style=\"color: #ff0000;\">スコープ</span>」</strong>と呼ばれる変数が有効な範囲が関係してきます。</p>\n\n\n\n<!-- wp:heading {\"level\":3} -->\n<h3>擬似変数：$this-&gt; って何だ？</h3>\n<!-- /wp:heading -->\n\n<p>https://www.sejuku.net/blog/51537</p>\n\n<!-- wp:heading -->\n<h2>global宣言と$GLOBALS</h2>\n<!-- /wp:heading -->','phpの変数とスコープ','wordpressのコアファイルを読んでる途中でglobal宣言と$GLOBALS[]が出てきたのでphpの基礎から確認','inherit','closed','closed','','368-revision-v1','','','2019-06-13 13:27:40','2019-06-13 04:27:40','',368,'https://tech.embodyer.com/anothor/368-revision-v1',0,'revision','',0),(2486,1,'2019-06-13 13:29:05','2019-06-13 04:29:05','<p>wor